-- Schema-only export from read-only production catalogs. No business/auth/secret rows.
-- Restore only into a NEW Supabase project after reviewing extensions and external bindings.
BEGIN;
SET LOCAL check_function_bodies = false;
SET LOCAL search_path = public, extensions, pg_catalog;
CREATE SCHEMA IF NOT EXISTS "pgmq";
CREATE SCHEMA IF NOT EXISTS "private";
CREATE SCHEMA IF NOT EXISTS "public";

-- Required extensions are listed in REQUIRED_EXTENSIONS.md; provider-managed ones are not recreated here.
