CREATE OR REPLACE FUNCTION private.dpw_dataset_indexes(_dataset_id uuid, _logical_side text)
 RETURNS integer[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$

 SELECT CASE WHEN EXISTS(SELECT 1 FROM private.dpdi_public_output_links WHERE dataset_id=_dataset_id) THEN private.dpdi_public_dataset_indexes(_dataset_id,_logical_side) ELSE (SELECT coalesce(array_agg((l.value->>'output_index')::integer ORDER BY (l.value->>'output_index')::integer),ARRAY[]::integer[])
 FROM public.data_prep_prepared_datasets d JOIN public.data_prep_delivery_runs r ON r.id=d.run_id,
 jsonb_array_elements(r.result->'outputLineage') l
 WHERE d.id=_dataset_id AND (_logical_side IS NULL OR
 NOT EXISTS(SELECT 1 FROM jsonb_array_elements(l.value->'sources') source WHERE source.value->>'business_side' IS DISTINCT FROM _logical_side))) END
$function$
;

