 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF current_setting('role', true) = 'service_role' THEN RETURN COALESCE(NEW, OLD); END IF;
  RAISE EXCEPTION 'ai_governance_prompt_log is append-only';
END $function$
;

CREATE OR REPLACE FUNCTION public.evaluate_security_alerts()
 RETURNS TABLE(rule_id uuid, tenant_id uuid, event_count integer, fired boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r RECORD;
  v_count integer;
  v_samples bigint[];
  v_severity_filter text[];
  v_min_ts timestamptz;
  v_incident_id uuid;
BEGIN
  FOR r IN
    SELECT * FROM public.security_alert_rules WHERE enabled = true
  LOOP
    -- Respect cooldown
    IF r.last_triggered_at IS NOT NULL
       AND r.last_triggered_at > now() - (r.cooldown_minutes || ' minutes')::interval
    THEN
      RETURN QUERY SELECT r.id, r.tenant_id, 0, false;
      CONTINUE;
    END IF;

    v_min_ts := now() - (r.window_minutes || ' minutes')::interval;
    v_severity_filter := CASE r.min_severity
      WHEN 'info' THEN ARRAY['info','warning','critical']
      WHEN 'warning' THEN ARRAY['warning','critical']
      ELSE ARRAY['critical']
    END;

    -- Per-tenant rule (tenant_id NOT NULL): scope to that tenant only.
    -- Platform-wide rule (tenant_id IS NULL): evaluate per-tenant of the matching events.
    IF r.tenant_id IS NOT NULL THEN
      SELECT count(*)::int,
             COALESCE(array_agg(id ORDER BY occurred_at DESC) FILTER (WHERE id IS NOT NULL), '{}')
        INTO v_count, v_samples
      FROM (
        SELECT id, occurred_at
        FROM public.security_events
        WHERE security_events.tenant_id = r.tenant_id
          AND event_type ILIKE r.event_type_pattern
          AND severity = ANY(v_severity_filter)
          AND occurred_at >= v_min_ts
        ORDER BY occurred_at DESC
        LIMIT 25
      ) s;

      IF v_count >= r.threshold THEN
        INSERT INTO public.security_alert_incidents
          (rule_id, tenant_id, event_count, window_minutes, severity, sample_event_ids, context)
        VALUES
          (r.id, r.tenant_id, v_count, r.window_minutes, r.severity, v_samples,
           jsonb_build_object('rule_code', r.code, 'pattern', r.event_type_pattern))
        RETURNING id INTO v_incident_id;

        UPDATE public.security_alert_rules
           SET last_triggered_at = now(), last_triggered_count = v_count
         WHERE id = r.id;

        -- Notify tenant admins (best-effort; ignore if notifications table is unavailable)
        BEGIN
          INSERT INTO public.notifications (user_id, tenant_id, kind, title, body, link_to, severity, context)
          SELECT tm.user_id, r.tenant_id, 'security_alert',
                 'Security alert: ' || r.code,
                 v_count || ' matching events in last ' || r.window_minutes || 'min',
                 '/security-audit',
                 r.severity,
                 jsonb_build_object('incident_id', v_incident_id, 'rule_id', r.id)
          FROM public.tenant_members tm
          WHERE tm.tenant_id = r.tenant_id
            AND tm.active = true
            AND tm.role = 'tenant_admin'::public.tenant_role;
        EXCEPTION WHEN OTHERS THEN NULL;
        END;

        RETURN QUERY SELECT r.id, r.tenant_id, v_count, true;
      ELSE
        RETURN QUERY SELECT r.id, r.tenant_id, v_count, false;
      END IF;

    ELSE
      -- Platform-wide rule: group by tenant
      FOR v_count, v_samples, v_incident_id IN
        SELECT count(*)::int AS c,
               COALESCE(array_agg(s.id ORDER BY s.occurred_at DESC), '{}'::bigint[]) AS samples,
               s.tenant_id
        FROM public.security_events s
        WHERE s.event_type ILIKE r.event_type_pattern
          AND s.severity = ANY(v_severity_filter)
          AND s.occurred_at >= v_min_ts
        GROUP BY s.tenant_id
        HAVING count(*) >= r.threshold
      LOOP
        -- v_incident_id reused as tenant_id loop var; rebind:
        NULL;
      END LOOP;

      -- Re-run cleanly with proper loop variables:
      FOR r IN
        SELECT alert_rule.id AS rid, alert_rule.code, alert_rule.event_type_pattern, alert_rule.severity,
               alert_rule.window_minutes, alert_rule.threshold, alert_rule.cooldown_minutes,
               grp.tenant_id AS t_id, grp.c AS cnt, grp.samples
        FROM public.security_alert_rules alert_rule
        CROSS JOIN LATERAL (
          SELECT s.tenant_id,
                 count(*)::int AS c,
                 COALESCE(array_agg(s.id ORDER BY s.occurred_at DESC), '{}'::bigint[]) AS samples
          FROM public.security_events s
          WHERE s.event_type ILIKE alert_rule.event_type_pattern
            AND s.severity = ANY(v_severity_filter)
            AND s.occurred_at >= now() - (alert_rule.window_minutes || ' minutes')::interval
          GROUP BY s.tenant_id
          HAVING count(*) >= alert_rule.threshold
        ) grp
        WHERE alert_rule.enabled = true AND alert_rule.tenant_id IS NULL
          AND (alert_rule.last_triggered_at IS NULL
            OR alert_rule.last_triggered_at <= now() - (alert_rule.cooldown_minutes || ' minutes')::interval)
      LOOP
        INSERT INTO public.security_alert_incidents
          (rule_id, tenant_id, event_count, window_minutes, severity, sample_event_ids, context)
        VALUES
          (r.rid, r.t_id, r.cnt, r.window_minutes, r.severity, r.samples,
           jsonb_build_object('rule_code', r.code, 'pattern', r.event_type_pattern, 'platform_rule', true))
        RETURNING id INTO v_incident_id;

        UPDATE public.security_alert_rules
           SET last_triggered_at = now(), last_triggered_count = r.cnt
         WHERE id = r.rid;

        BEGIN
          INSERT INTO public.notifications (user_id, tenant_id, kind, title, body, link_to, severity, context)
          SELECT tm.user_id, r.t_id, 'security_alert',
                 'Security alert: ' || r.code,
                 r.cnt || ' matching events in last ' || r.window_minutes || 'min',
                 '/security-audit',
                 r.severity,
                 jsonb_build_object('incident_id', v_incident_id, 'rule_id', r.rid)
          FROM public.tenant_members tm
          WHERE tm.tenant_id = r.t_id
            AND tm.active = true
            AND tm.role = 'tenant_admin'::public.tenant_role;
        EXCEPTION WHEN OTHERS THEN NULL;
        END;

        RETURN QUERY SELECT r.rid, r.t_id, r.cnt, true;
      END LOOP;
    END IF;
  END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.failed_login_delivery_receipt(_id uuid, _provider_message_id text, _state text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'public', 'pg_temp'
AS $function$
DECLARE a private.failed_login_attempts;
BEGIN
  IF _state NOT IN ('delivered','bounced') OR _state IS NULL THEN RAISE EXCEPTION 'Invalid delivery state' USING ERRCODE='22023'; END IF;
  SELECT * INTO a FROM private.failed_login_attempts WHERE id=_id FOR UPDATE;
  IF NOT FOUND OR a.provider_message_id IS DISTINCT FROM _provider_message_id OR _provider_message_id IS NULL OR a.delivery_state NOT IN ('provider_accepted','delivered','bounced') THEN RETURN false; END IF;
  IF a.delivery_state=_state THEN RETURN true; END IF;
  IF a.delivery_state IN ('delivered','bounced') THEN RETURN false; END IF;
  UPDATE private.failed_login_attempts SET delivery_state=_state,updated_at=clock_timestamp() WHERE id=_id;
  INSERT INTO private.failed_login_delivery_audit(attempt_id,state,provider_message_id) VALUES(_id,_state,_provider_message_id);
  RETURN true;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.release_ai_kill_switch(p_tenant uuid, p_scope text)
 RETURNS ai_governance_kill_switches
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.ai_governance_kill_switches;
BEGIN
  IF NOT (has_tenant_role(auth.uid(), p_tenant, 'tenant_admin') OR is_platform_admin(auth.uid())) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  UPDATE public.ai_governance_kill_switches
    SET engaged = false, released_by = auth.uid(), released_at = now(), updated_at = now()
    WHERE tenant_id = p_tenant AND scope = p_scope
    RETURNING * INTO r;
  INSERT INTO public.audit_log(tenant_id, actor_user_id, scope, action, resource_type, resource_id, context)
  VALUES (p_tenant, auth.uid(), 'tenant', 'ai.kill_switch.released', 'ai_governance_kill_switches', r.id::text,
          jsonb_build_object('scope', p_scope));
  RETURN r;
END $function$
;

CREATE OR REPLACE FUNCTION private.dpw_attachment_register()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE policy jsonb; days integer; input public.data_prep_delivery_files%ROWTYPE;
BEGIN
 IF NEW.finished_at IS NULL OR OLD.finished_at IS NOT NULL THEN RETURN NEW; END IF;
 policy:=private.dpw_effective_attachment_policy(NEW.tenant_id);days:=(policy->>'period_days')::integer;
 IF days IS NULL OR days<1 OR policy->>'source' NOT IN('platform','tenant') OR policy->>'policy_id' IS NULL OR policy->>'version' IS NULL THEN RAISE EXCEPTION 'dpw.retention_policy_unavailable'; END IF;
 FOR input IN SELECT f.* FROM public.data_prep_delivery_files f JOIN public.data_prep_run_inputs i ON i.file_id=f.id WHERE i.run_id=NEW.id LOOP
 INSERT INTO public.data_prep_attachment_retention(file_id,tenant_id,pipeline_id,bucket_id,original_path,original_file_bytes_sha256,original_size_bytes,run_id,attached_at,expires_at,
 policy_id,policy_version,period_days,policy_source,notice_30_at,notice_10_at,notice)
 VALUES(input.id,input.tenant_id,input.pipeline_id,'data-prep-inputs',input.original_path,input.content_sha256,(input.descriptor->>'size_bytes')::bigint,
 NEW.id,NEW.finished_at,NEW.finished_at+days*interval '1 day',(policy->>'policy_id')::uuid,policy->>'version',days,policy->>'source',
 NEW.finished_at+greatest(days-30,0)*interval '1 day',NEW.finished_at+greatest(days-10,0)*interval '1 day',
 'Data Prep attachment data is available for '||days::text||' days under its snapshotted policy. Run, configuration, count, hash and audit metadata are retained. Legal holds stop purge.');
 END LOOP;
 RETURN NEW;
END $function$
;

