CREATE OR REPLACE FUNCTION public.tg_recon_run_autopack()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status IN ('completed','failed','cancelled')
     AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN
    BEGIN
      PERFORM public.generate_recon_run_evidence_pack(NEW.id);
    EXCEPTION WHEN OTHERS THEN
      -- never block the run on evidence-pack errors; surface via audit_log
      INSERT INTO public.audit_log (tenant_id, scope, action, resource_type, resource_id, context)
      VALUES (NEW.tenant_id, 'tenant', 'recon.evidence_pack.failed', 'recon_run', NEW.id::text,
              jsonb_build_object('error', SQLERRM));
    END;
  END IF;
  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.step_up_grants_mark_expired()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count integer := 0;
BEGIN
  WITH expired AS (
    SELECT g.id, g.user_id
    FROM public.step_up_grants g
    LEFT JOIN LATERAL (
      SELECT 1 FROM public.step_up_grant_lifecycle l
       WHERE l.grant_id = g.id AND l.action IN ('consumed','expired')
       LIMIT 1
    ) seen ON true
    WHERE g.consumed_at IS NULL
      AND g.expires_at < now()
      AND seen IS NULL
  ),
  ins AS (
    INSERT INTO public.step_up_grant_lifecycle (grant_id, action, actor_user_id)
    SELECT id, 'expired', user_id FROM expired
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_count FROM ins;
  RETURN v_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.consume_platform_invitations_on_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  inv record;
  seeded_name text;
BEGIN
  IF NEW.email IS NULL THEN
    RETURN NEW;
  END IF;

  FOR inv IN
    SELECT id, role, invited_by, full_name
    FROM public.platform_invitations
    WHERE lower(email::text) = lower(NEW.email)
      AND accepted_at IS NULL
      AND revoked_at IS NULL
      AND expires_at > now()
  LOOP
    BEGIN
      INSERT INTO public.platform_roles (user_id, role, granted_by)
      VALUES (NEW.id, inv.role::platform_role, inv.invited_by);
    EXCEPTION WHEN unique_violation THEN
      NULL;
    END;

    UPDATE public.platform_invitations
       SET accepted_at = now(), accepted_by = NEW.id
     WHERE id = inv.id;

    IF seeded_name IS NULL AND inv.full_name IS NOT NULL AND btrim(inv.full_name) <> '' THEN
      seeded_name := btrim(inv.full_name);
    END IF;

    INSERT INTO public.audit_log (actor_user_id, scope, action, resource_type, resource_id, context)
    VALUES (inv.invited_by, 'platform', 'platform_invitation.accept', 'platform_invitation', inv.id,
            jsonb_build_object('email', NEW.email, 'role', inv.role));
  END LOOP;

  IF seeded_name IS NOT NULL AND (NEW.full_name IS NULL OR btrim(NEW.full_name) = '') THEN
    NEW.full_name := seeded_name;
  END IF;

  RETURN NEW;
END;
$function$
;

