CREATE OR REPLACE FUNCTION public.mkt_bootstrap_super_admin(_caller uuid, _email text)
 RETURNS TABLE(promoted boolean, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _exists boolean;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('mkt_bootstrap_super_admin'));
  SELECT EXISTS(SELECT 1 FROM public.mkt_admin_roles WHERE role = 'super_admin')
    INTO _exists;
  IF _exists THEN
    RETURN QUERY SELECT false, 'super_admin_exists'::text;
    RETURN;
  END IF;
  INSERT INTO public.mkt_admin_roles(user_id, role, granted_by)
    VALUES (_caller, 'super_admin', _caller);
  INSERT INTO public.mkt_admin_users(user_id, display_name, status)
    VALUES (_caller, _email, 'active')
    ON CONFLICT (user_id) DO UPDATE SET status = 'active';
  RETURN QUERY SELECT true, 'bootstrapped'::text;
END$function$
;

CREATE OR REPLACE FUNCTION private.is_platform_super_admin(_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT private.has_platform_role(_user_id, 'platform_super_admin'::platform_role)
$function$
;

CREATE OR REPLACE FUNCTION public.pipeline_stats_window(_minutes integer DEFAULT 60)
 RETURNS TABLE(sink text, bucket_ts timestamp with time zone, ok_count bigint, drop_count bigint, error_count bigint, latency_avg_ms numeric, latency_max_ms integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT sink, bucket_ts, ok_count, drop_count, error_count,
    CASE WHEN (ok_count + error_count) > 0
         THEN latency_sum_ms::numeric / (ok_count + error_count)
         ELSE 0 END AS latency_avg_ms,
    latency_max_ms
  FROM public.observability_pipeline_stats
  WHERE bucket_ts >= now() - make_interval(mins => GREATEST(_minutes, 1))
  ORDER BY bucket_ts ASC, sink ASC;
$function$
;

CREATE OR REPLACE FUNCTION public.is_platform_super_admin(_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$ SELECT private.is_platform_super_admin(_user_id) $function$
;

