CREATE OR REPLACE FUNCTION public.tg_github_sync_cr_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
BEGIN
  -- Terminal states are immutable
  IF TG_OP = 'UPDATE' AND OLD.status IN ('applied','rejected','cancelled') THEN
    RAISE EXCEPTION 'github_sync change request % is terminal (status=%) and cannot be modified',
      OLD.id, OLD.status;
  END IF;

  -- Self-approval and duplicate-approver prevention
  IF NEW.approver_1 IS NOT NULL AND NEW.approver_1 = NEW.requested_by THEN
    RAISE EXCEPTION 'requester cannot be approver_1 (4-eyes violation)';
  END IF;
  IF NEW.approver_2 IS NOT NULL AND NEW.approver_2 = NEW.requested_by THEN
    RAISE EXCEPTION 'requester cannot be approver_2 (4-eyes violation)';
  END IF;
  IF NEW.approver_1 IS NOT NULL AND NEW.approver_2 IS NOT NULL
     AND NEW.approver_1 = NEW.approver_2 THEN
    RAISE EXCEPTION 'approver_1 and approver_2 must be distinct (4-eyes violation)';
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.complete_regulatory_install(_install_id uuid, _recon_id uuid, _pipeline_ids uuid[], _folder_name text, _field_count integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old_status text;
  v_tenant uuid;
  v_actor uuid;
BEGIN
  SELECT status, tenant_id, installed_by
    INTO v_old_status, v_tenant, v_actor
    FROM public.regulatory_pack_installs
   WHERE id = _install_id
   FOR UPDATE;

  UPDATE public.regulatory_pack_installs
     SET status = 'ready', completed_at = now(), materialized_at = now(),
         generated_process_count = COALESCE(array_length(_pipeline_ids, 1), 0) + 1,
         tenant_root_process_id = _recon_id, recon_id = _recon_id,
         materialized_artifacts = jsonb_build_object(
           'folder', _folder_name, 'pipeline_ids', to_jsonb(_pipeline_ids),
           'recon_id', _recon_id, 'field_count', _field_count
         )
   WHERE id = _install_id;

  INSERT INTO public.audit_log(
    actor_user_id, tenant_id, scope, action, resource_type, resource_id, context
  ) VALUES (
    v_actor, v_tenant, 'tenant',
    'regulatory.install.transition',
    'regulatory_pack_installs', _install_id::text,
    jsonb_build_object(
      'from', v_old_status, 'to', 'ready',
      'transitioned_at', now(), 'worker', 'regulatory-install-worker',
      'recon_id', _recon_id,
      'pipeline_count', COALESCE(array_length(_pipeline_ids, 1), 0),
      'folder', _folder_name, 'field_count', _field_count
    )
  );
END $function$
;

CREATE OR REPLACE FUNCTION public.guard_last_tenant_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid;
  v_remaining int;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_tenant := OLD.tenant_id;
    IF OLD.role::text <> 'tenant_admin' THEN RETURN OLD; END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    v_tenant := NEW.tenant_id;
    -- Only fire if losing admin status or being deactivated
    IF NEW.active = OLD.active AND NEW.role = OLD.role THEN RETURN NEW; END IF;
    IF OLD.role::text <> 'tenant_admin' THEN RETURN NEW; END IF;
  END IF;

  SELECT count(*) INTO v_remaining
  FROM public.tenant_members
  WHERE tenant_id = v_tenant
    AND role::text = 'tenant_admin'
    AND active = true
    AND id <> COALESCE(NEW.id, OLD.id);

  IF v_remaining = 0 THEN
    RAISE EXCEPTION 'Cannot remove last active tenant_admin for tenant %', v_tenant
      USING ERRCODE = '23514', HINT = 'Promote another member to tenant_admin first.';
  END IF;

  RETURN COALESCE(NEW, OLD);
END $function$
;

CREATE OR REPLACE FUNCTION public.enforce_sod_on_grant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r record;
BEGIN
  FOR r IN
    SELECT s.name, s.permission_a, s.permission_b, s.severity
    FROM public.rbac_sod_rules s
    WHERE (s.tenant_id IS NULL OR s.tenant_id = NEW.tenant_id)
      AND EXISTS (
        SELECT 1 FROM public.rbac_role_permissions rp
        WHERE rp.role_id = NEW.role_id AND rp.permission_id = s.permission_a
      )
  LOOP
    IF EXISTS (
      SELECT 1
      FROM public.rbac_user_grants g2
      JOIN public.rbac_role_permissions rp2 ON rp2.role_id = g2.role_id
      WHERE g2.user_id = NEW.user_id
        AND g2.tenant_id = NEW.tenant_id
        AND g2.revoked_at IS NULL
        AND rp2.permission_id = r.permission_b
    ) THEN
      IF r.severity = 'block' THEN
        RAISE EXCEPTION 'SoD violation: % (permissions % and %)', r.name, r.permission_a, r.permission_b
          USING ERRCODE = '23514';
      END IF;
    END IF;
  END LOOP;
  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.validate_data_resource_registry_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
