BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.business_units bu
    WHERE bu.id = NEW.bu_id AND bu.tenant_id = NEW.tenant_id AND NOT bu.is_archived
  ) THEN RAISE EXCEPTION 'owner business unit must be active in the same tenant'; END IF;
  RETURN NEW;
END $function$
;

