CREATE OR REPLACE FUNCTION private.data_resource_shadow_allows_actor(_actor uuid, _registry_id uuid, _action text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
  WITH target AS (
    SELECT r.id, r.tenant_id
    FROM public.data_resource_registry r
    WHERE r.id = _registry_id
      AND _action IN ('view', 'ingest', 'run', 'edit', 'manage', 'approve')
      AND EXISTS (
        SELECT 1 FROM public.data_resource_registry_owner_bu owner_link
        JOIN public.business_units owner_bu ON owner_bu.id = owner_link.bu_id
          AND owner_bu.tenant_id = owner_link.tenant_id AND NOT owner_bu.is_archived
        WHERE owner_link.tenant_id = r.tenant_id AND owner_link.registry_id = r.id
      )
  ), active_actor AS (
    SELECT t.tenant_id, tm.role
    FROM target t
    JOIN public.tenant_members tm ON tm.tenant_id = t.tenant_id AND tm.user_id = _actor AND tm.active
  ), admin_override AS (
    SELECT 1 FROM active_actor WHERE role = 'tenant_admin'::public.tenant_role
  ), direct_grant AS (
    SELECT 1
    FROM target t
    JOIN active_actor aa ON aa.tenant_id = t.tenant_id
    JOIN public.data_resource_registry_owner_bu o ON o.tenant_id = t.tenant_id AND o.registry_id = t.id
    JOIN public.business_units target_bu ON target_bu.id = o.bu_id AND target_bu.tenant_id = t.tenant_id AND NOT target_bu.is_archived
    JOIN public.data_resource_registry_grants g ON g.tenant_id = t.tenant_id AND g.registry_id = t.id AND g.bu_id = o.bu_id
    WHERE g.action = _action AND g.principal_type = 'user' AND g.principal_user_id = _actor
      AND EXISTS (
        SELECT 1 FROM public.bu_user_assignments ua
        JOIN public.business_units assigned_bu ON assigned_bu.id = ua.bu_id AND assigned_bu.tenant_id = ua.tenant_id AND NOT assigned_bu.is_archived
        WHERE ua.tenant_id = t.tenant_id AND ua.user_id = _actor
          AND (assigned_bu.id = target_bu.id OR (ua.inherit_descendants AND target_bu.path <@ assigned_bu.path))
      )
  ), group_grant AS (
    SELECT 1
    FROM target t
    JOIN active_actor aa ON aa.tenant_id = t.tenant_id
    JOIN public.data_resource_registry_owner_bu o ON o.tenant_id = t.tenant_id AND o.registry_id = t.id
    JOIN public.business_units target_bu ON target_bu.id = o.bu_id AND target_bu.tenant_id = t.tenant_id AND NOT target_bu.is_archived
    JOIN public.data_resource_registry_grants g ON g.tenant_id = t.tenant_id AND g.registry_id = t.id AND g.bu_id = o.bu_id
    JOIN public.tenant_groups grant_group ON grant_group.id = g.principal_group_id AND grant_group.tenant_id = t.tenant_id
    JOIN public.tenant_group_members gm ON gm.group_id = grant_group.id AND gm.user_id = _actor
    WHERE g.action = _action AND g.principal_type = 'group'
      AND EXISTS (
        SELECT 1 FROM public.bu_group_assignments ga
        JOIN public.business_units assigned_bu ON assigned_bu.id = ga.bu_id AND assigned_bu.tenant_id = ga.tenant_id AND NOT assigned_bu.is_archived
        WHERE ga.tenant_id = t.tenant_id AND ga.group_id = grant_group.id
          AND (assigned_bu.id = target_bu.id OR (ga.inherit_descendants AND target_bu.path <@ assigned_bu.path))
      )
  )
  SELECT CASE
    WHEN _actor IS NULL OR _registry_id IS NULL OR _action NOT IN ('view', 'ingest', 'run', 'edit', 'manage', 'approve') THEN false
    WHEN NOT EXISTS (SELECT 1 FROM target) OR NOT EXISTS (SELECT 1 FROM active_actor) THEN false
    -- The generic ledger cannot prove a lifecycle request maker. Never let a
    -- grant or admin override substitute for workflow-specific SoD evidence.
    WHEN _action = 'approve' THEN false
    WHEN EXISTS (SELECT 1 FROM admin_override) THEN true
    ELSE EXISTS (SELECT 1 FROM direct_grant) OR EXISTS (SELECT 1 FROM group_grant)
  END
$function$
;

CREATE OR REPLACE FUNCTION public.audit_log_chain()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_prev bytea;
  v_payload text;
  v_session_role text;
  v_system_action boolean;
begin
  select last_hash into v_prev
  from public.audit_chain_head
  where singleton = true
  for update;

  new.prev_hash := v_prev;
  v_session_role := current_setting('role', true);

  if v_session_role = 'authenticated' then
    if auth.uid() is null then
      raise exception 'audit_log: authenticated actor is missing'
        using errcode = 'check_violation';
    end if;
    new.actor_user_id := auth.uid();
    if new.tenant_id is not null
       and not public.is_tenant_member(auth.uid(), new.tenant_id)
       and not public.is_platform_admin(auth.uid()) then
      raise exception 'audit_log: tenant attribution is not authorized'
        using errcode = 'insufficient_privilege';
    end if;
  else
    new.actor_user_id := coalesce(new.actor_user_id, auth.uid());
  end if;

  v_system_action := (
    new.actor_user_id is not null
    or v_session_role in ('service_role', 'postgres')
    or new.scope = 'system'
    or new.action like 'cron.%'
    or new.action like 'webhook.%'
    or new.action like 'system.%'
    or new.action like 'scim.%'
    or new.action like 'retention.%'
    or new.action like 'backup.%'
    or new.action like 'recon.evidence_pack.%'
  );
  if not v_system_action then
    raise exception 'audit_log: actor_user_id required for non-system action "%" (scope=%)', new.action, new.scope
      using errcode = 'check_violation';
  end if;

  v_payload := coalesce(encode(v_prev,'hex'),'') || '|' ||
               coalesce(new.actor_user_id::text,'') || '|' ||
               coalesce(new.tenant_id::text,'') || '|' || new.scope || '|' || new.action || '|' ||
               coalesce(new.resource_type,'') || '|' || coalesce(new.resource_id,'') || '|' ||
               coalesce(new.context::text,'{}') || '|' || new.occurred_at::text;
  new.row_hash := digest(v_payload, 'sha256');

  update public.audit_chain_head
  set last_audit_id = new.id,
      last_hash = new.row_hash,
      updated_at = now()
  where singleton = true;

  return new;
end
$function$
;

CREATE OR REPLACE FUNCTION private.rlnext_base_private_user_can_access_recon(_user uuid, _recon uuid, _perm text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH d AS (SELECT tenant_id, visibility FROM public.recon_definitions WHERE id = _recon)
  SELECT
    private.is_platform_admin(_user)
    OR EXISTS (
      SELECT 1 FROM d
      WHERE private.is_tenant_member(_user, d.tenant_id) AND (
        (d.visibility = 'tenant' AND (_perm = 'read'
          OR private.has_tenant_role(_user, d.tenant_id, 'tenant_admin')
          OR (private.has_tenant_role(_user, d.tenant_id, 'tenant_analyst') AND _perm IN ('run','edit','approve'))))
        OR (d.visibility = 'restricted' AND private.has_tenant_role(_user, d.tenant_id, 'tenant_admin'))
        OR EXISTS (SELECT 1 FROM public.recon_permissions rp
            WHERE rp.recon_id = _recon AND rp.principal_type = 'user'
              AND rp.principal_id = _user AND rp.permission = _perm)
        OR EXISTS (SELECT 1 FROM public.recon_permissions rp
            JOIN public.tenant_group_members gm ON gm.group_id = rp.principal_id AND gm.user_id = _user
            WHERE rp.recon_id = _recon AND rp.principal_type = 'group' AND rp.permission = _perm)
      )
    )
$function$
;

CREATE OR REPLACE FUNCTION private.user_can_access_recon(_user uuid, _recon uuid, _perm text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$SELECT (private.rlnext_account_allowed(auth.uid(),NULL) AND private.rlnext_account_allowed(_user,NULL)) AND private.rlnext_base_private_user_can_access_recon(_user,_recon,_perm)$function$
;

CREATE OR REPLACE FUNCTION public.worm_append(_tenant_id uuid, _evidence_type text, _resource_type text, _resource_id text, _sha256 text, _size_bytes bigint, _object_url text, _bucket_name text, _retention_days integer)
 RETURNS worm_evidence_ledger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  _prev text;
  _chain text;
  _row public.worm_evidence_ledger;
begin
  if not (public.has_tenant_role(auth.uid(), _tenant_id, 'tenant_admin')
       or public.is_platform_admin(auth.uid())) then
    raise exception 'Forbidden: tenant_admin required';
  end if;
  select chain_hash into _prev
    from public.worm_evidence_ledger
   where tenant_id = _tenant_id
   order by recorded_at desc, id desc
   limit 1;
  _chain := encode(
    digest(coalesce(_prev,'') || '|' || _sha256 || '|' || _evidence_type
           || '|' || coalesce(_resource_id,''), 'sha256'),
    'hex');
  insert into public.worm_evidence_ledger
    (tenant_id, evidence_type, resource_type, resource_id, sha256, size_bytes,
     object_url, bucket_name, object_lock_until, prev_hash, chain_hash, recorded_by)
  values
    (_tenant_id, _evidence_type, _resource_type, _resource_id, _sha256, _size_bytes,
     _object_url, _bucket_name,
     case when _retention_days is null then null
          else now() + make_interval(days => _retention_days) end,
     _prev, _chain, auth.uid())
  returning * into _row;
  return _row;
end $function$
;

CREATE OR REPLACE FUNCTION public.fail_regulatory_install(_install_id uuid, _error text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old_status text;
  v_tenant uuid;
  v_actor uuid;
BEGIN
  SELECT status, tenant_id, installed_by
    INTO v_old_status, v_tenant, v_actor
    FROM public.regulatory_pack_installs
   WHERE id = _install_id
   FOR UPDATE;

  UPDATE public.regulatory_pack_installs
     SET status = 'failed',
         error_message = _error,
         materialization_error = _error
   WHERE id = _install_id;

  INSERT INTO public.audit_log(
    actor_user_id, tenant_id, scope, action, resource_type, resource_id, context
  ) VALUES (
    v_actor, v_tenant, 'tenant',
    'regulatory.install.transition',
    'regulatory_pack_installs', _install_id::text,
    jsonb_build_object(
      'from', v_old_status, 'to', 'failed',
      'transitioned_at', now(), 'worker', 'regulatory-install-worker',
      'error', _error
    )
  );
END $function$
;

CREATE OR REPLACE FUNCTION public.evaluate_roadmap_audit_ready(_item_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_total int; v_satisfied int;
BEGIN
  SELECT count(*) FILTER (WHERE true),
         count(*) FILTER (WHERE satisfied)
    INTO v_total, v_satisfied
  FROM public.roadmap_readiness_criteria WHERE roadmap_item_id = _item_id;
  IF v_total = 0 THEN RETURN false; END IF;
  RETURN v_satisfied = v_total;
END $function$
;

CREATE OR REPLACE FUNCTION public.audit_scim_provisioning_settings_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.audit_log(
    actor_user_id, tenant_id, scope, action, resource_type, resource_id, context
  ) VALUES (
    COALESCE(NEW.updated_by, auth.uid()),
    NEW.tenant_id,
    'tenant',
    CASE TG_OP
      WHEN 'INSERT' THEN 'scim.settings.create'
      WHEN 'UPDATE' THEN 'scim.settings.update'
      ELSE 'scim.settings.change'
    END,
    'scim_provisioning_settings',
    NEW.tenant_id::text,
    jsonb_build_object(
      'enabled', NEW.enabled,
      'auto_deprovision', NEW.auto_deprovision,
      'default_role', NEW.default_role,
      'prev_enabled', CASE WHEN TG_OP='UPDATE' THEN OLD.enabled ELSE NULL END,
      'attribute_mapping_keys', (SELECT jsonb_agg(k) FROM jsonb_object_keys(NEW.attribute_mapping) k)
    )
  );
  RETURN NEW;
END;
$function$
;

