CREATE OR REPLACE FUNCTION private.rlnext_base_private_user_has_tenant_role_or_group(_user uuid, _tenant uuid, _role tenant_role)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.tenant_members member
    WHERE member.user_id = _user AND member.tenant_id = _tenant
      AND member.active IS TRUE
  ) AND (
    private.has_tenant_role(_user, _tenant, _role)
    OR EXISTS (
      SELECT 1 FROM public.tenant_group_members gm
        JOIN public.tenant_groups g ON g.id = gm.group_id AND g.tenant_id = _tenant
        JOIN public.tenant_group_roles gr ON gr.group_id = g.id
        JOIN public.rbac_roles rr ON rr.id = gr.role_id
      WHERE gm.user_id = _user AND rr.is_system IS TRUE
        AND rr.tenant_id IS NULL AND rr.key = _role::text
    )
  )
$function$
;

CREATE OR REPLACE FUNCTION private.user_has_tenant_role_or_group(_user uuid, _tenant uuid, _role tenant_role)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$SELECT (private.rlnext_account_allowed(auth.uid(),NULL) AND private.rlnext_account_allowed(_user,_tenant)) AND private.rlnext_base_private_user_has_tenant_role_or_group(_user,_tenant,_role)$function$
;

CREATE OR REPLACE FUNCTION public.tg_regulatory_install_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.audit_log(
      actor_user_id, tenant_id, scope, action, resource_type, resource_id, context
    ) VALUES (
      NEW.installed_by, NEW.tenant_id, 'tenant',
      'regulatory.install.transition',
      'regulatory_pack_installs', NEW.id::text,
      jsonb_build_object(
        'from', NULL, 'to', NEW.status,
        'transitioned_at', now(),
        'pack_id', NEW.pack_id,
        'installed_version', NEW.installed_version
      )
    );
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
    -- Skip if the transition came from one of our SECURITY DEFINER RPCs,
    -- which already insert their own (richer) audit row. We detect that via
    -- the action label seen on the most recent audit row for this resource
    -- within the current statement window.
    IF NOT EXISTS (
      SELECT 1 FROM public.audit_log
       WHERE resource_type = 'regulatory_pack_installs'
         AND resource_id = NEW.id::text
         AND action = 'regulatory.install.transition'
         AND occurred_at > now() - interval '2 seconds'
         AND (context->>'to') = NEW.status
    ) THEN
      INSERT INTO public.audit_log(
        actor_user_id, tenant_id, scope, action, resource_type, resource_id, context
      ) VALUES (
        COALESCE(auth.uid(), NEW.installed_by), NEW.tenant_id, 'tenant',
        'regulatory.install.transition',
        'regulatory_pack_installs', NEW.id::text,
        jsonb_build_object(
          'from', OLD.status, 'to', NEW.status,
          'transitioned_at', now(),
          'source', 'trigger'
        )
      );
    END IF;
  END IF;

  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.agent_actions_no_self_approve()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  requester_id uuid;
BEGIN
  IF NEW.approved_by IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.approved_by IS NOT DISTINCT FROM NEW.approved_by THEN
    RETURN NEW;
  END IF;
  SELECT user_id INTO requester_id FROM public.agent_runs WHERE id = NEW.run_id;
  IF requester_id IS NOT NULL AND requester_id = NEW.approved_by THEN
    RAISE EXCEPTION 'agent.self_approve_blocked'
      USING HINT = 'Approver must differ from the user who started the agent run.';
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.rlnext_base_public_has_permission(_user_id uuid, _permission text, _tenant_id uuid, _scope_type rbac_scope_type DEFAULT 'tenant'::rbac_scope_type, _scope_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.rbac_user_grants g
    JOIN public.rbac_role_permissions rp ON rp.role_id = g.role_id
    WHERE g.user_id = _user_id
      AND g.tenant_id = _tenant_id
      AND g.revoked_at IS NULL
      AND (g.expires_at IS NULL OR g.expires_at > now())
      AND rp.permission_id = _permission
      AND (
        -- Tenant-wide grant covers any scope
        g.scope_type = 'tenant'
        -- Exact scope match
        OR (g.scope_type = _scope_type AND g.scope_id = _scope_id)
        -- BU grant inherits down (via ltree)
        OR (g.scope_type = 'business_unit' AND _scope_type = 'business_unit'
            AND EXISTS (
              SELECT 1 FROM public.business_units child
              JOIN public.business_units parent ON parent.id = g.scope_id
              WHERE child.id = _scope_id
                AND child.tenant_id = _tenant_id
                AND child.path <@ parent.path
            ))
      )
  );
$function$
;

CREATE OR REPLACE FUNCTION public.worker_record_failure(_tenant uuid, _scope worker_breaker_scope, _target uuid, _step text, _run_id uuid, _attempt integer, _max_attempts integer, _error text, _backoff_seconds integer)
 RETURNS TABLE(breaker_state worker_breaker_state, action text, next_probe_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.worker_circuit_breakers%ROWTYPE;
  v_action text;
  v_new_state public.worker_breaker_state;
BEGIN
  INSERT INTO public.worker_circuit_breakers (tenant_id, scope, target_id, last_failure_at, last_error, consecutive_failures)
  VALUES (_tenant, _scope, _target, now(), _error, 1)
  ON CONFLICT (tenant_id, scope, target_id) DO UPDATE
    SET consecutive_failures = public.worker_circuit_breakers.consecutive_failures + 1,
        last_failure_at = now(),
        last_error = _error,
        updated_at = now()
  RETURNING * INTO v_row;

  v_new_state := v_row.state;
  v_action := CASE WHEN _attempt < _max_attempts THEN 'retry_scheduled' ELSE 'retry_exhausted' END;

  IF v_row.consecutive_failures >= v_row.failure_threshold AND v_row.state <> 'open' THEN
    UPDATE public.worker_circuit_breakers
       SET state = 'open',
           opened_at = now(),
           next_probe_at = now() + make_interval(secs => v_row.cooldown_seconds),
           updated_at = now()
     WHERE id = v_row.id
    RETURNING * INTO v_row;
    v_new_state := 'open';
    v_action := 'breaker_open';

    INSERT INTO public.audit_log(actor_user_id, tenant_id, scope, action, resource_type, resource_id, context)
    VALUES (NULL, _tenant, 'tenant', 'worker.breaker.open', _scope::text, _target::text,
            jsonb_build_object('consecutive_failures', v_row.consecutive_failures,
                               'threshold', v_row.failure_threshold,
                               'cooldown_seconds', v_row.cooldown_seconds,
                               'last_error', _error,
                               'step', _step,
                               'run_id', _run_id));
  END IF;

  INSERT INTO public.worker_retry_attempts(
    tenant_id, pipeline_id, data_source_id, run_id, step, attempt, max_attempts,
    status, error, backoff_seconds, breaker_state
  ) VALUES (
    _tenant,
    CASE WHEN _scope = 'pipeline' THEN _target ELSE NULL END,
    CASE WHEN _scope = 'data_source' THEN _target ELSE NULL END,
    _run_id, _step, _attempt, _max_attempts,
    v_action, _error, _backoff_seconds, v_new_state
  );

  INSERT INTO public.audit_log(actor_user_id, tenant_id, scope, action, resource_type, resource_id, context)
  VALUES (NULL, _tenant, 'tenant', 'worker.step.retry', _scope::text, _target::text,
          jsonb_build_object('step', _step, 'attempt', _attempt, 'max_attempts', _max_attempts,
                             'backoff_seconds', _backoff_seconds, 'breaker_state', v_new_state,
                             'action', v_action, 'error', _error, 'run_id', _run_id));

  RETURN QUERY SELECT v_new_state, v_action, v_row.next_probe_at;
END $function$
;

CREATE OR REPLACE FUNCTION public.worker_record_success(_tenant uuid, _scope worker_breaker_scope, _target uuid, _step text, _run_id uuid, _attempt integer)
 RETURNS worker_breaker_state
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.worker_circuit_breakers%ROWTYPE; v_prev public.worker_breaker_state;
BEGIN
  INSERT INTO public.worker_circuit_breakers (tenant_id, scope, target_id, last_success_at, consecutive_failures, state)
  VALUES (_tenant, _scope, _target, now(), 0, 'closed')
  ON CONFLICT (tenant_id, scope, target_id) DO UPDATE
    SET last_success_at = now(),
        consecutive_failures = 0,
        state = 'closed',
        opened_at = NULL,
        next_probe_at = NULL,
        updated_at = now()
  RETURNING * INTO v_row;

  GET DIAGNOSTICS v_prev = ROW_COUNT;

  INSERT INTO public.worker_retry_attempts(
    tenant_id, pipeline_id, data_source_id, run_id, step, attempt, max_attempts,
    status, breaker_state
  ) VALUES (
    _tenant,
    CASE WHEN _scope = 'pipeline' THEN _target ELSE NULL END,
    CASE WHEN _scope = 'data_source' THEN _target ELSE NULL END,
    _run_id, _step, _attempt, _attempt, 'success', 'closed'
  );

  INSERT INTO public.audit_log(actor_user_id, tenant_id, scope, action, resource_type, resource_id, context)
  VALUES (NULL, _tenant, 'tenant', 'worker.step.success', _scope::text, _target::text,
          jsonb_build_object('step', _step, 'attempt', _attempt, 'run_id', _run_id, 'breaker_state', 'closed'));

  RETURN 'closed'::public.worker_breaker_state;
END $function$
;

CREATE OR REPLACE FUNCTION public.recon_matches_audit_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_deleted_by uuid;
  v_reason text;
BEGIN
  BEGIN
    v_deleted_by := NULLIF(current_setting('app.deleted_by', true), '')::uuid;
  EXCEPTION WHEN others THEN
    v_deleted_by := NULL;
  END;
  BEGIN
    v_reason := NULLIF(current_setting('app.delete_reason', true), '');
  EXCEPTION WHEN others THEN
    v_reason := NULL;
  END;

  INSERT INTO public.recon_match_deletions (
    match_id, tenant_id, run_id, deleted_by, reason, snapshot
  )
  VALUES (
    OLD.id, OLD.tenant_id, OLD.run_id, v_deleted_by, v_reason,
    to_jsonb(OLD)
  );
  RETURN OLD;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.worker_check_breaker(_tenant uuid, _scope worker_breaker_scope, _target uuid)
 RETURNS TABLE(allow boolean, state worker_breaker_state, retry_after_seconds integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.worker_circuit_breakers%ROWTYPE;
BEGIN
  SELECT * INTO v_row FROM public.worker_circuit_breakers
   WHERE tenant_id = _tenant AND scope = _scope AND target_id = _target FOR UPDATE;
  IF NOT FOUND THEN RETURN QUERY SELECT true, 'closed'::public.worker_breaker_state, 0; RETURN; END IF;
  IF v_row.state = 'closed' THEN RETURN QUERY SELECT true, v_row.state, 0; RETURN; END IF;
  IF v_row.state = 'open' AND v_row.next_probe_at IS NOT NULL AND now() >= v_row.next_probe_at THEN
    UPDATE public.worker_circuit_breakers SET state = 'half_open', updated_at = now() WHERE id = v_row.id;
    INSERT INTO public.audit_log(actor_user_id, tenant_id, scope, action, resource_type, resource_id, context)
    VALUES (NULL, _tenant, 'tenant', 'worker.breaker.half_open', _scope::text, _target::text, '{}'::jsonb);
    RETURN QUERY SELECT true, 'half_open'::public.worker_breaker_state, 0; RETURN;
  END IF;
  IF v_row.state = 'open' THEN
    RETURN QUERY SELECT false, v_row.state,
      GREATEST(0, EXTRACT(EPOCH FROM (COALESCE(v_row.next_probe_at, now()) - now()))::int);
    RETURN;
  END IF;
  RETURN QUERY SELECT true, v_row.state, 0;
END $function$
;

CREATE OR REPLACE FUNCTION public.purge_expired_data()
 RETURNS TABLE(t_name text, t_tenant uuid, t_deleted bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; d bigint;
BEGIN
  FOR r IN SELECT id FROM public.tenants LOOP
    WITH del AS (DELETE FROM public.ai_usage_events
       WHERE tenant_id = r.id AND created_at < now() - make_interval(days => public.effective_retention_days(r.id,'ai_usage_events'))
      RETURNING 1) SELECT count(*) INTO d FROM del;
    IF d > 0 THEN t_name := 'ai_usage_events'; t_tenant := r.id; t_deleted := d; RETURN NEXT; END IF;

    WITH del AS (DELETE FROM public.security_events
       WHERE tenant_id = r.id AND occurred_at < now() - make_interval(days => public.effective_retention_days(r.id,'security_events'))
      RETURNING 1) SELECT count(*) INTO d FROM del;
    IF d > 0 THEN t_name := 'security_events'; t_tenant := r.id; t_deleted := d; RETURN NEXT; END IF;

    WITH del AS (DELETE FROM public.recon_runs
       WHERE tenant_id = r.id AND started_at < now() - make_interval(days => public.effective_retention_days(r.id,'recon_runs'))
      RETURNING 1) SELECT count(*) INTO d FROM del;
    IF d > 0 THEN t_name := 'recon_runs'; t_tenant := r.id; t_deleted := d; RETURN NEXT; END IF;

    WITH del AS (DELETE FROM public.recon_exceptions
       WHERE tenant_id = r.id AND created_at < now() - make_interval(days => public.effective_retention_days(r.id,'recon_exceptions'))
      RETURNING 1) SELECT count(*) INTO d FROM del;
    IF d > 0 THEN t_name := 'recon_exceptions'; t_tenant := r.id; t_deleted := d; RETURN NEXT; END IF;

    WITH del AS (DELETE FROM public.recon_matches
       WHERE tenant_id = r.id AND created_at < now() - make_interval(days => public.effective_retention_days(r.id,'recon_matches'))
      RETURNING 1) SELECT count(*) INTO d FROM del;
    IF d > 0 THEN t_name := 'recon_matches'; t_tenant := r.id; t_deleted := d; RETURN NEXT; END IF;

    WITH del AS (DELETE FROM public.aidp_pages p USING public.aidp_documents dd
       WHERE p.document_id = dd.id AND dd.tenant_id = r.id
         AND p.created_at < now() - make_interval(days => public.effective_retention_days(r.id,'aidp_pages'))
      RETURNING 1) SELECT count(*) INTO d FROM del;
    IF d > 0 THEN t_name := 'aidp_pages'; t_tenant := r.id; t_deleted := d; RETURN NEXT; END IF;

    WITH del AS (DELETE FROM public.aidp_output_recon_invalidations
       WHERE tenant_id = r.id AND created_at < now() - make_interval(days => public.effective_retention_days(r.id,'aidp_output_recon_invalidations'))
      RETURNING 1) SELECT count(*) INTO d FROM del;
    IF d > 0 THEN t_name := 'aidp_output_recon_invalidations'; t_tenant := r.id; t_deleted := d; RETURN NEXT; END IF;
  END LOOP;

  WITH del AS (DELETE FROM public.email_send_log
     WHERE created_at < now() - make_interval(days => COALESCE((SELECT retention_days FROM public.retention_policies WHERE table_name='email_send_log'), 365))
    RETURNING 1) SELECT count(*) INTO d FROM del;
  IF d > 0 THEN t_name := 'email_send_log'; t_tenant := NULL; t_deleted := d; RETURN NEXT; END IF;

  RETURN;
END $function$
;

CREATE OR REPLACE FUNCTION public.dump_public_schema_ddl()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_out text;
BEGIN
  SELECT string_agg(ddl, E'\n\n' ORDER BY ord)
  INTO v_out
  FROM (
    SELECT 1 AS ord, '-- FVI schema dump generated ' || now()::text AS ddl
    UNION ALL
    SELECT 2, 'SET statement_timeout = 0;'
    UNION ALL
    SELECT 3, pg_catalog.pg_get_viewdef(v.oid, true)
    FROM pg_class v WHERE v.relkind = 'v' AND v.relnamespace =
      (SELECT oid FROM pg_namespace WHERE nspname = 'public')
    UNION ALL
    SELECT 4, pg_catalog.pg_get_functiondef(p.oid)
    FROM pg_proc p WHERE p.pronamespace =
      (SELECT oid FROM pg_namespace WHERE nspname = 'public')
      AND p.prokind = 'f'
  ) sub;
  RETURN COALESCE(v_out, '-- No schema objects found');
END $function$
;

CREATE OR REPLACE FUNCTION public.status_confirm_subscriber(_token text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE updated int;
BEGIN
  UPDATE public.status_subscribers
     SET confirmed_at = now()
   WHERE confirm_token_hash = sha256(convert_to(_token,'UTF8'))
     AND confirmed_at IS NULL;
  GET DIAGNOSTICS updated = ROW_COUNT;
  RETURN updated > 0;
END $function$
;

CREATE OR REPLACE FUNCTION public.status_subscribe(_email text, _component_keys text[], _confirm_token text, _unsub_token text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _bucket_key text;
  _window timestamptz := date_trunc('hour', now());
  _cur int;
BEGIN
  IF _email IS NULL OR length(_email) > 254
     OR _email !~* '^[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}$' THEN
    RAISE EXCEPTION 'invalid email';
  END IF;
  IF _confirm_token IS NULL OR length(_confirm_token) < 32
     OR _unsub_token IS NULL OR length(_unsub_token) < 32 THEN
    RAISE EXCEPTION 'invalid token';
  END IF;

  -- Rate-limit: max 3 subscription attempts per email per hour.
  _bucket_key := 'status_subscribe:' || lower(_email);
  INSERT INTO public.rate_limit_buckets(bucket_key, window_start, count)
  VALUES (_bucket_key, _window, 1)
  ON CONFLICT (bucket_key, window_start)
  DO UPDATE SET count = public.rate_limit_buckets.count + 1
  RETURNING count INTO _cur;
  IF _cur > 3 THEN
    RAISE EXCEPTION 'rate_limited' USING ERRCODE = '42901';
  END IF;

  INSERT INTO public.status_subscribers(
    email, component_keys, confirm_token_hash, unsubscribe_token_hash
  ) VALUES (
    lower(_email),
    COALESCE(_component_keys, '{}'::text[]),
    extensions.digest(convert_to(_confirm_token,'UTF8'),'sha256'),
    extensions.digest(convert_to(_unsub_token,'UTF8'),'sha256')
  )
  ON CONFLICT (email) DO NOTHING;
  RETURN FOUND;
END $function$
;

CREATE OR REPLACE FUNCTION public.status_unsubscribe(_token text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE deleted int;
BEGIN
  DELETE FROM public.status_subscribers
   WHERE unsubscribe_token_hash = sha256(convert_to(_token,'UTF8'));
  GET DIAGNOSTICS deleted = ROW_COUNT;
  RETURN deleted > 0;
END $function$
;

