$function$
;

CREATE OR REPLACE FUNCTION public.log_mkt_content_change(_entity_type text, _entity_key text, _action text, _actor_id uuid, _actor_email text, _before jsonb, _after jsonb, _summary text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _id uuid;
BEGIN
  INSERT INTO public.mkt_content_audit_log
    (entity_type, entity_key, action, actor_id, actor_email, before, after, summary)
  VALUES
    (_entity_type, _entity_key, _action, _actor_id, _actor_email, _before, _after, _summary)
