    AND (NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.access_mode IS DISTINCT FROM OLD.access_mode) THEN
    RAISE EXCEPTION 'schedule_scope_identity_immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$
;

