 SET search_path TO 'pg_catalog', 'private'
AS $function$ SELECT private.task_eod_snapshot(_tenant_id,_run_ids) $function$
;

CREATE OR REPLACE FUNCTION private.rs_resolve_ordinary_policy(_tenant uuid, _definition uuid, _business_date date, _pins jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid:=private.rs_actor(_tenant,_definition,'run');contract jsonb;s jsonb;pin jsonb;c jsonb;approved public.recon_definition_approved_versions%ROWTYPE;
 d public.recon_definitions%ROWTYPE;snapshot jsonb;configuration_sha text;authority text;declared jsonb;
 u public.workspace_data_source_uploads%ROWTYPE;pins jsonb:='[]';proofs jsonb:='[]';identity jsonb;v_policy jsonb;qualification jsonb;hash text;v_policy_id uuid;
BEGIN
 IF _business_date IS NULL OR _business_date::text !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'rs.explicit_business_date_required' USING ERRCODE='22023';END IF;
 SELECT * INTO d FROM public.recon_definitions WHERE id=_definition AND tenant_id=_tenant;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.current_configuration_required' USING ERRCODE='42501';END IF;
 approved:=private.recon_run_bound_approved_version(_tenant,_definition,actor);
 IF approved.id IS NOT NULL THEN
  contract:=public.read_recon_contract(_tenant,_definition,approved.id);authority:='native_approved_revision';
  IF contract->'approved' IS DISTINCT FROM 'true'::jsonb OR contract->'current_revision' IS DISTINCT FROM 'true'::jsonb
  OR contract->'contract_available' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'rs.current_approved_contract_required' USING ERRCODE='42501';END IF;
 ELSE
  -- Existing native helper permits these governed non-production configurations.
  -- Do not invent a checker, approval hash or historical revision for them.
  IF NOT ((d.environment='development' AND d.governance_state='development_draft')
   OR (d.environment IN('development','staging') AND d.governance_state='staging_copy')
   OR (d.access_mode='mapped_exact' AND d.governance_state='legacy_mapped'))
  THEN RAISE EXCEPTION 'rs.native_configuration_not_executable' USING ERRCODE='42501';END IF;
  snapshot:=private.recon_definition_config_snapshot(d);configuration_sha:=encode(sha256(convert_to(snapshot::text,'UTF8')),'hex');
  contract:=jsonb_build_object('sides',snapshot->'sides','input_contracts',private.rs_approved_rule_contracts(snapshot),
   'revision_id',NULL,'expected_definition_sha256',configuration_sha);authority:='native_current_configuration';
 END IF;
 IF _pins IS NOT NULL AND (jsonb_typeof(_pins) IS DISTINCT FROM 'array' OR jsonb_array_length(_pins)<>jsonb_array_length(contract->'sides')
 OR (SELECT count(DISTINCT x->>'side_id') FROM jsonb_array_elements(_pins) x)<>jsonb_array_length(_pins))
 THEN RAISE EXCEPTION 'rs.complete_distinct_pins_required' USING ERRCODE='22023';END IF;
 FOR s IN SELECT x.value FROM jsonb_array_elements(contract->'sides') x ORDER BY x.value->>'side_id' LOOP
  IF _pins IS NULL THEN pin:=jsonb_build_object('side_id',s->>'side_id','upload_id',s->>'upload_id');
  ELSE SELECT x.value INTO pin FROM jsonb_array_elements(_pins) x WHERE x.value->>'side_id'=s->>'side_id';END IF;
  IF pin->>'upload_id' IS NULL OR s->>'upload_id' IS NOT NULL AND s->>'upload_id' IS DISTINCT FROM pin->>'upload_id'
  THEN RAISE EXCEPTION 'rs.explicit_input_selection_required_no_latest_fallback' USING ERRCODE='PT409';END IF;
  IF private.data_source_child_allows(actor,_tenant,(s->>'data_source_id')::uuid,'view') IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'rs.current_source_denied' USING ERRCODE='42501';END IF;
  SELECT * INTO u FROM public.workspace_data_source_uploads WHERE id=(pin->>'upload_id')::uuid AND tenant_id=_tenant AND data_source_id=(s->>'data_source_id')::uuid;
  IF NOT FOUND OR jsonb_typeof(u.rows) IS DISTINCT FROM 'array' OR u.row_count<>jsonb_array_length(u.rows) OR u.row_count=0
  THEN RAISE EXCEPTION 'rs.exact_nonempty_input_required' USING ERRCODE='42501';END IF;
  IF s->>'upload_id' IS NULL AND (EXISTS(SELECT 1 FROM public.data_prep_prepared_datasets x WHERE x.tenant_id=_tenant AND x.upload_id=u.id)
   OR EXISTS(SELECT 1 FROM public.data_prep_pipelines p WHERE p.tenant_id=_tenant AND p.output_data_source_id=u.data_source_id))
  THEN RAISE EXCEPTION 'rs.prepared_source_requires_native_per_run_binding' USING ERRCODE='42501';END IF;
  SELECT x.value INTO c FROM jsonb_array_elements(contract->'input_contracts') x WHERE x.value->>'side_id'=s->>'side_id';
  IF authority='native_current_configuration' THEN
   declared:=private.rs_schema_profile(_tenant,(s->>'data_source_id')::uuid,coalesce(s->'column_mapping','{}'));
   c:=c||jsonb_build_object('provenance','configured_rule_contract','approval_bound',false,'source_declared_fields',coalesce(declared->'fields','[]'));
  END IF;
  IF c IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(u.rows) x WHERE private.rs_contract_row_allowed(x.value,c) IS DISTINCT FROM true)
  THEN RAISE EXCEPTION 'rs.approved_input_domain_refused' USING ERRCODE='22023';END IF;
  pins:=pins||jsonb_build_array(jsonb_build_object('side_id',s->>'side_id','upload_id',u.id));
  proofs:=proofs||jsonb_build_array(jsonb_build_object('side_id',s->>'side_id','data_source_id',u.data_source_id,'upload_id',u.id,
   'rows_sha256',encode(sha256(convert_to(u.rows::text,'UTF8')),'hex'),'arrival_at',u.created_at,'input_rows',u.row_count));
 END LOOP;
 identity:=jsonb_build_object('tenant_id',_tenant,'definition_id',_definition,'approved_revision_id',contract->>'revision_id',
  'configuration_sha256',contract->>'expected_definition_sha256','configuration_authority',authority,'business_date',_business_date,'pins',pins,'input_proofs',proofs,'cohort_mode','explicit_snapshot_selection','version','ordinary_snapshot_v1');
 hash:=encode(sha256(convert_to(identity::text,'UTF8')),'hex');v_policy_id:=substr(hash,1,32)::uuid;
 v_policy:=identity||jsonb_build_object('policy_id',v_policy_id,'version','ordinary_snapshot_v1','policy_kind','ordinary_native_snapshot',
  'date_basis','user_selected_business_date','as_of',_business_date::text||'T00:00:00Z','market_calendar_available',false,
  'feed_timing_available',false,'no_market_cutoff_inferred',true,'source_business_dates_inferred',false);
 qualification:=jsonb_build_object('state','native_qualified','kind','ordinary_native_snapshot','producer','resolve_recon_ordinary_cohort',
  'actor_id',actor,'approved_revision_id',contract->>'revision_id','configuration_authority',authority,'configuration_sha256',contract->>'expected_definition_sha256','identity_sha256',hash);
 INSERT INTO private.rs_policies(tenant_id,definition_id,policy_id,version,policy,qualification)
 VALUES(_tenant,_definition,v_policy_id,'ordinary_snapshot_v1',v_policy,qualification) ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT 1 FROM private.rs_policies p WHERE p.tenant_id=_tenant AND p.definition_id=_definition AND p.policy_id=v_policy_id
  AND p.version='ordinary_snapshot_v1' AND p.policy=v_policy) THEN RAISE EXCEPTION 'rs.immutable_cohort_policy_conflict' USING ERRCODE='PT409';END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant,'definition_id',_definition,'business_date',_business_date,'policy_id',v_policy_id,
  'policy_version','ordinary_snapshot_v1','pins',pins,'input_proofs',proofs,'expected_definition_sha256',contract->>'expected_definition_sha256',
  'approved_revision_id',contract->>'revision_id','configuration_authority',authority,'cohort_mode','explicit_snapshot_selection','market_calendar_available',false,'feed_timing_available',false);
END $function$
;

CREATE OR REPLACE FUNCTION public.get_workspace_dashboard_team_scope(_tenant_id uuid)
 RETURNS TABLE(team_scope_available boolean, definition_ids uuid[])
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_scope_available boolean;
BEGIN
  IF v_actor IS NULL OR _tenant_id IS NULL OR NOT EXISTS (
    SELECT 1
    FROM public.tenant_members member_row
    WHERE member_row.tenant_id = _tenant_id
      AND member_row.user_id = v_actor
      AND member_row.active = true
  ) THEN
    RAISE EXCEPTION 'Workspace dashboard team scope is unavailable'
      USING ERRCODE = '42501';
  END IF;

  -- Distinguish a caller with a mapped BU/group team from an authorized team
  -- whose current mapping has no reconciliation rows.
  SELECT
    EXISTS (
      SELECT 1
      FROM public.bu_user_assignments user_assignment
      JOIN public.business_units assigned_unit
        ON assigned_unit.id = user_assignment.bu_id
       AND assigned_unit.tenant_id = user_assignment.tenant_id
       AND NOT assigned_unit.is_archived
      WHERE user_assignment.tenant_id = _tenant_id
        AND user_assignment.user_id = v_actor
    )
    OR EXISTS (
      SELECT 1
      FROM public.tenant_group_members group_member
      JOIN public.tenant_groups group_row
        ON group_row.id = group_member.group_id
       AND group_row.tenant_id = _tenant_id
      JOIN public.bu_group_assignments group_assignment
        ON group_assignment.group_id = group_row.id
       AND group_assignment.tenant_id = _tenant_id
      JOIN public.business_units assigned_unit
        ON assigned_unit.id = group_assignment.bu_id
       AND assigned_unit.tenant_id = _tenant_id
       AND NOT assigned_unit.is_archived
      WHERE group_member.user_id = v_actor
    )
  INTO v_scope_available;

  RETURN QUERY
  SELECT
    v_scope_available,
    coalesce(array_agg(DISTINCT definition.id ORDER BY definition.id), ARRAY[]::uuid[])
  FROM public.recon_definitions definition
  WHERE definition.tenant_id = _tenant_id
    AND definition.access_mode = 'mapped_exact'
    AND private.recon_authoritative_access_decision(definition.id, 'view')
    AND (
      EXISTS (
        SELECT 1
        FROM public.recon_definition_business_units owner_bu
        JOIN public.business_units owner_unit
          ON owner_unit.id = owner_bu.bu_id
         AND owner_unit.tenant_id = owner_bu.tenant_id
         AND NOT owner_unit.is_archived
        JOIN public.recon_definition_bu_grants grant_row
          ON grant_row.tenant_id = owner_bu.tenant_id
         AND grant_row.recon_id = owner_bu.recon_id
         AND grant_row.bu_id = owner_bu.bu_id
        JOIN public.bu_user_assignments user_assignment
          ON user_assignment.tenant_id = owner_bu.tenant_id
         AND user_assignment.user_id = v_actor
        JOIN public.business_units assigned_unit
          ON assigned_unit.id = user_assignment.bu_id
         AND assigned_unit.tenant_id = user_assignment.tenant_id
         AND NOT assigned_unit.is_archived
        WHERE owner_bu.tenant_id = _tenant_id
          AND owner_bu.recon_id = definition.id
          AND grant_row.action IN ('view', 'read')
          AND grant_row.principal_type = 'user'
          AND grant_row.principal_id = v_actor
          AND (
            owner_unit.id = assigned_unit.id
            OR (user_assignment.inherit_descendants AND owner_unit.path <@ assigned_unit.path)
          )
      )
      OR EXISTS (
        SELECT 1
        FROM public.recon_definition_business_units owner_bu
        JOIN public.business_units owner_unit
          ON owner_unit.id = owner_bu.bu_id
         AND owner_unit.tenant_id = owner_bu.tenant_id
         AND NOT owner_unit.is_archived
        JOIN public.recon_definition_bu_grants grant_row
          ON grant_row.tenant_id = owner_bu.tenant_id
         AND grant_row.recon_id = owner_bu.recon_id
         AND grant_row.bu_id = owner_bu.bu_id
        JOIN public.tenant_groups grant_group
          ON grant_group.id = grant_row.principal_id
         AND grant_group.tenant_id = _tenant_id
        JOIN public.tenant_group_members group_member
          ON group_member.group_id = grant_group.id
         AND group_member.user_id = v_actor
        JOIN public.bu_group_assignments group_assignment
          ON group_assignment.group_id = grant_group.id
         AND group_assignment.tenant_id = _tenant_id
        JOIN public.business_units assigned_unit
          ON assigned_unit.id = group_assignment.bu_id
         AND assigned_unit.tenant_id = group_assignment.tenant_id
         AND NOT assigned_unit.is_archived
        WHERE owner_bu.tenant_id = _tenant_id
          AND owner_bu.recon_id = definition.id
          AND grant_row.action IN ('view', 'read')
          AND grant_row.principal_type = 'group'
          AND (
            owner_unit.id = assigned_unit.id
            OR (group_assignment.inherit_descendants AND owner_unit.path <@ assigned_unit.path)
          )
      )
    );
END
$function$
;

CREATE OR REPLACE FUNCTION public.exception_assignment_member_allowed(_tenant_id uuid, _exception_id uuid, _recipient uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE definition uuid; actor uuid:=auth.uid();
BEGIN
 IF actor IS NULL OR NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=actor AND active) OR NOT(public.has_tenant_role(actor,_tenant_id,'tenant_admin') OR public.user_has_permission(actor,_tenant_id,'break.assign',NULL)) THEN RETURN false; END IF;
 SELECT r.definition_id INTO definition FROM public.recon_exceptions e JOIN public.recon_runs r ON r.id=e.run_id AND r.tenant_id=e.tenant_id WHERE e.id=_exception_id AND e.tenant_id=_tenant_id;
 IF NOT FOUND OR NOT public.recon_authoritative_access_decision(definition,'edit') THEN RETURN false; END IF;
 RETURN EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=_recipient AND active) AND private.recon_authoritative_access_decision_as(_recipient,definition,'view');
END $function$
;

CREATE OR REPLACE FUNCTION public.apply_exception_workflow_atomic(_tenant_id uuid, _exception_ids uuid[], _patch jsonb, _comment text DEFAULT NULL::text, _internal boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE actor uuid:=auth.uid(); target uuid; prior public.recon_exceptions%ROWTYPE; next_row public.recon_exceptions%ROWTYPE; definition uuid; capability text; comment_id uuid; changed_ids uuid[]:=ARRAY[]::uuid[]; actual_changes integer:=0;
BEGIN
 IF actor IS NULL OR _exception_ids IS NULL OR cardinality(_exception_ids) NOT BETWEEN 1 AND 500 OR (SELECT count(DISTINCT id) FROM unnest(_exception_ids) ids(id))<>cardinality(_exception_ids) THEN RAISE EXCEPTION 'Unique selected cases required' USING ERRCODE='42501'; END IF;
 IF jsonb_typeof(_patch) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(_patch) k WHERE k NOT IN ('status','lifecycle_state','priority','assignee','due_date','root_cause','tags','labels','review_state','resolution_note','close_reason','reopen_reason')) THEN RAISE EXCEPTION 'Unsupported exception update'; END IF;
 IF _comment IS NOT NULL AND (length(btrim(_comment)) NOT BETWEEN 1 AND 4000 OR cardinality(_exception_ids)<>1) THEN RAISE EXCEPTION 'One case and a comment of 1 to 4000 characters required'; END IF;
 IF _patch='{}'::jsonb AND _comment IS NULL THEN RAISE EXCEPTION 'An action is required'; END IF;
 capability:=CASE WHEN _patch ? 'assignee' THEN 'break.assign' WHEN _patch->>'status'='open' OR _patch ? 'reopen_reason' THEN 'break.reopen' WHEN _patch->>'status' IN ('resolved','wont_fix') OR _patch->>'lifecycle_state'='resolved' THEN 'break.resolve' ELSE 'break.update' END;
 IF NOT EXISTS(SELECT 1 FROM public.tenant_members m WHERE m.tenant_id=_tenant_id AND m.user_id=actor AND m.active)
   OR NOT(public.has_tenant_role(actor,_tenant_id,'tenant_admin') OR public.user_has_permission(actor,_tenant_id,capability,NULL)) THEN RAISE EXCEPTION 'Current action permission required' USING ERRCODE='42501'; END IF;
 FOR target IN SELECT id FROM unnest(_exception_ids) ids(id) ORDER BY id LOOP
  SELECT * INTO prior FROM public.recon_exceptions WHERE id=target AND tenant_id=_tenant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Selected case unavailable' USING ERRCODE='42501'; END IF;
  SELECT r.definition_id INTO definition FROM public.recon_runs r WHERE r.id=prior.run_id AND r.tenant_id=_tenant_id;
  IF NOT FOUND OR NOT public.recon_authoritative_access_decision(definition,'edit') THEN RAISE EXCEPTION 'Current reconciliation edit access required' USING ERRCODE='42501'; END IF;
  next_row:=jsonb_populate_record(prior,_patch);
  IF _patch ? 'status' THEN
   next_row.lifecycle_state:=CASE next_row.status WHEN 'open' THEN 'new' WHEN 'investigating' THEN 'investigating' WHEN 'resolved' THEN 'resolved' WHEN 'wont_fix' THEN 'resolved' ELSE NULL END;
  ELSIF _patch ? 'lifecycle_state' THEN
   next_row.status:=CASE next_row.lifecycle_state WHEN 'resolved' THEN 'resolved' WHEN 'investigating' THEN 'investigating' ELSE 'open' END;
  END IF;
  IF next_row.lifecycle_state IS NULL OR next_row.lifecycle_state NOT IN ('new','assigned','investigating','pending_counterparty','resolved','written_off') OR next_row.status NOT IN ('open','investigating','resolved','wont_fix') THEN RAISE EXCEPTION 'Invalid transition' USING ERRCODE='23514'; END IF;
  IF prior.lifecycle_state='written_off' AND (next_row.lifecycle_state<>prior.lifecycle_state OR next_row.status<>prior.status OR _patch ? 'assignee') THEN RAISE EXCEPTION 'Governed write-off workflow required' USING ERRCODE='23514'; END IF;
  IF prior.status IN ('resolved','wont_fix') AND next_row.status NOT IN ('resolved','wont_fix') AND length(coalesce(_patch->>'reopen_reason',''))<3 THEN RAISE EXCEPTION 'Reopen reason required' USING ERRCODE='23514'; END IF;
  IF _patch ? 'assignee' THEN
   IF prior.status IN ('resolved','wont_fix') THEN RAISE EXCEPTION 'Reopen the case before assignment' USING ERRCODE='23514'; END IF;
   IF next_row.assignee IS NOT NULL AND NOT public.exception_assignment_member_allowed(_tenant_id,prior.id,next_row.assignee) THEN RAISE EXCEPTION 'Assignee must have current scoped access' USING ERRCODE='42501'; END IF;
   IF next_row.assignee IS DISTINCT FROM prior.assignee THEN
   next_row.assigned_by:=CASE WHEN next_row.assignee IS NULL THEN NULL ELSE actor END; next_row.assigned_at:=CASE WHEN next_row.assignee IS NULL THEN NULL ELSE now() END;
   IF prior.lifecycle_state IN ('new','assigned') THEN next_row.lifecycle_state:=CASE WHEN next_row.assignee IS NULL THEN 'new' ELSE 'assigned' END; END IF;
   END IF;
  END IF;
  IF next_row.lifecycle_state='assigned' AND next_row.assignee IS NULL THEN RAISE EXCEPTION 'Select a verified assignee before moving to Assigned' USING ERRCODE='23514'; END IF;
  IF next_row.status IN ('resolved','wont_fix') AND (prior.status NOT IN ('resolved','wont_fix') OR next_row.status<>prior.status) THEN next_row.resolved_by:=actor; next_row.resolved_at:=now(); next_row.closed_at:=now();
  ELSIF prior.status IN ('resolved','wont_fix') AND next_row.status NOT IN ('resolved','wont_fix') THEN next_row.resolved_by:=NULL; next_row.resolved_at:=NULL; next_row.closed_at:=NULL; next_row.reopened_at:=now(); END IF;
  IF to_jsonb(next_row)=to_jsonb(prior) AND _comment IS NULL THEN changed_ids:=array_append(changed_ids,prior.id);CONTINUE;END IF;
  IF _patch<>'{}'::jsonb THEN
   UPDATE public.recon_exceptions SET status=next_row.status,lifecycle_state=next_row.lifecycle_state,priority=next_row.priority,assignee=next_row.assignee,assigned_by=next_row.assigned_by,assigned_at=next_row.assigned_at,due_date=next_row.due_date,root_cause=next_row.root_cause,tags=next_row.tags,labels=next_row.labels,review_state=next_row.review_state,resolution_note=next_row.resolution_note,close_reason=next_row.close_reason,reopen_reason=next_row.reopen_reason,closed_at=next_row.closed_at,reopened_at=next_row.reopened_at,resolved_by=next_row.resolved_by,resolved_at=next_row.resolved_at WHERE id=prior.id AND tenant_id=_tenant_id;
   IF NOT FOUND THEN RAISE EXCEPTION 'Selected case was not updated' USING ERRCODE='42501'; END IF;
  END IF;
  IF _comment IS NOT NULL THEN INSERT INTO public.break_comments(tenant_id,exception_id,author_id,body,internal) VALUES(_tenant_id,prior.id,actor,btrim(_comment),_internal) RETURNING id INTO comment_id; END IF;
  INSERT INTO public.recon_exception_transitions(tenant_id,exception_id,actor_user_id,from_state,to_state,transition_type,reason,context) VALUES(_tenant_id,prior.id,actor,prior.lifecycle_state,next_row.lifecycle_state,CASE WHEN _comment IS NULL THEN 'workflow_update' ELSE 'comment' END,coalesce(_patch->>'reopen_reason',_patch->>'close_reason',_patch->>'resolution_note'),jsonb_build_object('run_id',prior.run_id,'patch',_patch));
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context) VALUES(actor,_tenant_id,'workspace',CASE WHEN _comment IS NULL THEN 'exception.workflow_update' ELSE 'break.comment.create' END,'recon_exception',prior.id::text,jsonb_build_object('run_id',prior.run_id,'patch',_patch,'comment_id',comment_id));
  changed_ids:=array_append(changed_ids,prior.id);actual_changes:=actual_changes+1;
 END LOOP;
 RETURN jsonb_build_object('ok',true,'ids',to_jsonb(changed_ids),'count',cardinality(changed_ids),'comment_id',comment_id,'changed_count',actual_changes,'noop_count',cardinality(changed_ids)-actual_changes);
END $function$
;

CREATE OR REPLACE FUNCTION public.save_nrl_rule_atomic(_tenant_id uuid, _definition_id uuid, _rule_id uuid, _config jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE actor uuid:=auth.uid(); rule_id uuid; fields public.recon_nrl_rules%ROWTYPE;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.recon_definitions d WHERE d.id=_definition_id AND d.tenant_id=_tenant_id) OR NOT public.recon_authoritative_access_decision(_definition_id,'edit') THEN RAISE EXCEPTION 'Current reconciliation edit access required' USING ERRCODE='42501'; END IF;
 fields:=jsonb_populate_record(NULL::public.recon_nrl_rules,_config);
 IF fields.name IS NULL OR length(fields.name) NOT BETWEEN 2 AND 120 OR fields.nrl_source IS NULL OR jsonb_typeof(fields.compiled_rule)<>'object' OR fields.pass_order NOT BETWEEN 1 AND 50 OR fields.enabled IS NULL THEN RAISE EXCEPTION 'Invalid NRL draft'; END IF;
 IF _rule_id IS NULL THEN
  INSERT INTO public.recon_nrl_rules(tenant_id,definition_id,name,description,nrl_source,compiled_rule,pass_order,enabled,validation_errors,created_by) VALUES(_tenant_id,_definition_id,fields.name,fields.description,fields.nrl_source,fields.compiled_rule,fields.pass_order,fields.enabled,'[]',actor) RETURNING id INTO rule_id;
 ELSE
  UPDATE public.recon_nrl_rules SET name=fields.name,description=CASE WHEN _config ? 'description' THEN fields.description ELSE description END,nrl_source=fields.nrl_source,compiled_rule=fields.compiled_rule,pass_order=fields.pass_order,enabled=fields.enabled,validation_errors='[]' WHERE id=_rule_id AND tenant_id=_tenant_id AND definition_id=_definition_id RETURNING id INTO rule_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Rule not in selected reconciliation' USING ERRCODE='42501'; END IF;
 END IF;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context) VALUES(actor,_tenant_id,'workspace','nrl.draft.saved','recon_nrl_rule',rule_id::text,jsonb_build_object('definition_id',_definition_id,'pass_order',fields.pass_order,'source_sha256',encode(extensions.digest(fields.nrl_source,'sha256'),'hex')));
 RETURN rule_id;
END $function$
;

CREATE OR REPLACE FUNCTION public.list_recon_ordinary_inputs(_tenant_id uuid, _definition_id uuid, _side_id text, _page integer DEFAULT 0, _page_size integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid:=private.rs_actor(_tenant_id,_definition_id,'run');d public.recon_definitions%ROWTYPE;s jsonb;items jsonb;total bigint;
BEGIN
 IF _page NOT BETWEEN 0 AND 1000000 OR _page_size NOT BETWEEN 1 AND 100 OR _page IS NULL OR _page_size IS NULL
 THEN RAISE EXCEPTION 'rs.finite_input_page_required' USING ERRCODE='22023';END IF;
 SELECT * INTO d FROM public.recon_definitions WHERE id=_definition_id AND tenant_id=_tenant_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.visible_definition_required' USING ERRCODE='42501';END IF;
 PERFORM private.recon_run_bound_approved_version(_tenant_id,_definition_id,actor);
 SELECT x.value INTO s FROM jsonb_array_elements(d.sides) x WHERE x.value->>'side_id'=_side_id;
 IF s IS NULL OR private.data_source_child_allows(actor,_tenant_id,(s->>'data_source_id')::uuid,'view') IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'rs.exact_configured_source_required' USING ERRCODE='42501';END IF;
 SELECT count(*) INTO total FROM public.workspace_data_source_uploads u WHERE u.tenant_id=_tenant_id AND u.data_source_id=(s->>'data_source_id')::uuid
 AND (s->>'upload_id' IS NULL OR u.id::text=s->>'upload_id');
 SELECT coalesce(jsonb_agg(jsonb_build_object('upload_id',u.id,'data_source_id',u.data_source_id,'arrival_at',u.created_at,'row_count',u.row_count,
  'fixed_approved_or_configured_pin',s->>'upload_id' IS NOT NULL) ORDER BY u.created_at DESC,u.id DESC),'[]') INTO items
 FROM (SELECT u.id,u.data_source_id,u.created_at,u.row_count FROM public.workspace_data_source_uploads u WHERE u.tenant_id=_tenant_id
  AND u.data_source_id=(s->>'data_source_id')::uuid AND (s->>'upload_id' IS NULL OR u.id::text=s->>'upload_id') ORDER BY u.created_at DESC,u.id DESC
  OFFSET _page*_page_size LIMIT _page_size) u;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'definition_id',_definition_id,'side_id',_side_id,
  'input_options',items,'total',total::text,'page',_page,'page_size',_page_size,'has_next',((_page::bigint+1)*_page_size)<total,
  'automatic_latest_selection',false,'original_source_rows_returned',false);
END $function$
;

CREATE OR REPLACE FUNCTION public.review_proposed_match_scoped(_tenant_id uuid, _match_id uuid, _decision text, _note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE proposal public.proposed_matches%ROWTYPE; run public.recon_runs%ROWTYPE; actor uuid:=auth.uid();
BEGIN
 SELECT * INTO proposal FROM public.proposed_matches WHERE id=_match_id AND tenant_id=_tenant_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Proposal unavailable in current scope' USING ERRCODE='42501'; END IF;
 SELECT * INTO run FROM public.recon_runs WHERE id=proposal.run_id AND tenant_id=_tenant_id;
 IF NOT FOUND OR proposal.definition_id IS DISTINCT FROM run.definition_id OR NOT public.recon_authoritative_access_decision(run.definition_id,'approve') THEN RAISE EXCEPTION 'Current scoped approval required' USING ERRCODE='42501'; END IF;
 IF run.run_by IS NULL OR run.run_by=actor THEN RAISE EXCEPTION 'Independent reviewer and known run provenance required' USING ERRCODE='42501'; END IF;
 IF _decision='accepted' AND (jsonb_typeof(proposal.members)<>'object' OR NOT EXISTS(SELECT 1 FROM jsonb_each(proposal.members)) OR EXISTS(SELECT 1 FROM jsonb_each(proposal.members) WHERE key NOT IN ('A','B','C') OR jsonb_typeof(value)<>'array' OR value='[]')) THEN RAISE EXCEPTION 'Source members unavailable; use governed manual matching'; END IF;
 RETURN public.review_proposed_match_atomic(_tenant_id,_match_id,_decision,_note);
END $function$
;

CREATE OR REPLACE FUNCTION private.rs_prior_ordinary_policy(_tenant uuid, _definition uuid, _business_date date, _pins jsonb, _key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid:=private.rs_actor(_tenant,_definition,'run');q private.rs_requests%ROWTYPE;p jsonb;normalized jsonb;
BEGIN
 SELECT * INTO q FROM private.rs_requests WHERE tenant_id=_tenant AND definition_id=_definition AND actor_id=actor AND request_key=_key;
 IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT policy INTO p FROM private.rs_policies WHERE tenant_id=_tenant AND definition_id=_definition AND policy_id=(q.intent->>'policy_id')::uuid AND version=q.intent->>'policy_version';
 IF _pins IS NOT NULL THEN SELECT jsonb_agg(x.value ORDER BY x.value->>'side_id') INTO normalized FROM jsonb_array_elements(_pins) x;END IF;
 IF p->>'policy_kind' IS DISTINCT FROM 'ordinary_native_snapshot' OR p->>'business_date' IS DISTINCT FROM _business_date::text
 OR _pins IS NOT NULL AND normalized IS DISTINCT FROM p->'pins' THEN RAISE EXCEPTION 'rs.request_key_conflict' USING ERRCODE='PT409';END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant,'definition_id',_definition,'business_date',p->>'business_date',
  'policy_id',p->>'policy_id','policy_version',p->>'version','pins',p->'pins','input_proofs',p->'input_proofs',
  'expected_definition_sha256',p->>'configuration_sha256','approved_revision_id',p->>'approved_revision_id','configuration_authority',p->>'configuration_authority',
  'cohort_mode','explicit_snapshot_selection','market_calendar_available',false,'feed_timing_available',false,'replayed_policy',true);
END $function$
;

CREATE OR REPLACE FUNCTION public.review_proposed_matches_scoped(_tenant_id uuid, _match_ids uuid[], _decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE item uuid; n integer:=0;
BEGIN
 IF _match_ids IS NULL OR cardinality(_match_ids) NOT BETWEEN 1 AND 100 OR (SELECT count(DISTINCT id) FROM unnest(_match_ids) x(id))<>cardinality(_match_ids) THEN RAISE EXCEPTION 'Select 1 to 100 distinct proposals'; END IF;
 FOR item IN SELECT id FROM unnest(_match_ids) x(id) ORDER BY id LOOP PERFORM public.review_proposed_match_scoped(_tenant_id,item,_decision,NULL);n:=n+1; END LOOP;
 RETURN jsonb_build_object('ok',true,'count',n);
END $function$
;

CREATE OR REPLACE FUNCTION public.resolve_recon_ordinary_cohort(_tenant_id uuid, _definition_id uuid, _business_date date, _pins jsonb, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE result jsonb;p jsonb;
BEGIN
 PERFORM private.rs_actor(_tenant_id,_definition_id,'run');
 PERFORM 1 FROM public.recon_definitions WHERE id=_definition_id AND tenant_id=_tenant_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.visible_definition_required' USING ERRCODE='42501';END IF;
 IF _request_key IS NULL THEN RAISE EXCEPTION 'rs.explicit_request_key_required' USING ERRCODE='22023';END IF;
 result:=private.rs_prior_ordinary_policy(_tenant_id,_definition_id,_business_date,_pins,_request_key);
 IF result IS NOT NULL THEN RETURN result;END IF;
 result:=private.rs_resolve_ordinary_policy(_tenant_id,_definition_id,_business_date,_pins);
 FOR p IN SELECT x.value FROM jsonb_array_elements(result->'input_proofs') x LOOP
  PERFORM 1 FROM public.workspace_data_sources WHERE id=(p->>'data_source_id')::uuid AND tenant_id=_tenant_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'rs.visible_source_required' USING ERRCODE='42501';END IF;
  PERFORM 1 FROM public.workspace_data_source_uploads WHERE id=(p->>'upload_id')::uuid AND tenant_id=_tenant_id AND data_source_id=(p->>'data_source_id')::uuid;
  IF NOT FOUND THEN RAISE EXCEPTION 'rs.visible_exact_upload_required' USING ERRCODE='42501';END IF;
 END LOOP;
 RETURN result;
END $function$
;

CREATE OR REPLACE FUNCTION public.request_task_eod_signoff_atomic(_tenant_id uuid, _period date, _run_ids uuid[], _note text, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE actor uuid:=auth.uid(); snapshot jsonb; old public.eod_signoffs%ROWTYPE; new_id uuid; input_hash text; ids uuid[];
BEGIN
 IF actor IS NULL OR _request_key IS NULL OR _period IS NULL OR NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=actor AND active AND role::text IN ('tenant_admin','tenant_analyst')) THEN RAISE EXCEPTION 'Active preparer required' USING ERRCODE='42501'; END IF;
 SELECT array_agg(x ORDER BY x) INTO ids FROM (SELECT DISTINCT unnest(_run_ids) x) s;
 IF ids IS NULL OR cardinality(ids) NOT BETWEEN 1 AND 100 OR cardinality(ids)<>cardinality(_run_ids) OR array_position(ids,NULL) IS NOT NULL OR (SELECT count(*) FROM public.recon_runs WHERE tenant_id=_tenant_id AND id=ANY(ids))<>cardinality(ids) OR EXISTS(SELECT 1 FROM public.recon_runs WHERE tenant_id=_tenant_id AND id=ANY(ids) AND NOT public.recon_authoritative_access_decision(definition_id,'view')) THEN RAISE EXCEPTION 'Current retained Run scope required' USING ERRCODE='42501'; END IF;
 input_hash:=encode(extensions.digest(jsonb_build_object('period',_period,'runs',ids,'note',coalesce(_note,''))::text,'sha256'),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended(_tenant_id::text||':'||actor::text||':'||_request_key::text,0));
 SELECT * INTO old FROM public.eod_signoffs WHERE tenant_id=_tenant_id AND prepared_by=actor AND request_key=_request_key FOR UPDATE;
 IF FOUND THEN IF old.request_hash IS DISTINCT FROM input_hash THEN RAISE EXCEPTION 'Request key changed' USING ERRCODE='22023'; END IF; RETURN jsonb_build_object('id',old.id,'replayed',true); END IF;
 PERFORM 1 FROM public.recon_runs WHERE tenant_id=_tenant_id AND id=ANY(ids) ORDER BY id FOR SHARE;
 snapshot:=private.task_eod_snapshot(_tenant_id,_run_ids);
 IF EXISTS(SELECT 1 FROM public.recon_runs WHERE tenant_id=_tenant_id AND id=ANY(ids) AND started_at>=((_period+1)::timestamp AT TIME ZONE 'UTC')) THEN RAISE EXCEPTION 'Selected Run is after the closing date' USING ERRCODE='22023'; END IF;
 IF coalesce(length(_note),0)>2000 THEN RAISE EXCEPTION 'Closing note is too long' USING ERRCODE='22023'; END IF;
 IF NOT (snapshot->'checks'->>'manual_reviews_clear')::boolean OR (((snapshot->>'open_exceptions')::int+(snapshot->>'waived_exceptions')::int)>0 AND length(btrim(coalesce(_note,'')))<10) THEN RAISE EXCEPTION 'Complete manual reviews and explain open exceptions' USING ERRCODE='22023'; END IF;
 INSERT INTO public.eod_signoffs(tenant_id,period_date,scope,status,prepared_by,prepared_at,metrics,note,request_key,request_hash,retained_run_refs,checks_snapshot,scope_snapshot_hash)
 VALUES(_tenant_id,_period,'selected_runs','prepared',actor,now(),jsonb_build_object('open_at_signoff',(snapshot->>'open_exceptions')::int,'waived_at_signoff',(snapshot->>'waived_exceptions')::int,'run_count',(snapshot->>'run_count')::int),_note,_request_key,input_hash,snapshot->'run_refs',snapshot->'checks',snapshot->>'snapshot_hash') RETURNING id INTO new_id;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context) VALUES(actor,_tenant_id,'workspace','eod.prepare','eod_signoffs',new_id::text,jsonb_build_object('period',_period,'run_refs',snapshot->'run_refs','checks',snapshot->'checks','scope_hash',snapshot->>'snapshot_hash','request_key',_request_key));
 RETURN jsonb_build_object('id',new_id,'replayed',false);
END $function$
;

CREATE OR REPLACE FUNCTION private.ticket_message_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE t public.support_tickets%ROWTYPE; actor uuid:=auth.uid(); manager boolean;
BEGIN
 SELECT * INTO t FROM public.support_tickets WHERE id=NEW.ticket_id FOR UPDATE;
 PERFORM id FROM public.tenant_members WHERE user_id=actor AND tenant_id=t.tenant_id FOR SHARE;
 manager:=private.ticket_manager(actor,t.tenant_id);
 IF actor IS NULL OR t.id IS NULL OR NEW.author_id<>actor OR
    NOT (manager OR (private.ticket_active_member(actor,t.tenant_id) AND (t.created_by=actor OR private.ticket_responder(actor,t.tenant_id)))) OR
    (NEW.internal_note AND NOT manager) THEN RAISE EXCEPTION 'Current ticket reply permission required' USING ERRCODE='42501'; END IF;
 IF length(NEW.body) NOT BETWEEN 1 AND 50000 THEN RAISE EXCEPTION 'Bounded ticket message required' USING ERRCODE='22023'; END IF;
 NEW.created_at:=statement_timestamp();
 RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.apply_nrl_rule_to_draft_atomic(_tenant_id uuid, _definition_id uuid, _rule_id uuid, _compiled jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE def public.recon_definitions%ROWTYPE; saved public.recon_nrl_rules%ROWTYPE; rule jsonb; fields jsonb; ref jsonb; binding jsonb; cols jsonb;
BEGIN
 SELECT * INTO def FROM public.recon_definitions WHERE id=_definition_id AND tenant_id=_tenant_id FOR UPDATE;
 IF NOT FOUND OR NOT public.recon_authoritative_access_decision(def.id,'edit') THEN RAISE EXCEPTION 'Current edit scope required' USING ERRCODE='42501'; END IF;
 IF def.environment NOT IN ('development','staging') OR def.governance_state NOT IN ('development_draft','staging_copy') THEN RAISE EXCEPTION 'Governed editable copy required' USING ERRCODE='42501'; END IF;
 SELECT * INTO saved FROM public.recon_nrl_rules WHERE id=_rule_id AND tenant_id=_tenant_id AND definition_id=def.id AND enabled;
 IF NOT FOUND OR saved.compiled_rule IS DISTINCT FROM _compiled OR _compiled->>'kind'<>'match' OR _compiled ? 'lookup' THEN RAISE EXCEPTION 'Saved executable rule preimage changed'; END IF;
 FOR ref IN SELECT value FROM jsonb_array_elements(jsonb_build_array(_compiled#>'{match,left}',_compiled#>'{match,right}')||coalesce((SELECT jsonb_agg(x) FROM (SELECT value->'left' x FROM jsonb_array_elements(coalesce(_compiled->'where','[]')) UNION ALL SELECT value->'right' FROM jsonb_array_elements(coalesce(_compiled->'where','[]')) WHERE jsonb_typeof(value->'right')='object') refs),'[]')) LOOP
  SELECT value INTO binding FROM jsonb_array_elements(def.sides) WHERE value->>'side_id'=ref->>'side';
  IF NOT FOUND THEN RAISE EXCEPTION 'Rule side not bound'; END IF;
  SELECT to_jsonb(u.columns) INTO cols FROM public.workspace_data_source_uploads u WHERE u.tenant_id=_tenant_id AND u.data_source_id=(binding->>'data_source_id')::uuid AND (binding->>'upload_id' IS NULL OR u.id=(binding->>'upload_id')::uuid) ORDER BY u.created_at DESC,u.id DESC LIMIT 1;
  IF cols IS NULL OR jsonb_typeof(cols)<>'array' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(cols) c WHERE (jsonb_typeof(c)='string' AND c#>>'{}'=ref->>'column') OR c->>'name'=ref->>'column') THEN RAISE EXCEPTION 'Current source field binding unavailable'; END IF;
 END LOOP;
 fields:=jsonb_build_object(_compiled#>>'{match,left,side}',_compiled#>>'{match,left,column}',_compiled#>>'{match,right,side}',_compiled#>>'{match,right,column}');
 rule:=jsonb_build_object('id','nrl:'||saved.id::text,'kind','nrl_rule','description',saved.name,'fields',fields,'params',jsonb_build_object('nrl_rule',_compiled));
 UPDATE public.recon_definitions SET rules=coalesce((SELECT jsonb_agg(value) FROM jsonb_array_elements(def.rules) WHERE value->>'id'<>'nrl:'||saved.id::text),'[]'::jsonb)||jsonb_build_array(rule) WHERE id=def.id AND tenant_id=_tenant_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Definition not updated' USING ERRCODE='42501'; END IF;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context) VALUES(auth.uid(),_tenant_id,'workspace','nrl.draft.applied','recon_definition',def.id::text,jsonb_build_object('rule_id',saved.id,'pass',saved.pass_order));
 RETURN jsonb_build_object('ok',true,'definition_id',def.id);
END $function$
;

CREATE OR REPLACE FUNCTION public.disable_exception_assignment_rule(_tenant_id uuid, _rule_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE row_id uuid;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=auth.uid() AND active AND role='tenant_admin') THEN RAISE EXCEPTION 'Active tenant administrator required' USING ERRCODE='42501';END IF;
 UPDATE public.exception_assignment_rules SET enabled=false,updated_at=now() WHERE id=_rule_id AND tenant_id=_tenant_id RETURNING id INTO row_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Assignment rule unavailable' USING ERRCODE='42501';END IF;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context) VALUES(auth.uid(),_tenant_id,'tenant','assignment_rule.disabled','exception_assignment_rule',row_id::text,'{"history_retained":true}');
 RETURN jsonb_build_object('ok',true,'id',row_id,'enabled',false);
END $function$
;

CREATE OR REPLACE FUNCTION private.manual_match_group_evidence(_tenant uuid, _run uuid, _exceptions uuid[], _action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE r public.recon_runs%ROWTYPE; d public.recon_definitions%ROWTYPE; e record; member_map jsonb; ids uuid[]; expected integer; source_json jsonb; cardinality_text text;
BEGIN
 IF auth.uid() IS NULL OR _exceptions IS NULL OR cardinality(_exceptions) NOT BETWEEN 1 AND 100 OR array_position(_exceptions,NULL) IS NOT NULL THEN RAISE EXCEPTION 'Select current exception groups' USING ERRCODE='22023'; END IF;
 SELECT array_agg(x ORDER BY x) INTO ids FROM (SELECT DISTINCT unnest(_exceptions) x) s;
 IF cardinality(ids)<>cardinality(_exceptions) THEN RAISE EXCEPTION 'Duplicate exception group' USING ERRCODE='22023'; END IF;
 SELECT * INTO r FROM public.recon_runs WHERE id=_run AND tenant_id=_tenant;
 SELECT * INTO d FROM public.recon_definitions WHERE id=r.definition_id AND tenant_id=_tenant;
 IF r.id IS NULL OR d.id IS NULL OR r.status::text<>'completed' OR NOT public.recon_authoritative_access_decision(d.id,_action) THEN RAISE EXCEPTION 'Completed Run access required' USING ERRCODE='42501'; END IF;
 expected:=CASE d.recon_type::text WHEN 'two_sided' THEN 2 WHEN 'three_sided' THEN 3 ELSE 0 END;
 IF expected=0 THEN RAISE EXCEPTION 'Manual matching needs two or three sources' USING ERRCODE='22023'; END IF;
 IF (SELECT count(*) FROM public.recon_exceptions WHERE tenant_id=_tenant AND run_id=_run AND id=ANY(ids) AND status::text IN ('open','investigating'))<>cardinality(ids) THEN RAISE EXCEPTION 'Exception group is unavailable or already resolved' USING ERRCODE='42501'; END IF;
 FOR e IN SELECT payload FROM public.recon_exceptions WHERE tenant_id=_tenant AND run_id=_run AND id=ANY(ids) LOOP
  IF jsonb_typeof(e.payload->'members') IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_each(e.payload->'members') m WHERE m.key NOT IN ('SOURCE_A','SOURCE_B','SOURCE_C') OR jsonb_typeof(m.value)<>'array') THEN RAISE EXCEPTION 'Persisted source members unavailable' USING ERRCODE='22023'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_each(e.payload->'members') m CROSS JOIN LATERAL jsonb_array_elements(m.value) v WHERE jsonb_typeof(v.value)<>'object') THEN RAISE EXCEPTION 'Persisted member rows must be objects' USING ERRCODE='22023'; END IF;
 END LOOP;
 WITH groups AS (SELECT id,payload->'members' members FROM public.recon_exceptions WHERE tenant_id=_tenant AND run_id=_run AND id=ANY(ids)),
 parts AS (SELECT g.id,s.key,a.value,a.ordinality FROM groups g CROSS JOIN LATERAL jsonb_each(g.members) s CROSS JOIN LATERAL jsonb_array_elements(s.value) WITH ORDINALITY a),
 sides AS (SELECT key,jsonb_agg(value ORDER BY id,ordinality) rows FROM parts GROUP BY key)
 SELECT jsonb_object_agg(key,rows),string_agg(jsonb_array_length(rows)::text,':' ORDER BY key) INTO member_map,cardinality_text FROM sides;
 IF (SELECT count(*) FROM jsonb_object_keys(coalesce(member_map,'{}')))<>expected OR EXISTS(SELECT 1 FROM jsonb_each(member_map) m WHERE jsonb_array_length(m.value)=0 OR (expected=2 AND m.key='SOURCE_C')) THEN RAISE EXCEPTION 'Select complete source groups; no missing counterpart is invented' USING ERRCODE='22023'; END IF;
 SELECT jsonb_agg(jsonb_build_object('id',id,'members',payload->'members') ORDER BY id) INTO source_json FROM public.recon_exceptions WHERE tenant_id=_tenant AND run_id=_run AND id=ANY(ids);
 RETURN jsonb_build_object('definition_id',d.id,'recon_name',d.name,'recon_code',d.recon_code,'run_uid',r.run_uid,'exception_ids',ids,'members',member_map,'cardinality',cardinality_text,'source_hash',encode(extensions.digest(source_json::text,'sha256'),'hex'));
END $function$
;

CREATE OR REPLACE FUNCTION public.preview_manual_match_request(_tenant_id uuid, _run_id uuid, _exception_ids uuid[])
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$ SELECT private.manual_match_group_evidence(_tenant_id,_run_id,_exception_ids,'view') $function$
;

CREATE OR REPLACE FUNCTION public.propose_manual_match_atomic(_tenant_id uuid, _run_id uuid, _exception_ids uuid[], _rationale text, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE actor uuid:=auth.uid(); r public.recon_runs%ROWTYPE; old public.manual_match_approvals%ROWTYPE; ids uuid[]; evidence jsonb; input_hash text; new_id uuid;
BEGIN
 IF actor IS NULL OR _request_key IS NULL OR length(btrim(coalesce(_rationale,''))) NOT BETWEEN 10 AND 2000 OR NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=actor AND active AND role::text IN ('tenant_admin','tenant_analyst')) THEN RAISE EXCEPTION 'Active maker and explanation required' USING ERRCODE='42501'; END IF;
 SELECT * INTO r FROM public.recon_runs WHERE id=_run_id AND tenant_id=_tenant_id FOR UPDATE;
 IF r.id IS NULL OR NOT public.recon_authoritative_access_decision(r.definition_id,'edit') THEN RAISE EXCEPTION 'Run edit access required' USING ERRCODE='42501'; END IF;
 SELECT array_agg(x ORDER BY x) INTO ids FROM (SELECT DISTINCT unnest(_exception_ids) x) s;
 IF ids IS NULL OR cardinality(ids)<>cardinality(_exception_ids) THEN RAISE EXCEPTION 'Select distinct exception groups' USING ERRCODE='22023'; END IF;
 input_hash:=encode(extensions.digest(jsonb_build_object('run',_run_id,'exceptions',ids,'rationale',btrim(_rationale))::text,'sha256'),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended(_tenant_id::text||':'||actor::text||':'||_request_key::text,0));
 SELECT * INTO old FROM public.manual_match_approvals WHERE tenant_id=_tenant_id AND proposed_by=actor AND request_key=_request_key FOR UPDATE;
 IF FOUND THEN IF old.request_hash IS DISTINCT FROM input_hash THEN RAISE EXCEPTION 'Request key reused with changed evidence' USING ERRCODE='22023'; END IF; RETURN jsonb_build_object('id',old.id,'replayed',true); END IF;
 PERFORM 1 FROM public.recon_exceptions WHERE tenant_id=_tenant_id AND run_id=_run_id AND id=ANY(ids) ORDER BY id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM public.manual_match_approvals WHERE tenant_id=_tenant_id AND run_id=_run_id AND status='pending' AND exception_ids&&ids) THEN RAISE EXCEPTION 'Selected group already has a pending request' USING ERRCODE='23505'; END IF;
 evidence:=private.manual_match_group_evidence(_tenant_id,_run_id,ids,'edit');
 INSERT INTO public.manual_match_approvals(tenant_id,run_id,exception_ids,members,cardinality,rationale,proposed_by,request_key,request_hash)
 VALUES(_tenant_id,_run_id,ids,evidence->'members',evidence->>'cardinality',btrim(_rationale),actor,_request_key,input_hash) RETURNING id INTO new_id;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
 VALUES(actor,_tenant_id,'workspace','manual_match.propose','manual_match_approvals',new_id::text,jsonb_build_object('run_id',_run_id,'run_uid',r.run_uid,'definition_id',r.definition_id,'request_key',_request_key,'source_hash',evidence->>'source_hash'));
 RETURN jsonb_build_object('id',new_id,'replayed',false);
END $function$
;

CREATE OR REPLACE FUNCTION private.task_eod_snapshot(_tenant uuid, _runs uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE ids uuid[]; r record; refs jsonb; states jsonb; pending jsonb; body jsonb; open_count integer; waived_count integer;
BEGIN
 IF auth.uid() IS NULL OR _runs IS NULL OR cardinality(_runs) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Select retained Runs' USING ERRCODE='22023'; END IF;
 SELECT array_agg(x ORDER BY x) INTO ids FROM (SELECT DISTINCT unnest(_runs) x) s;
 IF cardinality(ids)<>cardinality(_runs) OR array_position(ids,NULL) IS NOT NULL OR (SELECT count(*) FROM public.recon_runs WHERE tenant_id=_tenant AND id=ANY(ids))<>cardinality(ids) THEN RAISE EXCEPTION 'Run scope unavailable' USING ERRCODE='42501'; END IF;
 FOR r IN SELECT * FROM public.recon_runs WHERE tenant_id=_tenant AND id=ANY(ids) LOOP
  IF NOT public.recon_authoritative_access_decision(r.definition_id,'view') OR r.run_uid IS NULL OR r.status::text<>'completed' OR r.started_at IS NULL OR r.completed_at IS NULL OR jsonb_typeof(r.stats->'total_rows') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'Completed, counted Run evidence required' USING ERRCODE='42501'; END IF;
 END LOOP;
 SELECT jsonb_agg(jsonb_build_object('run_id',rr.id,'run_uid',rr.run_uid,'definition_id',rr.definition_id,'recon_name',d.name,'recon_code',d.recon_code,'stats',rr.stats,'started_at',rr.started_at,'completed_at',rr.completed_at) ORDER BY rr.id) INTO refs FROM public.recon_runs rr JOIN public.recon_definitions d ON d.id=rr.definition_id AND d.tenant_id=rr.tenant_id WHERE rr.tenant_id=_tenant AND rr.id=ANY(ids);
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'run_id',run_id,'status',status,'updated_at',updated_at) ORDER BY id),'[]'::jsonb),count(*) FILTER(WHERE status::text IN ('open','investigating')),count(*) FILTER(WHERE status::text='wont_fix') INTO states,open_count,waived_count FROM public.recon_exceptions WHERE tenant_id=_tenant AND run_id=ANY(ids);
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'run_id',run_id) ORDER BY id),'[]'::jsonb) INTO pending FROM public.manual_match_approvals WHERE tenant_id=_tenant AND run_id=ANY(ids) AND status='pending';
 body:=jsonb_build_object('run_refs',refs,'exception_state',states,'pending_manual',pending,'open_exceptions',open_count,'waived_exceptions',waived_count,'run_count',cardinality(ids));
 RETURN body||jsonb_build_object('snapshot_hash',encode(extensions.digest(body::text,'sha256'),'hex'),'checks',jsonb_build_object('completed_runs',true,'counted_evidence',true,'manual_reviews_clear',jsonb_array_length(pending)=0,'exceptions_clear',open_count=0 AND waived_count=0));
END $function$
;

CREATE OR REPLACE FUNCTION private.rs_read_group_intents(_tenant uuid, _definition uuid, _run uuid, _group uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid:=private.rs_actor(_tenant,_definition,'read');g private.rs_groups%ROWTYPE;result jsonb;
BEGIN
 SELECT * INTO g FROM private.rs_groups WHERE run_id=_run AND native_id=_group;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.recon_runs WHERE id=_run AND tenant_id=_tenant AND definition_id=_definition)
 THEN RAISE EXCEPTION 'rs.exact_group_history_required' USING ERRCODE='42501';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',e.id,'actor_id',e.actor_id,'occurred_at',e.occurred_at,'payload',e.payload) ORDER BY e.occurred_at,e.id),'[]') INTO result
 FROM private.rs_events e WHERE e.run_id=_run AND e.kind='group_action_requested' AND e.payload->>'group_id'=_group::text;
 RETURN result;
END $function$
;

CREATE OR REPLACE FUNCTION public.request_recon_group_action(_tenant_id uuid, _definition_id uuid, _run_id uuid, _group_id uuid, _action text, _detail text, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
BEGIN
 PERFORM private.rs_actor(_tenant_id,_definition_id,'edit');
 PERFORM 1 FROM public.recon_runs WHERE id=_run_id AND tenant_id=_tenant_id AND definition_id=_definition_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.visible_group_run_required' USING ERRCODE='42501';END IF;
 RETURN private.rs_record_group_intent(_tenant_id,_definition_id,_run_id,_group_id,_action,_detail,_request_key);
END $function$
;

CREATE OR REPLACE FUNCTION private.dpdi_reviewer_evidence(_tenant uuid, _kind text, _request uuid, _actor uuid, _context uuid, _include_payload boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE f jsonb:=private.dpdi_reviewer_frame(_tenant,_kind,_request,_actor);r jsonb:=f->'reference';j private.dpdi_jobs%ROWTYPE;c public.data_prep_configuration_revisions%ROWTYPE;e private.dpdi_job_events%ROWTYPE;ctx private.dpd_request_contexts%ROWTYPE;available boolean:=f->>'availability'='available';
BEGIN
 SELECT * INTO j FROM private.dpdi_jobs WHERE id=(f->>'job_id')::uuid;SELECT * INTO c FROM public.data_prep_configuration_revisions WHERE id=(f->>'configuration_id')::uuid;e:=private.dpdi_head(j.id);SELECT * INTO ctx FROM private.dpd_request_contexts WHERE id=_context AND tenant_id=_tenant AND actor_id=_actor;
 RETURN jsonb_build_object('actor_id',_actor,'tenant_id',_tenant,'setup_id',j.setup_id,'request_id',_request,'request_key',r->>'request_key','kind',_kind,'status',r->>'status','requested_by',r->>'requested_by','approver_group_id',r->>'approver_group_id','decision',r->'decision','draft_version',j.draft_version,'pipeline_id',c.pipeline_id,'pipeline_version',c.pipeline_version,'availability',f->>'availability','can_decide',(f->>'can_decide')::boolean,'reason',f->'reason',
 'job',private.dpdi_dto(j)||jsonb_build_object('actor_id',_actor,'execution_actor_id',j.actor_id,'draft_version',j.draft_version,'configuration_id',c.id,'configuration_sha256',c.payload_sha256,'snapshot',CASE WHEN available AND _include_payload THEN j.snapshot ELSE NULL END),
 'configuration',jsonb_build_object('id',c.id,'pipeline_id',c.pipeline_id,'pipeline_version',c.pipeline_version,'payload_sha256',c.payload_sha256,'payload',CASE WHEN available AND _include_payload THEN c.payload ELSE NULL END),
 'quality',jsonb_build_object('phase',e.phase,'source_records',e.source_records::text,'blocking_records',e.blocking_records::text,'output_pages',e.output_pages,'output_root_sha256',e.output_root_sha256,'full_final_ack',e.phase IN('success','blocked'),'records_available',available),
 'current_context',jsonb_build_object('actor_id',_actor,'tenant_id',_tenant,'setup_id',j.setup_id,'request_id',_request,'kind',_kind,'operation',ctx.operation,'issued_at',ctx.created_at,'expires_at',ctx.expires_at,'snapshot_sha256',j.snapshot_sha256,'configuration_sha256',c.payload_sha256,'read_context_sha256',private.dpw_hash(jsonb_build_object('context',ctx.id,'actor',_actor,'tenant',_tenant,'setup',j.setup_id,'request',_request,'kind',_kind,'group',r->>'approver_group_id','configuration_sha256',c.payload_sha256,'snapshot_sha256',j.snapshot_sha256))));
END $function$
;

CREATE OR REPLACE FUNCTION private.rs_queue_snapshot(_tenant uuid, _definition uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid:=private.rs_actor(_tenant,_definition,'read');items jsonb;active_count integer;
BEGIN
 SELECT count(*) INTO active_count FROM public.recon_runs WHERE tenant_id=_tenant AND definition_id=_definition AND status='running';
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',x.id,'public_id',x.run_uid,'status',x.status,'position',x.position,
  'progress',NULL,'owned_intent_available',x.intent_available,'dispatch_actor_is_current',x.run_by=actor) ORDER BY x.position),'[]') INTO items
 FROM (SELECT r.id,r.run_uid,r.status,r.run_by,q.run_id IS NOT NULL AS intent_available,
  row_number() OVER(ORDER BY CASE WHEN r.status='running' THEN 0 ELSE 1 END,coalesce(q.created_at,r.started_at),r.id) AS position
  FROM public.recon_runs r LEFT JOIN private.rs_requests q ON q.run_id=r.id
  WHERE r.tenant_id=_tenant AND r.definition_id=_definition AND r.status IN('queued','running')) x;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant,'definition_id',_definition,'queue',items,
  'queue_complete',true,'active_count',active_count,'one_active_invariant',active_count<=1,'observed_at',statement_timestamp());
END $function$
;

CREATE OR REPLACE FUNCTION public.decide_task_eod_signoff_atomic(_tenant_id uuid, _id uuid, _decision text, _reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE actor uuid:=auth.uid(); row public.eod_signoffs%ROWTYPE; snapshot jsonb; ids uuid[]; prior_flag text; r record;
BEGIN
 IF actor IS NULL OR _decision NOT IN ('approved','rejected') OR length(btrim(coalesce(_reason,''))) NOT BETWEEN 10 AND 2000 OR NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=actor AND active AND role::text='tenant_admin') THEN RAISE EXCEPTION 'Independent administrator and decision note required' USING ERRCODE='42501'; END IF;
 SELECT * INTO row FROM public.eod_signoffs WHERE id=_id AND tenant_id=_tenant_id FOR UPDATE;
 IF NOT FOUND OR row.prepared_by=actor OR row.status<>'prepared' OR row.locked OR row.request_key IS NULL OR row.retained_run_refs IS NULL THEN RAISE EXCEPTION 'Current independent scoped request required' USING ERRCODE='42501'; END IF;
 IF row.version IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Request version changed; request a fresh sign-off' USING ERRCODE='22023'; END IF;
 IF (SELECT count(*) FROM public.audit_log WHERE tenant_id=_tenant_id AND resource_id=_id::text AND action='eod.prepare' AND actor_user_id=row.prepared_by)<>1 THEN RAISE EXCEPTION 'Retained preparer request audit required' USING ERRCODE='42501'; END IF;
 SELECT array_agg((v->>'run_id')::uuid ORDER BY v->>'run_id') INTO ids FROM jsonb_array_elements(row.retained_run_refs) v;
 PERFORM 1 FROM public.recon_runs WHERE tenant_id=_tenant_id AND id=ANY(ids) ORDER BY id FOR UPDATE;
 FOR r IN SELECT definition_id FROM public.recon_runs WHERE tenant_id=_tenant_id AND id=ANY(ids) LOOP IF NOT public.recon_authoritative_access_decision(r.definition_id,'approve') THEN RAISE EXCEPTION 'Run reviewer scope required' USING ERRCODE='42501'; END IF; END LOOP;
 IF _decision='approved' THEN
  PERFORM 1 FROM public.recon_exceptions WHERE tenant_id=_tenant_id AND run_id=ANY(ids) ORDER BY id FOR SHARE;
  snapshot:=private.task_eod_snapshot(_tenant_id,ids);
  IF snapshot->>'snapshot_hash' IS DISTINCT FROM row.scope_snapshot_hash OR NOT (snapshot->'checks'->>'manual_reviews_clear')::boolean THEN RAISE EXCEPTION 'Evidence changed; request a fresh sign-off' USING ERRCODE='22023'; END IF;
 END IF;
 prior_flag:=current_setting('app.signoff_advance_ok',true); PERFORM set_config('app.signoff_advance_ok','on',true);
 UPDATE public.eod_signoffs SET status=_decision,approved_by=actor,approved_at=now(),decision_note=btrim(_reason),locked=(_decision='approved'),version=coalesce(version,0)+1,updated_at=now() WHERE id=_id AND tenant_id=_tenant_id;
 PERFORM set_config('app.signoff_advance_ok',coalesce(prior_flag,'off'),true);
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context) VALUES(actor,_tenant_id,'workspace','eod.'||_decision,'eod_signoffs',_id::text,jsonb_build_object('period',row.period_date,'run_refs',row.retained_run_refs,'checks',row.checks_snapshot,'scope_hash',row.scope_snapshot_hash,'reason',btrim(_reason)));
 RETURN jsonb_build_object('ok',true,'id',_id,'status',_decision);
END $function$
;

CREATE OR REPLACE FUNCTION private.ticket_active_member(_user uuid, _tenant uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$ SELECT EXISTS(SELECT 1 FROM public.tenant_members WHERE user_id=_user AND tenant_id=_tenant AND active); $function$
;

CREATE OR REPLACE FUNCTION private.ticket_manager(_user uuid, _tenant uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$ SELECT private.is_platform_admin(_user) OR EXISTS(SELECT 1 FROM public.tenant_members
 WHERE user_id=_user AND tenant_id=_tenant AND active AND role='tenant_admin'); $function$
;

CREATE OR REPLACE FUNCTION private.ticket_responder(_user uuid, _tenant uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$ SELECT private.ticket_active_member(_user,_tenant) AND public.user_has_permission(_user,_tenant,'support.ticket.respond',NULL); $function$
;

CREATE OR REPLACE FUNCTION private.ticket_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE actor uuid := auth.uid(); manager boolean; assigned boolean; p public.sla_policies%ROWTYPE;
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'Authenticated ticket actor required' USING ERRCODE='42501'; END IF;
 PERFORM id FROM public.tenant_members WHERE user_id=actor AND tenant_id=NEW.tenant_id FOR SHARE;
 PERFORM id FROM public.platform_roles WHERE user_id=actor AND role='platform_admin' FOR SHARE;
 IF TG_OP='INSERT' THEN
   IF NEW.created_by<>actor OR NEW.status<>'open' OR NEW.first_response_at IS NOT NULL
      OR NEW.resolved_at IS NOT NULL OR NEW.closed_at IS NOT NULL THEN
     RAISE EXCEPTION 'New ticket identity/state must belong to requester' USING ERRCODE='42501';
   END IF;
   IF (NEW.scope='platform' AND (NEW.tenant_id IS NOT NULL OR NOT private.is_platform_admin(actor)))
      OR (NEW.scope<>'platform' AND NOT private.ticket_active_member(actor,NEW.tenant_id)) THEN
     RAISE EXCEPTION 'Current active ticket scope required' USING ERRCODE='42501';
   END IF;
   NEW.ref := 'FVI-'||upper(replace(NEW.id::text,'-',''));
   NEW.created_at := statement_timestamp();
   NEW.sla_revision := 0;
 ELSE
   IF ROW(NEW.id,NEW.ref,NEW.tenant_id,NEW.scope,NEW.created_by,NEW.created_at)
      IS DISTINCT FROM ROW(OLD.id,OLD.ref,OLD.tenant_id,OLD.scope,OLD.created_by,OLD.created_at) THEN
     RAISE EXCEPTION 'Ticket identity/scope is immutable' USING ERRCODE='42501';
   END IF;
   manager := private.ticket_manager(actor,OLD.tenant_id);
   assigned := coalesce(OLD.assignee_id=actor AND private.ticket_responder(actor,OLD.tenant_id),false);
   IF NOT manager AND NOT assigned AND NOT (OLD.created_by=actor AND private.ticket_active_member(actor,OLD.tenant_id)) THEN
     RAISE EXCEPTION 'Current ticket update permission required' USING ERRCODE='42501';
   END IF;
   IF NOT manager AND (to_jsonb(NEW)-ARRAY['status','updated_at','first_response_at','resolved_at','closed_at','csat_score','csat_comment'])
       IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','updated_at','first_response_at','resolved_at','closed_at','csat_score','csat_comment']) THEN
     RAISE EXCEPTION 'Only managers may change ticket assignment/configuration' USING ERRCODE='42501';
   END IF;
   IF ROW(NEW.csat_score,NEW.csat_comment) IS DISTINCT FROM ROW(OLD.csat_score,OLD.csat_comment) AND (actor<>OLD.created_by OR NOT private.ticket_active_member(actor,OLD.tenant_id)) THEN RAISE EXCEPTION 'Only current requester records customer feedback' USING ERRCODE='42501'; END IF;
   IF length(NEW.csat_comment)>1000 THEN RAISE EXCEPTION 'Bounded customer feedback required' USING ERRCODE='22023'; END IF;
   IF NEW.first_response_at IS DISTINCT FROM OLD.first_response_at AND pg_trigger_depth()<2 THEN
     RAISE EXCEPTION 'First response is recorded by the actual public message' USING ERRCODE='42501';
   END IF;
   IF ROW(NEW.sla_snapshot,NEW.sla_started_at,NEW.first_response_due_at,NEW.resolution_due_at)
      IS DISTINCT FROM ROW(OLD.sla_snapshot,OLD.sla_started_at,OLD.first_response_due_at,OLD.resolution_due_at) THEN
     RAISE EXCEPTION 'SLA deadlines are generated from configured policy' USING ERRCODE='42501';
   END IF;
   IF NEW.sla_revision<>OLD.sla_revision AND (NOT manager OR NEW.sla_revision<>OLD.sla_revision+1) THEN
     RAISE EXCEPTION 'SLA revision requires a manager policy decision' USING ERRCODE='42501';
   END IF;
   -- Completion events come from this transition, never requester-supplied dates.
   IF NEW.status IS DISTINCT FROM OLD.status THEN
     IF NEW.status='resolved' THEN NEW.resolved_at:=statement_timestamp(); NEW.closed_at:=NULL;
     ELSIF NEW.status='closed' THEN NEW.closed_at:=statement_timestamp();
     ELSE NEW.resolved_at:=NULL; NEW.closed_at:=NULL; END IF;
   ELSE NEW.resolved_at:=OLD.resolved_at; NEW.closed_at:=OLD.closed_at; END IF;
 END IF;
 manager := private.ticket_manager(actor,NEW.tenant_id);
 IF TG_OP='INSERT' OR NEW.assignee_id IS DISTINCT FROM OLD.assignee_id THEN
   IF NEW.assignee_id IS NOT NULL THEN
     PERFORM id FROM public.tenant_members WHERE user_id=NEW.assignee_id AND tenant_id=NEW.tenant_id FOR SHARE;
     IF NOT manager THEN RAISE EXCEPTION 'Only managers assign tickets' USING ERRCODE='42501'; END IF;
     IF (NEW.scope='platform' AND NOT private.is_platform_admin(NEW.assignee_id))
        OR (NEW.scope<>'platform' AND NOT (private.ticket_active_member(NEW.assignee_id,NEW.tenant_id)
          AND (private.ticket_manager(NEW.assignee_id,NEW.tenant_id) OR private.ticket_responder(NEW.assignee_id,NEW.tenant_id)))) THEN
       RAISE EXCEPTION 'Assignee must be current permitted member of ticket scope' USING ERRCODE='42501';
     END IF;
   END IF;
 END IF;
 IF NEW.category NOT IN ('general_question','bug','feature_request','design_feedback','data_quality','integration',
    'access_permissions','billing','security_concern','compliance','performance','training','documentation','incident','other') THEN
   RAISE EXCEPTION 'Unsupported ticket category' USING ERRCODE='22023';
 END IF;
 IF TG_OP='INSERT' THEN
   IF NEW.sla_policy_id IS NULL AND NEW.tenant_id IS NOT NULL THEN
     SELECT * INTO p FROM public.sla_policies WHERE tenant_id=NEW.tenant_id AND priority=NEW.priority;
     NEW.sla_policy_id:=p.id;
   END IF;
 END IF;
 IF TG_OP='INSERT' OR NEW.sla_policy_id IS DISTINCT FROM OLD.sla_policy_id OR NEW.sla_revision<>OLD.sla_revision THEN
   IF TG_OP='UPDATE' AND NOT manager THEN RAISE EXCEPTION 'Manager SLA decision required' USING ERRCODE='42501'; END IF;
   IF NEW.sla_policy_id IS NULL THEN
     NEW.sla_snapshot:=NULL; NEW.sla_started_at:=NULL; NEW.first_response_due_at:=NULL; NEW.resolution_due_at:=NULL;
   ELSE
     SELECT * INTO p FROM public.sla_policies WHERE id=NEW.sla_policy_id FOR SHARE;
     IF NEW.status IN ('resolved','closed') THEN RAISE EXCEPTION 'No new SLA baseline for a completed case' USING ERRCODE='22023'; END IF;
     IF p.id IS NULL OR p.tenant_id IS DISTINCT FROM NEW.tenant_id OR p.priority<>NEW.priority
        OR p.first_response_mins<=0 OR p.resolution_mins<=0 THEN
       RAISE EXCEPTION 'Valid configured policy for ticket tenant/priority required' USING ERRCODE='22023';
     END IF;
     NEW.sla_started_at:=statement_timestamp();
     NEW.sla_snapshot:=jsonb_build_object('policy_id',p.id,'name',p.name,'priority',p.priority,
       'first_response_mins',p.first_response_mins,'resolution_mins',p.resolution_mins,'started_at',NEW.sla_started_at);
     NEW.first_response_due_at:=NEW.sla_started_at+make_interval(mins=>p.first_response_mins);
     NEW.resolution_due_at:=NEW.sla_started_at+make_interval(mins=>p.resolution_mins);
   END IF;
 END IF;
 IF NEW.recon_id IS NOT NULL AND (TG_OP='INSERT' OR NEW.recon_id IS DISTINCT FROM OLD.recon_id) AND NOT EXISTS(SELECT FROM public.recon_definitions WHERE id=NEW.recon_id AND tenant_id=NEW.tenant_id) THEN RAISE EXCEPTION 'Reconciliation association outside ticket tenant' USING ERRCODE='42501'; END IF;
 IF (TG_OP='INSERT' OR NEW.attachments IS DISTINCT FROM OLD.attachments OR NEW.body IS DISTINCT FROM OLD.body) AND (length(trim(NEW.subject))<3 OR length(NEW.subject)>160 OR length(NEW.body)>50000
    OR jsonb_typeof(NEW.attachments)<>'array' OR jsonb_array_length(NEW.attachments)>5) THEN
   RAISE EXCEPTION 'Invalid bounded ticket content' USING ERRCODE='22023';
 END IF;
 RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.read_recon_execution_queue(_tenant_id uuid, _definition_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE result jsonb;item jsonb;
BEGIN
 PERFORM private.rs_actor(_tenant_id,_definition_id,'read');result:=private.rs_queue_snapshot(_tenant_id,_definition_id);
 FOR item IN SELECT x.value FROM jsonb_array_elements(result->'queue') x LOOP
  PERFORM 1 FROM public.recon_runs WHERE id=(item->>'id')::uuid AND tenant_id=_tenant_id AND definition_id=_definition_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'rs.queue_rlp_scope_changed' USING ERRCODE='42501';END IF;
 END LOOP;RETURN result;
END $function$
;

CREATE OR REPLACE FUNCTION private.rs_record_group_intent(_tenant uuid, _definition uuid, _run uuid, _group uuid, _action text, _detail text, _key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid:=private.rs_actor(_tenant,_definition,'edit');g private.rs_groups%ROWTYPE;e private.rs_events%ROWTYPE;intent jsonb;
BEGIN
 IF _key IS NULL OR (_action IN('comment','label','accept','rematch','carry_forward','exclude_request')) IS DISTINCT FROM true
 OR length(btrim(coalesce(_detail,''))) NOT BETWEEN 1 AND 4000 THEN RAISE EXCEPTION 'rs.explicit_group_intent_required' USING ERRCODE='22023';END IF;
 SELECT * INTO g FROM private.rs_groups WHERE run_id=_run AND native_id=_group;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.recon_runs WHERE id=_run AND tenant_id=_tenant AND definition_id=_definition AND status='completed')
 THEN RAISE EXCEPTION 'rs.exact_completed_group_required' USING ERRCODE='42501';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(g.source_rows) x WHERE private.data_source_child_allows(actor,_tenant,(x.value->>'data_source_id')::uuid,'view') IS DISTINCT FROM true)
 THEN RAISE EXCEPTION 'rs.current_group_source_denied' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('rs-group:'||_run::text||':'||actor::text||':'||_key::text,0));
 intent:=jsonb_build_object('request_key',_key,'group_id',_group,'match_status',g.match_status,'action',_action,'detail',btrim(_detail),
  'disposition',CASE WHEN _action='comment' THEN 'recorded' ELSE 'requested' END,'business_effect_applied',false,'ai_authority','Suggest');
 SELECT * INTO e FROM private.rs_events WHERE run_id=_run AND actor_id=actor AND kind='group_action_requested' AND payload->>'request_key'=_key::text;
 IF FOUND AND e.payload IS DISTINCT FROM intent THEN RAISE EXCEPTION 'rs.group_request_key_conflict' USING ERRCODE='PT409';END IF;
 IF NOT FOUND THEN INSERT INTO private.rs_events(run_id,actor_id,kind,payload) VALUES(_run,actor,'group_action_requested',intent) RETURNING * INTO e;END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant,'definition_id',_definition,'run_id',_run,'group_id',_group,
  'action',_action,'audit_event_id',e.id,'occurred_at',e.occurred_at,'request_key',_key,'disposition',intent->>'disposition',
  'business_effect_applied',false,'matching_outcome_changed',false,'settlement_state_changed',false);
END $function$
;

CREATE OR REPLACE FUNCTION private.governance_membership_scope(_tenant uuid, _bu uuid, _workspace uuid, _group uuid, _env text, _user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE result jsonb; rights text[];
BEGIN
  IF NOT private.governance_membership_active(_tenant,_user) THEN RAISE EXCEPTION 'Active tenant membership required' USING ERRCODE='42501'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.business_units WHERE id=_bu AND tenant_id=_tenant AND NOT is_archived)
    OR NOT EXISTS(SELECT 1 FROM public.tenant_groups WHERE id=_group AND tenant_id=_tenant AND bu_id=_bu)
    OR NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=_workspace AND tenant_id=_tenant AND business_unit_id=_bu AND status='active')
    OR NOT EXISTS(SELECT 1 FROM public.tenant_environments WHERE tenant_id=_tenant AND env::text=_env AND is_active)
  THEN RAISE EXCEPTION 'Current tenant/BU/group/workspace/environment association required' USING ERRCODE='42501'; END IF;
  -- user_bu_scope has no platform-admin shortcut. An actual tenant admin is explicitly accepted.
  IF NOT private.governance_membership_active(_tenant,_user,true) AND (
    NOT EXISTS(SELECT 1 FROM public.user_bu_scope(_user,_tenant) s WHERE s=_bu)
    OR NOT EXISTS(SELECT 1 FROM public.workspace_members WHERE workspace_id=_workspace AND tenant_id=_tenant AND user_id=_user)
  ) THEN RAISE EXCEPTION 'Current BU and workspace access required' USING ERRCODE='42501'; END IF;
  IF EXISTS(SELECT 1 FROM public.tenant_group_roles gr JOIN public.rbac_roles r ON r.id=gr.role_id
    WHERE gr.group_id=_group AND (NOT r.is_assignable OR (r.tenant_id IS NOT NULL AND r.tenant_id<>_tenant)
      OR r.key ~* '(admin|owner|platform|system)' OR r.key NOT IN ('tenant_analyst','tenant_viewer') AND r.is_system))
    OR EXISTS(SELECT 1 FROM public.tenant_group_roles gr JOIN public.rbac_role_permissions rp ON rp.role_id=gr.role_id
      JOIN public.permissions p ON p.id=rp.permission_id WHERE gr.group_id=_group
      AND ((p.category IN ('admin','security','billing') OR p.resource ~* '(^|[.])(role|user|group|tenant|platform|vault|environment)([.]|$)') AND p.action NOT IN ('read','view')))
    OR EXISTS(SELECT 1 FROM public.bu_group_assignments WHERE group_id=_group AND (tenant_id<>_tenant OR role::text='bu_admin'))
  THEN RAISE EXCEPTION 'Administrative or cross-tenant group privileges cannot be requested' USING ERRCODE='42501'; END IF;
  IF EXISTS(SELECT 1 FROM public.recon_definition_bu_grants WHERE principal_type='group' AND principal_id=_group AND tenant_id<>_tenant)
    OR EXISTS(SELECT 1 FROM public.recon_permissions g JOIN public.recon_definitions d ON d.id=g.recon_id WHERE g.principal_type='group' AND g.principal_id=_group AND d.tenant_id<>_tenant)
    OR EXISTS(SELECT 1 FROM public.data_resource_registry_grants WHERE principal_type='group' AND principal_group_id=_group AND tenant_id<>_tenant)
    OR EXISTS(SELECT 1 FROM public.data_resource_bu_grants WHERE principal_type='group' AND principal_id=_group AND tenant_id<>_tenant)
  THEN RAISE EXCEPTION 'Cross-tenant resource rights cannot be requested' USING ERRCODE='42501'; END IF;
  SELECT coalesce(array_agg(DISTINCT permission_id ORDER BY permission_id),'{}'::text[]) INTO rights FROM (
    SELECT rp.permission_id FROM public.tenant_group_roles gr JOIN public.rbac_role_permissions rp ON rp.role_id=gr.role_id WHERE gr.group_id=_group
    UNION SELECT 'reconciliation:'||recon_id::text||':'||action FROM public.recon_definition_bu_grants WHERE principal_type='group' AND principal_id=_group
    UNION SELECT 'legacy_reconciliation:'||recon_id::text||':'||permission FROM public.recon_permissions WHERE principal_type='group' AND principal_id=_group
    UNION SELECT 'data_resource:'||registry_id::text||':'||action FROM public.data_resource_registry_grants WHERE principal_type='group' AND principal_group_id=_group
    UNION SELECT 'legacy_data_resource:'||resource_type||':'||resource_id::text||':'||action FROM public.data_resource_bu_grants WHERE principal_type='group' AND principal_id=_group
  ) all_rights;
  SELECT jsonb_build_object(
    'scope_label','Tenant group membership; existing group rights can apply across workspaces',
    'group', (SELECT jsonb_build_object('id',id,'tenant_id',tenant_id,'bu_id',bu_id,'is_system',is_system,'preset_key',preset_key) FROM public.tenant_groups WHERE id=_group),
    'workspace', (SELECT jsonb_build_object('id',id,'tenant_id',tenant_id,'business_unit_id',business_unit_id,'status',status) FROM public.workspaces WHERE id=_workspace),
    'environment',_env,
    'requested_rights',to_jsonb(rights),
    'roles',coalesce((SELECT jsonb_agg(jsonb_build_object('id',r.id,'key',r.key,'tenant_id',r.tenant_id,'is_system',r.is_system,'is_assignable',r.is_assignable) ORDER BY r.id)
      FROM public.tenant_group_roles gr JOIN public.rbac_roles r ON r.id=gr.role_id WHERE gr.group_id=_group),'[]'::jsonb),
    'bu_assignments',coalesce((SELECT jsonb_agg(jsonb_build_object('bu_id',bu_id,'tenant_id',tenant_id,'role',role,'inherit_descendants',inherit_descendants) ORDER BY bu_id) FROM public.bu_group_assignments WHERE group_id=_group),'[]'::jsonb),
    'reconciliation_grants',coalesce((SELECT jsonb_agg(jsonb_build_object('id',g.id,'tenant_id',g.tenant_id,'bu_id',g.bu_id,'recon_id',g.recon_id,'action',g.action,'environment',d.environment) ORDER BY g.id)
      FROM public.recon_definition_bu_grants g JOIN public.recon_definitions d ON d.id=g.recon_id AND d.tenant_id=g.tenant_id
      WHERE g.principal_type='group' AND g.principal_id=_group),'[]'::jsonb),
    'legacy_reconciliation_grants',coalesce((SELECT jsonb_agg(jsonb_build_object('id',g.id,'recon_id',g.recon_id,'permission',g.permission,'tenant_id',d.tenant_id,'environment',d.environment) ORDER BY g.id) FROM public.recon_permissions g JOIN public.recon_definitions d ON d.id=g.recon_id WHERE g.principal_type='group' AND g.principal_id=_group),'[]'::jsonb),
    'legacy_data_resource_grants',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'tenant_id',tenant_id,'bu_id',bu_id,'resource_type',resource_type,'resource_id',resource_id,'action',action) ORDER BY id)
      FROM public.data_resource_bu_grants WHERE principal_type='group' AND principal_id=_group),'[]'::jsonb),
    'data_resource_grants',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'tenant_id',tenant_id,'bu_id',bu_id,'registry_id',registry_id,'action',action) ORDER BY id)
      FROM public.data_resource_registry_grants WHERE principal_type='group' AND principal_group_id=_group),'[]'::jsonb)
  ) INTO result;
  RETURN result;
END $function$
;

CREATE OR REPLACE FUNCTION private.governance_membership_record(_r governance_membership_requests, _action text, _actor uuid, _reason text, _outcome text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE audit_id bigint;
BEGIN
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES(_actor,_r.tenant_id,'tenant',_action,'governance_membership_request',_r.id::text,
    jsonb_build_object('request_id',_r.id,'actor_role',CASE WHEN private.governance_membership_active(_r.tenant_id,_actor,true) THEN 'tenant_admin' ELSE 'tenant_member' END,
      'bu_id',_r.bu_id,'workspace_id',_r.workspace_id,'group_id',_r.group_id,'environment',_r.environment,
      'reason',_reason,'version',_r.version,'correlation_id',_r.correlation_id,'outcome',_outcome,
      'scope_label','Tenant group membership; existing group rights can apply across workspaces')) RETURNING id INTO audit_id;
  INSERT INTO public.governance_membership_events(tenant_id,request_id,actor_user_id,action,version,reason,outcome,correlation_id,audit_id)
  VALUES(_r.tenant_id,_r.id,_actor,_action,_r.version,_reason,_outcome,_r.correlation_id,audit_id);
  RETURN audit_id;
END $function$
;

CREATE OR REPLACE FUNCTION private.governance_membership_active(_tenant uuid, _user uuid, _admin boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT _user IS NOT NULL AND EXISTS(SELECT 1 FROM public.tenant_members
    WHERE tenant_id=_tenant AND user_id=_user AND active AND (NOT _admin OR role::text='tenant_admin'))
$function$
;

CREATE OR REPLACE FUNCTION public.dpw_check_current_ip_access(_tenant_id uuid, _ip text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid:=private.wfm_actor(_tenant_id);enabled boolean;allowed boolean:=false;available boolean;
BEGIN
 IF actor IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR current_setting('role',true) IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'dpw.ip_actor_denied' USING ERRCODE='42501';END IF;
 SELECT ip_allowlist_enabled INTO enabled FROM public.tenant_security_settings WHERE tenant_id=_tenant_id;
 available:=FOUND AND enabled IS NOT NULL;
 IF available AND enabled=false THEN allowed:=true;
 ELSIF available AND _ip IS NOT NULL AND btrim(_ip)<>'' THEN allowed:=public.ip_in_tenant_allowlist(_tenant_id,_ip) IS TRUE;END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'policy_available',available,'enabled',CASE WHEN available THEN enabled ELSE NULL END,'allowed',allowed);
END $function$
;

CREATE OR REPLACE FUNCTION private.rs_mixed_preflight(_tenant uuid, _definition uuid, _business_date date, _bindings jsonb, _expected_definition_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_actor(_tenant); approved jsonb; side jsonb; input jsonb;
 d public.data_prep_prepared_datasets%ROWTYPE; u public.workspace_data_source_uploads%ROWTYPE; contract jsonb; field jsonb; indexes integer[]; row_value jsonb;resolved_logical_side text;
BEGIN
 approved:=private.dpw_recon_approved_attest(actor,_tenant,_definition);
 IF (approved->>'reconciliation_feature_enabled')::boolean IS DISTINCT FROM true
 OR _business_date IS NULL OR approved->>'snapshot_sha256' IS DISTINCT FROM _expected_definition_sha256
 OR jsonb_typeof(approved->'snapshot'->'sides') IS DISTINCT FROM 'array' OR jsonb_typeof(_bindings) IS DISTINCT FROM 'array'
 OR jsonb_array_length(_bindings)<>jsonb_array_length(approved->'snapshot'->'sides')
 OR (SELECT count(DISTINCT value->>'side_id') FROM jsonb_array_elements(_bindings))<>jsonb_array_length(_bindings)
 THEN RAISE EXCEPTION 'dpw.recon_approved_input_mismatch'; END IF;
 FOR side IN SELECT value FROM jsonb_array_elements(approved->'snapshot'->'sides') LOOP
  SELECT value INTO input FROM jsonb_array_elements(_bindings) WHERE value->>'side_id'=side->>'side_id';
  IF input IS NULL OR input->>'data_source_id' IS DISTINCT FROM side->>'data_source_id'
  OR private.dpw_source_allows(actor,_tenant,(side->>'data_source_id')::uuid,'view') IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'dpw.recon_source_binding_denied'; END IF;
  IF nullif(side->>'upload_id','') IS NOT NULL OR input->>'kind'='fixed_upload' THEN
   IF input->>'kind' IS DISTINCT FROM 'fixed_upload' OR (side->>'upload_id' IS NOT NULL AND input->>'upload_id' IS DISTINCT FROM side->>'upload_id')
   OR input ? 'dataset_id' THEN RAISE EXCEPTION 'dpw.fixed_definition_pin_cannot_be_overridden'; END IF;
   SELECT * INTO u FROM public.workspace_data_source_uploads WHERE id=(input->>'upload_id')::uuid
   AND tenant_id=_tenant AND data_source_id=(side->>'data_source_id')::uuid;
   IF NOT FOUND OR jsonb_typeof(u.rows)<>'array' OR u.row_count<>jsonb_array_length(u.rows) THEN RAISE EXCEPTION 'dpw.fixed_input_unavailable'; END IF;
   SELECT x.value INTO contract FROM jsonb_array_elements(approved->'input_contracts') x WHERE x.value->>'side_id'=side->>'side_id';
   IF contract IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(u.rows) x WHERE private.rs_contract_row_allowed(x.value,contract) IS DISTINCT FROM true)
   THEN RAISE EXCEPTION 'rs.mixed_raw_approved_domain_refused' USING ERRCODE='22023';END IF;
   IF side->>'upload_id' IS NULL AND (EXISTS(SELECT 1 FROM public.data_prep_prepared_datasets x WHERE x.tenant_id=_tenant AND x.upload_id=u.id)
    OR EXISTS(SELECT 1 FROM public.data_prep_pipelines p WHERE p.tenant_id=_tenant AND p.output_data_source_id=u.data_source_id))
   THEN RAISE EXCEPTION 'rs.prepared_source_requires_dataset_identity' USING ERRCODE='42501';END IF;
  ELSE
   SELECT value INTO contract FROM jsonb_array_elements(coalesce(approved->'input_contracts','[]'::jsonb)) WHERE value->>'side_id'=side->>'side_id';
   IF contract IS NULL OR (contract->>'logical_side' IS NOT NULL AND contract->>'logical_side' IS DISTINCT FROM input->>'logical_side')
   OR jsonb_typeof(contract->'fields') IS DISTINCT FROM 'array'
   THEN RAISE EXCEPTION 'dpw.recon_authoritative_schema_missing_governed_revision_required'; END IF;
   SELECT * INTO d FROM public.data_prep_prepared_datasets WHERE id=(input->>'dataset_id')::uuid AND tenant_id=_tenant;
   IF NOT FOUND THEN RAISE EXCEPTION 'dpw.current_ready_dataset_required';END IF;
   resolved_logical_side:=coalesce(contract->>'logical_side',private.rs_select_compatible_logical_side(_tenant,d.id,contract));
   IF resolved_logical_side IS DISTINCT FROM input->>'logical_side' THEN RAISE EXCEPTION 'dpw.unique_approved_rule_compatible_cohort_required';END IF;
   IF NOT FOUND OR input->>'kind' IS DISTINCT FROM 'prepared_dataset' OR d.business_date<>_business_date
   OR input->>'pipeline_id' IS DISTINCT FROM d.pipeline_id::text OR (input->>'pipeline_version')::integer IS DISTINCT FROM d.pipeline_version
   OR input->>'upload_id' IS DISTINCT FROM d.upload_id::text OR d.data_source_id::text IS DISTINCT FROM side->>'data_source_id'
   OR private.data_prep_pipeline_scope_allows(actor,_tenant,d.pipeline_id,'view') IS DISTINCT FROM true
   OR private.dpw_run_payload_available(d.run_id) IS DISTINCT FROM true
   OR NOT EXISTS(SELECT 1 FROM public.data_prep_pipelines p WHERE p.id=d.pipeline_id AND p.tenant_id=_tenant AND p.status='approved'
   AND p.lifecycle_state='production' AND p.version=d.pipeline_version AND p.output_data_source_id=d.data_source_id)
   OR NOT EXISTS(SELECT 1 FROM public.data_prep_delivery_runs r,jsonb_array_elements(r.snapshot->'feeds') f
   WHERE r.id=d.run_id AND f.value->>'business_side'=resolved_logical_side)
   OR NOT EXISTS(SELECT 1 FROM public.data_prep_delivery_batches b JOIN public.data_prep_delivery_runs r ON r.id=d.run_id AND r.batch_id=b.id
   WHERE b.id=d.batch_id AND b.mode='prepare' AND b.state='published' AND r.pipeline_version=d.pipeline_version
   AND r.finished_at IS NOT NULL AND r.state IN('success','warn') AND (r.result->>'publication_eligible')::boolean IS TRUE)
   THEN RAISE EXCEPTION 'dpw.current_ready_dataset_required'; END IF;
   SELECT * INTO u FROM public.workspace_data_source_uploads WHERE id=d.upload_id AND tenant_id=_tenant AND data_source_id=d.data_source_id;
   IF NOT FOUND OR u.content_sha256 IS DISTINCT FROM d.content_sha256 OR u.row_count<>d.rows
   OR jsonb_typeof(u.rows)<>'array' OR jsonb_array_length(u.rows)<>d.rows OR private.dpw_hash(u.rows) IS DISTINCT FROM d.content_sha256
   THEN RAISE EXCEPTION 'dpw.prepared_upload_lineage_mismatch'; END IF;
   indexes:=private.dpw_dataset_indexes(d.id,resolved_logical_side);
   FOR row_value IN SELECT u.rows->x FROM unnest(indexes) x LOOP
    IF private.rs_contract_row_allowed(row_value,contract) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpw.recon_approved_field_domain_incompatible';END IF;
   END LOOP;
  END IF;
 END LOOP;
 RETURN approved;
END $function$
;

CREATE OR REPLACE FUNCTION public.dpdi_publish_dataset(_tenant_id uuid, _setup_id uuid, _job_id uuid, _publication_decision_id uuid, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'publication.perform',_request_context_id);j private.dpdi_jobs%ROWTYPE:=private.dpdi_authorize(_tenant_id,_setup_id,_job_id,actor,true);e private.dpdi_job_events%ROWTYPE:=private.dpdi_head(j.id);r private.dpdi_publication_requests%ROWTYPE;dec private.dpdi_publication_decisions%ROWTYPE;d private.dpdi_published_datasets%ROWTYPE;src uuid;
BEGIN
 SELECT * INTO dec FROM private.dpdi_publication_decisions WHERE id=_publication_decision_id AND decision='approved';SELECT * INTO r FROM private.dpdi_publication_requests WHERE id=dec.request_id AND tenant_id=_tenant_id AND setup_id=_setup_id AND job_id=j.id;
 src:=(j.snapshot->'pipeline_configuration'->>'output_data_source_id')::uuid;
 IF j.snapshot->>'mode' IS DISTINCT FROM 'prepare' OR j.snapshot->>'approval_origin' IS DISTINCT FROM 'dpdi_setup_review_v1' OR e.phase<>'success' OR e.blocking_records<>0 OR r.id IS NULL OR dec.decided_by=r.requested_by OR dec.decided_by=j.actor_id OR dec.output_root_sha256<>e.output_root_sha256 OR _request_key IS NULL OR private.dpw_source_allows(actor,_tenant_id,src,'edit') IS DISTINCT FROM true OR private.dpw_source_allows(actor,_tenant_id,src,'ingest') IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpdi.actual_final_human_publication_required_zero_on_failure' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM private.dpdi_jobs WHERE id=j.id FOR UPDATE;SELECT * INTO d FROM private.dpdi_published_datasets WHERE job_id=j.id;
 IF FOUND THEN IF d.request_key<>_request_key OR d.publication_decision_id<>dec.id THEN RAISE EXCEPTION 'dpdi.immutable_publication_request_conflict' USING ERRCODE='PT409';END IF;RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'dataset',private.dpdi_dataset_dto(d),'request_replay',true);END IF;
 INSERT INTO private.dpdi_published_datasets(tenant_id,setup_id,draft_version,pipeline_id,pipeline_version,configuration_id,job_id,run_id,business_date,data_source_id,rows,content_sha256,output_schema_sha256,publication_decision_id,request_key,published_by)
 VALUES(_tenant_id,_setup_id,j.draft_version,(j.snapshot->>'pipeline_id')::uuid,(j.snapshot->>'pipeline_version')::integer,(j.snapshot->>'configuration_id')::uuid,j.id,j.reserved_run_id,(j.snapshot->>'business_date')::date,src,e.source_records,e.output_root_sha256,private.dpw_hash(j.snapshot->'confirmed_mapping'->'output_schema'),dec.id,_request_key,actor) RETURNING * INTO d;
 PERFORM private.dpd_event(_tenant_id,_setup_id,actor,'dataset.published',d.id,jsonb_build_object('manifest_id',d.manifest_id,'rows',d.rows::text,'content_sha256',d.content_sha256,'publication_decision_id',dec.id,'representation','dpdi_approved_prepare_v1','upload_id',NULL));RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'dataset',private.dpdi_dataset_dto(d),'request_replay',false);
END $function$
;

CREATE OR REPLACE FUNCTION public.submit_governance_membership_request(_tenant_id uuid, _bu_id uuid, _workspace_id uuid, _group_id uuid, _environment text, _reason text, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE actor uuid:=auth.uid(); payload jsonb; op private.governance_membership_operations; r public.governance_membership_requests; snapshot jsonb; result jsonb; aid bigint;
BEGIN
  IF _request_key IS NULL OR _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Reason and request key required' USING ERRCODE='22023'; END IF;
  IF NOT private.governance_membership_active(_tenant_id,actor) THEN RAISE EXCEPTION 'Active tenant membership required' USING ERRCODE='42501'; END IF;
  payload:=jsonb_build_object('operation','submit','bu_id',_bu_id,'workspace_id',_workspace_id,'group_id',_group_id,'environment',_environment,'reason',btrim(_reason));
  PERFORM pg_advisory_xact_lock(hashtextextended(_tenant_id::text||_request_key::text,0));
  SELECT * INTO op FROM private.governance_membership_operations WHERE tenant_id=_tenant_id AND request_key=_request_key;
  IF FOUND THEN
    IF op.actor_id<>actor OR op.payload<>payload THEN RAISE EXCEPTION 'Request key collision' USING ERRCODE='23505'; END IF;
    PERFORM private.governance_membership_scope(_tenant_id,_bu_id,_workspace_id,_group_id,_environment,actor);
    RETURN op.result;
  END IF;
  PERFORM private.governance_membership_lock_scope();
  snapshot:=private.governance_membership_scope(_tenant_id,_bu_id,_workspace_id,_group_id,_environment,actor);
  IF EXISTS(SELECT 1 FROM public.tenant_group_members WHERE group_id=_group_id AND user_id=actor) THEN RAISE EXCEPTION 'Already a group member' USING ERRCODE='23505'; END IF;
  INSERT INTO public.governance_membership_requests(tenant_id,requested_by,bu_id,workspace_id,environment,group_id,requested_rights,scope_snapshot,request_reason)
  VALUES(_tenant_id,actor,_bu_id,_workspace_id,_environment,_group_id,ARRAY(SELECT jsonb_array_elements_text(snapshot->'requested_rights')),snapshot,btrim(_reason)) RETURNING * INTO r;
  aid:=private.governance_membership_record(r,'governance.membership.request',actor,btrim(_reason),'pending');
  result:=jsonb_build_object('id',r.id,'status',r.status,'version',r.version,'correlation_id',r.correlation_id,'audit_id',aid::text,'outcome','pending');
  INSERT INTO private.governance_membership_operations VALUES(_tenant_id,_request_key,actor,payload,result);
  RETURN result;
END $function$
;

CREATE OR REPLACE FUNCTION private.dpd_pipeline_payload(_payload jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
 SELECT _payload-ARRAY['_draft_scope','owning_business_unit_ids','sharing_user_group_ids','requested_owning_business_unit_ids','shared_scope_contract']
$function$
;

CREATE OR REPLACE FUNCTION public.dps_save_configuration(_tenant_id uuid, _pipeline_id uuid, _payload jsonb, _owning_business_unit_ids uuid[], _sharing_user_group_ids uuid[], _request_key uuid, _request_context_id uuid DEFAULT NULL::uuid, _setup_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE v private.dpd_versions%ROWTYPE;operation text;expected jsonb;feeds jsonb;
BEGIN
 IF _payload ?| ARRAY['_draft_scope','owning_business_unit_ids','sharing_user_group_ids','requested_owning_business_unit_ids','shared_scope_contract'] THEN RAISE EXCEPTION 'dps.reserved_scope_metadata' USING ERRCODE='22023';END IF;
 SELECT c.operation INTO operation FROM private.dpd_request_contexts c WHERE c.id=_request_context_id;
 IF operation NOT IN('scope.save','preview.bind') OR operation IS NULL THEN RAISE EXCEPTION 'dps.configuration_operation_required' USING ERRCODE='42501';END IF;
 PERFORM private.dps_context_actor(_tenant_id,_setup_id,operation,_request_context_id);
 SELECT * INTO v FROM private.dpd_versions WHERE setup_id=_setup_id ORDER BY version DESC LIMIT 1;
 IF v.version IS NULL OR private.dps_ids(v.owner_bu_ids,100,true) IS DISTINCT FROM private.dps_ids(_owning_business_unit_ids,100,true) OR private.dps_ids(v.group_ids,100,false) IS DISTINCT FROM private.dps_ids(_sharing_user_group_ids,100,false)
 THEN RAISE EXCEPTION 'dps.exact_saved_draft_scope_required' USING ERRCODE='42501';END IF;
 SELECT coalesce(jsonb_agg(f.value||jsonb_build_object('data_source_id',mapped.value->>'data_source_id') ORDER BY f.ordinality),'[]') INTO feeds
 FROM jsonb_array_elements(v.payload->'feeds') WITH ORDINALITY f(value,ordinality)
 JOIN LATERAL(SELECT x.value FROM jsonb_array_elements(v.payload->'confirmed_mapping'->'feeds') x(value) WHERE x.value->>'key'=f.value->>'key') mapped ON true;
 expected:=private.dpd_pipeline_payload(v.payload)||jsonb_build_object('feeds',feeds);
 IF expected IS DISTINCT FROM _payload THEN RAISE EXCEPTION 'dps.exact_saved_mapping_payload_required' USING ERRCODE='42501';END IF;
 IF _pipeline_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM private.dpd_preview_links WHERE setup_id=_setup_id AND tenant_id=_tenant_id AND pipeline_id=_pipeline_id) THEN RAISE EXCEPTION 'dps.setup_pipeline_binding_required' USING ERRCODE='42501';END IF;
 RETURN private.dps_save_configuration_core(_tenant_id,_pipeline_id,_payload,_owning_business_unit_ids,_sharing_user_group_ids,_request_key);
END $function$
;

CREATE OR REPLACE FUNCTION public.decide_governance_membership_request(_tenant_id uuid, _request_id uuid, _expected_version integer, _decision text, _reason text, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE actor uuid:=auth.uid(); payload jsonb; op private.governance_membership_operations; r public.governance_membership_requests; result jsonb; aid bigint; outcome text;
BEGIN
  IF _request_key IS NULL OR _expected_version IS NULL OR _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 1 AND 2000 OR _decision IS NULL OR _decision NOT IN ('approve','reject') THEN RAISE EXCEPTION 'Decision, current version, reason and request key required' USING ERRCODE='22023'; END IF;
  PERFORM private.governance_membership_lock_scope();
  IF NOT private.governance_membership_active(_tenant_id,actor,true) THEN RAISE EXCEPTION 'Active tenant administrator required' USING ERRCODE='42501'; END IF;
  payload:=jsonb_build_object('operation','decide','request_id',_request_id,'expected_version',_expected_version,'decision',_decision,'reason',btrim(_reason));
  PERFORM pg_advisory_xact_lock(hashtextextended(_tenant_id::text||_request_key::text,0));
  SELECT * INTO op FROM private.governance_membership_operations WHERE tenant_id=_tenant_id AND request_key=_request_key;
  IF FOUND THEN
    IF op.actor_id<>actor OR op.payload<>payload THEN RAISE EXCEPTION 'Request key collision' USING ERRCODE='23505'; END IF;
    RETURN op.result;
  END IF;
  SELECT * INTO r FROM public.governance_membership_requests WHERE tenant_id=_tenant_id AND id=_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Request not found in current tenant' USING ERRCODE='42501'; END IF;
  IF actor=r.requested_by THEN RAISE EXCEPTION 'Independent checker required' USING ERRCODE='42501'; END IF;
  IF r.version<>_expected_version OR r.status<>'pending' THEN RAISE EXCEPTION 'Stale request version or closed request' USING ERRCODE='PT409'; END IF;
  IF _decision='approve' THEN
    IF private.governance_membership_scope(r.tenant_id,r.bu_id,r.workspace_id,r.group_id,r.environment,r.requested_by)<>r.scope_snapshot THEN RAISE EXCEPTION 'Group rights or association changed; renewed request required' USING ERRCODE='PT409'; END IF;
    -- Do not re-grant after an unrelated manual grant/revocation. Require this exact insert.
    INSERT INTO public.tenant_group_members(group_id,user_id,added_by) VALUES(r.group_id,r.requested_by,actor);
    outcome:='grant_confirmed';
  ELSE outcome:='no_access_granted'; END IF;
  UPDATE public.governance_membership_requests SET status=CASE WHEN _decision='approve' THEN 'approved' ELSE 'rejected' END,
    version=version+1,approved_by=actor,decided_at=now(),decision_reason=btrim(_reason) WHERE id=r.id RETURNING * INTO r;
  aid:=private.governance_membership_record(r,'governance.membership.'||_decision,actor,btrim(_reason),outcome);
  result:=jsonb_build_object('id',r.id,'status',r.status,'version',r.version,'correlation_id',r.correlation_id,'audit_id',aid::text,'outcome',outcome);
  INSERT INTO private.governance_membership_operations VALUES(_tenant_id,_request_key,actor,payload,result);
  RETURN result;
END $function$
;

CREATE OR REPLACE FUNCTION private.rs_persist_mixed_binding(_tenant uuid, _definition uuid, _run uuid, _business_date date, _bindings jsonb, _request_key uuid, _expected_definition_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_actor(_tenant); approved jsonb; r public.recon_runs%ROWTYPE; input jsonb;
 d public.data_prep_prepared_datasets%ROWTYPE; u public.workspace_data_source_uploads%ROWTYPE; indexes integer[]; selected_rows jsonb;
BEGIN
 -- No adoption of old/failed/partial runs and no status rewrite to hide errors.
 SELECT * INTO r FROM public.recon_runs WHERE id=_run AND tenant_id=_tenant AND definition_id=_definition FOR UPDATE;
 IF NOT FOUND OR r.run_by IS DISTINCT FROM actor OR r.status<>'queued' OR r.completed_at IS NOT NULL
 OR r.started_at<transaction_timestamp() OR r.matched_count<>0 OR r.exception_count<>0
 OR EXISTS(SELECT 1 FROM public.recon_matches WHERE run_id=r.id) OR EXISTS(SELECT 1 FROM public.recon_exceptions WHERE run_id=r.id)
 THEN RAISE EXCEPTION 'dpw.new_owned_recon_run_required'; END IF;
 approved:=private.rs_mixed_preflight(_tenant,_definition,_business_date,_bindings,_expected_definition_sha256);
 IF r.definition_snapshot IS DISTINCT FROM approved->'snapshot'
 OR r.approved_revision_id IS DISTINCT FROM (approved->>'revision_id')::uuid
 OR r.approved_revision_number IS DISTINCT FROM (approved->>'revision_number')::integer
 OR r.approved_revision_sha256 IS DISTINCT FROM approved->>'snapshot_sha256'
 THEN RAISE EXCEPTION 'dpw.recon_native_approval_snapshot_mismatch'; END IF;
 INSERT INTO public.data_prep_recon_run_requests(recon_run_id,tenant_id,definition_id,created_by,request_key,approved_snapshot,approved_snapshot_sha256,approved_revision_id,approved_revision_number,input_bindings,business_date)
 VALUES(r.id,_tenant,_definition,actor,_request_key,approved->'snapshot',approved->>'snapshot_sha256',(approved->>'revision_id')::uuid,
 (approved->>'revision_number')::integer,_bindings,_business_date);
 FOR input IN SELECT value FROM jsonb_array_elements(_bindings) LOOP
  SELECT * INTO u FROM public.workspace_data_source_uploads WHERE id=(input->>'upload_id')::uuid;
  IF input->>'kind'='prepared_dataset' THEN
   SELECT * INTO d FROM public.data_prep_prepared_datasets WHERE id=(input->>'dataset_id')::uuid;
   indexes:=private.dpw_dataset_indexes(d.id,input->>'logical_side');
   SELECT coalesce(jsonb_agg(u.rows->i ORDER BY i),'[]'::jsonb) INTO selected_rows FROM unnest(indexes) i;
   INSERT INTO public.data_prep_recon_run_inputs VALUES(r.id,input->>'side_id',_tenant,_definition,d.data_source_id,d.upload_id,
   d.id,d.batch_id,d.run_id,d.pipeline_id,d.pipeline_version,d.business_date,'prepared_dataset',d.content_sha256,cardinality(indexes),input->>'logical_side',indexes,private.dpw_hash(selected_rows));
  ELSE
   INSERT INTO public.data_prep_recon_run_inputs VALUES(r.id,input->>'side_id',_tenant,_definition,u.data_source_id,u.id,
   NULL,NULL,NULL,NULL,NULL,NULL,'fixed_upload',u.content_sha256,u.row_count,NULL,NULL,private.dpw_hash(u.rows));
  END IF;
 END LOOP;
 PERFORM private.dpw_audit(actor,_tenant,'dpw.recon.inputs.bind',r.id,jsonb_build_object('definition_id',_definition,'bindings',_bindings,'approved_sha256',_expected_definition_sha256));
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant,'run_id',r.id,'run_uid',r.run_uid,'input_bindings',_bindings,'approved_snapshot',approved->'snapshot','is_new',true);
END $function$
;

CREATE OR REPLACE FUNCTION public.withdraw_governance_membership_request(_tenant_id uuid, _request_id uuid, _expected_version integer, _reason text, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE actor uuid:=auth.uid(); payload jsonb; op private.governance_membership_operations; r public.governance_membership_requests; result jsonb; aid bigint;
BEGIN
  IF _request_key IS NULL OR _expected_version IS NULL OR _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Current version, reason and request key required' USING ERRCODE='22023'; END IF;
  PERFORM private.governance_membership_lock_scope();
  IF NOT private.governance_membership_active(_tenant_id,actor) THEN RAISE EXCEPTION 'Active tenant membership required' USING ERRCODE='42501'; END IF;
  payload:=jsonb_build_object('operation','withdraw','request_id',_request_id,'expected_version',_expected_version,'reason',btrim(_reason));
  PERFORM pg_advisory_xact_lock(hashtextextended(_tenant_id::text||_request_key::text,0));
  SELECT * INTO op FROM private.governance_membership_operations WHERE tenant_id=_tenant_id AND request_key=_request_key;
  IF FOUND THEN
    IF op.actor_id<>actor OR op.payload<>payload THEN RAISE EXCEPTION 'Request key collision' USING ERRCODE='23505'; END IF;
    RETURN op.result;
  END IF;
  SELECT * INTO r FROM public.governance_membership_requests WHERE tenant_id=_tenant_id AND id=_request_id FOR UPDATE;
  IF NOT FOUND OR r.requested_by<>actor THEN RAISE EXCEPTION 'Current requester required' USING ERRCODE='42501'; END IF;
  IF r.version<>_expected_version OR r.status<>'pending' THEN RAISE EXCEPTION 'Stale request version or closed request' USING ERRCODE='PT409'; END IF;
  UPDATE public.governance_membership_requests SET status='withdrawn',version=version+1,approved_by=actor,decided_at=now(),decision_reason=btrim(_reason) WHERE id=r.id RETURNING * INTO r;
  aid:=private.governance_membership_record(r,'governance.membership.withdraw',actor,btrim(_reason),'no_access_granted');
  result:=jsonb_build_object('id',r.id,'status',r.status,'version',r.version,'correlation_id',r.correlation_id,'audit_id',aid::text,'outcome','no_access_granted');
  INSERT INTO private.governance_membership_operations VALUES(_tenant_id,_request_key,actor,payload,result);
  RETURN result;
END $function$
;

CREATE OR REPLACE FUNCTION public.list_governance_membership_requests(_tenant_id uuid, _page integer DEFAULT 1, _page_size integer DEFAULT 25, _search text DEFAULT ''::text, _status text DEFAULT NULL::text, _bu_id uuid DEFAULT NULL::uuid, _environment text DEFAULT NULL::text, _own_only boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb; admin boolean;
BEGIN
  IF NOT private.governance_membership_active(_tenant_id,auth.uid()) THEN RAISE EXCEPTION 'Active tenant membership required' USING ERRCODE='42501'; END IF;
  IF _own_only IS NULL OR _page IS NULL OR _page<1 OR _page>100000 OR _page_size IS NULL OR _page_size NOT BETWEEN 1 AND 100 OR _search IS NULL OR length(_search)>200
     OR _status IS NOT NULL AND _status NOT IN ('pending','approved','rejected','withdrawn')
     OR _environment IS NOT NULL AND _environment NOT IN ('prod','dev','sandbox','uat')
  THEN RAISE EXCEPTION 'Invalid list filter or pagination' USING ERRCODE='22023'; END IF;
  admin:=private.governance_membership_active(_tenant_id,auth.uid(),true);
  WITH visible AS MATERIALIZED (
    SELECT r.*,p.full_name AS requester_name,a.full_name AS approver_name,b.name AS bu_name,
      w.name AS workspace_name,NULL::text AS team_name,g.name AS group_name,
      (admin AND r.requested_by<>auth.uid() AND r.status='pending') AS can_decide,
      (r.requested_by=auth.uid() AND r.status='pending') AS can_withdraw
    FROM public.governance_membership_requests r
      LEFT JOIN public.profiles p ON p.id=r.requested_by
      LEFT JOIN public.profiles a ON a.id=r.approved_by
      LEFT JOIN public.business_units b ON b.id=r.bu_id AND b.tenant_id=r.tenant_id
      LEFT JOIN public.workspaces w ON w.id=r.workspace_id AND w.tenant_id=r.tenant_id
      LEFT JOIN public.tenant_groups g ON g.id=r.group_id AND g.tenant_id=r.tenant_id
    WHERE r.tenant_id=_tenant_id AND (NOT _own_only OR r.requested_by=auth.uid()) AND (_status IS NULL OR r.status=_status)
      AND (_bu_id IS NULL OR r.bu_id=_bu_id) AND (_environment IS NULL OR r.environment=_environment)
      AND (_search='' OR strpos(lower(concat_ws(' ',r.id::text,p.full_name,a.full_name,b.name,w.name,w.department,g.name,r.environment,r.correlation_id::text)),lower(_search))>0)
  ), page_rows AS (
    SELECT * FROM visible ORDER BY requested_at DESC,id DESC OFFSET ((_page-1)*_page_size) LIMIT _page_size
  ) SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY requested_at DESC,id DESC) FROM page_rows p),'[]'::jsonb),
    'total',(SELECT count(*) FROM visible),'page',_page,'page_size',_page_size,
    'kpis',jsonb_build_object('awaiting_decision',(SELECT count(*) FROM visible WHERE status='pending'),
      'approved_last_7_days',(SELECT count(*) FROM visible WHERE status='approved' AND decided_at>=now()-interval '7 days'),
      'independent_checker_needed',(SELECT count(*) FROM visible WHERE status='pending' AND requested_by=auth.uid()),
      'rejected_or_withdrawn',(SELECT count(*) FROM visible WHERE status IN ('rejected','withdrawn'))),
    'permissions',jsonb_build_object('can_submit',true,'can_review_queue',admin)) INTO result;
  RETURN result;
END $function$
;

CREATE OR REPLACE FUNCTION public.get_governance_membership_request(_tenant_id uuid, _request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb; admin boolean;
BEGIN
  IF NOT private.governance_membership_active(_tenant_id,auth.uid()) THEN RAISE EXCEPTION 'Active tenant membership required' USING ERRCODE='42501'; END IF;
  admin:=private.governance_membership_active(_tenant_id,auth.uid(),true);
  SELECT to_jsonb(r)||jsonb_build_object('requester_name',p.full_name,'approver_name',a.full_name,
    'bu_name',b.name,'workspace_name',w.name,'team_name',NULL,'group_name',g.name,
    'effective_scope',r.scope_snapshot,'scope_label',r.scope_snapshot->>'scope_label',
    'membership_active',EXISTS(SELECT 1 FROM public.tenant_group_members gm WHERE gm.group_id=r.group_id AND gm.user_id=r.requested_by),
    'history',coalesce((SELECT jsonb_agg(to_jsonb(e) ORDER BY e.id) FROM public.governance_membership_events e WHERE e.tenant_id=_tenant_id AND e.request_id=r.id),'[]'::jsonb),
    'permissions',jsonb_build_object('can_approve',admin AND r.requested_by<>auth.uid() AND r.status='pending',
      'can_reject',admin AND r.requested_by<>auth.uid() AND r.status='pending','can_withdraw',r.requested_by=auth.uid() AND r.status='pending'))
    INTO result FROM public.governance_membership_requests r
    LEFT JOIN public.profiles p ON p.id=r.requested_by LEFT JOIN public.profiles a ON a.id=r.approved_by
    LEFT JOIN public.business_units b ON b.id=r.bu_id AND b.tenant_id=r.tenant_id
    LEFT JOIN public.workspaces w ON w.id=r.workspace_id AND w.tenant_id=r.tenant_id
    LEFT JOIN public.tenant_groups g ON g.id=r.group_id AND g.tenant_id=r.tenant_id
    WHERE r.tenant_id=_tenant_id AND r.id=_request_id;
  IF result IS NULL THEN RAISE EXCEPTION 'Request not found in authorized scope' USING ERRCODE='42501'; END IF;
  RETURN result;
END $function$
;

CREATE OR REPLACE FUNCTION private.rs_resolve_mixed_bindings(_tenant uuid, _definition uuid, _business_date date, _datasets jsonb, _raw_uploads jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid:=private.rs_actor(_tenant,_definition,'run');d public.recon_definitions%ROWTYPE;v public.recon_definition_approved_versions%ROWTYPE;
 contracts jsonb;s jsonb;c jsonb;dataset public.data_prep_prepared_datasets%ROWTYPE;bindings jsonb:='[]';approved jsonb;chosen_policy private.rs_policies%ROWTYPE;policies integer;logical_side text;
BEGIN
 IF _business_date IS NULL OR jsonb_typeof(_datasets) IS DISTINCT FROM 'object' OR _datasets='{}'::jsonb OR jsonb_typeof(_raw_uploads) IS DISTINCT FROM 'object'
 THEN RAISE EXCEPTION 'rs.explicit_prepared_side_selection_required' USING ERRCODE='22023';END IF;
 v:=private.recon_run_bound_approved_version(_tenant,_definition,actor);
 IF v.id IS NULL THEN RAISE EXCEPTION 'rs.actual_native_approved_snapshot_required' USING ERRCODE='42501';END IF;
 SELECT * INTO d FROM public.recon_definitions WHERE id=_definition AND tenant_id=_tenant;
 contracts:=private.rs_recon_input_contracts(_tenant,_definition,v.id);
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(_datasets||_raw_uploads) k WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v.snapshot->'sides') x WHERE x->>'side_id'=k))
 THEN RAISE EXCEPTION 'rs.unconfigured_prepared_side' USING ERRCODE='22023';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(_raw_uploads) k WHERE _datasets ? k)
 THEN RAISE EXCEPTION 'rs.mixed_side_selection_overlap' USING ERRCODE='22023';END IF;
 FOR s IN SELECT value FROM jsonb_array_elements(v.snapshot->'sides') LOOP
  IF _datasets ? (s->>'side_id') THEN
   SELECT value INTO c FROM jsonb_array_elements(contracts->'input_contracts') WHERE value->>'side_id'=s->>'side_id';
   IF c IS NULL OR jsonb_typeof(c->'fields') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'rs.approved_prepared_side_domains_unavailable' USING ERRCODE='42501';END IF;
   SELECT * INTO dataset FROM public.data_prep_prepared_datasets WHERE id=(_datasets->>(s->>'side_id'))::uuid AND tenant_id=_tenant;
   IF NOT FOUND OR dataset.data_source_id::text IS DISTINCT FROM s->>'data_source_id'
    OR (s ? 'upload_id' AND s->>'upload_id' IS NOT NULL AND s->>'upload_id' IS DISTINCT FROM dataset.upload_id::text)
   THEN RAISE EXCEPTION 'rs.prepared_source_or_approved_pin_conflict' USING ERRCODE='42501';END IF;
   logical_side:=coalesce(c->>'logical_side',private.rs_select_compatible_logical_side(_tenant,dataset.id,c));
   bindings:=bindings||jsonb_build_array(jsonb_build_object('kind','prepared_dataset','side_id',s->>'side_id','data_source_id',s->>'data_source_id','dataset_id',dataset.id,
    'pipeline_id',dataset.pipeline_id,'pipeline_version',dataset.pipeline_version,'upload_id',dataset.upload_id,'logical_side',logical_side));
  ELSE
   IF coalesce(s->>'upload_id',_raw_uploads->>(s->>'side_id')) IS NULL THEN RAISE EXCEPTION 'rs.required_counterpart_unpinned_no_latest_fallback' USING ERRCODE='42501';END IF;
   IF s->>'upload_id' IS NOT NULL AND _raw_uploads ? (s->>'side_id') AND _raw_uploads->>(s->>'side_id') IS DISTINCT FROM s->>'upload_id'
   THEN RAISE EXCEPTION 'rs.fixed_approved_pin_override_refused' USING ERRCODE='42501';END IF;
   bindings:=bindings||jsonb_build_array(jsonb_build_object('kind','fixed_upload','side_id',s->>'side_id','data_source_id',s->>'data_source_id','upload_id',coalesce(s->>'upload_id',_raw_uploads->>(s->>'side_id'))));
  END IF;
 END LOOP;
 -- Exact authoritative intersection: current published dataset, pipeline version,
 -- independent release, source RLP, logical-side output indexes and typed row hash.
 approved:=private.rs_mixed_preflight(_tenant,_definition,_business_date,bindings,v.snapshot_sha256);
 IF approved->>'snapshot_sha256' IS DISTINCT FROM v.snapshot_sha256 OR approved->'reconciliation_feature_enabled' IS DISTINCT FROM 'true'::jsonb
 THEN RAISE EXCEPTION 'rs.actual_native_preflight_required' USING ERRCODE='42501';END IF;
 SELECT count(*) INTO policies FROM private.rs_policies WHERE tenant_id=_tenant AND definition_id=_definition
 AND policy->>'business_date'=_business_date::text AND qualification->>'state'='native_qualified'
 AND qualification->>'approved_definition_sha256'=v.snapshot_sha256;
 IF policies>1 THEN RAISE EXCEPTION 'rs.unambiguous_approved_native_execution_policy_required' USING ERRCODE='42501';END IF;
 IF policies=1 THEN SELECT * INTO chosen_policy FROM private.rs_policies WHERE tenant_id=_tenant AND definition_id=_definition AND policy->>'business_date'=_business_date::text
 AND qualification->>'state'='native_qualified' AND qualification->>'approved_definition_sha256'=v.snapshot_sha256;
 ELSE chosen_policy.policy_id:=v.id;chosen_policy.version:=v.version_number::text;chosen_policy.policy:=jsonb_build_object('business_date',_business_date,'policy_kind','approved_native_input_binding');END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant,'definition_id',d.id,'business_date',_business_date,'revision_id',v.id,'revision_number',v.version_number,
 'expected_definition_sha256',v.snapshot_sha256,'approved_snapshot_sha256',v.snapshot_sha256,'input_bindings',bindings,
 'execution_policy',jsonb_build_object('policy_id',chosen_policy.policy_id,'policy_version',chosen_policy.version,'business_date',chosen_policy.policy->>'business_date','policy_kind',chosen_policy.policy->>'policy_kind'),
 'compatibility','native_current_published_contract_hash_checked','approved_snapshot',approved->'snapshot');
END $function$
;

CREATE OR REPLACE FUNCTION private.rs_validate_prepared_execution(_tenant uuid, _run uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE q private.rs_requests%ROWTYPE;actor uuid;actual jsonb;
BEGIN
 SELECT * INTO q FROM private.rs_requests WHERE tenant_id=_tenant AND run_id=_run AND actor_id=auth.uid();
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.owned_execution_input_required' USING ERRCODE='42501';END IF;
 actor:=private.rs_actor(_tenant,q.definition_id,'run');
 IF q.intent->>'input_kind'='prepared_bound' THEN
  IF q.intent ? 'mixed_selection' THEN actual:=private.rs_mixed_preflight(_tenant,q.definition_id,(q.intent->>'business_date')::date,q.intent->'bindings',q.intent->>'expected_definition_sha256');
  ELSE actual:=private.dpw_recon_preflight(_tenant,q.definition_id,(q.intent->>'business_date')::date,q.intent->'bindings',q.intent->>'expected_definition_sha256');END IF;
  IF actual->>'snapshot_sha256' IS DISTINCT FROM q.intent->>'expected_definition_sha256'
  THEN RAISE EXCEPTION 'rs.current_prepared_execution_contract_changed' USING ERRCODE='42501';END IF;
 END IF;
END $function$
;

CREATE OR REPLACE FUNCTION private.rs_prior_mixed(_tenant uuid, _definition uuid, _date date, _datasets jsonb, _raw jsonb, _key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid:=private.rs_actor(_tenant,_definition,'run');q private.rs_requests%ROWTYPE;selection jsonb;
BEGIN
 selection:=jsonb_build_object('business_date',_date,'prepared_dataset_by_side',_datasets,'raw_upload_by_side',_raw);
 SELECT * INTO q FROM private.rs_requests WHERE tenant_id=_tenant AND definition_id=_definition AND actor_id=actor AND request_key=_key;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF q.intent->'mixed_selection' IS DISTINCT FROM selection THEN RAISE EXCEPTION 'rs.mixed_request_key_conflict' USING ERRCODE='PT409';END IF;
 RETURN private.rs_prior(_tenant,_definition,_key,q.intent);
END $function$
;

CREATE OR REPLACE FUNCTION public.request_recon_mixed_execution(_tenant_id uuid, _definition_id uuid, _business_date date, _prepared_dataset_by_side jsonb, _raw_upload_by_side jsonb, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid:=private.rs_actor(_tenant_id,_definition_id,'run');prior jsonb;resolved jsonb;bindings jsonb;intent jsonb;pins jsonb;r public.recon_runs%ROWTYPE;persisted jsonb;
BEGIN
 IF _request_key IS NULL OR _business_date IS NULL OR jsonb_typeof(_prepared_dataset_by_side) IS DISTINCT FROM 'object'
 OR _prepared_dataset_by_side='{}'::jsonb OR jsonb_typeof(_raw_upload_by_side) IS DISTINCT FROM 'object'
 THEN RAISE EXCEPTION 'rs.explicit_mixed_selection_required' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('rs:'||_tenant_id::text||':'||_definition_id::text,0));
 PERFORM 1 FROM public.recon_definitions WHERE id=_definition_id AND tenant_id=_tenant_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.visible_mixed_definition_required' USING ERRCODE='42501';END IF;
 prior:=private.rs_prior_mixed(_tenant_id,_definition_id,_business_date,_prepared_dataset_by_side,_raw_upload_by_side,_request_key);
 IF prior IS NOT NULL THEN
  PERFORM 1 FROM public.recon_runs WHERE id=(prior->>'run_id')::uuid AND tenant_id=_tenant_id AND run_by=actor;
  IF NOT FOUND THEN RAISE EXCEPTION 'rs.current_original_run_rlp_required' USING ERRCODE='42501';END IF;
  RETURN prior;
 END IF;
 resolved:=private.rs_resolve_mixed_bindings(_tenant_id,_definition_id,_business_date,_prepared_dataset_by_side,_raw_upload_by_side);
 bindings:=resolved->'input_bindings';
 -- Invoker visibility is checked before the same-transaction native INSERT.
 PERFORM 1 FROM public.workspace_data_source_uploads u JOIN jsonb_array_elements(bindings) b ON u.id=(b->>'upload_id')::uuid
 WHERE u.tenant_id=_tenant_id AND u.data_source_id=(b->>'data_source_id')::uuid;
 IF (SELECT count(*) FROM public.workspace_data_source_uploads u JOIN jsonb_array_elements(bindings) b ON u.id=(b->>'upload_id')::uuid
  WHERE u.tenant_id=_tenant_id AND u.data_source_id=(b->>'data_source_id')::uuid)<>jsonb_array_length(bindings)
 THEN RAISE EXCEPTION 'rs.current_mixed_upload_rlp_required' USING ERRCODE='42501';END IF;
 INSERT INTO public.recon_runs(tenant_id,definition_id,status,run_by) VALUES(_tenant_id,_definition_id,'queued',actor) RETURNING * INTO r;
 persisted:=private.rs_persist_mixed_binding(_tenant_id,_definition_id,r.id,_business_date,bindings,_request_key,resolved->>'expected_definition_sha256');
 IF persisted->>'run_id' IS DISTINCT FROM r.id::text OR persisted->>'actor_id' IS DISTINCT FROM actor::text
 THEN RAISE EXCEPTION 'rs.actual_mixed_binding_receipt_required' USING ERRCODE='PT409';END IF;
 SELECT jsonb_agg(jsonb_build_object('side_id',b->>'side_id','upload_id',b->>'upload_id') ORDER BY b->>'side_id') INTO pins FROM jsonb_array_elements(bindings) b;
 intent:=jsonb_build_object('input_kind','prepared_bound','bindings',bindings,'pins',pins,'business_date',_business_date,
  'policy_id',resolved->'execution_policy'->>'policy_id','policy_version',resolved->'execution_policy'->>'policy_version',
  'expected_definition_sha256',resolved->>'expected_definition_sha256','mixed_selection',jsonb_build_object('business_date',_business_date,
   'prepared_dataset_by_side',_prepared_dataset_by_side,'raw_upload_by_side',_raw_upload_by_side));
 RETURN private.rs_store(_tenant_id,r.id,_request_key,intent);
END $function$
;

CREATE OR REPLACE FUNCTION private.governance_review_assert_member(_tenant uuid, _admin boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
BEGIN
 IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated'
    OR NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant AND user_id=auth.uid() AND active)
    OR (_admin AND NOT private.governance_review_is_admin(_tenant)) THEN
   RAISE EXCEPTION 'Current active tenant membership and required authority missing' USING ERRCODE='42501';
 END IF;
END $function$
;

CREATE OR REPLACE FUNCTION private.governance_review_member_option(_input jsonb, _subject uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE t uuid:=(_input->>'tenant_id')::uuid; snap jsonb; group_id uuid:=(_input->>'group_id')::uuid;
BEGIN
 PERFORM private.governance_review_assert_member(t,true);
 snap:=private.governance_review_snapshot(t,_subject,group_id,(_input->>'workspace_id')::uuid);
 RETURN jsonb_build_object('subject_user_id',_subject,'team_name',(SELECT string_agg(t.name,', ' ORDER BY t.name)
   FROM public.teams t JOIN public.team_members tm ON tm.team_id=t.id AND tm.tenant_id=t.tenant_id WHERE t.tenant_id=(_input->>'tenant_id')::uuid AND tm.user_id=_subject AND t.is_active),
   'group_name',snap->'group'->>'name','bu_name',(SELECT string_agg(b->>'name',', ' ORDER BY b->>'name') FROM jsonb_array_elements(snap->'business_units') b),
   'workspace_id',_input->>'workspace_id','workspace_name',snap->'workspace'->>'name',
   'environment',CASE WHEN (SELECT count(DISTINCT r->>'environment') FROM jsonb_array_elements(snap->'resource_grants') r WHERE r->>'environment' IS NOT NULL)=1
     THEN (SELECT min(r->>'environment') FROM jsonb_array_elements(snap->'resource_grants') r) ELSE NULL END,
   'current_rights',snap->'current_rights','snapshot_hash',private.governance_review_hash(snap),'version',1,
   'effective_scope',jsonb_build_object('workspace_context_only',true,'group_membership_scope','tenant group; all existing group grants across workspaces','resource_grants',snap->'resource_grants'));
END $function$
;

CREATE OR REPLACE FUNCTION private.governance_review_list_rows(_tenant uuid)
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
BEGIN
 PERFORM private.governance_review_assert_member(_tenant);
 RETURN QUERY SELECT private.governance_review_row(i)||jsonb_build_object('_campaign_status',c.status,'_created_at',i.created_at)
 FROM public.access_review_items i JOIN public.access_review_campaigns c ON c.id=i.campaign_id AND c.tenant_id=i.tenant_id
 WHERE i.tenant_id=_tenant AND private.governance_review_can_read(i);
END $function$
;

CREATE OR REPLACE FUNCTION public.governance_access_review_decide(_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
 SET lock_timeout TO '5s'
 SET statement_timeout TO '30s'
AS $function$
DECLARE t uuid:=(_input->>'tenant_id')::uuid; actor uuid:=auth.uid(); k uuid:=(_input->>'request_key')::uuid;
 d text:=_input->>'decision'; note text:=btrim(_input->>'reason'); h text;
 receipt public.governance_access_review_receipts%ROWTYPE; i public.access_review_items%ROWTYPE;
 c public.access_review_campaigns%ROWTYPE; snap jsonb; result jsonb; affected int; audit_id bigint;
 correlation uuid:=gen_random_uuid(); event text; outcome text; history jsonb;
BEGIN
 PERFORM private.governance_review_assert_member(t);
 IF k IS NULL OR d IS NULL OR d NOT IN ('retain','request_change','revoke') OR note IS NULL OR length(note) NOT BETWEEN 1 AND 2000
   OR coalesce((_input->>'expected_version')::int,0)<1 OR coalesce(_input->>'snapshot_hash','') !~ '^[a-f0-9]{64}$' THEN
   RAISE EXCEPTION 'Invalid decision' USING ERRCODE='22023'; END IF;
 h:=private.governance_review_hash(jsonb_build_object('operation','decision','input',_input));
 PERFORM pg_advisory_xact_lock(hashtextextended('governance.access_review.'||t::text||k::text,0));
 PERFORM private.governance_review_lock_sources();
 PERFORM private.governance_review_assert_member(t,d<>'request_change');
 SELECT * INTO i FROM public.access_review_items WHERE id=(_input->>'id')::uuid AND tenant_id=t FOR UPDATE;
 SELECT * INTO c FROM public.access_review_campaigns WHERE id=i.campaign_id AND tenant_id=t FOR UPDATE;
 IF i.id IS NULL OR c.id IS NULL OR NOT private.governance_review_can_read(i) OR i.reviewer_id IS DISTINCT FROM actor
   OR c.created_by IS NULL OR c.created_by=actor OR i.subject_user_id=actor THEN
   RAISE EXCEPTION 'Independent current assigned reviewer required' USING ERRCODE='42501'; END IF;
 SELECT * INTO receipt FROM public.governance_access_review_receipts WHERE tenant_id=t AND request_key=k;
 IF FOUND THEN
   IF receipt.actor_id<>actor OR receipt.payload_hash<>h THEN RAISE EXCEPTION 'Request key collision' USING ERRCODE='23505'; END IF;
   RETURN receipt.result;
 END IF;
 IF c.status<>'active' OR i.governance_snapshot IS NULL OR i.governance_outcome NOT IN ('pending','change_requested')
   OR i.governance_version<>(_input->>'expected_version')::int OR i.governance_snapshot_hash<>_input->>'snapshot_hash' THEN
   RAISE EXCEPTION 'Review version/snapshot is stale or not actionable' USING ERRCODE='PT409'; END IF;
 snap:=private.governance_review_snapshot(t,i.subject_user_id,(i.subject_scope->>'group_id')::uuid,(i.subject_scope->>'workspace_id')::uuid);
 IF private.governance_review_hash(snap)<>i.governance_snapshot_hash THEN
   RAISE EXCEPTION 'Current access changed; create a fresh review snapshot' USING ERRCODE='PT409'; END IF;
 IF d='revoke' THEN
   DELETE FROM public.tenant_group_members WHERE group_id=(i.subject_scope->>'group_id')::uuid AND user_id=i.subject_user_id;
   GET DIAGNOSTICS affected=ROW_COUNT;
   IF affected<>1 OR EXISTS(SELECT 1 FROM public.tenant_group_members WHERE group_id=(i.subject_scope->>'group_id')::uuid AND user_id=i.subject_user_id)
     OR EXISTS(SELECT 1 FROM public.effective_user_permissions(i.subject_user_id,t,NULL) p WHERE p.group_id=(i.subject_scope->>'group_id')::uuid) THEN
     RAISE EXCEPTION 'Reviewed membership revocation did not take effect' USING ERRCODE='PT409'; END IF;
 END IF;
 outcome:=CASE d WHEN 'retain' THEN 'retained' WHEN 'revoke' THEN 'revoked' ELSE 'change_requested' END;
 event:=CASE d WHEN 'retain' THEN 'governance.access_review.retain' WHEN 'revoke' THEN 'governance.access_review.revoke' ELSE 'governance.access_review.change_requested' END;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
 VALUES(actor,t,'tenant',event,'access_review_items',i.id::text,jsonb_build_object(
   'review_id',i.id,'campaign_id',c.id,'correlation_id',correlation,'actor_role',CASE WHEN private.governance_review_is_admin(t) THEN 'tenant_admin' ELSE 'assigned_reviewer' END,
   'reason',note,'version',i.governance_version+1,'reviewed_version',i.governance_version,'snapshot_hash',i.governance_snapshot_hash,
   'group_id',i.subject_scope->>'group_id','subject_user_id',i.subject_user_id,'outcome',outcome,'membership_revoked',d='revoke')) RETURNING id INTO audit_id;
 history:=coalesce(i.evidence->'governance_history','[]')||jsonb_build_array(jsonb_build_object(
   'actor_user_id',actor,'action',event,'outcome',outcome,'reason',note,'occurred_at',now(),'version',i.governance_version+1,'audit_id',audit_id,'correlation_id',correlation));
 UPDATE public.access_review_items SET decision=CASE d WHEN 'retain' THEN 'approved' WHEN 'revoke' THEN 'revoked' ELSE 'pending' END,
   governance_outcome=outcome,decision_note=note,decided_at=CASE WHEN d='request_change' THEN NULL ELSE now() END,
   governance_decided_by=actor,governance_correlation_id=correlation,governance_version=governance_version+1,
   evidence=evidence||jsonb_build_object('governance_history',history) WHERE id=i.id RETURNING * INTO i;
 result:=private.governance_review_row(i)||jsonb_build_object('history',history,'snapshot_current',d='request_change',
   'permitted_actions','[]'::jsonb,'membership_revoked',d='revoke',
   'remaining_effective_permissions',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.permission_id,p.source,p.role_id,p.group_id,p.bu_id),'[]') FROM public.effective_user_permissions(i.subject_user_id,t,NULL) p));
 INSERT INTO public.governance_access_review_receipts VALUES(t,k,actor,h,result,now());
 RETURN result;
END $function$
;

CREATE OR REPLACE FUNCTION public.governance_access_review_list(_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE t uuid:=(_input->>'tenant_id')::uuid; p int:=coalesce((_input->>'page')::int,1);
 n int:=coalesce((_input->>'page_size')::int,25); result jsonb;
BEGIN
 IF p<1 OR p>100000 OR n<1 OR n>100 OR length(coalesce(_input->>'search',''))>160
   OR (_input->>'outcome' IS NOT NULL AND _input->>'outcome' NOT IN ('pending','retained','change_requested','revoked','historical_unknown')) THEN
   RAISE EXCEPTION 'Invalid list bounds/filter' USING ERRCODE='22023'; END IF;
 WITH scoped AS MATERIALIZED (
   SELECT r->>'id' id,r->>'campaign_id' campaign_id,r->>'_campaign_status' campaign_status,
     (r->>'due_at')::timestamptz due_at,(r->>'_created_at')::timestamptz created_at,
     r->>'outcome' governance_outcome,(r->>'decided_at')::timestamptz decided_at,
     (r-'_campaign_status'-'_created_at')||jsonb_build_object('member_name',member.full_name,'reviewer_name',reviewer.full_name) row
   FROM private.governance_review_list_rows(t) AS source(r)
   LEFT JOIN public.profiles member ON member.id=(r->>'subject_user_id')::uuid
   LEFT JOIN public.profiles reviewer ON reviewer.id=(r->>'reviewer_id')::uuid
   WHERE (_input->>'campaign_id' IS NULL OR (r->>'campaign_id')::uuid=(_input->>'campaign_id')::uuid)
     AND (_input->>'reviewer_id' IS NULL OR (r->>'reviewer_id')::uuid=(_input->>'reviewer_id')::uuid)
     AND (_input->>'outcome' IS NULL OR r->>'outcome'=_input->>'outcome')
 ), filtered AS MATERIALIZED (
   SELECT * FROM scoped WHERE coalesce(_input->>'search','')='' OR position(lower(_input->>'search') IN lower(row::text))>0
 ), paged AS (SELECT * FROM filtered ORDER BY created_at DESC,id DESC LIMIT n OFFSET (p-1)*n)
 SELECT jsonb_build_object('rows',(SELECT coalesce(jsonb_agg(row ORDER BY created_at DESC,id DESC),'[]') FROM paged),
   'total',(SELECT count(*) FROM filtered),'page',p,'page_size',n,'kpis',jsonb_build_object(
    'open_campaigns',(SELECT count(DISTINCT campaign_id) FROM filtered WHERE campaign_status='active'),
    'memberships_to_review',(SELECT count(*) FROM filtered WHERE governance_outcome IN ('pending','change_requested')),
    'overdue_decisions',(SELECT count(*) FROM filtered WHERE governance_outcome IN ('pending','change_requested') AND due_at<now()),
    'completed_last_30_days',(SELECT count(*) FROM filtered WHERE governance_outcome IN ('retained','revoked') AND decided_at>=now()-interval '30 days')),
   'permissions',jsonb_build_object('can_create_campaign',private.governance_review_is_admin(t),'can_decide',private.governance_review_is_admin(t))) INTO result;
 RETURN result;
END $function$
;

CREATE OR REPLACE FUNCTION public.governance_access_review_options(_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE p int:=coalesce((_input->>'page')::int,1); n int:=coalesce((_input->>'page_size')::int,25); result jsonb;
BEGIN
 IF p<1 OR p>100000 OR n<1 OR n>100 OR length(coalesce(_input->>'search',''))>160 THEN RAISE EXCEPTION 'Invalid option bounds' USING ERRCODE='22023'; END IF;
 WITH eligible AS MATERIALIZED (
   SELECT x.id,coalesce(x.label,profile.full_name) label,x.group_id FROM private.governance_review_options_scope(_input) x
   LEFT JOIN public.profiles profile ON profile.id=x.id AND _input->>'kind' IN ('members','reviewers')
 ), filtered AS MATERIALIZED (SELECT * FROM eligible WHERE coalesce(_input->>'search','')=''
   OR position(lower(_input->>'search') IN lower(coalesce(label,'')||' '||id::text))>0),
 paged AS (SELECT * FROM filtered ORDER BY label NULLS LAST,id LIMIT n OFFSET (p-1)*n)
 SELECT jsonb_build_object('rows',(SELECT coalesce(jsonb_agg(to_jsonb(x)||CASE WHEN _input->>'kind'='members'
     THEN private.governance_review_member_option(_input,x.id)||jsonb_build_object('member_name',x.label) ELSE '{}'::jsonb END ORDER BY x.label NULLS LAST,x.id),'[]') FROM paged x),
   'total',(SELECT count(*) FROM filtered),'page',p,'page_size',n) INTO result;
 RETURN result;
END $function$
;

CREATE OR REPLACE FUNCTION public.governance_access_review_campaign_create(_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
 SET lock_timeout TO '5s'
 SET statement_timeout TO '30s'
AS $function$
DECLARE t uuid:=(_input->>'tenant_id')::uuid; actor uuid:=auth.uid(); k uuid:=(_input->>'request_key')::uuid;
 h text; receipt public.governance_access_review_receipts%ROWTYPE; campaign uuid; item uuid;
 entry jsonb; snap jsonb; ids jsonb:='[]'; result jsonb; correlation uuid:=gen_random_uuid();
BEGIN
 PERFORM private.governance_review_assert_member(t,true);
 IF k IS NULL OR length(btrim(coalesce(_input->>'name',''))) NOT BETWEEN 1 AND 160
   OR length(coalesce(_input->>'description',''))>1000 OR jsonb_typeof(_input->'memberships') IS DISTINCT FROM 'array'
   OR jsonb_array_length(_input->'memberships') NOT BETWEEN 1 AND 200 OR _input->>'due_at' IS NULL THEN
   RAISE EXCEPTION 'Invalid campaign' USING ERRCODE='22023'; END IF;
 h:=private.governance_review_hash(jsonb_build_object('operation','campaign.create','input',_input));
 PERFORM pg_advisory_xact_lock(hashtextextended('governance.access_review.'||t::text||k::text,0));
 SELECT * INTO receipt FROM public.governance_access_review_receipts WHERE tenant_id=t AND request_key=k;
 IF FOUND THEN
   IF receipt.actor_id<>actor OR receipt.payload_hash<>h THEN RAISE EXCEPTION 'Request key collision' USING ERRCODE='23505'; END IF;
   RETURN receipt.result;
 END IF;
 IF (_input->>'due_at')::timestamptz<=now() THEN RAISE EXCEPTION 'Due date must be in the future' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(_input->'memberships') e GROUP BY e->>'subject_user_id',e->>'group_id' HAVING count(*)>1) THEN
   RAISE EXCEPTION 'Duplicate membership' USING ERRCODE='22023'; END IF;
 PERFORM private.governance_review_lock_sources();
 PERFORM private.governance_review_assert_member(t,true);
 INSERT INTO public.access_review_campaigns(tenant_id,name,description,scope,status,starts_at,due_at,created_by,metadata)
 VALUES(t,btrim(_input->>'name'),_input->>'description','tenant','active',now(),(_input->>'due_at')::timestamptz,actor,
   jsonb_build_object('governance_schema_version',1,'correlation_id',correlation)) RETURNING id INTO campaign;
 FOR entry IN SELECT value FROM jsonb_array_elements(_input->'memberships') LOOP
   IF (entry->>'reviewer_id')::uuid IS NULL OR (entry->>'reviewer_id')::uuid IN (actor,(entry->>'subject_user_id')::uuid)
     OR NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=t AND user_id=(entry->>'reviewer_id')::uuid AND active AND role::text='tenant_admin') THEN
     RAISE EXCEPTION 'An independent active tenant-admin reviewer is required' USING ERRCODE='42501'; END IF;
   snap:=private.governance_review_snapshot(t,(entry->>'subject_user_id')::uuid,(entry->>'group_id')::uuid,(entry->>'workspace_id')::uuid);
   IF entry->>'snapshot_hash' IS NOT NULL AND entry->>'snapshot_hash' IS DISTINCT FROM private.governance_review_hash(snap) THEN
     RAISE EXCEPTION 'Selected membership rights changed; refresh the option snapshot' USING ERRCODE='PT409'; END IF;
   INSERT INTO public.access_review_items(campaign_id,tenant_id,subject_user_id,subject_role,subject_scope,reviewer_id,
     decision,governance_snapshot,governance_snapshot_hash,governance_outcome,governance_correlation_id)
   VALUES(campaign,t,(entry->>'subject_user_id')::uuid,'tenant_group_member',
     jsonb_build_object('group_id',entry->>'group_id','workspace_id',entry->>'workspace_id'),(entry->>'reviewer_id')::uuid,
     'pending',snap,private.governance_review_hash(snap),'pending',correlation) RETURNING id INTO item;
   IF NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=t AND user_id=(entry->>'reviewer_id')::uuid AND active AND role::text='tenant_admin')
     AND NOT EXISTS(SELECT 1 FROM public.tenant_group_members WHERE user_id=(entry->>'reviewer_id')::uuid AND group_id=(entry->>'group_id')::uuid) THEN
     RAISE EXCEPTION 'Reviewer lacks current group scope' USING ERRCODE='42501'; END IF;
   ids:=ids||jsonb_build_array(item);
 END LOOP;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
 VALUES(actor,t,'tenant','governance.access_review.campaign.create','access_review_campaigns',campaign::text,
   jsonb_build_object('correlation_id',correlation,'actor_role','tenant_admin','outcome','active','version',1,'item_ids',ids,'due_at',_input->>'due_at'));
 result:=jsonb_build_object('campaign_id',campaign,'item_ids',ids,'correlation_id',correlation);
 INSERT INTO public.governance_access_review_receipts VALUES(t,k,actor,h,result,now());
 RETURN result;
END $function$
;

CREATE OR REPLACE FUNCTION public.governance_access_review_get(_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE t uuid:=(_input->>'tenant_id')::uuid; i public.access_review_items%ROWTYPE;
 c public.access_review_campaigns%ROWTYPE; fresh boolean:=false; actions jsonb:='[]';
BEGIN
 PERFORM private.governance_review_assert_member(t);
 SELECT * INTO i FROM public.access_review_items WHERE id=(_input->>'id')::uuid AND tenant_id=t;
 IF i.id IS NULL OR NOT private.governance_review_can_read(i) THEN RAISE EXCEPTION 'Review unavailable in current scope' USING ERRCODE='42501'; END IF;
 SELECT * INTO c FROM public.access_review_campaigns WHERE id=i.campaign_id AND tenant_id=t;
 IF i.governance_snapshot IS NOT NULL AND i.governance_outcome IN ('pending','change_requested') THEN
   BEGIN
     fresh:=private.governance_review_hash(private.governance_review_snapshot(t,i.subject_user_id,(i.subject_scope->>'group_id')::uuid,(i.subject_scope->>'workspace_id')::uuid))=i.governance_snapshot_hash;
   EXCEPTION WHEN SQLSTATE 'PT409' THEN fresh:=false; END;
 END IF;
 IF fresh AND c.status='active' AND i.reviewer_id=auth.uid() AND c.created_by<>auth.uid() AND i.subject_user_id<>auth.uid() THEN
   actions:=CASE WHEN private.governance_review_is_admin(t) THEN '["retain","request_change","revoke"]'::jsonb ELSE '["request_change"]'::jsonb END;
 END IF;
 RETURN private.governance_review_row(i)||jsonb_build_object('history',coalesce(i.evidence->'governance_history','[]'),
   'snapshot_current',fresh,'permitted_actions',actions);
END $function$
;

CREATE OR REPLACE FUNCTION private.dps_manifest(_tenant uuid, _pipeline uuid, _configuration uuid, _owners uuid[], _groups uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE actor uuid:=private.dps_admin(_tenant);cfg public.data_prep_configuration_revisions%ROWTYPE;p public.data_prep_pipelines%ROWTYPE;source uuid;g uuid;registry uuid;result jsonb:='[]';item jsonb;
BEGIN
 PERFORM private.dpw_authorize(_tenant,_pipeline,'edit');PERFORM private.dps_selections(_tenant,_owners,_groups);
 SELECT * INTO cfg FROM public.data_prep_configuration_revisions WHERE id=_configuration AND tenant_id=_tenant AND pipeline_id=_pipeline;
 SELECT * INTO p FROM public.data_prep_pipelines WHERE id=_pipeline AND tenant_id=_tenant;
 IF cfg.id IS NULL OR p.id IS NULL OR p.version<>cfg.pipeline_version OR p.lifecycle_state='archived' OR p.status='archived'
 OR NOT EXISTS(SELECT 1 FROM private.dpw_configuration_heads WHERE pipeline_id=p.id AND configuration_id=cfg.id)
 THEN RAISE EXCEPTION 'dps.configuration_not_current' USING ERRCODE='42501';END IF;
 FOR source IN SELECT DISTINCT (value->>'data_source_id')::uuid FROM jsonb_array_elements(cfg.payload->'feeds') LOOP
  IF private.dpw_source_allows(actor,_tenant,source,'view') IS DISTINCT FROM true OR private.dpw_source_allows(actor,_tenant,source,'ingest') IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'dps.creator_source_denied' USING ERRCODE='42501';END IF;
  SELECT id INTO registry FROM public.data_resource_registry WHERE tenant_id=_tenant AND resource_type='data_source' AND data_source_id=source;
  IF registry IS NULL THEN RAISE EXCEPTION 'dps.registered_input_scope_required' USING ERRCODE='42501';END IF;
  FOREACH g IN ARRAY _groups LOOP
   IF NOT EXISTS(SELECT 1 FROM public.data_resource_registry_grants grant_row
    JOIN public.data_resource_registry_owner_bu owner ON owner.tenant_id=grant_row.tenant_id AND owner.registry_id=grant_row.registry_id AND owner.bu_id=grant_row.bu_id
    WHERE grant_row.registry_id=registry AND grant_row.tenant_id=_tenant AND grant_row.action='view' AND grant_row.principal_type='group' AND grant_row.principal_group_id=g
    AND cardinality(private.dps_group_bus(_tenant,g,ARRAY[owner.bu_id]))>0)
   THEN
    IF private.dps_owned_draft_input(_tenant,source,cfg.id) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dps.group_input_view_ceiling_denied' USING ERRCODE='42501';END IF;
    IF NOT EXISTS(SELECT 1 FROM public.data_resource_registry_owner_bu o WHERE o.registry_id=registry AND o.tenant_id=_tenant AND cardinality(private.dps_group_bus(_tenant,g,ARRAY[o.bu_id]))>0) THEN RAISE EXCEPTION 'dps.owned_input_group_bu_denied' USING ERRCODE='42501';END IF;
   END IF;
  END LOOP;
  SELECT jsonb_build_object('kind','input','source_id',source,'registry_id',registry,'owned_draft_input',private.dps_owned_draft_input(_tenant,source,cfg.id),'owned_originals',coalesce((SELECT jsonb_agg(jsonb_build_object('file_id',original.id,'setup_id',original.setup_id,'content_sha256',original.content_sha256,'verified_original_sha256',receipt.verified_original_sha256,'verified_size_bytes',receipt.verified_size_bytes::text,'source_request_key',raw.source_request_key,'ownership_request_key',raw.ownership_request_key) ORDER BY original.id) FROM private.dpd_raw_source_links raw JOIN private.dpd_original_intents original ON original.id=raw.file_id JOIN private.dpd_original_receipts receipt ON receipt.file_id=original.id WHERE raw.data_source_id=source AND raw.tenant_id=_tenant),'[]'),
   'owners',coalesce((SELECT jsonb_agg(to_jsonb(o) ORDER BY o.bu_id) FROM public.data_resource_registry_owner_bu o WHERE o.registry_id=registry AND o.tenant_id=_tenant),'[]'),
   'group_view_grants',coalesce((SELECT jsonb_agg(to_jsonb(v) ORDER BY v.id) FROM public.data_resource_registry_grants v WHERE v.registry_id=registry AND v.tenant_id=_tenant AND v.principal_group_id=ANY(_groups) AND v.action='view'),'[]')) INTO item;
  result:=result||jsonb_build_array(item);
 END LOOP;
 IF private.dpw_source_allows(actor,_tenant,p.output_data_source_id,'edit') IS DISTINCT FROM true OR private.dpw_source_allows(actor,_tenant,p.output_data_source_id,'ingest') IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'dps.output_writer_ceiling_denied' USING ERRCODE='42501';END IF;
 FOR registry IN SELECT id FROM public.data_resource_registry WHERE tenant_id=_tenant AND (data_prep_pipeline_id=p.id OR data_source_id=p.output_data_source_id) ORDER BY id LOOP
  SELECT jsonb_build_object('kind',CASE WHEN r.data_prep_pipeline_id IS NOT NULL THEN 'pipeline' ELSE 'output' END,'registry_id',r.id,
   'owners',coalesce((SELECT jsonb_agg(to_jsonb(o) ORDER BY o.bu_id) FROM public.data_resource_registry_owner_bu o WHERE o.registry_id=r.id AND o.tenant_id=_tenant),'[]'),
   'grants',coalesce((SELECT jsonb_agg(to_jsonb(v) ORDER BY v.id) FROM public.data_resource_registry_grants v WHERE v.registry_id=r.id AND v.tenant_id=_tenant),'[]')) INTO item
  FROM public.data_resource_registry r WHERE r.id=registry;
  result:=result||jsonb_build_array(item);
 END LOOP;
 IF (SELECT count(*) FROM jsonb_array_elements(result) x WHERE x->>'kind' IN('pipeline','output'))<>2 THEN RAISE EXCEPTION 'dps.pipeline_output_registry_required' USING ERRCODE='42501';END IF;
 RETURN result||jsonb_build_array(jsonb_build_object('kind','selection_catalog',
 'groups',coalesce((SELECT jsonb_agg(to_jsonb(group_header) ORDER BY group_header.id) FROM public.tenant_groups group_header WHERE group_header.tenant_id=_tenant AND group_header.id=ANY(_groups)),'[]'),
 'group_bu_assignments',coalesce((SELECT jsonb_agg(to_jsonb(a) ORDER BY a.group_id,a.bu_id) FROM public.bu_group_assignments a WHERE a.tenant_id=_tenant AND a.group_id=ANY(_groups)),'[]'),
 'business_units',coalesce((SELECT jsonb_agg(to_jsonb(b) ORDER BY b.id) FROM public.business_units b WHERE b.tenant_id=_tenant),'[]')));
END $function$
;

CREATE OR REPLACE FUNCTION private.ssb_actor(_tenant uuid, _bu uuid, _create boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.wfm_actor(_tenant);
BEGIN
 -- Bare WFM actor attests actual account/factor/expiry without a Prep circular
 -- dependency. The feature checks apply to this Data Prep bootstrap purpose.
 PERFORM private.wfm_assert_enabled(_tenant,'prep');PERFORM private.wfm_assert_enabled(_tenant,'data');
 IF NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant AND user_id=actor AND active)
 OR (_bu IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.business_units WHERE tenant_id=_tenant AND id=_bu AND is_archived IS NOT TRUE))
 THEN RAISE EXCEPTION 'ssb.current_tenant_bu_denied' USING ERRCODE='42501';END IF;
 IF _create AND public.user_has_permission(actor,_tenant,'data.source.create',_bu) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'ssb.source_create_permission_required' USING ERRCODE='42501';END IF;
 RETURN actor;
END $function$
;

CREATE OR REPLACE FUNCTION private.ssb_guard_upload()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN IF EXISTS(SELECT 1 FROM private.ssb_create_receipts WHERE tenant_id=NEW.tenant_id AND source_id=NEW.data_source_id)
 AND private.ssb_is_mapped(NEW.tenant_id,NEW.data_source_id) IS DISTINCT FROM true THEN RAISE EXCEPTION 'ssb.ownership_pending_source_use_denied' USING ERRCODE='42501';END IF;RETURN NEW;END $function$
;

CREATE OR REPLACE FUNCTION public.ssb_authorize_create(_tenant_id uuid, _bu_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.ssb_actor(_tenant_id,_bu_id,true);
BEGIN RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'bu_id',_bu_id,'auth_role',auth.role(),
 'can_create',true,'can_save_ownership',private.ssb_is_admin(actor,_tenant_id),'ownership_policy','actual_active_tenant_admin',
 'source_create_permission','data.source.create','source_id_origin','native_generated','request_key_required',true);END $function$
;

CREATE OR REPLACE FUNCTION public.ssb_create_source(_tenant_id uuid, _bu_id uuid, _name text, _description text, _source_type text, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.ssb_actor(_tenant_id,_bu_id,true);r private.ssb_create_receipts%ROWTYPE;s public.workspace_data_sources%ROWTYPE;
 canonical jsonb;aid bigint;
BEGIN
 IF _request_key IS NULL OR length(coalesce(btrim(_name),'')) NOT BETWEEN 2 AND 80 OR length(coalesce(_description,''))>500
 OR _source_type IS NULL OR _source_type NOT IN('csv','xlsx','json','api','database','manual') THEN RAISE EXCEPTION 'ssb.invalid_source_request' USING ERRCODE='22023';END IF;
 canonical:=jsonb_build_object('tenant_id',_tenant_id,'bu_id',_bu_id,'name',btrim(_name),'description',_description,'source_type',_source_type);
 PERFORM pg_advisory_xact_lock(hashtextextended('ssb:'||_tenant_id::text||':'||actor::text||':'||_request_key::text,0));
 SELECT * INTO r FROM private.ssb_create_receipts WHERE tenant_id=_tenant_id AND actor_id=actor AND request_key=_request_key;
 IF FOUND THEN
  IF r.input IS DISTINCT FROM canonical OR r.input_sha256 IS DISTINCT FROM private.dpw_hash(canonical) THEN RAISE EXCEPTION 'ssb.request_conflict' USING ERRCODE='PT409';END IF;
  RETURN private.ssb_status(actor,_tenant_id,r.source_id)||jsonb_build_object('is_new',false);
 END IF;
 INSERT INTO public.workspace_data_sources(tenant_id,bu_id,name,description,source_type,connection_config,inferred_schema,sample_rows,row_count,status,created_by)
 VALUES(_tenant_id,_bu_id,btrim(_name),_description,_source_type,'{}','[]','[]',0,'draft',actor) RETURNING * INTO s;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
 VALUES(actor,_tenant_id,'workspace','data_source.bootstrap.create','workspace_data_source',s.id::text,
 jsonb_build_object('request_key',_request_key,'bu_id',_bu_id,'name',s.name,'source_type',s.source_type,'ownership_policy','actual_active_tenant_admin')) RETURNING id INTO aid;
 INSERT INTO private.ssb_create_receipts(tenant_id,actor_id,request_key,source_id,bu_id,input,input_sha256,audit_event_id)
 VALUES(_tenant_id,actor,_request_key,s.id,_bu_id,canonical,private.dpw_hash(canonical),aid);
 RETURN private.ssb_status(actor,_tenant_id,s.id)||jsonb_build_object('is_new',true);
END $function$
;

CREATE OR REPLACE FUNCTION private.fvi_structure_write_context(_tenant uuid, _actor uuid, _executor name, _depth integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
BEGIN
 IF _actor IS DISTINCT FROM auth.uid() THEN RETURN false;END IF;
 IF private.fvi_active_structure_admin(_tenant,_actor) THEN RETURN true;END IF;
 IF auth.role()='service_role' AND _executor IN ('service_role','postgres','supabase_admin') THEN RETURN true;END IF;
 IF auth.role() IS NULL AND _executor IN ('postgres','supabase_admin') THEN RETURN true;END IF;
 -- Only the existing nested new-tenant bootstrap, not a caller-controlled GUC.
 IF auth.role()='authenticated' AND _executor IN ('postgres','supabase_admin') AND _depth>1
   AND public.is_platform_admin(_actor) IS TRUE
   AND EXISTS(SELECT 1 FROM public.tenants t WHERE t.id=_tenant AND t.xmin=pg_current_xact_id()::xid)
 THEN RETURN true;END IF;
 RETURN false;
END $function$
;

CREATE OR REPLACE FUNCTION private.fvi_bu_structure_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
BEGIN
 IF NOT private.fvi_structure_write_context(NEW.tenant_id,auth.uid(),current_user,pg_trigger_depth()) THEN
   RAISE EXCEPTION 'Active tenant administrator required for business-unit writes' USING ERRCODE='42501';END IF;
 IF TG_OP='UPDATE' AND NEW.tenant_id=OLD.tenant_id AND NEW.parent_id IS NOT DISTINCT FROM OLD.parent_id THEN RETURN NEW;END IF;
 IF NEW.parent_id IS NOT NULL THEN
   PERFORM 1 FROM public.business_units b WHERE b.id=NEW.parent_id AND b.tenant_id=NEW.tenant_id AND NOT b.is_archived FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'Parent business unit must be active in this tenant' USING ERRCODE='22023';END IF;
 END IF;
 RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION private.fvi_group_structure_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
BEGIN
 IF NOT private.fvi_structure_write_context(NEW.tenant_id,auth.uid(),current_user,pg_trigger_depth()) THEN
   RAISE EXCEPTION 'Active tenant administrator required for group writes' USING ERRCODE='42501';END IF;
 IF TG_OP='UPDATE' AND NEW.tenant_id=OLD.tenant_id AND NEW.bu_id IS NOT DISTINCT FROM OLD.bu_id THEN RETURN NEW;END IF;
 IF NEW.bu_id IS NULL THEN RAISE EXCEPTION 'Every new or reassociated group requires a business unit' USING ERRCODE='22023';END IF;
 PERFORM 1 FROM public.business_units b WHERE b.id=NEW.bu_id AND b.tenant_id=NEW.tenant_id AND NOT b.is_archived FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Group business unit must be active in this tenant' USING ERRCODE='22023';END IF;
 RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.ssb_find_sources(_tenant_id uuid, _search text, _page integer DEFAULT 1, _page_size integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.ssb_actor(_tenant_id,NULL,false);off integer:=private.dpw_page(_page,_page_size);result jsonb;
BEGIN
 IF public.user_has_permission(actor,_tenant_id,'data.source.read',NULL) IS DISTINCT FROM true OR length(coalesce(_search,''))>120 THEN RAISE EXCEPTION 'ssb.source_catalog_read_denied' USING ERRCODE='42501';END IF;
 WITH allowed AS(SELECT s.* FROM public.workspace_data_sources s WHERE s.tenant_id=_tenant_id AND s.status<>'archived'
 AND (_search IS NULL OR position(lower(_search) IN lower(s.name))>0)
 AND private.ssb_is_mapped(_tenant_id,s.id) AND private.registered_typed_resource_allows(actor,_tenant_id,'data_source',s.id,'view') IS TRUE),
 paged AS(SELECT * FROM allowed ORDER BY name,id LIMIT _page_size OFFSET off)
 SELECT jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'rows',coalesce((SELECT jsonb_agg(private.ssb_source_metadata(s) ORDER BY name,id) FROM paged s),'[]'),
 'total',(SELECT count(*) FROM allowed),'page',_page,'page_size',_page_size,'catalog_match_is_request_confirmation',false) INTO result;
 RETURN result;
END $function$
;

CREATE OR REPLACE FUNCTION public.ssb_get_create_request(_tenant_id uuid, _bu_id uuid, _request_key uuid, _expected_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.ssb_actor(_tenant_id,_bu_id,true);r private.ssb_create_receipts%ROWTYPE;
BEGIN
 IF _request_key IS NULL OR jsonb_typeof(_expected_input) IS DISTINCT FROM 'object' OR _expected_input->>'tenant_id' IS DISTINCT FROM _tenant_id::text
 OR _expected_input->>'bu_id' IS DISTINCT FROM _bu_id::text THEN RAISE EXCEPTION 'ssb.lookup_scope_mismatch' USING ERRCODE='PT409';END IF;
 SELECT * INTO r FROM private.ssb_create_receipts WHERE tenant_id=_tenant_id AND actor_id=actor AND request_key=_request_key;
 IF NOT FOUND THEN RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'request_key',_request_key,'lookup_state','absent');END IF;
 IF r.input IS DISTINCT FROM _expected_input OR r.input_sha256 IS DISTINCT FROM private.dpw_hash(_expected_input) THEN RAISE EXCEPTION 'ssb.request_conflict' USING ERRCODE='PT409';END IF;
 RETURN private.ssb_status(actor,_tenant_id,r.source_id)||jsonb_build_object('lookup_state','found','is_new',false);
END $function$
;

CREATE OR REPLACE FUNCTION public.ssb_get_ownership_request(_tenant_id uuid, _source_id uuid, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.ssb_actor(_tenant_id,NULL,false);r private.ssb_ownership_receipts%ROWTYPE;state jsonb;
BEGIN
 IF private.ssb_is_admin(actor,_tenant_id) IS DISTINCT FROM true OR _request_key IS NULL THEN RAISE EXCEPTION 'ssb.actual_tenant_admin_ownership_required' USING ERRCODE='42501';END IF;
 state:=private.ssb_status(actor,_tenant_id,_source_id);
 SELECT * INTO r FROM private.ssb_ownership_receipts WHERE tenant_id=_tenant_id AND actor_id=actor AND request_key=_request_key;
 IF NOT FOUND THEN RETURN state||jsonb_build_object('lookup_state','absent','request_key',_request_key);END IF;
 IF r.source_id IS DISTINCT FROM _source_id THEN RAISE EXCEPTION 'ssb.request_conflict' USING ERRCODE='PT409';END IF;
 RETURN state||jsonb_build_object('lookup_state','found','request_key',_request_key,'recorded_ownership',r.actual_editor,
 'ownership',public.get_typed_data_resource_editor(_tenant_id,'data_source',_source_id));
END $function$
;

CREATE OR REPLACE FUNCTION private.ssb_is_admin(_actor uuid, _tenant uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 SELECT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant AND user_id=_actor AND active AND role='tenant_admin'::public.tenant_role)
$function$
;

CREATE OR REPLACE FUNCTION private.ssb_is_mapped(_tenant uuid, _source uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 SELECT EXISTS(SELECT 1 FROM public.data_resource_registry r JOIN public.data_resource_registry_owner_bu o ON o.registry_id=r.id AND o.tenant_id=r.tenant_id
 JOIN public.business_units b ON b.id=o.bu_id AND b.tenant_id=o.tenant_id AND b.is_archived IS NOT TRUE
 WHERE r.tenant_id=_tenant AND r.resource_type='data_source' AND r.data_source_id=_source)
$function$
;

CREATE OR REPLACE FUNCTION public.ssb_read_ownership(_tenant_id uuid, _source_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.ssb_actor(_tenant_id,NULL,false);state jsonb;editor jsonb;registry uuid;
BEGIN
 state:=private.ssb_status(actor,_tenant_id,_source_id);
 IF private.ssb_is_admin(actor,_tenant_id) THEN
  editor:=public.get_typed_data_resource_editor(_tenant_id,'data_source',_source_id);
 ELSE
  -- Read actual mappings, not the administrator's full tenant/group catalog.
  SELECT id INTO registry FROM public.data_resource_registry WHERE tenant_id=_tenant_id AND resource_type='data_source' AND data_source_id=_source_id;
  editor:=jsonb_build_object('registered',private.ssb_is_mapped(_tenant_id,_source_id),
   'owner_bu_ids',coalesce((SELECT jsonb_agg(bu_id ORDER BY bu_id) FROM public.data_resource_registry_owner_bu WHERE tenant_id=_tenant_id AND registry_id=registry),'[]'),
   'group_ids',coalesce((SELECT jsonb_agg(gid ORDER BY gid) FROM(SELECT DISTINCT principal_group_id gid FROM public.data_resource_registry_grants WHERE tenant_id=_tenant_id AND registry_id=registry AND principal_type='group' AND action='view') g),'[]'),
   'business_units','[]'::jsonb,'user_groups','[]'::jsonb,'read_only',true);
 END IF;
 RETURN state||jsonb_build_object('ownership',editor);
END $function$
;

CREATE OR REPLACE FUNCTION public.ssb_read_source(_tenant_id uuid, _source_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.ssb_actor(_tenant_id,NULL,false);state jsonb;
BEGIN state:=private.ssb_status(actor,_tenant_id,_source_id);
 IF state->'can_bind' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'ssb.registered_current_source_view_required' USING ERRCODE='42501';END IF;
 RETURN state;END $function$
;

CREATE OR REPLACE FUNCTION public.ssb_save_ownership(_tenant_id uuid, _source_id uuid, _owner_bu_ids uuid[], _group_ids uuid[], _reason text, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.ssb_actor(_tenant_id,NULL,false);before_state jsonb;saved jsonb;after_state jsonb;canonical jsonb;r private.ssb_ownership_receipts%ROWTYPE;aid bigint;
BEGIN
 IF private.ssb_is_admin(actor,_tenant_id) IS DISTINCT FROM true THEN RAISE EXCEPTION 'ssb.actual_tenant_admin_ownership_required' USING ERRCODE='42501';END IF;
 IF _request_key IS NULL OR length(coalesce(btrim(_reason),'')) NOT BETWEEN 3 AND 1000 THEN RAISE EXCEPTION 'ssb.invalid_ownership_request' USING ERRCODE='22023';END IF;
 canonical:=jsonb_build_object('source_id',_source_id,'owner_bu_ids',(SELECT jsonb_agg(x ORDER BY x) FROM(SELECT DISTINCT unnest(_owner_bu_ids) x) ids),
 'group_ids',coalesce((SELECT jsonb_agg(x ORDER BY x) FROM(SELECT DISTINCT unnest(_group_ids) x) ids),'[]'),'reason',btrim(_reason));
 PERFORM pg_advisory_xact_lock(hashtextextended('ssb-ownership:'||_tenant_id::text||':'||actor::text||':'||_request_key::text,0));
 before_state:=private.ssb_status(actor,_tenant_id,_source_id);
 SELECT * INTO r FROM private.ssb_ownership_receipts WHERE tenant_id=_tenant_id AND actor_id=actor AND request_key=_request_key;
 IF FOUND THEN
  IF r.source_id IS DISTINCT FROM _source_id OR r.input IS DISTINCT FROM canonical OR r.input_sha256 IS DISTINCT FROM private.dpw_hash(canonical)
  THEN RAISE EXCEPTION 'ssb.request_conflict' USING ERRCODE='PT409';END IF;
  RETURN before_state||jsonb_build_object('ownership',public.get_typed_data_resource_editor(_tenant_id,'data_source',_source_id),
  'recorded_ownership',r.actual_editor,'is_new',false,'request_key',_request_key);
 END IF;
 -- Exact existing ordinary administrator producer; all genuine tenant/BU/group
 -- assignment/current grants and registration/audit checks remain inside it.
 saved:=public.save_typed_data_resource_access(_tenant_id,'data_source',_source_id,_owner_bu_ids,_group_ids,_reason);
 after_state:=public.get_typed_data_resource_editor(_tenant_id,'data_source',_source_id);
 IF saved->'registered' IS DISTINCT FROM 'true'::jsonb OR after_state->'registered' IS DISTINCT FROM 'true'::jsonb
 OR (SELECT coalesce(array_agg(x ORDER BY x),'{}'::uuid[]) FROM(SELECT DISTINCT unnest(_owner_bu_ids) x) ids)
 IS DISTINCT FROM (SELECT coalesce(array_agg(x::uuid ORDER BY x::uuid),'{}'::uuid[]) FROM jsonb_array_elements_text(after_state->'owner_bu_ids') x)
 OR (SELECT coalesce(array_agg(x ORDER BY x),'{}'::uuid[]) FROM(SELECT DISTINCT unnest(_group_ids) x) ids)
 IS DISTINCT FROM (SELECT coalesce(array_agg(x::uuid ORDER BY x::uuid),'{}'::uuid[]) FROM jsonb_array_elements_text(after_state->'group_ids') x)
 THEN RAISE EXCEPTION 'ssb.ownership_readback_mismatch' USING ERRCODE='PT409';END IF;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
 VALUES(actor,_tenant_id,'workspace','data_source.bootstrap.ownership','workspace_data_source',_source_id::text,
 canonical||jsonb_build_object('request_key',_request_key,'actual_editor',after_state)) RETURNING id INTO aid;
 INSERT INTO private.ssb_ownership_receipts(tenant_id,actor_id,request_key,source_id,input,input_sha256,actual_editor,audit_event_id)
 VALUES(_tenant_id,actor,_request_key,_source_id,canonical,private.dpw_hash(canonical),after_state,aid);
 RETURN private.ssb_status(actor,_tenant_id,_source_id)||jsonb_build_object('ownership',after_state,'saved',saved,'is_new',true,'request_key',_request_key);
END $function$
;

CREATE OR REPLACE FUNCTION private.ssb_source_metadata(_source workspace_data_sources)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
 SELECT jsonb_build_object('id',_source.id,'tenant_id',_source.tenant_id,'name',_source.name,'description',_source.description,
 'source_type',_source.source_type,'status',_source.status,'bu_id',_source.bu_id,'created_by',_source.created_by,'created_at',_source.created_at,'updated_at',_source.updated_at)
$function$
;

CREATE OR REPLACE FUNCTION private.ssb_status(_actor uuid, _tenant uuid, _source uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE s public.workspace_data_sources%ROWTYPE;r private.ssb_create_receipts%ROWTYPE;mapped boolean;creator boolean;admin boolean;
BEGIN
 SELECT * INTO s FROM public.workspace_data_sources WHERE id=_source AND tenant_id=_tenant;
 IF NOT FOUND THEN RAISE EXCEPTION 'ssb.source_unknown' USING ERRCODE='42501';END IF;
 SELECT * INTO r FROM private.ssb_create_receipts WHERE source_id=s.id AND tenant_id=_tenant;
 creator:=r.actor_id=_actor;admin:=private.ssb_is_admin(_actor,_tenant);mapped:=private.ssb_is_mapped(_tenant,s.id);
 IF NOT coalesce(creator,false) AND NOT admin AND (NOT mapped OR private.registered_typed_resource_allows(_actor,_tenant,'data_source',s.id,'view') IS DISTINCT FROM true)
 THEN RAISE EXCEPTION 'ssb.source_scope_denied' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('actor_id',_actor,'tenant_id',_tenant,'source',private.ssb_source_metadata(s),'registered',mapped,
 'request_key',CASE WHEN creator THEN r.request_key ELSE NULL END,'audit_event_id',CASE WHEN creator OR admin THEN r.audit_event_id::text ELSE NULL END,
 'ownership_state',CASE WHEN s.status='archived' THEN 'archived' WHEN mapped THEN 'registered' ELSE 'awaiting_tenant_admin' END,
 'can_save_ownership',admin,'ownership_policy','actual_active_tenant_admin',
 'can_bind',mapped AND s.status<>'archived' AND private.registered_typed_resource_allows(_actor,_tenant,'data_source',s.id,'view') IS TRUE,
 'can_ingest',mapped AND s.status<>'archived' AND private.registered_typed_resource_allows(_actor,_tenant,'data_source',s.id,'ingest') IS TRUE,
 'can_edit',mapped AND s.status<>'archived' AND private.registered_typed_resource_allows(_actor,_tenant,'data_source',s.id,'edit') IS TRUE,
 'ownership_editor',jsonb_build_object('rpc','get_typed_data_resource_editor','resource_type','data_source','tenant_id',_tenant,'resource_id',s.id),
 'ownership_save',jsonb_build_object('rpc','save_typed_data_resource_access','resource_type','data_source','tenant_id',_tenant,'resource_id',s.id),
 'ownership_is_approval_queue',false);
END $function$
;

CREATE OR REPLACE FUNCTION public.dpw_lookup_file_intent(_tenant_id uuid, _pipeline_id uuid, _batch_id uuid, _feed_key text, _identity jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE authority jsonb:=public.dpw_authorize_file_intake(_tenant_id,_pipeline_id,_batch_id,_feed_key,'intake');
 f public.data_prep_delivery_files%ROWTYPE;
BEGIN
 IF NOT (_identity ? 'correction_of') OR (jsonb_typeof(_identity->'correction_of') IS DISTINCT FROM 'null' AND (jsonb_typeof(_identity->'correction_of') IS DISTINCT FROM 'string' OR (_identity->>'correction_of') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$')) THEN RAISE EXCEPTION 'dpw.lookup_correction_identity_required';END IF;
 IF _identity->>'data_source_id' IS DISTINCT FROM authority->>'data_source_id'
 OR (_identity->>'pipeline_version')::integer IS DISTINCT FROM (authority->>'pipeline_version')::integer
 OR _identity->>'content_sha256' IS NULL OR _identity->>'content_sha256' !~ '^[a-f0-9]{64}$'
 OR _identity->>'request_key' IS NULL THEN RAISE EXCEPTION 'dpw.lookup_identity_mismatch'; END IF;
 SELECT x.* INTO f FROM public.data_prep_delivery_files x JOIN public.data_prep_file_requests a ON a.file_id=x.id
 WHERE a.batch_id=_batch_id AND a.feed_key=_feed_key AND a.request_key=(_identity->>'request_key')::uuid;
 IF FOUND AND (f.correction_of IS DISTINCT FROM nullif(_identity->>'correction_of','')::uuid OR f.content_sha256<>_identity->>'content_sha256' OR f.descriptor->'selected_sheet' IS DISTINCT FROM coalesce(_identity->'selected_sheet','null'::jsonb))
 THEN RAISE EXCEPTION 'dpw.request_conflict'; END IF;
 IF f.id IS NULL THEN
  SELECT * INTO f FROM public.data_prep_delivery_files WHERE batch_id=_batch_id AND feed_key=_feed_key AND content_sha256=_identity->>'content_sha256';
  IF FOUND AND (f.correction_of IS DISTINCT FROM nullif(_identity->>'correction_of','')::uuid OR f.descriptor->'selected_sheet' IS DISTINCT FROM coalesce(_identity->'selected_sheet','null'::jsonb)) THEN RAISE EXCEPTION 'dpw.sheet_binding_conflict'; END IF;
 END IF;
 RETURN authority||jsonb_build_object('state',CASE WHEN f.id IS NULL THEN 'absent' ELSE 'found' END,'intent',CASE WHEN f.id IS NULL THEN NULL ELSE private.dpw_file_metadata(f) END);
END $function$
;

CREATE OR REPLACE FUNCTION private.dpd_request_actor(_tenant uuid, _setup uuid, _operation text, _request_context_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE c private.dpd_request_contexts%ROWTYPE;actor uuid:=auth.uid();enabled boolean;
BEGIN
 IF auth.role() IS DISTINCT FROM 'authenticated' OR current_setting('role',true) IS DISTINCT FROM 'authenticated' OR actor IS NULL OR _request_context_id IS NULL THEN RAISE EXCEPTION 'dpd.original_authenticated_context_required' USING ERRCODE='42501';END IF;
 SELECT * INTO c FROM private.dpd_request_contexts WHERE id=_request_context_id AND tenant_id=_tenant AND actor_id=actor AND setup_id IS NOT DISTINCT FROM _setup AND operation=_operation;
 IF NOT FOUND OR c.expires_at<=clock_timestamp() OR c.verified_subject->>'sub' IS DISTINCT FROM actor::text OR c.verified_subject->>'aal' IS DISTINCT FROM auth.jwt()->>'aal' OR c.verified_subject->>'exp' IS DISTINCT FROM auth.jwt()->>'exp' THEN RAISE EXCEPTION 'dpd.fresh_original_request_context_required' USING ERRCODE='42501';END IF;
 PERFORM private.dpd_peer_actor(_tenant,c.verified_subject);IF private.wfm_actor(_tenant) IS DISTINCT FROM actor OR public.user_has_permission(actor,_tenant,CASE WHEN _operation IN('setup.create','setup.save','original.authorize','original.claim','source.register','preview.bind','parser.enqueue','review.shared.decide','preview.job.enqueue','preview.job.claim','review.setup.request','review.setup.decide','prepare.job.enqueue','publication.request','publication.decide','publication.perform') THEN 'data.prep.author' ELSE 'data.prep.read' END,NULL) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.actual_current_actor_denied' USING ERRCODE='42501';END IF;
 SELECT ip_allowlist_enabled INTO enabled FROM public.tenant_security_settings WHERE tenant_id=_tenant;
 IF NOT FOUND OR enabled IS NULL OR (enabled AND (c.request_ip IS NULL OR public.ip_in_tenant_allowlist(_tenant,host(c.request_ip)) IS DISTINCT FROM true)) THEN RAISE EXCEPTION 'dpd.current_bound_network_denied' USING ERRCODE='42501';END IF;
 IF _operation IN('setup.create','setup.save','original.authorize','original.claim','source.register','preview.bind','parser.enqueue','review.shared.decide','preview.job.enqueue','preview.job.claim','review.setup.request','review.setup.decide','prepare.job.enqueue','publication.request','publication.decide','publication.perform') THEN PERFORM public.assert_data_prep_actor(_tenant,actor,false);END IF;
 RETURN actor;
END $function$
;

CREATE OR REPLACE FUNCTION public.dpw_open_file_intent(_tenant_id uuid, _pipeline_id uuid, _batch_id uuid, _feed_key text, _descriptor jsonb, _request_key uuid, _correction_of uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_authorize(_tenant_id,_pipeline_id,'run'); b public.data_prep_delivery_batches%ROWTYPE;
 f public.data_prep_delivery_files%ROWTYPE; profile jsonb; fid uuid:=gen_random_uuid(); newfile boolean:=true;
BEGIN
 PERFORM private.wfm_assert_enabled(_tenant_id,'data');
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,false);
 b:=private.dpw_lock_batch(_tenant_id,_pipeline_id,_batch_id,actor,false);
 SELECT value INTO profile FROM jsonb_array_elements(b.configuration_snapshot->'feeds') WHERE value->>'key'=_feed_key;
 IF profile IS NULL OR private.dpw_source_allows(actor,_tenant_id,(profile->>'data_source_id')::uuid,'ingest') IS DISTINCT FROM true
 OR _request_key IS NULL OR jsonb_typeof(_descriptor) IS DISTINCT FROM 'object'
 OR (_descriptor->>'content_sha256') IS NULL OR (_descriptor->>'content_sha256') !~ '^[a-f0-9]{64}$'
 OR (_descriptor->>'parsed_sha256') IS NULL OR (_descriptor->>'parsed_sha256') !~ '^[a-f0-9]{64}$'
 OR (_descriptor->>'size_bytes') IS NULL OR (_descriptor->>'size_bytes')::bigint NOT BETWEEN 1 AND 52428800
 OR (_descriptor->>'parsed_bytes') IS NULL OR (_descriptor->>'parsed_bytes')::bigint NOT BETWEEN 2 AND 52428800
 OR (_descriptor->>'row_count') IS NULL OR (_descriptor->>'row_count')::integer NOT BETWEEN 0 AND 50000
 OR jsonb_typeof(_descriptor->'columns') IS DISTINCT FROM 'array' OR jsonb_array_length(_descriptor->'columns') NOT BETWEEN 1 AND 500
 OR length(coalesce(_descriptor->>'filename','')) NOT BETWEEN 1 AND 255 OR length(coalesce(_descriptor->>'mime_type','')) NOT BETWEEN 1 AND 255
 THEN RAISE EXCEPTION 'dpw.invalid_file_intent'; END IF;
 SELECT x.* INTO f FROM public.data_prep_delivery_files x JOIN public.data_prep_file_requests a ON a.file_id=x.id
 WHERE a.batch_id=b.id AND a.feed_key=_feed_key AND a.request_key=_request_key;
 IF FOUND THEN
  IF f.descriptor IS DISTINCT FROM _descriptor OR f.correction_of IS DISTINCT FROM _correction_of THEN RAISE EXCEPTION 'dpw.request_conflict'; END IF;
  newfile:=false;
 ELSE
  SELECT * INTO f FROM public.data_prep_delivery_files WHERE batch_id=b.id AND feed_key=_feed_key AND content_sha256=_descriptor->>'content_sha256';
  IF FOUND THEN
   IF f.descriptor IS DISTINCT FROM _descriptor OR f.correction_of IS DISTINCT FROM _correction_of THEN RAISE EXCEPTION 'dpw.same_file_descriptor_conflict'; END IF;
   newfile:=false;
  ELSE
   IF b.state<>'collecting' THEN RAISE EXCEPTION 'dpw.late_file_requires_correction'; END IF;
   IF _correction_of IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.data_prep_delivery_files
   WHERE id=_correction_of AND batch_id=b.correction_of AND feed_key=_feed_key AND tenant_id=_tenant_id)
   THEN RAISE EXCEPTION 'dpw.file_correction_mismatch'; END IF;
   INSERT INTO public.data_prep_delivery_files(id,tenant_id,pipeline_id,batch_id,pipeline_version,feed_key,data_source_id,created_by,descriptor,request_key,content_sha256,original_path,correction_of)
   VALUES(fid,_tenant_id,_pipeline_id,b.id,b.pipeline_version,_feed_key,(profile->>'data_source_id')::uuid,actor,_descriptor,_request_key,
   _descriptor->>'content_sha256',_tenant_id::text||'/'||b.id::text||'/'||fid::text||'/original',_correction_of) RETURNING * INTO f;
  END IF;
 END IF;
 INSERT INTO public.data_prep_file_requests(batch_id,feed_key,request_key,file_id,requested_descriptor,created_by)
 VALUES(b.id,_feed_key,_request_key,f.id,_descriptor,actor) ON CONFLICT(batch_id,feed_key,request_key) DO NOTHING;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'file',private.dpw_file_metadata(f),'intent',private.dpw_file_metadata(f),'created',newfile,
 'storage_capability',jsonb_build_object('bucket_id','data-prep-inputs','public',false,'max_original_bytes',52428800,
 'max_expanded_bytes',52428800,'max_parsed_bytes',52428800,'max_rows',50000,'max_columns',500));
END $function$
;

CREATE OR REPLACE FUNCTION public.wfm_assert_current_section(_tenant_id uuid, _page_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.wfm_actor(_tenant_id);
BEGIN
 PERFORM private.wfm_assert_enabled(_tenant_id,_page_key);
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'page_key',_page_key,'enabled',true);
END $function$
;

CREATE OR REPLACE FUNCTION public.wfm_assert_recon_scope(_resource_id uuid, _kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE tenant uuid; actor uuid; receipt jsonb;
BEGIN
 IF _kind='definition' THEN SELECT r.tenant_id INTO tenant FROM public.recon_definitions r WHERE r.id=_resource_id;
 ELSIF _kind='governance_request' THEN SELECT r.tenant_id INTO tenant FROM public.recon_definition_governance_requests r WHERE r.id=_resource_id;
 ELSE RAISE EXCEPTION 'Invalid reconciliation scope' USING ERRCODE='22023';END IF;
 IF tenant IS NULL THEN RAISE EXCEPTION 'Current reconciliation scope is unavailable' USING ERRCODE='42501';END IF;
 receipt:=public.wfm_assert_current_section(tenant,'recons');
 RETURN receipt||jsonb_build_object('resource_id',_resource_id,'kind',_kind);
END $function$
;

CREATE OR REPLACE FUNCTION public.wfm_workspace_row_allowed(_tenant_id uuid, _page_key text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 PERFORM private.wfm_actor(_tenant_id);
 PERFORM private.wfm_assert_enabled(_tenant_id,_page_key);
 RETURN true;
EXCEPTION WHEN insufficient_privilege THEN RETURN false;
END $function$
;

CREATE OR REPLACE FUNCTION private.wfm_workspace_write_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP IN ('UPDATE','DELETE') THEN
  IF current_setting('role',true)='authenticated' THEN PERFORM private.wfm_actor(OLD.tenant_id);END IF;
  PERFORM private.wfm_assert_enabled(OLD.tenant_id,TG_ARGV[0]);END IF;
 IF TG_OP IN ('INSERT','UPDATE') THEN
  IF current_setting('role',true)='authenticated' THEN PERFORM private.wfm_actor(NEW.tenant_id);END IF;
  PERFORM private.wfm_assert_enabled(NEW.tenant_id,TG_ARGV[0]);END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;ELSE RETURN NEW;END IF;
END $function$
;

CREATE OR REPLACE FUNCTION public.assign_exceptions_from_rule(_tenant_id uuid, _rule_id uuid, _exception_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  actor_id uuid := auth.uid();
  rule_row public.exception_assignment_rules%ROWTYPE;
  exception_id uuid;
  exception_row public.recon_exceptions%ROWTYPE;
  candidate uuid;
  affected integer;
  assigned_count integer := 0;
  skipped_count integer := 0;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'assignment');

  IF actor_id IS NULL OR NOT (
    public.has_tenant_role(actor_id,_tenant_id,'tenant_admin')
    OR public.user_has_permission(actor_id,_tenant_id,'break.assign',NULL)
  ) THEN
    RAISE EXCEPTION 'forbidden: break.assign permission required';
  END IF;
  IF _exception_ids IS NULL OR cardinality(_exception_ids) NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'assignment batch must contain 1 to 500 exception IDs';
  END IF;
  IF (SELECT count(DISTINCT selected.id) FROM unnest(_exception_ids) AS selected(id))
     <> cardinality(_exception_ids) THEN
    RAISE EXCEPTION 'assignment batch IDs must be non-null and unique';
  END IF;
  SELECT * INTO rule_row FROM public.exception_assignment_rules
  WHERE id=_rule_id AND tenant_id=_tenant_id AND enabled=true;
  IF NOT FOUND THEN RAISE EXCEPTION 'assignment rule not found'; END IF;

  FOREACH exception_id IN ARRAY _exception_ids LOOP
    SELECT * INTO exception_row FROM public.recon_exceptions
    WHERE id=exception_id AND tenant_id=_tenant_id FOR UPDATE;
    IF NOT FOUND OR exception_row.status<>'open' OR exception_row.assignee IS NOT NULL
       OR exception_row.lifecycle_state IN ('resolved','written_off')
       OR (rule_row.recon_id IS NOT NULL AND NOT EXISTS (
         SELECT 1 FROM public.recon_runs run
         WHERE run.id=exception_row.run_id AND run.tenant_id=_tenant_id
           AND run.definition_id=rule_row.recon_id
       )) THEN
      skipped_count := skipped_count + 1;
      CONTINUE;
    END IF;
    candidate := public.pick_next_assignee(
      _rule_id,
      exception_row.severity,
      exception_row.tags
    );
    IF candidate IS NULL THEN
      skipped_count := skipped_count + 1;
      CONTINUE;
    END IF;
    UPDATE public.recon_exceptions
    SET assignee=candidate, assigned_by=actor_id, assigned_at=now()
    WHERE id=exception_row.id AND tenant_id=_tenant_id
      AND status='open' AND assignee IS NULL
      AND lifecycle_state NOT IN ('resolved','written_off');
    GET DIAGNOSTICS affected = ROW_COUNT;
    IF affected<>1 THEN
      skipped_count := skipped_count + 1;
      CONTINUE;
    END IF;
    INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
    VALUES (actor_id,_tenant_id,'workspace','exception.auto_assigned','recon_exception',exception_row.id::text,
      jsonb_build_object('rule_id',_rule_id,'assignee_id',candidate));
    assigned_count := assigned_count + 1;
  END LOOP;
  RETURN jsonb_build_object('assigned',assigned_count,'skipped',skipped_count);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.collateral_qa_vm_create(_tenant uuid, _schedule uuid, _valuation_at timestamp with time zone, _exposure_reference text, _gross numeric, _assets jsonb, _reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_schedule public.collateral_schedules%ROWTYPE;
  v_id uuid;
  v_collateral numeric(20,4);
  v_net numeric(20,4);
  v_proposed numeric(20,4);
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant,'collateral');

  IF v_actor IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.collateral_qa_tenants scope
    JOIN public.tenant_members tm ON tm.tenant_id = scope.tenant_id
    WHERE scope.tenant_id = _tenant AND scope.enabled AND tm.user_id = v_actor
      AND tm.active AND tm.role::text IN ('tenant_admin','tenant_analyst')
  ) THEN RAISE EXCEPTION 'collateral_qa_access_denied' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_schedule FROM public.collateral_schedules
    WHERE id = _schedule AND tenant_id = _tenant AND schedule_type = 'VM';
  IF NOT FOUND OR _valuation_at IS NULL OR _gross IS NULL OR _gross < 0
     OR length(coalesce(_exposure_reference,'')) NOT BETWEEN 3 AND 120
     OR length(coalesce(_reason,'')) NOT BETWEEN 3 AND 1000
     OR jsonb_typeof(_assets) IS DISTINCT FROM 'array'
     OR jsonb_array_length(_assets) NOT BETWEEN 1 AND 20 THEN
    RAISE EXCEPTION 'invalid_synthetic_vm_inputs' USING ERRCODE='23514';
  END IF;
  IF (v_schedule.effective_from IS NOT NULL AND _valuation_at::date < v_schedule.effective_from)
     OR (v_schedule.effective_to IS NOT NULL AND _valuation_at::date > v_schedule.effective_to) THEN
    RAISE EXCEPTION 'vm_valuation_outside_agreement_period' USING ERRCODE='23514';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_to_recordset(_assets) AS a(
      asset_type text, description text, provenance_reference text, market_value numeric, haircut_bps integer)
    WHERE length(coalesce(a.asset_type,'')) NOT BETWEEN 2 AND 80
      OR length(coalesce(a.description,'')) NOT BETWEEN 2 AND 160
      OR length(coalesce(a.provenance_reference,'')) NOT BETWEEN 3 AND 120
      OR a.market_value IS NULL OR a.market_value < 0
      OR a.haircut_bps IS NULL OR a.haircut_bps NOT BETWEEN 0 AND 10000
  ) THEN RAISE EXCEPTION 'invalid_synthetic_vm_asset' USING ERRCODE='23514'; END IF;
  SELECT sum(round(a.market_value * (10000 - a.haircut_bps) / 10000, 4))
    INTO v_collateral
  FROM jsonb_to_recordset(_assets) AS a(
    asset_type text, description text, provenance_reference text, market_value numeric, haircut_bps integer);
  v_net := greatest(_gross - v_collateral - v_schedule.threshold_amount, 0);
  v_proposed := CASE WHEN v_net < v_schedule.minimum_transfer THEN 0
    WHEN v_schedule.rounding > 0 THEN round(v_net / v_schedule.rounding) * v_schedule.rounding
    ELSE v_net END;
  INSERT INTO public.collateral_qa_vm_calls(
    tenant_id,schedule_id,valuation_at,exposure_reference,gross_exposure,
    eligible_collateral,threshold_snapshot,mta_snapshot,rounding_snapshot,
    proposed_vm,maker_id,maker_reason
  ) VALUES (_tenant,_schedule,_valuation_at,_exposure_reference,_gross,
    v_collateral,v_schedule.threshold_amount,v_schedule.minimum_transfer,
    v_schedule.rounding,v_proposed,v_actor,_reason) RETURNING id INTO v_id;
  INSERT INTO public.collateral_qa_vm_assets(
    call_id,asset_type,description,provenance_reference,market_value,haircut_bps)
  SELECT v_id,a.asset_type,a.description,a.provenance_reference,a.market_value,a.haircut_bps
  FROM jsonb_to_recordset(_assets) AS a(
    asset_type text, description text, provenance_reference text, market_value numeric, haircut_bps integer);
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES(v_actor,_tenant,'tenant','collateral.qa_vm.created','collateral_qa_vm_call',v_id::text,
    jsonb_build_object('schedule_id',_schedule,'proposed_vm',v_proposed,'synthetic',true));
  RETURN v_id;
END $function$
;

CREATE OR REPLACE FUNCTION public.collateral_qa_vm_transition(_tenant uuid, _call uuid, _action text, _reason text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_role text;
  v_call public.collateral_qa_vm_calls%ROWTYPE;
  v_status text;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant,'collateral');

  SELECT tm.role::text INTO v_role FROM public.collateral_qa_tenants scope
  JOIN public.tenant_members tm ON tm.tenant_id=scope.tenant_id
  WHERE scope.tenant_id=_tenant AND scope.enabled AND tm.user_id=v_actor AND tm.active;
  IF v_role IS NULL OR length(coalesce(_reason,'')) NOT BETWEEN 3 AND 1000 THEN
    RAISE EXCEPTION 'collateral_qa_access_denied' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_call FROM public.collateral_qa_vm_calls
    WHERE id=_call AND tenant_id=_tenant FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'collateral_qa_call_not_found' USING ERRCODE='02000'; END IF;
  IF _action='submit' AND v_call.status='draft' AND v_call.maker_id=v_actor THEN
    v_status := 'pending_checker';
    UPDATE public.collateral_qa_vm_calls SET status=v_status,updated_at=now() WHERE id=_call;
  ELSIF _action IN ('approve','reject') AND v_call.status='pending_checker'
      AND v_role='tenant_admin' AND v_call.maker_id<>v_actor THEN
    v_status := CASE WHEN _action='approve' THEN 'approved' ELSE 'rejected' END;
    UPDATE public.collateral_qa_vm_calls SET status=v_status,checker_id=v_actor,
      checker_reason=_reason,updated_at=now() WHERE id=_call;
  ELSIF _action='record_settlement' AND v_call.status='approved'
      AND v_role IN ('tenant_admin','tenant_analyst') AND v_call.maker_id=v_actor THEN
    v_status := 'settlement_recorded';
    UPDATE public.collateral_qa_vm_calls SET status=v_status,
      internal_settlement_reference=_reason,settlement_recorded_at=now(),updated_at=now() WHERE id=_call;
  ELSE RAISE EXCEPTION 'invalid_collateral_qa_transition' USING ERRCODE='42501'; END IF;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES(v_actor,_tenant,'tenant','collateral.qa_vm.'||_action,'collateral_qa_vm_call',_call::text,
    jsonb_build_object('from',v_call.status,'to',v_status,'synthetic',true));
  RETURN v_status;
END $function$
;

CREATE OR REPLACE FUNCTION public.create_collateral_csa_draft(_tenant_id uuid, _agreement_id uuid, _agreement_key text, _own_legal_entity text, _counterparty text, _currency text, _threshold_amount numeric, _minimum_transfer numeric, _rounding_increment numeric, _effective_from date, _effective_to date, _terms_snapshot jsonb, _idempotency_key text)
 RETURNS TABLE(agreement_id uuid, version_id uuid, version_no integer, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  actor uuid := auth.uid();
  agreement_row public.collateral_csa_agreements%ROWTYPE;
  version_row public.collateral_csa_versions%ROWTYPE;
  request_digest text;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'collateral');

  IF NOT public.csa_assurance_actor(_tenant_id,actor) THEN
    RAISE EXCEPTION 'Active tenant administrator required' USING ERRCODE='42501';
  END IF;
  IF _threshold_amount < 0 OR _minimum_transfer < 0 OR _rounding_increment < 0
     OR _effective_to IS NOT NULL AND _effective_to < _effective_from
     OR _currency !~ '^[A-Z]{3}$' OR _terms_snapshot IS NULL OR jsonb_typeof(_terms_snapshot) <> 'object' THEN
    RAISE EXCEPTION 'Invalid bilateral VM agreement terms' USING ERRCODE='22023';
  END IF;
  request_digest := encode(extensions.digest(jsonb_build_object(
    'agreement_id',_agreement_id,'agreement_key',_agreement_key,'own_legal_entity',_own_legal_entity,
    'counterparty',_counterparty,'currency',_currency,'threshold_amount',_threshold_amount,
    'minimum_transfer',_minimum_transfer,'rounding_increment',_rounding_increment,
    'effective_from',_effective_from,'effective_to',_effective_to,'terms_snapshot',_terms_snapshot
  )::text,'sha256'),'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended(_tenant_id::text||':'||actor::text||':'||_idempotency_key,0));
  SELECT * INTO version_row FROM public.collateral_csa_versions
    WHERE tenant_id=_tenant_id AND created_by=actor AND idempotency_key=_idempotency_key;
  IF FOUND THEN
    IF version_row.request_hash <> request_digest THEN RAISE EXCEPTION 'Idempotency key reused with different agreement terms' USING ERRCODE='22023'; END IF;
    RETURN QUERY SELECT version_row.agreement_id,version_row.id,version_row.version_no,true; RETURN;
  END IF;
  IF _agreement_id IS NULL THEN
    IF _agreement_key IS NULL OR _own_legal_entity IS NULL OR _counterparty IS NULL THEN
      RAISE EXCEPTION 'New agreement identity is required' USING ERRCODE='22023';
    END IF;
    INSERT INTO public.collateral_csa_agreements(tenant_id,agreement_key,own_legal_entity,counterparty,currency,created_by)
    VALUES (_tenant_id,_agreement_key,_own_legal_entity,_counterparty,_currency,actor) RETURNING * INTO agreement_row;
  ELSE
    SELECT * INTO agreement_row FROM public.collateral_csa_agreements
      WHERE id=_agreement_id AND tenant_id=_tenant_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Agreement is unavailable in this tenant' USING ERRCODE='42501'; END IF;
    IF agreement_row.currency IS DISTINCT FROM _currency OR agreement_row.agreement_key IS DISTINCT FROM _agreement_key
       OR agreement_row.own_legal_entity IS DISTINCT FROM _own_legal_entity OR agreement_row.counterparty IS DISTINCT FROM _counterparty THEN
      RAISE EXCEPTION 'Agreement identity is immutable' USING ERRCODE='22023';
    END IF;
  END IF;
  INSERT INTO public.collateral_csa_versions(tenant_id,agreement_id,version_no,threshold_amount,minimum_transfer,
    rounding_increment,effective_from,effective_to,terms_snapshot,created_by,idempotency_key,request_hash)
  SELECT _tenant_id,agreement_row.id,coalesce(max(v.version_no),0)+1,_threshold_amount,_minimum_transfer,
    _rounding_increment,_effective_from,_effective_to,coalesce(_terms_snapshot,'{}'::jsonb),actor,_idempotency_key,request_digest
  FROM public.collateral_csa_versions v WHERE v.tenant_id=_tenant_id AND v.agreement_id=agreement_row.id
  RETURNING * INTO version_row;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES(actor,_tenant_id,'tenant','collateral.csa.version.draft','collateral_csa_version',version_row.id::text,
    jsonb_build_object('agreement_id',agreement_row.id,'version_no',version_row.version_no,'currency',_currency));
  RETURN QUERY SELECT agreement_row.id,version_row.id,version_row.version_no,false;
END $function$
;

CREATE OR REPLACE FUNCTION public.create_recon_definition_with_owners(_tenant_id uuid, _name text, _description text, _recon_type text, _sides jsonb, _rules jsonb, _owner_bu_ids uuid[])
 RETURNS TABLE(id uuid, recon_code text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_is_admin boolean;
  v_bu_ids uuid[];
  v_source_ids uuid[];
  v_source_count integer;
  v_side_count integer;
  v_definition_id uuid;
  v_recon_code text;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'recons');

  IF v_actor IS NULL OR _tenant_id IS NULL OR length(btrim(coalesce(_name,''))) NOT BETWEEN 1 AND 200
     OR _recon_type IS NULL OR _recon_type NOT IN ('one_sided','two_sided','three_sided')
     OR jsonb_typeof(coalesce(_sides,'[]'::jsonb)) <> 'array'
     OR jsonb_typeof(coalesce(_rules,'[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'invalid reconciliation creation request' USING ERRCODE='22023';
  END IF;
  v_side_count := jsonb_array_length(coalesce(_sides,'[]'::jsonb));
  IF v_side_count <> (CASE _recon_type WHEN 'one_sided' THEN 1 WHEN 'two_sided' THEN 2 ELSE 3 END)
     OR EXISTS (
       SELECT 1 FROM jsonb_array_elements(coalesce(_sides,'[]'::jsonb)) side
       WHERE nullif(side->>'data_source_id','') IS NULL
          OR (nullif(side->>'upload_id','') IS NOT NULL
            AND NOT EXISTS (
              SELECT 1 FROM public.workspace_data_source_uploads upload_row
              WHERE upload_row.id=(side->>'upload_id')::uuid
                AND upload_row.tenant_id=_tenant_id
                AND upload_row.data_source_id=(side->>'data_source_id')::uuid
            ))
     ) THEN
    RAISE EXCEPTION 'source bindings must be complete and belong to this workspace' USING ERRCODE='42501';
  END IF;
  SELECT coalesce(array_agg(DISTINCT nullif(side->>'data_source_id','')::uuid
                            ORDER BY nullif(side->>'data_source_id','')::uuid),ARRAY[]::uuid[])
  INTO v_source_ids
  FROM jsonb_array_elements(coalesce(_sides,'[]'::jsonb)) side;
  SELECT count(DISTINCT source_row.id) INTO v_source_count
  FROM public.workspace_data_sources source_row
  WHERE source_row.tenant_id=_tenant_id AND source_row.id=ANY(v_source_ids);
  IF v_source_count <> cardinality(v_source_ids) THEN
    RAISE EXCEPTION 'one or more reconciliation sources are unavailable in this workspace' USING ERRCODE='42501';
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.tenant_members member_row
    WHERE member_row.tenant_id=_tenant_id AND member_row.user_id=v_actor
      AND member_row.active AND member_row.role::text='tenant_admin'
  ) INTO v_is_admin;
  IF NOT v_is_admin AND NOT private.recon_governance_is_active_analyst(_tenant_id,v_actor) THEN
    RAISE EXCEPTION 'active tenant administrator or analyst required' USING ERRCODE='42501';
  END IF;

  SELECT coalesce(array_agg(DISTINCT bu_id ORDER BY bu_id), ARRAY[]::uuid[])
  INTO v_bu_ids FROM unnest(coalesce(_owner_bu_ids,ARRAY[]::uuid[])) AS bu_id;
  IF cardinality(v_bu_ids)=0 THEN
    RAISE EXCEPTION 'at least one owning business unit is required' USING ERRCODE='22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(v_bu_ids) requested(bu_id)
    LEFT JOIN public.business_units bu
      ON bu.id=requested.bu_id AND bu.tenant_id=_tenant_id
    WHERE bu.id IS NULL OR bu.is_archived
  ) THEN
    RAISE EXCEPTION 'owning business units must be active and belong to the reconciliation tenant' USING ERRCODE='22023';
  END IF;
  IF NOT v_is_admin AND EXISTS (
    SELECT 1 FROM unnest(v_bu_ids) requested(bu_id)
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.bu_user_assignments assignment
      JOIN public.business_units assigned_bu
        ON assigned_bu.id=assignment.bu_id AND assigned_bu.tenant_id=assignment.tenant_id
        AND NOT assigned_bu.is_archived
      JOIN public.business_units owner_bu
        ON owner_bu.id=requested.bu_id AND owner_bu.tenant_id=assignment.tenant_id
        AND NOT owner_bu.is_archived
      WHERE assignment.tenant_id=_tenant_id AND assignment.user_id=v_actor
        AND (owner_bu.id=assigned_bu.id
          OR (assignment.inherit_descendants AND owner_bu.path <@ assigned_bu.path))
    )
  ) THEN
    RAISE EXCEPTION 'analyst must be assigned to every selected owning business unit' USING ERRCODE='42501';
  END IF;

  INSERT INTO public.recon_definitions(
    tenant_id,name,description,recon_type,sides,rules,status,created_by,
    governance_state,access_mode,multi_bu_governed
  ) VALUES (
    _tenant_id,btrim(_name),nullif(btrim(coalesce(_description,'')),''),_recon_type,
    coalesce(_sides,'[]'::jsonb),coalesce(_rules,'[]'::jsonb),'draft',v_actor,
    'development_draft','unmapped_pending',false
  ) RETURNING recon_definitions.id,recon_definitions.recon_code
    INTO v_definition_id,v_recon_code;

  INSERT INTO public.recon_definition_business_units(tenant_id,recon_id,bu_id,created_by)
  SELECT _tenant_id,v_definition_id,owner_id,v_actor FROM unnest(v_bu_ids) owner_id;

  INSERT INTO public.recon_definition_bu_admin_audit(
    tenant_id,recon_id,operation,actor_id,reason,details
  ) VALUES (
    _tenant_id,v_definition_id,'replace_owners',v_actor,
    'Atomic definition creation owner binding',
    jsonb_build_object('previous_bu_ids',ARRAY[]::uuid[],'new_bu_ids',v_bu_ids,'source','atomic_create')
  );

  -- Active tenant admins have the authoritative in-tenant override and may
  -- not have per-BU assignments. Analysts were checked above for every owner
  -- BU, so grant only their explicit draft capabilities.
  IF NOT v_is_admin THEN
    INSERT INTO public.recon_definition_bu_grants(
      tenant_id,recon_id,bu_id,principal_type,principal_id,action,granted_by
    )
    SELECT _tenant_id,v_definition_id,owner_id,'user',v_actor,action_name,v_actor
    FROM unnest(v_bu_ids) owner_id
    CROSS JOIN unnest(ARRAY['view','edit','run']::text[]) action_name;
  END IF;

  UPDATE public.recon_definitions
  SET access_mode='mapped_exact',multi_bu_governed=true
  WHERE recon_definitions.id=v_definition_id AND recon_definitions.tenant_id=_tenant_id;

  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES (
    v_actor,_tenant_id,'workspace','recon.create','recon_definition',v_definition_id::text,
    jsonb_build_object('recon_code',v_recon_code,'name',btrim(_name),'type',_recon_type,
      'owner_bu_ids',v_bu_ids)
  );

  RETURN QUERY SELECT v_definition_id,v_recon_code;
END
$function$
;

CREATE OR REPLACE FUNCTION public.cutover_legacy_recon_definition_mapping(_tenant_id uuid, _recon_id uuid, _owner_bu_ids uuid[], _maker_user_id uuid, _checker_user_id uuid, _reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_definition public.recon_definitions%ROWTYPE;
  v_owner_ids uuid[];
  v_existing_owner_ids uuid[];
  v_maker_role text;
  v_checker_role text;
  v_receipt_id uuid;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'recons');

  IF v_actor IS NULL OR _tenant_id IS NULL OR _recon_id IS NULL
     OR _maker_user_id IS NULL OR _checker_user_id IS NULL
     OR _maker_user_id=_checker_user_id OR v_actor IN (_maker_user_id,_checker_user_id)
     OR _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 3 AND 1000 THEN
    RAISE EXCEPTION 'invalid legacy mapping cutover request' USING ERRCODE='22023';
  END IF;
  IF NOT private.recon_governance_is_active_admin(_tenant_id,v_actor) THEN
    RAISE EXCEPTION 'active same-tenant administrator required' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v_definition
  FROM public.recon_definitions d
  WHERE d.id=_recon_id AND d.tenant_id=_tenant_id
  FOR UPDATE;
  IF NOT FOUND OR v_definition.access_mode<>'legacy_passthrough'
     OR v_definition.governance_state<>'legacy_unreviewed'
     OR v_definition.multi_bu_governed THEN
    RAISE EXCEPTION 'definition is not an unmapped legacy reconciliation' USING ERRCODE='42501';
  END IF;

  SELECT coalesce(array_agg(DISTINCT requested.bu_id ORDER BY requested.bu_id),ARRAY[]::uuid[])
  INTO v_owner_ids FROM unnest(coalesce(_owner_bu_ids,ARRAY[]::uuid[])) requested(bu_id);
  IF cardinality(v_owner_ids)=0 OR cardinality(v_owner_ids)<>cardinality(coalesce(_owner_bu_ids,ARRAY[]::uuid[])) THEN
    RAISE EXCEPTION 'one or more distinct owner business units are required' USING ERRCODE='22023';
  END IF;
  SELECT coalesce(array_agg(owner_row.bu_id ORDER BY owner_row.bu_id),ARRAY[]::uuid[])
  INTO v_existing_owner_ids
  FROM public.recon_definition_business_units owner_row
  WHERE owner_row.tenant_id=_tenant_id AND owner_row.recon_id=_recon_id;
  IF v_existing_owner_ids IS DISTINCT FROM v_owner_ids OR cardinality(v_existing_owner_ids)<>cardinality(v_owner_ids)
     OR EXISTS (
       SELECT 1 FROM unnest(v_owner_ids) requested(bu_id)
       LEFT JOIN public.business_units owner_unit
         ON owner_unit.id=requested.bu_id AND owner_unit.tenant_id=_tenant_id
       WHERE owner_unit.id IS NULL OR owner_unit.is_archived
     ) THEN
    RAISE EXCEPTION 'owner links must exactly match active same-tenant business units' USING ERRCODE='42501';
  END IF;
  -- Serialize owner replacement and grant revocation/insertion across the
  -- validation-to-transition interval. The parent definition lock above also
  -- serializes set_recon_owners, which locks that row before changing links.
  PERFORM owner_row.bu_id
  FROM public.recon_definition_business_units owner_row
  WHERE owner_row.tenant_id=_tenant_id AND owner_row.recon_id=_recon_id
  ORDER BY owner_row.bu_id FOR UPDATE;
  PERFORM grant_row.id
  FROM public.recon_definition_bu_grants grant_row
  WHERE grant_row.tenant_id=_tenant_id AND grant_row.recon_id=_recon_id
  ORDER BY grant_row.id FOR SHARE;

  SELECT tm.role::text INTO v_maker_role FROM public.tenant_members tm
  WHERE tm.tenant_id=_tenant_id AND tm.user_id=_maker_user_id AND tm.active;
  SELECT tm.role::text INTO v_checker_role FROM public.tenant_members tm
  WHERE tm.tenant_id=_tenant_id AND tm.user_id=_checker_user_id AND tm.active;
  IF v_maker_role IS NULL OR v_checker_role IS NULL THEN
    RAISE EXCEPTION 'maker and checker must be active members of the same tenant' USING ERRCODE='42501';
  END IF;

  -- Each synthetic actor needs current assignment to every owner BU and a
  -- reviewed direct-user or assigned same-tenant group grant for every action.
  IF EXISTS (
    SELECT 1 FROM unnest(v_owner_ids) owner(bu_id)
    CROSS JOIN unnest(ARRAY['view','run','edit']::text[]) needed(action_name)
    WHERE NOT EXISTS (
      SELECT 1 FROM public.bu_user_assignments assignment
      JOIN public.business_units assigned_unit ON assigned_unit.id=assignment.bu_id
        AND assigned_unit.tenant_id=assignment.tenant_id AND NOT assigned_unit.is_archived
      JOIN public.business_units owner_unit ON owner_unit.id=owner.bu_id
        AND owner_unit.tenant_id=assignment.tenant_id AND NOT owner_unit.is_archived
      WHERE assignment.tenant_id=_tenant_id AND assignment.user_id=_maker_user_id
        AND (assigned_unit.id=owner_unit.id OR
             (assignment.inherit_descendants AND owner_unit.path <@ assigned_unit.path))
    ) OR NOT EXISTS (
      SELECT 1 FROM public.recon_definition_bu_grants grant_row
      WHERE grant_row.tenant_id=_tenant_id AND grant_row.recon_id=_recon_id
        AND grant_row.bu_id=owner.bu_id AND grant_row.action=needed.action_name
        AND ((grant_row.principal_type='user' AND grant_row.principal_id=_maker_user_id)
          OR (grant_row.principal_type='group' AND EXISTS (
            SELECT 1 FROM public.tenant_groups group_row
            JOIN public.tenant_group_members group_member ON group_member.group_id=group_row.id
              AND group_member.user_id=_maker_user_id
            JOIN public.tenant_members active_member ON active_member.tenant_id=_tenant_id
              AND active_member.user_id=group_member.user_id AND active_member.active
            JOIN public.bu_group_assignments group_assignment ON group_assignment.tenant_id=_tenant_id
              AND group_assignment.group_id=group_row.id
            JOIN public.business_units assigned_unit ON assigned_unit.id=group_assignment.bu_id
              AND assigned_unit.tenant_id=group_assignment.tenant_id AND NOT assigned_unit.is_archived
            JOIN public.business_units owner_unit ON owner_unit.id=owner.bu_id
              AND owner_unit.tenant_id=group_assignment.tenant_id AND NOT owner_unit.is_archived
            WHERE group_row.id=grant_row.principal_id AND group_row.tenant_id=_tenant_id
              AND (assigned_unit.id=owner_unit.id OR
                   (group_assignment.inherit_descendants AND owner_unit.path <@ assigned_unit.path))
          )))
    )
  ) OR EXISTS (
    SELECT 1 FROM unnest(v_owner_ids) owner(bu_id)
    CROSS JOIN unnest(ARRAY['view','approve']::text[]) needed(action_name)
    WHERE NOT EXISTS (
      SELECT 1 FROM public.bu_user_assignments assignment
      JOIN public.business_units assigned_unit ON assigned_unit.id=assignment.bu_id
        AND assigned_unit.tenant_id=assignment.tenant_id AND NOT assigned_unit.is_archived
      JOIN public.business_units owner_unit ON owner_unit.id=owner.bu_id
        AND owner_unit.tenant_id=assignment.tenant_id AND NOT owner_unit.is_archived
      WHERE assignment.tenant_id=_tenant_id AND assignment.user_id=_checker_user_id
        AND (assigned_unit.id=owner_unit.id OR
             (assignment.inherit_descendants AND owner_unit.path <@ assigned_unit.path))
    ) OR NOT EXISTS (
      SELECT 1 FROM public.recon_definition_bu_grants grant_row
      WHERE grant_row.tenant_id=_tenant_id AND grant_row.recon_id=_recon_id
        AND grant_row.bu_id=owner.bu_id AND grant_row.action=needed.action_name
        AND ((grant_row.principal_type='user' AND grant_row.principal_id=_checker_user_id)
          OR (grant_row.principal_type='group' AND EXISTS (
            SELECT 1 FROM public.tenant_groups group_row
            JOIN public.tenant_group_members group_member ON group_member.group_id=group_row.id
              AND group_member.user_id=_checker_user_id
            JOIN public.tenant_members active_member ON active_member.tenant_id=_tenant_id
              AND active_member.user_id=group_member.user_id AND active_member.active
            JOIN public.bu_group_assignments group_assignment ON group_assignment.tenant_id=_tenant_id
              AND group_assignment.group_id=group_row.id
            JOIN public.business_units assigned_unit ON assigned_unit.id=group_assignment.bu_id
              AND assigned_unit.tenant_id=group_assignment.tenant_id AND NOT assigned_unit.is_archived
            JOIN public.business_units owner_unit ON owner_unit.id=owner.bu_id
              AND owner_unit.tenant_id=group_assignment.tenant_id AND NOT owner_unit.is_archived
            WHERE group_row.id=grant_row.principal_id AND group_row.tenant_id=_tenant_id
              AND (assigned_unit.id=owner_unit.id OR
                   (group_assignment.inherit_descendants AND owner_unit.path <@ assigned_unit.path))
          )))
    )
  ) THEN
    RAISE EXCEPTION 'maker/checker assignments and reviewed grants are incomplete' USING ERRCODE='42501';
  END IF;

  INSERT INTO private.recon_legacy_mapping_cutover_receipts(
    tenant_id,recon_id,actor_id,owner_bu_ids,maker_user_id,checker_user_id,reason
  ) VALUES (_tenant_id,_recon_id,v_actor,v_owner_ids,_maker_user_id,_checker_user_id,btrim(_reason))
  RETURNING id INTO v_receipt_id;
  INSERT INTO public.recon_definition_bu_admin_audit(
    tenant_id,recon_id,operation,actor_id,reason,details
  ) VALUES (_tenant_id,_recon_id,'map_legacy',v_actor,btrim(_reason),jsonb_build_object(
    'receipt_id',v_receipt_id,'owner_bu_ids',v_owner_ids,'maker_user_id',_maker_user_id,
    'maker_actions',ARRAY['view','run','edit'],'checker_user_id',_checker_user_id,
    'checker_actions',ARRAY['view','approve'],'previous_access_mode',v_definition.access_mode,
    'previous_governance_state',v_definition.governance_state,'new_access_mode','mapped_exact',
    'new_governance_state','legacy_mapped','status_preserved',v_definition.status,
    'legacy_bu_id_preserved',v_definition.bu_id,'scope','owner_authorized_synthetic_assurance'
  ));
  UPDATE public.recon_definitions
  SET access_mode='mapped_exact', governance_state='legacy_mapped', multi_bu_governed=true
  WHERE id=_recon_id AND tenant_id=_tenant_id
    AND access_mode='legacy_passthrough' AND governance_state='legacy_unreviewed';
  IF NOT FOUND THEN RAISE EXCEPTION 'legacy definition changed during mapping cutover'; END IF;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES (v_actor,_tenant_id,'workspace','recon.legacy_mapping.cutover','recon_definition',_recon_id::text,
    jsonb_build_object('receipt_id',v_receipt_id,'recon_code',v_definition.recon_code,
      'owner_bu_ids',v_owner_ids,'maker_user_id',_maker_user_id,'checker_user_id',_checker_user_id,
      'reason',btrim(_reason),'status_preserved',v_definition.status,
      'legacy_bu_id_preserved',v_definition.bu_id,'governance_state','legacy_mapped'));
  RETURN jsonb_build_object('recon_id',_recon_id,'recon_code',v_definition.recon_code,
    'access_mode','mapped_exact','governance_state','legacy_mapped','status',v_definition.status,
    'legacy_bu_id',v_definition.bu_id,'owner_bu_ids',v_owner_ids,'audit_receipt_id',v_receipt_id);
END
$function$
;

CREATE OR REPLACE FUNCTION public.decide_collateral_csa_version(_tenant_id uuid, _version_id uuid, _approve boolean, _reason text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE actor uuid := auth.uid(); version_row public.collateral_csa_versions%ROWTYPE; other_active public.collateral_csa_versions%ROWTYPE;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'collateral');

  IF NOT public.csa_assurance_actor(_tenant_id,actor) THEN
    RAISE EXCEPTION 'Active tenant administrator required' USING ERRCODE='42501';
  END IF;
  SELECT * INTO version_row FROM public.collateral_csa_versions WHERE tenant_id=_tenant_id AND id=_version_id FOR UPDATE;
  IF NOT FOUND OR version_row.status<>'pending_approval' THEN RAISE EXCEPTION 'Version is not awaiting approval' USING ERRCODE='22023'; END IF;
  IF actor=version_row.created_by OR actor=version_row.submitted_by THEN RAISE EXCEPTION 'Maker and checker must be different users' USING ERRCODE='42501'; END IF;
  IF _approve THEN
    PERFORM 1 FROM public.collateral_csa_agreements WHERE tenant_id=_tenant_id AND id=version_row.agreement_id FOR UPDATE;
    IF EXISTS (SELECT 1 FROM public.collateral_csa_versions v WHERE v.tenant_id=_tenant_id AND v.agreement_id=version_row.agreement_id
      AND v.status IN ('active','superseded') AND daterange(v.effective_from,v.effective_to,'[]')
        && daterange(version_row.effective_from,version_row.effective_to,'[]')) THEN
      RAISE EXCEPTION 'Effective period overlaps the current active agreement version' USING ERRCODE='22023';
    END IF;
    SELECT * INTO other_active FROM public.collateral_csa_versions WHERE tenant_id=_tenant_id AND agreement_id=version_row.agreement_id AND id<>_version_id AND status='active';
    IF FOUND THEN UPDATE public.collateral_csa_versions SET status='superseded' WHERE id=other_active.id; END IF;
    UPDATE public.collateral_csa_versions SET status='active',approved_by=actor,approved_at=now() WHERE id=_version_id;
  ELSE
    UPDATE public.collateral_csa_versions SET status='rejected' WHERE id=_version_id;
  END IF;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES(actor,_tenant_id,'tenant',CASE WHEN _approve THEN 'collateral.csa.version.activate' ELSE 'collateral.csa.version.reject' END,
    'collateral_csa_version',_version_id::text,jsonb_build_object('version_no',version_row.version_no,'reason',left(coalesce(_reason,''),1000)));
  RETURN CASE WHEN _approve THEN 'active' ELSE 'rejected' END;
END $function$
;

CREATE OR REPLACE FUNCTION public.decide_reference_data_version(_tenant_id uuid, _version_id uuid, _approve boolean, _reason text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  actor uuid := auth.uid();
  v_version public.reference_data_versions%ROWTYPE;
  v_prior public.reference_data_versions%ROWTYPE;
  v_is_effective_now boolean;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'reference');

  SELECT * INTO v_version
  FROM public.reference_data_versions
  WHERE id = _version_id AND tenant_id = _tenant_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Reference version not found'; END IF;
  IF actor IS NULL OR NOT (
    EXISTS (
      SELECT 1 FROM public.tenant_members tm
      WHERE tm.user_id = actor AND tm.tenant_id = _tenant_id
        AND tm.role = 'tenant_admin' AND tm.active
    ) OR public.is_platform_admin(actor)
  ) THEN
    RAISE EXCEPTION 'Forbidden: active tenant administrator required' USING ERRCODE = '42501';
  END IF;
  IF actor = v_version.created_by OR actor = v_version.submitted_by THEN
    RAISE EXCEPTION 'Maker cannot approve or reject their own version' USING ERRCODE = '42501';
  END IF;
  IF v_version.status <> 'pending_approval' THEN
    RAISE EXCEPTION 'Only a pending version may be decided';
  END IF;
  IF NOT _approve AND length(btrim(coalesce(_reason, ''))) < 3 THEN
    RAISE EXCEPTION 'Rejection reason must contain at least 3 characters';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(v_version.table_id::text, 0));
  IF NOT _approve THEN
    UPDATE public.reference_data_versions
    SET status = 'rejected', decided_by = actor, decided_at = now(),
        decision_reason = btrim(_reason)
    WHERE id = _version_id;
    INSERT INTO public.audit_log(
      actor_user_id, tenant_id, scope, action, resource_type, resource_id, context
    ) VALUES (
      actor, _tenant_id, 'tenant', 'reference_data.version.reject',
      'reference_data_versions', _version_id::text,
      jsonb_build_object('table_id', v_version.table_id, 'version', v_version.version_number,
        'reason', btrim(_reason), 'content_sha256', v_version.content_sha256)
    );
    RETURN 'rejected';
  END IF;

  SELECT * INTO v_prior
  FROM public.reference_data_versions rdv
  WHERE rdv.table_id = v_version.table_id
    AND rdv.status IN ('published','superseded')
  ORDER BY rdv.effective_from DESC, rdv.version_number DESC
  LIMIT 1
  FOR UPDATE;

  IF FOUND AND v_version.effective_from <= v_prior.effective_from THEN
    RAISE EXCEPTION 'Approved versions must advance the effective date';
  END IF;
  IF FOUND AND (v_prior.effective_to IS NULL OR v_prior.effective_to >= v_version.effective_from) THEN
    UPDATE public.reference_data_versions
    SET effective_to = v_version.effective_from - 1
    WHERE id = v_prior.id;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.reference_data_versions rdv
    WHERE rdv.table_id = v_version.table_id
      AND rdv.id <> v_version.id
      AND rdv.id <> v_prior.id
      AND rdv.status IN ('published','superseded')
      AND daterange(rdv.effective_from, coalesce(rdv.effective_to, 'infinity'::date), '[]')
          && daterange(v_version.effective_from, coalesce(v_version.effective_to, 'infinity'::date), '[]')
  ) THEN
    RAISE EXCEPTION 'Published reference version effective dates overlap';
  END IF;

  UPDATE public.reference_data_versions
  SET status = 'published', decided_by = actor, decided_at = now(),
      decision_reason = nullif(btrim(coalesce(_reason, '')), ''), published_at = now()
  WHERE id = _version_id;

  v_is_effective_now := v_version.effective_from <= current_date
    AND (v_version.effective_to IS NULL OR v_version.effective_to >= current_date);
  IF v_is_effective_now THEN
    UPDATE public.reference_data_versions
    SET status = 'superseded'
    WHERE table_id = v_version.table_id AND id <> v_version.id AND status = 'published'
      AND effective_from <= current_date
      AND (effective_to IS NULL OR effective_to >= current_date);

    DELETE FROM public.reference_data_rows
    WHERE table_id = v_version.table_id AND tenant_id = _tenant_id;
    INSERT INTO public.reference_data_rows(table_id, tenant_id, row_data, version_id)
    SELECT v_version.table_id, _tenant_id, r.row_data, v_version.id
    FROM public.reference_data_version_rows r
    WHERE r.version_id = v_version.id;
    UPDATE public.reference_data_tables
    SET row_count = v_version.row_count, published_version_id = v_version.id
    WHERE id = v_version.table_id AND tenant_id = _tenant_id;
  END IF;

  INSERT INTO public.audit_log(
    actor_user_id, tenant_id, scope, action, resource_type, resource_id, context
  ) VALUES (
    actor, _tenant_id, 'tenant', 'reference_data.version.publish',
    'reference_data_versions', _version_id::text,
    jsonb_build_object('table_id', v_version.table_id, 'version', v_version.version_number,
      'rows', v_version.row_count, 'content_sha256', v_version.content_sha256,
      'effective_from', v_version.effective_from, 'effective_to', v_version.effective_to,
      'projection_updated', v_is_effective_now)
  );
  RETURN 'published';
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_collateral_csa_access_editor(_tenant_id uuid, _agreement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE v_registry uuid; v_owners uuid[]; v_groups uuid[];
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'collateral');

  IF auth.uid() IS NULL OR _tenant_id IS NULL OR _agreement_id IS NULL
    OR NOT EXISTS(SELECT 1 FROM public.tenant_members m WHERE m.tenant_id=_tenant_id
      AND m.user_id=auth.uid() AND m.active AND m.role='tenant_admin'::public.tenant_role)
    OR NOT EXISTS(SELECT 1 FROM public.collateral_csa_agreements a
      WHERE a.id=_agreement_id AND a.tenant_id=_tenant_id)
  THEN RAISE EXCEPTION 'not authorized' USING ERRCODE='42501'; END IF;
  SELECT r.id INTO v_registry FROM public.data_resource_registry r
    WHERE r.tenant_id=_tenant_id AND r.resource_type='collateral_csa_agreement'
      AND r.collateral_csa_agreement_id=_agreement_id;
  SELECT coalesce(array_agg(o.bu_id ORDER BY o.bu_id),ARRAY[]::uuid[]) INTO v_owners
    FROM public.data_resource_registry_owner_bu o
    WHERE o.tenant_id=_tenant_id AND o.registry_id=v_registry;
  SELECT coalesce(array_agg(DISTINCT g.principal_group_id ORDER BY g.principal_group_id),ARRAY[]::uuid[])
    INTO v_groups FROM public.data_resource_registry_grants g
    WHERE g.tenant_id=_tenant_id AND g.registry_id=v_registry
      AND g.principal_type='group' AND g.action='view';
  RETURN jsonb_build_object('registered',v_registry IS NOT NULL,
    'owner_bu_ids',v_owners,'group_ids',v_groups,
    'business_units',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',b.id,'name',b.name)
      ORDER BY b.name,b.id),'[]'::jsonb) FROM public.business_units b
      WHERE b.tenant_id=_tenant_id AND NOT b.is_archived),
    'user_groups',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',g.id,'name',g.name)
      ORDER BY g.name,g.id),'[]'::jsonb) FROM public.tenant_groups g
      WHERE g.tenant_id=_tenant_id));
END $function$
;

CREATE OR REPLACE FUNCTION public.import_recon_definitions_with_owners(_tenant_id uuid, _definitions jsonb, _owner_bu_ids uuid[], _mode text DEFAULT 'skip'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_is_admin boolean;
  v_owner_ids uuid[];
  v_existing_owner_ids uuid[];
  v_item jsonb;
  v_name text;
  v_description text;
  v_recon_type text;
  v_sides jsonb;
  v_rules jsonb;
  v_side_count integer;
  v_source_count integer;
  v_distinct_source_count integer;
  v_existing_id uuid;
  v_existing_status text;
  v_existing_state text;
  v_existing_access text;
  v_existing_environment text;
  v_existing_multi_bu boolean;
  v_inserted integer := 0;
  v_updated integer := 0;
  v_skipped integer := 0;
  v_created record;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'recons');

  IF v_actor IS NULL OR _tenant_id IS NULL OR _mode IS NULL OR _mode NOT IN ('skip','overwrite')
     OR jsonb_typeof(_definitions) IS DISTINCT FROM 'array'
     OR jsonb_array_length(_definitions) NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'invalid reconciliation import request' USING ERRCODE='22023';
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.tenant_members member_row
    WHERE member_row.tenant_id=_tenant_id AND member_row.user_id=v_actor
      AND member_row.active AND member_row.role::text='tenant_admin'
  ) INTO v_is_admin;
  IF NOT v_is_admin AND NOT private.recon_governance_is_active_analyst(_tenant_id,v_actor) THEN
    RAISE EXCEPTION 'active tenant administrator or analyst required' USING ERRCODE='42501';
  END IF;

  SELECT coalesce(array_agg(DISTINCT bu_id ORDER BY bu_id),ARRAY[]::uuid[])
  INTO v_owner_ids FROM unnest(coalesce(_owner_bu_ids,ARRAY[]::uuid[])) AS bu_id;
  IF cardinality(v_owner_ids)=0 OR cardinality(v_owner_ids)<>cardinality(coalesce(_owner_bu_ids,ARRAY[]::uuid[])) THEN
    RAISE EXCEPTION 'choose one or more distinct owning business units' USING ERRCODE='22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(v_owner_ids) requested(bu_id)
    LEFT JOIN public.business_units bu ON bu.id=requested.bu_id AND bu.tenant_id=_tenant_id
    WHERE bu.id IS NULL OR bu.is_archived
  ) THEN
    RAISE EXCEPTION 'owning business units must be active and belong to this tenant' USING ERRCODE='42501';
  END IF;
  IF NOT v_is_admin AND EXISTS (
    SELECT 1 FROM unnest(v_owner_ids) requested(bu_id)
    WHERE NOT EXISTS (
      SELECT 1 FROM public.bu_user_assignments assignment
      JOIN public.business_units assigned_bu
        ON assigned_bu.id=assignment.bu_id AND assigned_bu.tenant_id=assignment.tenant_id
        AND NOT assigned_bu.is_archived
      JOIN public.business_units owner_bu
        ON owner_bu.id=requested.bu_id AND owner_bu.tenant_id=assignment.tenant_id
        AND NOT owner_bu.is_archived
      WHERE assignment.tenant_id=_tenant_id AND assignment.user_id=v_actor
        AND (owner_bu.id=assigned_bu.id OR (assignment.inherit_descendants AND owner_bu.path <@ assigned_bu.path))
    )
  ) THEN
    RAISE EXCEPTION 'analyst must be assigned to every selected owning business unit' USING ERRCODE='42501';
  END IF;

  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(_definitions) item
    GROUP BY lower(btrim(coalesce(item->>'name','')))
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'import file contains duplicate definition names' USING ERRCODE='22023';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(_definitions) AS items(value)
  LOOP
    v_name := btrim(coalesce(v_item->>'name',''));
    v_description := nullif(btrim(coalesce(v_item->>'description','')),'');
    v_recon_type := v_item->>'recon_type';
    v_sides := v_item->'sides';
    v_rules := v_item->'rules';
    IF jsonb_typeof(v_item) IS DISTINCT FROM 'object'
       OR jsonb_typeof(v_item->'name') IS DISTINCT FROM 'string'
       OR (v_item ? 'description' AND jsonb_typeof(v_item->'description') NOT IN ('string','null'))
       OR length(v_name) NOT BETWEEN 1 AND 120
       OR length(coalesce(v_description,'')) > 2000
       OR v_recon_type IS NULL OR v_recon_type NOT IN ('one_sided','two_sided','three_sided')
       OR jsonb_typeof(v_sides) IS DISTINCT FROM 'array'
       OR jsonb_typeof(v_rules) IS DISTINCT FROM 'array'
       OR jsonb_array_length(v_sides) > 3
       OR jsonb_array_length(v_rules) > 100
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(v_sides) side WHERE jsonb_typeof(side) IS DISTINCT FROM 'object')
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(v_rules) rule WHERE jsonb_typeof(rule) IS DISTINCT FROM 'object') THEN
      RAISE EXCEPTION 'an imported definition has invalid fields' USING ERRCODE='22023';
    END IF;
    v_side_count := jsonb_array_length(v_sides);
    IF v_side_count <> (CASE v_recon_type WHEN 'one_sided' THEN 1 WHEN 'two_sided' THEN 2 ELSE 3 END)
       OR EXISTS (
         SELECT 1 FROM jsonb_array_elements(v_sides) side
         WHERE coalesce(side->>'data_source_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       ) THEN
      RAISE EXCEPTION 'an imported definition has incomplete source bindings' USING ERRCODE='22023';
    END IF;
    SELECT count(*) INTO v_distinct_source_count
    FROM (
      SELECT DISTINCT (side->>'data_source_id')::uuid AS id
      FROM jsonb_array_elements(v_sides) side
    ) imported_ids;
    SELECT count(DISTINCT source_row.id) INTO v_source_count
    FROM public.workspace_data_sources source_row
    JOIN (
      SELECT DISTINCT (side->>'data_source_id')::uuid AS id
      FROM jsonb_array_elements(v_sides) side
    ) imported_source ON imported_source.id=source_row.id
    WHERE source_row.tenant_id=_tenant_id;
    IF v_source_count <> v_distinct_source_count THEN
      RAISE EXCEPTION 'every imported source must belong to this tenant' USING ERRCODE='42501';
    END IF;
    IF EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_sides) side
      WHERE nullif(side->>'upload_id','') IS NOT NULL
        AND NOT EXISTS (
          SELECT 1 FROM public.workspace_data_source_uploads upload_row
          WHERE upload_row.id=(side->>'upload_id')::uuid AND upload_row.tenant_id=_tenant_id
            AND upload_row.data_source_id=(side->>'data_source_id')::uuid
        )
    ) THEN
      RAISE EXCEPTION 'every imported upload must belong to its same-tenant source' USING ERRCODE='42501';
    END IF;

    SELECT definition_row.id, definition_row.status, definition_row.governance_state,
           definition_row.access_mode, definition_row.environment, definition_row.multi_bu_governed
    INTO v_existing_id, v_existing_status, v_existing_state, v_existing_access,
         v_existing_environment, v_existing_multi_bu
    FROM public.recon_definitions definition_row
    WHERE definition_row.tenant_id=_tenant_id AND lower(definition_row.name)=lower(v_name)
    ORDER BY definition_row.created_at, definition_row.id
    LIMIT 1 FOR UPDATE;

    IF v_existing_id IS NOT NULL THEN
      IF _mode='skip' THEN
        v_skipped := v_skipped + 1;
        CONTINUE;
      END IF;
      IF v_existing_status IS DISTINCT FROM 'draft'
         OR v_existing_state IS DISTINCT FROM 'development_draft'
         OR v_existing_access IS DISTINCT FROM 'mapped_exact'
         OR v_existing_environment IS DISTINCT FROM 'development'
         OR v_existing_multi_bu IS DISTINCT FROM true
         OR NOT private.recon_authoritative_access_decision(v_existing_id,'read')
         OR NOT private.recon_authoritative_access_decision(v_existing_id,'edit') THEN
        RAISE EXCEPTION 'only an editable development draft can be overwritten; the batch was not applied' USING ERRCODE='42501';
      END IF;
      SELECT coalesce(array_agg(owner_row.bu_id ORDER BY owner_row.bu_id),ARRAY[]::uuid[])
      INTO v_existing_owner_ids
      FROM public.recon_definition_business_units owner_row
      WHERE owner_row.tenant_id=_tenant_id AND owner_row.recon_id=v_existing_id;
      IF v_existing_owner_ids IS DISTINCT FROM v_owner_ids THEN
        RAISE EXCEPTION 'overwrite owner units must match the existing definition exactly' USING ERRCODE='42501';
      END IF;
      UPDATE public.recon_definitions
      SET description=v_description, recon_type=v_recon_type, sides=v_sides, rules=v_rules
      WHERE id=v_existing_id AND tenant_id=_tenant_id;
      IF NOT FOUND THEN RAISE EXCEPTION 'an imported definition could not be updated'; END IF;
      INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
      VALUES (v_actor,_tenant_id,'workspace','recon.bulk_import.overwrite','recon_definition',v_existing_id::text,
        jsonb_build_object('name',v_name,'owner_bu_ids',v_owner_ids,'mode',_mode));
      v_updated := v_updated + 1;
    ELSE
      SELECT * INTO v_created
      FROM public.create_recon_definition_with_owners(
        _tenant_id,v_name,v_description,v_recon_type,v_sides,v_rules,v_owner_ids
      );
      IF v_created.id IS NULL THEN RAISE EXCEPTION 'an imported definition was not created'; END IF;
      v_inserted := v_inserted + 1;
    END IF;
  END LOOP;

  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,context)
  VALUES (v_actor,_tenant_id,'workspace','recon.bulk_import','recon_definitions',
    jsonb_build_object('inserted',v_inserted,'updated',v_updated,'skipped',v_skipped,'mode',_mode,
      'owner_bu_ids',v_owner_ids,'definition_count',jsonb_array_length(_definitions)));
  RETURN jsonb_build_object('inserted',v_inserted,'updated',v_updated,'skipped',v_skipped);
END
$function$
;

CREATE OR REPLACE FUNCTION public.install_recon_starter_template_atomic(_tenant_id uuid, _template_id uuid, _name text, _sides jsonb, _rules jsonb)
 RETURNS TABLE(recon_definition_id uuid, recon_code text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor uuid := auth.uid();
  template_row public.recon_definition_templates%ROWTYPE;
  new_definition public.recon_definitions%ROWTYPE;
  leg_count integer;
  valid_source_count integer;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'templates');
  PERFORM private.wfm_assert_enabled(_tenant_id,'recons');

  IF actor IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE='42501'; END IF;
  IF NOT (
    public.is_platform_admin(actor)
    OR public.has_tenant_role(actor, _tenant_id, 'tenant_admin')
    OR public.has_tenant_role(actor, _tenant_id, 'tenant_analyst')
  ) THEN
    RAISE EXCEPTION 'analyst or admin role required' USING ERRCODE='42501';
  END IF;
  IF length(btrim(COALESCE(_name,''))) NOT BETWEEN 2 AND 80 THEN
    RAISE EXCEPTION 'invalid reconciliation name' USING ERRCODE='22023';
  END IF;

  SELECT * INTO template_row
  FROM public.recon_definition_templates
  WHERE id = _template_id AND status = 'published'
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'published template not found' USING ERRCODE='P0002'; END IF;

  leg_count := jsonb_array_length(template_row.legs);
  IF jsonb_typeof(_sides) <> 'array' OR jsonb_array_length(_sides) <> leg_count OR leg_count NOT BETWEEN 1 AND 3 THEN
    RAISE EXCEPTION 'every template leg requires one source binding' USING ERRCODE='22023';
  END IF;
  IF jsonb_typeof(_rules) <> 'array' OR jsonb_array_length(_rules) < 1 OR jsonb_array_length(_rules) > 50 THEN
    RAISE EXCEPTION 'compiled template rules are invalid' USING ERRCODE='22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(_sides) side
    WHERE COALESCE(side->>'side_id','') NOT IN ('A','B','C')
      OR NULLIF(side->>'data_source_id','') IS NULL
  ) OR (
    SELECT count(DISTINCT side->>'side_id') FROM jsonb_array_elements(_sides) side
  ) <> leg_count OR (
    SELECT count(DISTINCT side->>'data_source_id') FROM jsonb_array_elements(_sides) side
  ) <> leg_count THEN
    RAISE EXCEPTION 'template side bindings are invalid or duplicated' USING ERRCODE='22023';
  END IF;

  SELECT count(*) INTO valid_source_count
  FROM jsonb_array_elements(_sides) side
  JOIN public.workspace_data_sources source
    ON source.id = (side->>'data_source_id')::uuid
   AND source.tenant_id = _tenant_id;
  IF valid_source_count <> leg_count THEN
    RAISE EXCEPTION 'template source does not belong to tenant' USING ERRCODE='42501';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(_rules) rule
    WHERE COALESCE(rule->>'kind','') NOT IN (
      'exact_match','case_insensitive_match','trimmed_match','numeric_equals',
      'numeric_tolerance_abs','numeric_tolerance_pct','amount_sign_flip','date_equals',
      'date_tolerance_days','date_within_range','date_age_days','string_contains','string_starts_with',
      'string_ends_with','regex_match','fuzzy_levenshtein','phonetic_soundex',
      'currency_equals','boolean_equals','non_null','unique','in_set','sum_to_match',
      'many_to_one_sum','one_to_many_sum','value_range','multiply','ignore_day_portion',
      'conditional_set','roll_up','reference_lookup','multi_pass','quick_fix'
    ) OR jsonb_typeof(rule->'fields') <> 'object'
  ) THEN
    RAISE EXCEPTION 'template compiled an unsupported rule' USING ERRCODE='22023';
  END IF;

  INSERT INTO public.recon_definitions(
    tenant_id,name,description,recon_type,sides,rules,status,created_by,
    starter_template_id,starter_template_code,starter_template_snapshot
  ) VALUES (
    _tenant_id,btrim(_name),template_row.summary,
    CASE leg_count WHEN 1 THEN 'one_sided' WHEN 2 THEN 'two_sided' ELSE 'three_sided' END,
    _sides,_rules,'draft',actor,template_row.id,template_row.code,
    jsonb_build_object(
      'template_code',template_row.code,'asset_class',template_row.asset_class,
      'legs',template_row.legs,'keys',template_row.keys,'rules',template_row.rules,
      'tolerances',template_row.tolerances,'sample_fields',template_row.sample_fields,
      'installed_at',now()
    )
  ) RETURNING * INTO new_definition;

  UPDATE public.recon_definition_templates
  SET install_count = install_count + 1
  WHERE id = template_row.id;

  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES (actor,_tenant_id,'workspace','recon.template.install','recon_definition',new_definition.id,
    jsonb_build_object(
      'recon_code',new_definition.recon_code,'template_id',template_row.id,
      'template_code',template_row.code,'asset_class',template_row.asset_class,
      'source_ids',(SELECT jsonb_agg(side->>'data_source_id') FROM jsonb_array_elements(_sides) side),
      'rule_count',jsonb_array_length(_rules)
    ));

  RETURN QUERY SELECT new_definition.id,new_definition.recon_code;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.mapped_recon_governance_hash(_value jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
 SELECT encode(sha256(convert_to(_value::text,'UTF8')),'hex')
$function$
;

CREATE OR REPLACE FUNCTION private.mapped_recon_governance_conflict(_code text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='recon_governance.'||_code; END $function$
;

CREATE OR REPLACE FUNCTION private.mapped_recon_governance_lock_scope(_tenant uuid, _recon uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
BEGIN
 -- A single per-parent workflow lock precedes request/definition locks. Parent
 -- Root FOR UPDATE fences new owner rows. Owner FOR UPDATE separately fences
 -- new grant FK references; FOR SHARE would still admit their KEY SHARE lock.
 PERFORM 1 FROM public.recon_definitions WHERE id=_recon AND tenant_id=_tenant FOR UPDATE;
 PERFORM 1 FROM public.recon_definition_business_units WHERE recon_id=_recon ORDER BY bu_id FOR UPDATE;
 PERFORM 1 FROM public.recon_definition_bu_grants WHERE recon_id=_recon ORDER BY id FOR SHARE;
 -- Protect the active owner/ancestor association used by native effective scope.
 PERFORM 1 FROM public.business_units b WHERE b.tenant_id=_tenant AND EXISTS(
  SELECT 1 FROM public.recon_definition_business_units o JOIN public.business_units owner ON owner.id=o.bu_id AND owner.tenant_id=o.tenant_id
  WHERE o.recon_id=_recon AND o.tenant_id=_tenant AND owner.path <@ b.path) ORDER BY b.id FOR UPDATE;
 PERFORM 1 FROM public.tenant_groups g WHERE g.tenant_id=_tenant AND EXISTS(
  SELECT 1 FROM public.recon_definition_bu_grants grant_row WHERE grant_row.recon_id=_recon
   AND grant_row.principal_type='group' AND grant_row.principal_id=g.id) ORDER BY g.id FOR UPDATE;
 PERFORM 1 FROM public.bu_user_assignments a WHERE a.tenant_id=_tenant AND EXISTS(
  SELECT 1 FROM public.recon_definition_bu_grants g WHERE g.recon_id=_recon AND g.tenant_id=_tenant
   AND g.principal_type='user' AND g.principal_id=a.user_id) ORDER BY a.bu_id,a.user_id FOR SHARE;
 PERFORM 1 FROM public.bu_group_assignments a WHERE a.tenant_id=_tenant AND EXISTS(
  SELECT 1 FROM public.recon_definition_bu_grants g WHERE g.recon_id=_recon AND g.tenant_id=_tenant
   AND g.principal_type='group' AND g.principal_id=a.group_id) ORDER BY a.bu_id,a.group_id FOR SHARE;
 PERFORM 1 FROM public.tenant_group_members m WHERE EXISTS(
  SELECT 1 FROM public.recon_definition_bu_grants g WHERE g.recon_id=_recon AND g.tenant_id=_tenant
   AND g.principal_type='group' AND g.principal_id=m.group_id) ORDER BY m.group_id,m.user_id FOR SHARE;
 PERFORM 1 FROM public.tenant_members m WHERE m.tenant_id=_tenant AND EXISTS (
  SELECT 1 FROM public.recon_definition_bu_grants g WHERE g.recon_id=_recon AND
   ((g.principal_type='user' AND g.principal_id=m.user_id) OR
    (g.principal_type='group' AND EXISTS(SELECT 1 FROM public.tenant_group_members gm WHERE gm.group_id=g.principal_id AND gm.user_id=m.user_id))))
 ORDER BY m.user_id FOR SHARE;
END $function$
;

CREATE OR REPLACE FUNCTION private.mapped_recon_governance_mapping(_tenant uuid, _recon uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE d public.recon_definitions%ROWTYPE; result jsonb;
BEGIN
 SELECT * INTO d FROM public.recon_definitions WHERE id=_recon AND tenant_id=_tenant;
 IF NOT FOUND OR d.access_mode<>'mapped_exact' THEN PERFORM private.mapped_recon_governance_conflict('mapped_scope_required'); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.recon_definition_business_units WHERE tenant_id=_tenant AND recon_id=_recon)
 OR EXISTS(SELECT 1 FROM public.recon_definition_business_units o LEFT JOIN public.business_units b ON b.id=o.bu_id AND b.tenant_id=o.tenant_id
  WHERE o.recon_id=_recon AND (o.tenant_id<>_tenant OR b.id IS NULL OR b.is_archived)) THEN
  PERFORM private.mapped_recon_governance_conflict('owner_scope_inactive_or_cross_tenant');
 END IF;
 IF EXISTS(SELECT 1 FROM public.recon_definition_bu_grants g WHERE g.recon_id=_recon AND
  (g.tenant_id<>_tenant OR NOT EXISTS(SELECT 1 FROM public.recon_definition_business_units o WHERE o.tenant_id=_tenant AND o.recon_id=_recon AND o.bu_id=g.bu_id)
   OR (g.principal_type='user' AND NOT EXISTS(SELECT 1 FROM public.tenant_members m WHERE m.tenant_id=_tenant AND m.user_id=g.principal_id AND m.active))
   OR (g.principal_type='group' AND NOT EXISTS(SELECT 1 FROM public.tenant_groups t WHERE t.id=g.principal_id AND t.tenant_id=_tenant))
   OR (g.principal_type='user' AND NOT EXISTS(
     SELECT 1 FROM public.bu_user_assignments a
     JOIN public.business_units assigned ON assigned.id=a.bu_id AND assigned.tenant_id=a.tenant_id AND NOT assigned.is_archived
     JOIN public.business_units owner ON owner.id=g.bu_id AND owner.tenant_id=g.tenant_id AND NOT owner.is_archived
     WHERE a.tenant_id=_tenant AND a.user_id=g.principal_id
     AND (owner.id=assigned.id OR (a.inherit_descendants AND owner.path <@ assigned.path))))
   OR (g.principal_type='group' AND NOT EXISTS(
     SELECT 1 FROM public.bu_group_assignments a
     JOIN public.business_units assigned ON assigned.id=a.bu_id AND assigned.tenant_id=a.tenant_id AND NOT assigned.is_archived
     JOIN public.business_units owner ON owner.id=g.bu_id AND owner.tenant_id=g.tenant_id AND NOT owner.is_archived
     WHERE a.tenant_id=_tenant AND a.group_id=g.principal_id
     AND (owner.id=assigned.id OR (a.inherit_descendants AND owner.path <@ assigned.path))))
   OR g.principal_type NOT IN ('user','group'))) THEN
  PERFORM private.mapped_recon_governance_conflict('grant_scope_inactive_or_cross_tenant');
 END IF;
 result:=jsonb_build_object('contract_version',1,'tenant_id',_tenant,'recon_id',_recon,'access_mode',d.access_mode,'multi_bu_governed',d.multi_bu_governed,
  'owners',(SELECT coalesce(jsonb_agg(to_jsonb(o) ORDER BY o.bu_id),'[]') FROM public.recon_definition_business_units o WHERE o.tenant_id=_tenant AND o.recon_id=_recon),
  'grants',(SELECT coalesce(jsonb_agg(to_jsonb(g) ORDER BY g.id),'[]') FROM public.recon_definition_bu_grants g WHERE g.tenant_id=_tenant AND g.recon_id=_recon),
  'owner_ancestors',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',b.id,'tenant_id',b.tenant_id,'path',b.path,'is_archived',b.is_archived) ORDER BY b.id),'[]') FROM public.business_units b WHERE b.tenant_id=_tenant AND EXISTS(SELECT 1 FROM public.recon_definition_business_units o JOIN public.business_units owner ON owner.id=o.bu_id AND owner.tenant_id=o.tenant_id WHERE o.tenant_id=_tenant AND o.recon_id=_recon AND owner.path <@ b.path)),
  'groups',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',g.id,'tenant_id',g.tenant_id,'bu_id',g.bu_id) ORDER BY g.id),'[]') FROM public.tenant_groups g WHERE g.tenant_id=_tenant AND EXISTS(SELECT 1 FROM public.recon_definition_bu_grants a WHERE a.recon_id=_recon AND a.principal_type='group' AND a.principal_id=g.id)),
  'user_assignments',(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.bu_id,a.user_id),'[]') FROM public.bu_user_assignments a WHERE a.tenant_id=_tenant AND EXISTS(SELECT 1 FROM public.recon_definition_bu_grants g WHERE g.recon_id=_recon AND g.principal_type='user' AND g.principal_id=a.user_id)),
  'group_assignments',(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.bu_id,a.group_id),'[]') FROM public.bu_group_assignments a WHERE a.tenant_id=_tenant AND EXISTS(SELECT 1 FROM public.recon_definition_bu_grants g WHERE g.recon_id=_recon AND g.principal_type='group' AND g.principal_id=a.group_id)),
  'group_members',(SELECT coalesce(jsonb_agg(to_jsonb(m) ORDER BY m.group_id,m.user_id),'[]') FROM public.tenant_group_members m WHERE EXISTS(SELECT 1 FROM public.recon_definition_bu_grants g WHERE g.tenant_id=_tenant AND g.recon_id=_recon AND g.principal_type='group' AND g.principal_id=m.group_id)),
  'principal_memberships',(SELECT coalesce(jsonb_agg(to_jsonb(m) ORDER BY m.user_id),'[]') FROM public.tenant_members m WHERE m.tenant_id=_tenant AND EXISTS(SELECT 1 FROM public.recon_definition_bu_grants g WHERE g.recon_id=_recon AND ((g.principal_type='user' AND g.principal_id=m.user_id) OR (g.principal_type='group' AND EXISTS(SELECT 1 FROM public.tenant_group_members gm WHERE gm.group_id=g.principal_id AND gm.user_id=m.user_id))))));
 RETURN result;
END $function$
;

CREATE OR REPLACE FUNCTION public.install_recon_starter_template_atomic(_tenant_id uuid, _template_id uuid, _name text, _sides jsonb, _rules jsonb, _owner_bu_ids uuid[])
 RETURNS TABLE(recon_definition_id uuid, recon_code text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE
  actor uuid := auth.uid();
  template_row public.recon_definition_templates%ROWTYPE;
  definition_row public.recon_definitions%ROWTYPE;
  leg_count integer;
  valid_source_count integer;
  definition_type text;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'templates');
  PERFORM private.wfm_assert_enabled(_tenant_id,'recons');

  IF actor IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE='42501'; END IF;
  IF NOT (
    public.is_platform_admin(actor)
    OR public.has_tenant_role(actor, _tenant_id, 'tenant_admin')
    OR public.has_tenant_role(actor, _tenant_id, 'tenant_analyst')
  ) THEN
    RAISE EXCEPTION 'analyst or admin role required' USING ERRCODE='42501';
  END IF;
  IF length(btrim(COALESCE(_name,''))) NOT BETWEEN 2 AND 80 THEN
    RAISE EXCEPTION 'invalid reconciliation name' USING ERRCODE='22023';
  END IF;
  IF coalesce(cardinality(_owner_bu_ids), 0) = 0 THEN
    RAISE EXCEPTION 'select at least one owning business unit' USING ERRCODE='22023';
  END IF;

  SELECT * INTO template_row
  FROM public.recon_definition_templates
  WHERE id = _template_id AND status = 'published'
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'published template not found' USING ERRCODE='P0002'; END IF;

  IF jsonb_typeof(template_row.legs) <> 'array' THEN
    RAISE EXCEPTION 'published template legs are invalid' USING ERRCODE='22023';
  END IF;
  leg_count := jsonb_array_length(template_row.legs);
  IF jsonb_typeof(_sides) <> 'array' OR jsonb_array_length(_sides) <> leg_count OR leg_count NOT BETWEEN 1 AND 3 THEN
    RAISE EXCEPTION 'every template leg requires one source binding' USING ERRCODE='22023';
  END IF;
  IF jsonb_typeof(_rules) <> 'array' OR jsonb_array_length(_rules) < 1 OR jsonb_array_length(_rules) > 50 THEN
    RAISE EXCEPTION 'compiled template rules are invalid' USING ERRCODE='22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(_sides) side
    WHERE COALESCE(side->>'side_id','') NOT IN ('A','B','C')
      OR NULLIF(side->>'data_source_id','') IS NULL
  ) OR (
    SELECT count(DISTINCT side->>'side_id') FROM jsonb_array_elements(_sides) side
  ) <> leg_count OR (
    SELECT count(DISTINCT side->>'data_source_id') FROM jsonb_array_elements(_sides) side
  ) <> leg_count THEN
    RAISE EXCEPTION 'template side bindings are invalid or duplicated' USING ERRCODE='22023';
  END IF;

  SELECT count(*) INTO valid_source_count
  FROM jsonb_array_elements(_sides) side
  JOIN public.workspace_data_sources source
    ON source.id = (side->>'data_source_id')::uuid
   AND source.tenant_id = _tenant_id;
  IF valid_source_count <> leg_count THEN
    RAISE EXCEPTION 'template source does not belong to tenant' USING ERRCODE='42501';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(_rules) rule
    WHERE COALESCE(rule->>'kind','') NOT IN (
      'exact_match','case_insensitive_match','trimmed_match','numeric_equals',
      'numeric_tolerance_abs','numeric_tolerance_pct','amount_sign_flip','date_equals',
      'date_tolerance_days','date_within_range','date_age_days','string_contains','string_starts_with',
      'string_ends_with','regex_match','fuzzy_levenshtein','phonetic_soundex',
      'currency_equals','boolean_equals','non_null','unique','in_set','sum_to_match',
      'many_to_one_sum','one_to_many_sum','value_range','multiply','ignore_day_portion',
      'conditional_set','roll_up','reference_lookup','multi_pass','quick_fix'
    ) OR jsonb_typeof(rule->'fields') <> 'object'
  ) THEN
    RAISE EXCEPTION 'template compiled an unsupported rule' USING ERRCODE='22023';
  END IF;

  definition_type := CASE leg_count WHEN 1 THEN 'one_sided' WHEN 2 THEN 'two_sided' ELSE 'three_sided' END;
  SELECT created.id, created.recon_code INTO definition_row.id, definition_row.recon_code
  FROM public.create_recon_definition_with_owners(
    _tenant_id, btrim(_name), template_row.summary, definition_type, _sides, _rules, _owner_bu_ids
  ) AS created;
  IF definition_row.id IS NULL THEN RAISE EXCEPTION 'owner-bound creation returned no reconciliation'; END IF;

  UPDATE public.recon_definitions
  SET starter_template_id = template_row.id,
      starter_template_code = template_row.code,
      starter_template_snapshot = jsonb_build_object(
        'template_code',template_row.code,'asset_class',template_row.asset_class,
        'legs',template_row.legs,'keys',template_row.keys,'rules',template_row.rules,
        'tolerances',template_row.tolerances,'sample_fields',template_row.sample_fields,
        'installed_at',now()
      )
  WHERE id = definition_row.id AND tenant_id = _tenant_id
  RETURNING * INTO definition_row;
  IF NOT FOUND THEN RAISE EXCEPTION 'created reconciliation was not readable in tenant'; END IF;

  UPDATE public.recon_definition_templates
  SET install_count = install_count + 1
  WHERE id = template_row.id;

  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES (actor,_tenant_id,'workspace','recon.template.install','recon_definition',definition_row.id::text,
    jsonb_build_object(
      'recon_code',definition_row.recon_code,'template_id',template_row.id,
      'template_code',template_row.code,'asset_class',template_row.asset_class,
      'owner_bu_ids',_owner_bu_ids,
      'source_ids',(SELECT jsonb_agg(side->>'data_source_id') FROM jsonb_array_elements(_sides) side),
      'rule_count',jsonb_array_length(_rules)
    ));

  RETURN QUERY SELECT definition_row.id,definition_row.recon_code;
END
$function$
;

CREATE OR REPLACE FUNCTION public.request_recon_retirement(_tenant_id uuid, _recon_id uuid, _reason text)
 RETURNS TABLE(request_id uuid, status text, tenant_id uuid, recon_id uuid, retired_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE actor uuid:=auth.uid(); definition_row public.recon_definitions%ROWTYPE; request_row public.recon_retirement_requests%ROWTYPE;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'recons');

  IF actor IS NULL OR _tenant_id IS NULL OR _recon_id IS NULL
     OR _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 1 AND 2000 THEN
    RAISE EXCEPTION 'valid authenticated actor, scope, and reason required' USING ERRCODE='22023';
  END IF;
  SELECT * INTO definition_row FROM public.recon_definitions d
    WHERE d.id=_recon_id AND d.tenant_id=_tenant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'reconciliation not found in tenant' USING ERRCODE='P0002'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.tenant_members m
    WHERE m.tenant_id=_tenant_id AND m.user_id=actor AND m.active=true)
     OR NOT private.user_can_govern_recon_retirement(actor,_recon_id,'edit') THEN
    RAISE EXCEPTION 'reconciliation edit and approval access required' USING ERRCODE='42501';
  END IF;
  IF definition_row.status='draft' THEN
    RAISE EXCEPTION 'unrun draft may use permission-governed physical delete' USING ERRCODE='22023';
  END IF;
  IF definition_row.retired_at IS NOT NULL THEN RAISE EXCEPTION 'reconciliation already retired' USING ERRCODE='23505'; END IF;
  IF EXISTS (SELECT 1 FROM public.recon_retirement_requests q
    WHERE q.recon_id=_recon_id AND q.status='pending') THEN
    RAISE EXCEPTION 'a retirement request is already pending' USING ERRCODE='23505';
  END IF;

  INSERT INTO public.recon_retirement_requests(tenant_id,recon_id,reason,requested_by)
    VALUES (_tenant_id,_recon_id,btrim(_reason),actor) RETURNING * INTO request_row;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
    VALUES (actor,_tenant_id,'workspace','recon.retirement.requested','recon_retirement_request',request_row.id::text,
      jsonb_build_object('recon_id',_recon_id,'reason',btrim(_reason),'requested_at',request_row.requested_at));
  RETURN QUERY SELECT request_row.id,request_row.status,request_row.tenant_id,request_row.recon_id,NULL::timestamptz;
END $function$
;

CREATE OR REPLACE FUNCTION public.request_reference_data_rollback(_tenant_id uuid, _table_id uuid, _source_version_id uuid, _effective_from date, _reason text)
 RETURNS TABLE(version_id uuid, version_number integer, row_count integer, content_sha256 text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor uuid := auth.uid();
  source_version public.reference_data_versions%ROWTYPE;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'reference');

  IF actor IS NULL OR NOT (
    EXISTS (
      SELECT 1 FROM public.tenant_members tm
      WHERE tm.user_id = actor AND tm.tenant_id = _tenant_id
        AND tm.role = 'tenant_admin' AND tm.active
    ) OR public.is_platform_admin(actor)
  ) THEN
    RAISE EXCEPTION 'Forbidden: active tenant administrator required' USING ERRCODE = '42501';
  END IF;
  IF length(btrim(coalesce(_reason, ''))) < 3 THEN
    RAISE EXCEPTION 'Rollback reason must contain at least 3 characters';
  END IF;
  SELECT * INTO source_version
  FROM public.reference_data_versions
  WHERE id = _source_version_id AND table_id = _table_id AND tenant_id = _tenant_id
    AND status IN ('published','superseded');
  IF NOT FOUND THEN RAISE EXCEPTION 'Published source version not found'; END IF;

  RETURN QUERY
  SELECT staged.version_id, staged.version_number, staged.row_count, staged.content_sha256
  FROM public.stage_reference_data_version(
    _tenant_id,
    _table_id,
    (SELECT jsonb_agg(r.row_data ORDER BY r.key_hash)
     FROM public.reference_data_version_rows r WHERE r.version_id = _source_version_id),
    _effective_from,
    NULL,
    format('Rollback to version %s: %s', source_version.version_number, btrim(_reason))
  ) staged;

  INSERT INTO public.audit_log(
    actor_user_id, tenant_id, scope, action, resource_type, resource_id, context
  ) VALUES (
    actor, _tenant_id, 'tenant', 'reference_data.version.rollback_requested',
    'reference_data_versions', _source_version_id::text,
    jsonb_build_object('table_id', _table_id, 'source_version', source_version.version_number,
      'effective_from', _effective_from, 'reason', btrim(_reason))
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION private.mapped_recon_governance_scope_shape(_tenant uuid, _recon uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 SELECT jsonb_build_object(
 'owners',(SELECT coalesce(jsonb_agg(bu_id ORDER BY bu_id),'[]') FROM public.recon_definition_business_units WHERE tenant_id=_tenant AND recon_id=_recon),
 'grants',(SELECT coalesce(jsonb_agg(jsonb_build_array(bu_id,principal_type,principal_id,action) ORDER BY bu_id,principal_type,principal_id,action),'[]') FROM public.recon_definition_bu_grants WHERE tenant_id=_tenant AND recon_id=_recon))
$function$
;

CREATE OR REPLACE FUNCTION private.mapped_recon_governance_stage_insert(_new recon_definitions)
 RETURNS recon_definitions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE q public.recon_definition_governance_requests%ROWTYPE; p public.recon_definitions%ROWTYPE; marker uuid;
BEGIN
 marker:=nullif(current_setting('fvi.recon_governance_request_id',true),'')::uuid;
 SELECT * INTO q FROM public.recon_definition_governance_requests WHERE id=marker;
 IF NOT FOUND OR NOT private.mapped_recon_governance_transition(q.id,'edit_decision')
 OR q.request_kind<>'edit' OR q.status<>'approved' OR q.mapped_governance_version IS DISTINCT FROM 1
 OR q.decided_by IS DISTINCT FROM auth.uid() OR q.requested_by=auth.uid() OR q.staging_definition_id IS NOT NULL THEN
  PERFORM private.mapped_recon_governance_conflict('native_stage_authorization_required');
 END IF;
 SELECT * INTO p FROM public.recon_definitions WHERE tenant_id=q.tenant_id AND id=q.parent_definition_id;
 PERFORM private.mapped_recon_governance_actor(q.tenant_id,p.id,'approve',true);
 PERFORM private.mapped_recon_governance_requester_current(q.tenant_id,p.id,q.requested_by);
 IF _new.id=p.id OR _new.tenant_id IS DISTINCT FROM p.tenant_id OR _new.created_by IS DISTINCT FROM q.requested_by
 OR _new.governance_parent_id IS DISTINCT FROM p.id OR _new.access_mode<>'mapped_exact'
 OR _new.governance_state<>'staging_copy' OR _new.environment<>'staging' OR _new.status<>'draft'
 OR _new.multi_bu_governed IS DISTINCT FROM p.multi_bu_governed OR NOT _new.multi_bu_governed
 OR _new.bu_id IS DISTINCT FROM p.bu_id OR _new.visibility IS DISTINCT FROM p.visibility
 OR _new.starter_template_id IS DISTINCT FROM p.starter_template_id OR _new.starter_template_code IS DISTINCT FROM p.starter_template_code
 OR _new.starter_template_snapshot IS DISTINCT FROM p.starter_template_snapshot OR _new.tenant_template_id IS DISTINCT FROM p.tenant_template_id
 OR _new.retired_at IS NOT NULL OR _new.retirement_request_id IS NOT NULL
 OR _new.staging_original_name IS DISTINCT FROM p.name OR _new.staging_generated_name IS DISTINCT FROM _new.name
 OR private.mapped_recon_governance_effective_config(_new) IS DISTINCT FROM private.recon_definition_config_snapshot(p)
 OR private.mapped_recon_governance_hash(private.recon_definition_config_snapshot(p)) IS DISTINCT FROM q.parent_config_fingerprint
 OR private.mapped_recon_governance_mapping(q.tenant_id,p.id) IS DISTINCT FROM q.parent_mapping_snapshot THEN
  PERFORM private.mapped_recon_governance_conflict('native_stage_snapshot_mismatch');
 END IF;
 RETURN _new;
END $function$
;

CREATE OR REPLACE FUNCTION private.mapped_recon_governance_update(_old recon_definitions, _new recon_definitions)
 RETURNS recon_definitions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE q public.recon_definition_governance_requests%ROWTYPE; marker uuid; purpose text; permitted boolean:=false;
BEGIN
 IF (to_jsonb(_old)-ARRAY['name','description','recon_type','sides','rules','extension','governance_state','environment','status','updated_at'])
 IS DISTINCT FROM (to_jsonb(_new)-ARRAY['name','description','recon_type','sides','rules','extension','governance_state','environment','status','updated_at']) THEN
  PERFORM private.mapped_recon_governance_conflict('native_identity_or_scope_immutable');
 END IF;
 IF _old.governance_state=_new.governance_state AND _old.governance_state IN ('development_draft','staging_copy') THEN
  IF _new.environment IS DISTINCT FROM _old.environment OR _new.status IS DISTINCT FROM _old.status THEN
   PERFORM private.mapped_recon_governance_conflict('native_draft_lifecycle_immutable');
  END IF;
  PERFORM private.mapped_recon_governance_actor(_old.tenant_id,_old.id,'edit',false);
  IF NOT private.recon_authoritative_access_decision_as(auth.uid(),_old.id,'read') THEN
   PERFORM private.mapped_recon_governance_conflict('native_current_read_required');
  END IF;
  RETURN _new;
 END IF;
 -- Pure trigger timestamps on a locked row do not change its configuration.
 IF to_jsonb(_old)-'updated_at'=to_jsonb(_new)-'updated_at' THEN RETURN _new; END IF;
 marker:=nullif(current_setting('fvi.recon_governance_request_id',true),'')::uuid;
 SELECT * INTO q FROM public.recon_definition_governance_requests WHERE id=marker AND tenant_id=_old.tenant_id;
 IF NOT FOUND OR q.mapped_governance_version IS DISTINCT FROM 1 THEN
  PERFORM private.mapped_recon_governance_conflict('native_workflow_receipt_required');
 END IF;
 purpose:=CASE WHEN q.request_kind='edit' AND q.status='pending' THEN 'edit_request'
 WHEN q.request_kind='edit' THEN 'edit_decision' WHEN q.status='pending' THEN 'promotion_submit' ELSE 'promotion_decision' END;
 IF NOT private.mapped_recon_governance_transition(q.id,purpose) THEN
  PERFORM private.mapped_recon_governance_conflict('native_workflow_receipt_required');
 END IF;
 IF q.status='pending' THEN
  IF q.requested_by IS DISTINCT FROM auth.uid() THEN PERFORM private.mapped_recon_governance_conflict('native_requester_mismatch'); END IF;
  PERFORM private.mapped_recon_governance_actor(q.tenant_id,_old.id,'edit',false);
 ELSE
  IF q.decided_by IS DISTINCT FROM auth.uid() OR q.requested_by=auth.uid() THEN PERFORM private.mapped_recon_governance_conflict('independent_checker_required'); END IF;
  PERFORM private.mapped_recon_governance_actor(q.tenant_id,q.parent_definition_id,'approve',true);
  PERFORM private.mapped_recon_governance_requester_current(q.tenant_id,q.parent_definition_id,q.requested_by);
 END IF;
 IF q.request_kind='edit' AND q.parent_definition_id=_old.id THEN
  permitted:=(q.status='pending' AND _old.governance_state='approved_locked' AND _new.governance_state='edit_request_pending')
   OR (q.status IN ('approved','rejected') AND _old.governance_state='edit_request_pending' AND _new.governance_state='approved_locked');
 ELSIF q.request_kind='promotion' THEN
  permitted:=(q.status='pending' AND q.staging_definition_id=_old.id AND _old.governance_state IN ('development_draft','staging_copy') AND _new.governance_state='promotion_request_pending')
   OR (q.status='rejected' AND q.staging_definition_id=_old.id AND _old.governance_state='promotion_request_pending' AND _new.governance_state=CASE WHEN q.parent_definition_id=_old.id THEN 'development_draft' ELSE 'staging_copy' END)
   OR (q.status='approved' AND q.parent_definition_id=_old.id AND _old.governance_state IN ('approved_locked','promotion_request_pending') AND _new.governance_state='approved_locked')
   OR (q.status='approved' AND q.staging_definition_id=_old.id AND q.parent_definition_id<>_old.id AND _old.governance_state='promotion_request_pending' AND _new.governance_state='promoted');
 END IF;
 IF NOT coalesce(permitted,false) THEN PERFORM private.mapped_recon_governance_conflict('native_invalid_transition'); END IF;
 IF q.request_kind='promotion' AND q.status='approved' AND q.parent_definition_id=_old.id THEN
  IF _new.environment<>'production' OR _new.status<>'active'
  OR private.recon_definition_config_snapshot(_new) IS DISTINCT FROM q.snapshot
  OR private.mapped_recon_governance_hash(q.snapshot) IS DISTINCT FROM q.snapshot_sha256
  OR private.mapped_recon_governance_mapping(q.tenant_id,_old.id) IS DISTINCT FROM q.parent_mapping_snapshot THEN
   PERFORM private.mapped_recon_governance_conflict('native_approved_snapshot_mismatch');
  END IF;
 ELSIF private.recon_definition_config_snapshot(_old) IS DISTINCT FROM private.recon_definition_config_snapshot(_new)
 OR _old.environment IS DISTINCT FROM _new.environment OR _old.status IS DISTINCT FROM _new.status THEN
  PERFORM private.mapped_recon_governance_conflict('native_transition_config_immutable');
 END IF;
 RETURN _new;
END $function$
;

CREATE OR REPLACE FUNCTION public.resolve_reference_data_version(_tenant_id uuid, _table_id uuid, _as_of date DEFAULT CURRENT_DATE)
 RETURNS TABLE(resolved_version_id uuid, resolved_version_number integer, resolved_content_sha256 text, resolved_rows jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'reference');

  IF NOT EXISTS(SELECT 1 FROM public.reference_data_tables root
      WHERE root.id=_table_id AND root.tenant_id=_tenant_id)
     OR NOT public.reference_scope_allows(_table_id,'view') THEN
    RAISE EXCEPTION 'reference_scope_denied' USING ERRCODE='42501'; END IF;
  RETURN QUERY SELECT * FROM public.resolve_reference_data_version_pre_scope(_tenant_id,_table_id,_as_of);
END $function$
;

CREATE OR REPLACE FUNCTION public.save_reference_table_atomic(_tenant_id uuid, _request_key uuid, _name text, _description text, _key_columns text[], _value_columns text[], _is_active boolean, _owner_bu_ids uuid[], _group_ids uuid[], _id uuid DEFAULT NULL::uuid, _expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, _expected_scope_hash text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth', 'extensions'
AS $function$
DECLARE
  v_actor uuid := auth.uid(); v_owners uuid[]; v_groups uuid[]; v_pairs jsonb;
  v_hash text; v_saved public.reference_table_save_requests%ROWTYPE;
  v_table public.reference_data_tables%ROWTYPE; v_registry uuid; v_before_scope text;
  v_group uuid; v_pair record; v_grant record; v_reply jsonb; v_audit_id bigint;
  v_reason text := 'Reference table atomic save'; v_changed boolean;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'reference');

  IF v_actor IS NULL OR auth.role() IS DISTINCT FROM 'authenticated'
    OR current_setting('role', true) IS DISTINCT FROM 'authenticated'
    OR _tenant_id IS NULL OR _request_key IS NULL THEN
    RAISE EXCEPTION 'Reference save requires an authenticated tenant administrator' USING ERRCODE = '42501';
  END IF;
  PERFORM 1 FROM public.tenant_members tm WHERE tm.tenant_id = _tenant_id
    AND tm.user_id = v_actor AND tm.active AND tm.role = 'tenant_admin'::public.tenant_role FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Reference save is not authorized' USING ERRCODE = '42501'; END IF;
  IF _name IS NULL OR length(_name) > 80 OR length(btrim(_name)) < 2
    OR length(_description) > 500 OR _is_active IS NULL
    OR coalesce(cardinality(_key_columns), 0) NOT BETWEEN 1 AND 50
    OR coalesce(cardinality(_value_columns), 0) > 50
    OR coalesce(cardinality(_owner_bu_ids), 0) NOT BETWEEN 1 AND 20
    OR coalesce(cardinality(_group_ids), 0) > 20
    OR array_ndims(_key_columns) <> 1 OR array_ndims(_owner_bu_ids) <> 1
    OR (coalesce(cardinality(_value_columns), 0) > 0 AND array_ndims(_value_columns) <> 1)
    OR (coalesce(cardinality(_group_ids), 0) > 0 AND array_ndims(_group_ids) <> 1)
    OR EXISTS (SELECT 1 FROM unnest(_key_columns || coalesce(_value_columns, ARRAY[]::text[])) x
      WHERE x IS NULL OR length(btrim(x)) NOT BETWEEN 1 AND 80)
    OR (SELECT count(DISTINCT lower(btrim(x))) FROM unnest(_key_columns) x) <> cardinality(_key_columns)
    OR (SELECT count(DISTINCT lower(btrim(x))) FROM unnest(coalesce(_value_columns, ARRAY[]::text[])) x)
      <> coalesce(cardinality(_value_columns), 0)
    OR array_position(_owner_bu_ids, NULL) IS NOT NULL OR array_position(_group_ids, NULL) IS NOT NULL THEN
    RAISE EXCEPTION 'Invalid Reference table save fields or scope' USING ERRCODE = '22023';
  END IF;
  IF _expected_scope_hash IS NOT NULL AND _expected_scope_hash !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'Invalid Reference scope version' USING ERRCODE = '22023';
  END IF;
  SELECT array_agg(DISTINCT x ORDER BY x) INTO v_owners FROM unnest(_owner_bu_ids) x;
  SELECT coalesce(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[]) INTO v_groups FROM unnest(_group_ids) x;
  v_hash := encode(extensions.digest(jsonb_build_object('tenant_id', _tenant_id, 'id', _id,
    'name', _name, 'description', _description, 'keys', _key_columns,
    'values', coalesce(_value_columns, ARRAY[]::text[]), 'is_active', _is_active,
    'owners', v_owners, 'groups', v_groups, 'expected_updated_at', _expected_updated_at,
    'expected_scope_hash', _expected_scope_hash)::text, 'sha256'), 'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended('fvi-reference-save:' || _tenant_id || ':' || v_actor || ':' || _request_key, 0));
  SELECT * INTO v_saved FROM public.reference_table_save_requests
    WHERE tenant_id = _tenant_id AND actor_id = v_actor AND request_key = _request_key;
  IF FOUND THEN
    IF v_saved.payload_hash <> v_hash THEN
      RAISE EXCEPTION 'Reference request key conflicts with another payload' USING ERRCODE = '23505';
    END IF;
    SELECT * INTO v_table FROM public.reference_data_tables
      WHERE id = v_saved.reference_table_id AND tenant_id = _tenant_id;
    v_changed := NOT FOUND OR v_table.updated_at IS DISTINCT FROM (v_saved.receipt->>'updated_at')::timestamptz;
    IF NOT v_changed THEN
      v_changed := private.reference_table_save_scope_hash(_tenant_id, (v_saved.receipt->>'registry_id')::uuid)
        IS DISTINCT FROM v_saved.receipt->>'scope_hash';
    END IF;
    IF NOT v_changed THEN
      v_changed := NOT public.reference_scope_allows(v_saved.reference_table_id, 'view')
        OR EXISTS (SELECT 1 FROM unnest(v_owners) AS requested(bu_id) WHERE NOT EXISTS (
          SELECT 1 FROM public.business_units b WHERE b.id = requested.bu_id AND b.tenant_id = _tenant_id AND NOT b.is_archived))
        OR EXISTS (SELECT 1 FROM jsonb_to_recordset(v_saved.receipt->'group_bu_pairs') AS pair(group_id uuid, bu_id uuid)
          WHERE NOT EXISTS (SELECT 1 FROM public.tenant_groups g JOIN public.bu_group_assignments ga
            ON ga.group_id = g.id AND ga.tenant_id = g.tenant_id
            JOIN public.business_units assigned ON assigned.id = ga.bu_id AND assigned.tenant_id = ga.tenant_id AND NOT assigned.is_archived
            JOIN public.business_units target ON target.id = pair.bu_id AND target.tenant_id = _tenant_id AND NOT target.is_archived
            WHERE g.id = pair.group_id AND g.tenant_id = _tenant_id
              AND (assigned.id = target.id OR (ga.inherit_descendants AND target.path <@ assigned.path))));
    END IF;
    RETURN v_saved.receipt || jsonb_build_object('replayed', true, 'current_state_changed', v_changed);
  END IF;

  IF _id IS NULL THEN
    IF _expected_updated_at IS NOT NULL OR _expected_scope_hash IS NOT NULL THEN
      RAISE EXCEPTION 'Creation has no prior version' USING ERRCODE = '22023';
    END IF;
  ELSE
    SELECT * INTO v_table FROM public.reference_data_tables WHERE id = _id AND tenant_id = _tenant_id FOR UPDATE;
    IF NOT FOUND OR NOT public.reference_scope_allows(_id, 'edit') THEN
      RAISE EXCEPTION 'Reference table edit is not authorized' USING ERRCODE = '42501';
    END IF;
    SELECT id INTO v_registry FROM public.data_resource_registry WHERE tenant_id = _tenant_id
      AND resource_type = 'reference_table' AND reference_table_id = _id FOR UPDATE;
    IF v_registry IS NULL OR v_table.access_mode <> 'mapped_exact' THEN
      RAISE EXCEPTION 'A mapped Reference table is required for governed update' USING ERRCODE = '23514';
    END IF;
    v_before_scope := private.reference_table_save_scope_hash(_tenant_id, v_registry);
    IF _expected_updated_at IS NULL OR _expected_scope_hash IS NULL
      OR v_table.updated_at IS DISTINCT FROM _expected_updated_at
      OR v_before_scope IS DISTINCT FROM _expected_scope_hash THEN
      RAISE EXCEPTION 'Reference table or access scope changed; refresh before saving' USING ERRCODE = '40001';
    END IF;
  END IF;

  -- Prevent assignment phantoms during pair validation/mutation; only a bounded
  -- save runs under this read lock. Selected group/BU rows are also locked.
  PERFORM set_config('lock_timeout', '5s', true);
  LOCK TABLE public.bu_group_assignments IN SHARE MODE;
  PERFORM 1 FROM public.business_units WHERE tenant_id = _tenant_id AND id = ANY(v_owners) AND NOT is_archived ORDER BY id FOR SHARE;
  IF EXISTS (SELECT 1 FROM unnest(v_owners) AS requested(bu_id) WHERE NOT EXISTS (
    SELECT 1 FROM public.business_units b WHERE b.id = requested.bu_id AND b.tenant_id = _tenant_id AND NOT b.is_archived)) THEN
    RAISE EXCEPTION 'Owner Business Units must be active in the same tenant' USING ERRCODE = '23514';
  END IF;
  FOREACH v_group IN ARRAY v_groups LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('fvi-principal-group:' || v_group::text, 0));
    PERFORM 1 FROM public.tenant_groups WHERE id = v_group AND tenant_id = _tenant_id FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Selected group is outside the tenant' USING ERRCODE = '23514'; END IF;
  END LOOP;
  PERFORM ga.id FROM public.bu_group_assignments ga JOIN public.business_units assigned
    ON assigned.id = ga.bu_id AND assigned.tenant_id = ga.tenant_id AND NOT assigned.is_archived
    WHERE ga.tenant_id = _tenant_id AND ga.group_id = ANY(v_groups) AND EXISTS (
      SELECT 1 FROM public.business_units target WHERE target.tenant_id = _tenant_id
        AND target.id = ANY(v_owners) AND NOT target.is_archived
        AND (assigned.id = target.id OR (ga.inherit_descendants AND target.path <@ assigned.path)))
    ORDER BY ga.group_id, ga.bu_id FOR SHARE OF ga, assigned;
  SELECT coalesce(jsonb_agg(jsonb_build_object('group_id', pair.group_id, 'bu_id', pair.bu_id)
    ORDER BY pair.group_id, pair.bu_id), '[]'::jsonb) INTO v_pairs
  FROM (SELECT g AS group_id, owner.id AS bu_id FROM unnest(v_groups) g
    JOIN public.business_units owner ON owner.tenant_id = _tenant_id AND owner.id = ANY(v_owners) AND NOT owner.is_archived
    WHERE EXISTS (SELECT 1 FROM public.bu_group_assignments ga JOIN public.business_units assigned
      ON assigned.id = ga.bu_id AND assigned.tenant_id = ga.tenant_id AND NOT assigned.is_archived
      WHERE ga.tenant_id = _tenant_id AND ga.group_id = g
        AND (assigned.id = owner.id OR (ga.inherit_descendants AND owner.path <@ assigned.path)))) pair;
  IF EXISTS (SELECT 1 FROM unnest(v_groups) g WHERE NOT EXISTS (
    SELECT 1 FROM jsonb_to_recordset(v_pairs) AS pair(group_id uuid, bu_id uuid) WHERE pair.group_id = g)) THEN
    RAISE EXCEPTION 'Selected group has no legitimate owning BU assignment' USING ERRCODE = '23514';
  END IF;

  IF _id IS NULL THEN
    INSERT INTO public.reference_data_tables(tenant_id, name, description, key_columns, value_columns, is_active, created_by)
      VALUES (_tenant_id, _name, _description, _key_columns, coalesce(_value_columns, ARRAY[]::text[]), _is_active, v_actor)
      RETURNING * INTO v_table;
    v_registry := public.register_typed_data_resource('reference_table', v_table.id, v_owners, v_reason);
  ELSE
    UPDATE public.reference_data_tables SET name = _name, description = _description,
      key_columns = _key_columns, value_columns = coalesce(_value_columns, ARRAY[]::text[]), is_active = _is_active
      WHERE id = _id AND tenant_id = _tenant_id RETURNING * INTO v_table;
    -- Replace only group-view pairs managed by this workflow. Non-view/user
    -- grants are preserved; the existing owner helper refuses conflicting removals.
    FOR v_grant IN SELECT g.id FROM public.data_resource_registry_grants g WHERE g.registry_id = v_registry
      AND g.tenant_id = _tenant_id AND g.principal_type = 'group' AND g.action = 'view'
      AND NOT EXISTS (SELECT 1 FROM jsonb_to_recordset(v_pairs) AS pair(group_id uuid, bu_id uuid)
        WHERE pair.group_id = g.principal_group_id AND pair.bu_id = g.bu_id)
    LOOP PERFORM public.revoke_typed_data_resource_action(v_grant.id, v_reason); END LOOP;
    PERFORM public.set_typed_data_resource_owners(v_registry, v_owners, v_reason);
  END IF;
  FOR v_pair IN SELECT * FROM jsonb_to_recordset(v_pairs) AS pair(group_id uuid, bu_id uuid)
  LOOP
    IF NOT EXISTS (SELECT 1 FROM public.data_resource_registry_grants WHERE tenant_id = _tenant_id
      AND registry_id = v_registry AND bu_id = v_pair.bu_id AND principal_type = 'group'
      AND principal_group_id = v_pair.group_id AND action = 'view') THEN
      PERFORM public.grant_typed_data_resource_action(v_registry, v_pair.bu_id, 'group', v_pair.group_id, 'view', v_reason);
    END IF;
  END LOOP;
  SELECT * INTO v_table FROM public.reference_data_tables WHERE id = v_table.id AND tenant_id = _tenant_id;
  v_reply := jsonb_build_object('id', v_table.id, 'registry_id', v_registry, 'request_key', _request_key,
    'updated_at', v_table.updated_at, 'scope_hash', private.reference_table_save_scope_hash(_tenant_id, v_registry),
    'group_bu_pairs', v_pairs, 'is_new', _id IS NULL, 'replayed', false, 'current_state_changed', false);
  INSERT INTO public.audit_log(actor_user_id, tenant_id, scope, action, resource_type, resource_id, context)
    VALUES (v_actor, _tenant_id, 'tenant', CASE WHEN _id IS NULL THEN 'reference_data.table.create' ELSE 'reference_data.table.update' END,
      'reference_data_tables', v_table.id::text, jsonb_build_object('name', _name, 'request_key', _request_key,
        'owner_bu_ids', v_owners, 'group_ids', v_groups, 'group_bu_pairs', v_pairs,
        'previous_scope_hash', v_before_scope, 'scope_hash', v_reply->>'scope_hash')) RETURNING id INTO v_audit_id;
  v_reply := v_reply || jsonb_build_object('audit_id', v_audit_id::text);
  INSERT INTO public.reference_table_save_requests(tenant_id, actor_id, request_key, payload_hash, reference_table_id, receipt)
    VALUES (_tenant_id, v_actor, _request_key, v_hash, v_table.id, v_reply);
  RETURN v_reply;
END $function$
;

CREATE OR REPLACE FUNCTION public.submit_collateral_csa_version(_tenant_id uuid, _version_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE actor uuid := auth.uid(); version_row public.collateral_csa_versions%ROWTYPE;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'collateral');

  IF NOT public.csa_assurance_actor(_tenant_id,actor) THEN
    RAISE EXCEPTION 'Active tenant administrator required' USING ERRCODE='42501';
  END IF;
  SELECT * INTO version_row FROM public.collateral_csa_versions WHERE tenant_id=_tenant_id AND id=_version_id FOR UPDATE;
  IF NOT FOUND OR version_row.created_by<>actor OR version_row.status<>'draft' THEN
    RAISE EXCEPTION 'Only the draft author can submit a draft version' USING ERRCODE='42501';
  END IF;
  UPDATE public.collateral_csa_versions SET status='pending_approval',submitted_by=actor,submitted_at=now() WHERE id=_version_id;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES(actor,_tenant_id,'tenant','collateral.csa.version.submit','collateral_csa_version',_version_id::text,jsonb_build_object('version_no',version_row.version_no));
  RETURN 'pending_approval';
END $function$
;

CREATE OR REPLACE FUNCTION public.submit_reference_data_version(_tenant_id uuid, _version_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor uuid := auth.uid();
  v_version public.reference_data_versions%ROWTYPE;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'reference');

  SELECT * INTO v_version
  FROM public.reference_data_versions
  WHERE id = _version_id AND tenant_id = _tenant_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Reference version not found'; END IF;
  IF actor IS NULL OR actor <> v_version.created_by THEN
    RAISE EXCEPTION 'Only the version maker may submit it' USING ERRCODE = '42501';
  END IF;
  IF v_version.status <> 'draft' THEN RAISE EXCEPTION 'Only a draft may be submitted'; END IF;
  IF v_version.row_count < 1 OR v_version.content_sha256 IS NULL THEN
    RAISE EXCEPTION 'Reference version has no verified content';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(v_version.table_id::text, 0));
  UPDATE public.reference_data_versions
  SET status = 'pending_approval', submitted_by = actor, submitted_at = now()
  WHERE id = _version_id;

  INSERT INTO public.audit_log(
    actor_user_id, tenant_id, scope, action, resource_type, resource_id, context
  ) VALUES (
    actor, _tenant_id, 'tenant', 'reference_data.version.submit',
    'reference_data_versions', _version_id::text,
    jsonb_build_object('table_id', v_version.table_id, 'version', v_version.version_number,
      'content_sha256', v_version.content_sha256)
  );
  RETURN 'pending_approval';
END;
$function$
;

CREATE OR REPLACE FUNCTION private.wfm_collateral_asset_write_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 DECLARE tenant uuid;
 BEGIN
  IF TG_OP IN('UPDATE','DELETE') THEN
   SELECT c.tenant_id INTO tenant FROM public.collateral_qa_vm_calls c WHERE c.id=OLD.call_id;
   IF tenant IS NULL THEN RAISE EXCEPTION 'Current collateral asset parent scope is unavailable' USING ERRCODE='42501';END IF;
   IF current_setting('role',true)='authenticated' THEN PERFORM private.wfm_actor(tenant);END IF;
   PERFORM private.wfm_assert_enabled(tenant,'collateral');
  END IF;
  IF TG_OP IN('INSERT','UPDATE') THEN
   SELECT c.tenant_id INTO tenant FROM public.collateral_qa_vm_calls c WHERE c.id=NEW.call_id;
   IF tenant IS NULL THEN RAISE EXCEPTION 'Current collateral asset parent scope is unavailable' USING ERRCODE='42501';END IF;
   IF current_setting('role',true)='authenticated' THEN PERFORM private.wfm_actor(tenant);END IF;
   PERFORM private.wfm_assert_enabled(tenant,'collateral');
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD;ELSE RETURN NEW;END IF;
 END $function$
;

CREATE OR REPLACE FUNCTION public.decide_recon_definition_promotion(_request_id uuid, _approve boolean, _reason text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
DECLARE actor uuid; q public.recon_definition_governance_requests%ROWTYPE; parent public.recon_definitions%ROWTYPE; stage public.recon_definitions%ROWTYPE;
 next_version integer; current_version integer:=0; current_hash text; mapping jsonb; stage_map jsonb;
BEGIN
 IF _request_id IS NULL OR _approve IS NULL OR length(btrim(coalesce(_reason,''))) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'invalid promotion decision' USING ERRCODE='22023'; END IF;
 SELECT * INTO q FROM public.recon_definition_governance_requests WHERE id=_request_id AND request_kind='promotion';
 IF NOT FOUND THEN PERFORM private.mapped_recon_governance_conflict('request_missing_or_replayed'); END IF;
 -- Registered availability at the actual native tenant scope; original mapped authority/independent checker/audit program follows unchanged.
 PERFORM private.wfm_actor(q.tenant_id);
 PERFORM private.wfm_assert_enabled(q.tenant_id,'recons');

 PERFORM pg_advisory_xact_lock(hashtextextended('mapped-recon:'||q.tenant_id::text||':'||q.parent_definition_id::text,0));
 PERFORM private.mapped_recon_governance_lock_scope(q.tenant_id,q.parent_definition_id);
 IF q.staging_definition_id<>q.parent_definition_id THEN PERFORM private.mapped_recon_governance_lock_scope(q.tenant_id,q.staging_definition_id); END IF;
 SELECT * INTO q FROM public.recon_definition_governance_requests WHERE id=_request_id FOR UPDATE;
 SELECT * INTO parent FROM public.recon_definitions WHERE tenant_id=q.tenant_id AND id=q.parent_definition_id;
 SELECT * INTO stage FROM public.recon_definitions WHERE tenant_id=q.tenant_id AND id=q.staging_definition_id;
 actor:=private.mapped_recon_governance_actor(q.tenant_id,parent.id,'approve',true);
 IF actor=q.requested_by THEN PERFORM private.mapped_recon_governance_conflict('independent_checker_required'); END IF;
 IF q.status<>'pending' OR q.mapped_governance_version IS DISTINCT FROM 1 OR stage.governance_state<>'promotion_request_pending' THEN PERFORM private.mapped_recon_governance_conflict('request_stale_or_replayed'); END IF;
 IF NOT private.recon_authoritative_access_decision_as(actor,stage.id,'approve') THEN PERFORM private.mapped_recon_governance_conflict('current_stage_approve_authority_required'); END IF;
 PERFORM private.mapped_recon_governance_requester_current(q.tenant_id,parent.id,q.requested_by);
 PERFORM private.mapped_recon_governance_requester_current(q.tenant_id,stage.id,q.requested_by);
 mapping:=private.mapped_recon_governance_mapping(q.tenant_id,parent.id);stage_map:=private.mapped_recon_governance_mapping(q.tenant_id,stage.id);
 IF private.mapped_recon_governance_effective_config(stage) IS DISTINCT FROM q.snapshot OR private.mapped_recon_governance_hash(q.snapshot) IS DISTINCT FROM q.snapshot_sha256
 OR private.mapped_recon_governance_hash(private.recon_definition_config_snapshot(parent)) IS DISTINCT FROM q.parent_config_fingerprint
 OR mapping IS DISTINCT FROM q.parent_mapping_snapshot OR private.mapped_recon_governance_hash(mapping) IS DISTINCT FROM q.parent_mapping_fingerprint
 OR stage_map IS DISTINCT FROM q.staging_mapping_snapshot OR private.mapped_recon_governance_hash(stage_map) IS DISTINCT FROM q.staging_mapping_fingerprint THEN PERFORM private.mapped_recon_governance_conflict('frozen_config_or_mapping_changed'); END IF;
 IF parent.id<>stage.id THEN
  SELECT version_number,snapshot_sha256 INTO current_version,current_hash FROM public.recon_definition_approved_versions WHERE tenant_id=q.tenant_id AND parent_definition_id=parent.id ORDER BY version_number DESC LIMIT 1;
  IF current_version IS DISTINCT FROM q.source_version OR current_hash IS DISTINCT FROM q.source_sha256 OR parent.governance_state<>'approved_locked' OR parent.retired_at IS NOT NULL OR parent.status<>'active' OR parent.environment<>'production' THEN PERFORM private.mapped_recon_governance_conflict('parent_revision_changed'); END IF;
 ELSIF q.source_version<>0 OR q.source_sha256 IS NOT NULL OR EXISTS(SELECT 1 FROM public.recon_definition_approved_versions WHERE tenant_id=q.tenant_id AND parent_definition_id=parent.id) THEN
  PERFORM private.mapped_recon_governance_conflict('initial_version_already_exists');
 END IF;
 IF EXISTS(SELECT 1 FROM public.recon_retirement_requests WHERE tenant_id=q.tenant_id AND recon_id=parent.id AND status='pending') THEN PERFORM private.mapped_recon_governance_conflict('parent_retirement_pending'); END IF;
 INSERT INTO private.mapped_recon_governance_transitions(request_id,actor_id,purpose) VALUES(q.id,actor,'promotion_decision');
 UPDATE public.recon_definition_governance_requests SET status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,decision_reason=btrim(_reason),decided_by=actor,decided_at=clock_timestamp() WHERE id=q.id;
 PERFORM set_config('fvi.recon_governance_request_id',q.id::text,true);
 IF _approve THEN
  UPDATE public.recon_definitions SET name=q.snapshot->>'name',description=q.snapshot->>'description',recon_type=q.snapshot->>'recon_type',sides=q.snapshot->'sides',rules=q.snapshot->'rules',extension=q.snapshot->'extension',environment='production',status='active',governance_state='approved_locked' WHERE id=parent.id;
  IF parent.id<>stage.id THEN UPDATE public.recon_definitions SET governance_state='promoted' WHERE id=stage.id; END IF;
  SELECT coalesce(max(version_number),0)+1 INTO next_version FROM public.recon_definition_approved_versions WHERE tenant_id=q.tenant_id AND parent_definition_id=parent.id;
  INSERT INTO public.recon_definition_approved_versions(tenant_id,parent_definition_id,version_number,snapshot,snapshot_sha256,request_id,approved_by,approved_mapping_snapshot,approved_mapping_fingerprint) VALUES(q.tenant_id,parent.id,next_version,q.snapshot,q.snapshot_sha256,q.id,actor,q.parent_mapping_snapshot,q.parent_mapping_fingerprint);
 ELSE
  UPDATE public.recon_definitions SET governance_state=CASE WHEN id=parent.id THEN 'development_draft' ELSE 'staging_copy' END WHERE id=stage.id;
 END IF;
 INSERT INTO public.recon_definition_governance_audit(tenant_id,request_id,parent_definition_id,staging_definition_id,event_type,actor_id,reason,snapshot_sha256) VALUES(q.tenant_id,q.id,parent.id,stage.id,CASE WHEN _approve THEN 'promotion_approved' ELSE 'promotion_rejected' END,actor,btrim(_reason),q.snapshot_sha256);
 IF _approve THEN INSERT INTO public.recon_definition_governance_audit(tenant_id,request_id,parent_definition_id,staging_definition_id,event_type,actor_id,reason,snapshot_sha256) VALUES(q.tenant_id,q.id,parent.id,stage.id,'version_approved',actor,btrim(_reason),q.snapshot_sha256); END IF;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context) VALUES(actor,q.tenant_id,'workspace',CASE WHEN _approve THEN 'recon.definition.promotion_approved' ELSE 'recon.definition.promotion_rejected' END,'recon_definition_governance_request',q.id::text,jsonb_build_object('parent_definition_id',parent.id,'staging_definition_id',stage.id,'version_number',next_version,'snapshot_sha256',q.snapshot_sha256,'mapping_fingerprint',q.parent_mapping_fingerprint));
 RETURN CASE WHEN _approve THEN next_version ELSE NULL END;
END $function$
;

CREATE OR REPLACE FUNCTION public.submit_recon_definition_promotion(_tenant_id uuid, _staging_id uuid, _reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
DECLARE actor uuid; d public.recon_definitions%ROWTYPE; parent public.recon_definitions%ROWTYPE; parent_id uuid;
 snap jsonb; snap_hash text; v_id uuid; source_version integer:=0; source_hash text; parent_mapping jsonb; stage_mapping jsonb;
BEGIN
 -- Registered availability at the actual native tenant scope; original mapped authority/independent checker/audit program follows unchanged.
 PERFORM private.wfm_actor(_tenant_id);
 PERFORM private.wfm_assert_enabled(_tenant_id,'recons');

 IF _tenant_id IS NULL OR _staging_id IS NULL OR length(btrim(coalesce(_reason,''))) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'invalid promotion request' USING ERRCODE='22023'; END IF;
 SELECT coalesce(governance_parent_id,id) INTO parent_id FROM public.recon_definitions WHERE tenant_id=_tenant_id AND id=_staging_id;
 IF NOT FOUND THEN PERFORM private.mapped_recon_governance_conflict('draft_missing'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('mapped-recon:'||_tenant_id::text||':'||parent_id::text,0));
 PERFORM private.mapped_recon_governance_lock_scope(_tenant_id,parent_id);
 IF parent_id<>_staging_id THEN PERFORM private.mapped_recon_governance_lock_scope(_tenant_id,_staging_id); END IF;
 SELECT * INTO d FROM public.recon_definitions WHERE tenant_id=_tenant_id AND id=_staging_id;
 SELECT * INTO parent FROM public.recon_definitions WHERE tenant_id=_tenant_id AND id=parent_id;
 IF d.access_mode<>'mapped_exact' OR d.environment NOT IN ('development','staging') OR d.governance_state NOT IN ('development_draft','staging_copy') OR d.retired_at IS NOT NULL OR d.status='archived' THEN PERFORM private.mapped_recon_governance_conflict('editable_mapped_draft_required'); END IF;
 actor:=private.mapped_recon_governance_actor(_tenant_id,d.id,'edit',false);
 PERFORM private.mapped_recon_governance_requester_current(_tenant_id,parent.id,actor);
 IF parent.id<>d.id AND (parent.governance_state<>'approved_locked' OR parent.environment<>'production' OR parent.status<>'active' OR parent.retired_at IS NOT NULL) THEN PERFORM private.mapped_recon_governance_conflict('promotion_parent_not_eligible'); END IF;
 IF EXISTS(SELECT 1 FROM public.recon_retirement_requests WHERE tenant_id=_tenant_id AND recon_id=parent.id AND status='pending')
 OR EXISTS(SELECT 1 FROM public.recon_definition_governance_requests WHERE tenant_id=_tenant_id AND parent_definition_id=parent.id AND status='pending') THEN PERFORM private.mapped_recon_governance_conflict('pending_workflow_exists'); END IF;
 snap:=private.mapped_recon_governance_effective_config(d);snap_hash:=private.mapped_recon_governance_hash(snap);
 parent_mapping:=private.mapped_recon_governance_mapping(_tenant_id,parent.id);stage_mapping:=private.mapped_recon_governance_mapping(_tenant_id,d.id);
 IF parent.id<>d.id THEN
  SELECT version_number,snapshot_sha256 INTO source_version,source_hash FROM public.recon_definition_approved_versions WHERE tenant_id=_tenant_id AND parent_definition_id=parent.id ORDER BY version_number DESC LIMIT 1;
  IF source_version IS NULL OR source_hash IS DISTINCT FROM private.mapped_recon_governance_hash(private.recon_definition_config_snapshot(parent))
  OR NOT EXISTS(SELECT 1 FROM public.recon_definition_approved_versions WHERE tenant_id=_tenant_id AND parent_definition_id=parent.id
   AND version_number=source_version AND snapshot=private.recon_definition_config_snapshot(parent)
   AND snapshot_sha256=private.mapped_recon_governance_hash(snapshot)
   AND EXISTS(SELECT 1 FROM public.recon_definition_governance_requests evidence_request
    JOIN public.recon_definition_governance_audit evidence_audit ON evidence_audit.request_id=evidence_request.id
    WHERE evidence_request.id=recon_definition_approved_versions.request_id AND evidence_request.tenant_id=_tenant_id
     AND evidence_request.parent_definition_id=parent.id AND evidence_request.request_kind='promotion' AND evidence_request.status='approved'
     AND evidence_request.decided_by=recon_definition_approved_versions.approved_by
     AND evidence_request.snapshot=recon_definition_approved_versions.snapshot AND evidence_request.snapshot_sha256=source_hash
     AND evidence_audit.tenant_id=_tenant_id AND evidence_audit.parent_definition_id=parent.id
     AND evidence_audit.event_type='version_approved' AND evidence_audit.actor_id=recon_definition_approved_versions.approved_by
     AND evidence_audit.snapshot_sha256=source_hash)) THEN
   PERFORM private.mapped_recon_governance_conflict('parent_version_evidence_required');
  END IF;
 ELSIF EXISTS(SELECT 1 FROM public.recon_definition_approved_versions WHERE tenant_id=_tenant_id AND parent_definition_id=parent.id) THEN
  PERFORM private.mapped_recon_governance_conflict('initial_version_already_exists');
 END IF;
 INSERT INTO public.recon_definition_governance_requests(tenant_id,parent_definition_id,staging_definition_id,request_kind,requested_by,reason,source_version,source_sha256,snapshot,snapshot_sha256,mapped_governance_version,parent_config_fingerprint,staging_config_fingerprint,parent_mapping_snapshot,parent_mapping_fingerprint,staging_mapping_snapshot,staging_mapping_fingerprint)
 VALUES(_tenant_id,parent.id,d.id,'promotion',actor,btrim(_reason),source_version,source_hash,snap,snap_hash,1,private.mapped_recon_governance_hash(private.recon_definition_config_snapshot(parent)),snap_hash,parent_mapping,private.mapped_recon_governance_hash(parent_mapping),stage_mapping,private.mapped_recon_governance_hash(stage_mapping)) RETURNING id INTO v_id;
 INSERT INTO private.mapped_recon_governance_transitions(request_id,actor_id,purpose) VALUES(v_id,actor,'promotion_submit');
 PERFORM set_config('fvi.recon_governance_request_id',v_id::text,true);
 UPDATE public.recon_definitions SET governance_state='promotion_request_pending' WHERE id=d.id;
 INSERT INTO public.recon_definition_governance_audit(tenant_id,request_id,parent_definition_id,staging_definition_id,event_type,actor_id,reason,snapshot_sha256) VALUES(_tenant_id,v_id,parent.id,d.id,'promotion_submitted',actor,btrim(_reason),snap_hash);
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context) VALUES(actor,_tenant_id,'workspace','recon.definition.promotion_submitted','recon_definition_governance_request',v_id::text,jsonb_build_object('parent_definition_id',parent.id,'staging_definition_id',d.id,'snapshot_sha256',snap_hash,'source_version',source_version,'mapping_fingerprint',private.mapped_recon_governance_hash(stage_mapping)));
 RETURN v_id;
END $function$
;

CREATE OR REPLACE FUNCTION private.dpd_original_has_hold(_file uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 SELECT EXISTS(SELECT 1 FROM private.dpd_original_holds h WHERE h.file_id=_file AND h.operation='hold' AND NOT EXISTS(SELECT 1 FROM private.dpd_original_holds release WHERE release.hold_id=h.id AND release.operation='release')) $function$
;

CREATE OR REPLACE FUNCTION public.wfm_get_snapshot(_tenant_id uuid, _bu_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.wfm_actor(_tenant_id);p jsonb;t jsonb;perms jsonb;
BEGIN
 SELECT jsonb_build_object('ai_enabled',ai_enabled,'allow_copilot_global',allow_copilot_global,'allow_agent_global',allow_agent_global,'default_autonomy_ceiling',default_autonomy_ceiling) INTO p FROM public.platform_ai_settings WHERE id=true;
 SELECT jsonb_build_object('ai_enabled',ai_enabled,'allow_copilot',allow_copilot,'allow_agent',allow_agent,'default_autonomy',default_autonomy) INTO t FROM public.tenant_ai_settings WHERE tenant_id=_tenant_id;
 IF public.is_platform_admin(actor) IS TRUE THEN
  SELECT coalesce(jsonb_agg(id ORDER BY id),'[]') INTO perms FROM public.permissions;
 ELSE
 SELECT coalesce(jsonb_agg(id ORDER BY id),'[]') INTO perms FROM public.permissions WHERE public.user_has_permission(actor,_tenant_id,id,_bu_id) IS TRUE;
 END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'bu_id',_bu_id,'epoch',coalesce((SELECT epoch::text FROM private.wfm_epoch WHERE tenant_id=_tenant_id),'0'),
 'page_enabled',(SELECT jsonb_object_agg(c.key,coalesce(v.enabled,true)) FROM private.wfm_page_catalog c LEFT JOIN public.tenant_workspace_page_visibility v ON v.tenant_id=_tenant_id AND v.page_key=c.key),
 'feature_flags',(SELECT jsonb_object_agg(c.key,jsonb_build_object('enabled',coalesce(f.enabled,c.default_enabled),'config',CASE WHEN c.key='data_prep' THEN jsonb_strip_nulls(jsonb_build_object('ai_enabled',f.config->'ai_enabled','assisted_enabled',f.config->'assisted_enabled','agentic_enabled',f.config->'agentic_enabled')) ELSE '{}'::jsonb END)) FROM private.wfm_feature_catalog c LEFT JOIN public.tenant_feature_flags f ON f.tenant_id=_tenant_id AND f.feature_key=c.key),
 'workspace_features',(SELECT jsonb_object_agg(c.key,coalesce(f.enabled,false)) FROM private.wfm_ux_catalog c LEFT JOIN public.tenant_workspace_features f ON f.tenant_id=_tenant_id AND f.feature_key=c.key),
 'entitlements',(SELECT jsonb_object_agg(c.key,CASE WHEN e.feature_key IS NULL THEN true ELSE e.allowed IS TRUE END) FROM private.wfm_feature_catalog c LEFT JOIN public.tenant_feature_entitlements e ON e.feature_key=c.key AND e.tenant_id=_tenant_id),
 'permission_ids',perms,'platform_ai',p,'tenant_ai',t,'tenant_ai_enabled',coalesce((SELECT ai_enabled FROM public.tenants WHERE id=_tenant_id),false),
 'kill_switch_engaged',EXISTS(SELECT 1 FROM public.ai_governance_kill_switches WHERE tenant_id=_tenant_id AND engaged IS TRUE),'can_manage',private.wfm_can_manage(_tenant_id,false),'can_manage_ai',private.wfm_can_manage(_tenant_id,true));
END $function$
;

CREATE OR REPLACE FUNCTION public.dpdi_decide_setup_review(_tenant_id uuid, _setup_id uuid, _request_id uuid, _decision text, _reason text, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'review.setup.decide',_request_context_id);r private.dpdi_setup_review_requests%ROWTYPE;d private.dpdi_setup_review_decisions%ROWTYPE;j private.dpdi_jobs%ROWTYPE;e private.dpdi_job_events%ROWTYPE;cfg public.data_prep_configuration_revisions%ROWTYPE;scope_req private.dps_scope_requests%ROWTYPE;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,true);SELECT * INTO r FROM private.dpdi_setup_review_requests WHERE id=_request_id AND tenant_id=_tenant_id AND setup_id=_setup_id FOR UPDATE;
 IF NOT FOUND OR actor=r.requested_by OR NOT EXISTS(SELECT 1 FROM public.tenant_group_members WHERE group_id=r.approver_group_id AND user_id=actor) OR _decision NOT IN('approved','rejected') OR length(btrim(coalesce(_reason,''))) NOT BETWEEN 3 AND 1000 THEN RAISE EXCEPTION 'dpdi.exact_independent_human_reviewer_required' USING ERRCODE='42501';END IF;
 SELECT * INTO j FROM private.dpdi_jobs WHERE id=r.job_id;e:=private.dpdi_head(j.id);SELECT * INTO cfg FROM public.data_prep_configuration_revisions WHERE id=(j.snapshot->>'configuration_id')::uuid;
 IF e.phase<>'success' OR e.blocking_records<>0 OR cfg.payload_sha256 IS DISTINCT FROM j.snapshot->>'configuration_sha256' OR j.snapshot_sha256<>r.snapshot_sha256 OR (SELECT max(version) FROM private.dpd_versions WHERE setup_id=r.setup_id)<>r.draft_version OR private.data_prep_pipeline_scope_allows(actor,_tenant_id,cfg.pipeline_id,'view') IS DISTINCT FROM true OR EXISTS(SELECT 1 FROM private.dpdi_run_inputs i WHERE i.job_id=j.id AND (NOT private.dpd_original_viewable(i.original_file_id) OR private.dpw_source_allows(actor,_tenant_id,i.data_source_id,'view') IS DISTINCT FROM true)) THEN RAISE EXCEPTION 'dpdi.current_complete_review_evidence_required' USING ERRCODE='42501';END IF;
 SELECT * INTO d FROM private.dpdi_setup_review_decisions WHERE request_id=r.id;
 IF FOUND THEN IF d.decision<>_decision OR d.decided_by<>actor OR d.reason<>btrim(_reason) THEN RAISE EXCEPTION 'dpdi.review_decision_immutable' USING ERRCODE='PT409';END IF;RETURN private.dpdi_review_dto(r,actor);END IF;
 IF _decision='approved' THEN
  SELECT * INTO scope_req FROM private.dps_scope_requests WHERE configuration_id=cfg.id AND tenant_id=_tenant_id;
  IF scope_req.id IS NULL THEN RAISE EXCEPTION 'dpdi.actual_scope_review_required' USING ERRCODE='42501';END IF;
  IF NOT EXISTS(SELECT 1 FROM private.dps_scope_decisions WHERE request_id=scope_req.id AND decision='approved') THEN PERFORM private.dps_decide_scope_core(_tenant_id,scope_req.id,'approved',btrim(_reason));END IF;
  -- Existing public four-eyes approval performs the lifecycle transition and
  -- invokes existing snapshot/immutability/audit triggers. Never set its GUC here.
  PERFORM 1 FROM public.data_prep_pipelines p WHERE p.id=cfg.pipeline_id AND p.tenant_id=_tenant_id AND p.version=cfg.pipeline_version AND p.lifecycle_state='production' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'dpdi.current_production_pipeline_version_required' USING ERRCODE='PT409';END IF;
  IF EXISTS(SELECT 1 FROM public.data_prep_pipelines p WHERE p.id=cfg.pipeline_id AND p.tenant_id=_tenant_id AND p.status='draft') THEN
   PERFORM 1 FROM public.approve_data_prep_pipeline(_tenant_id,cfg.pipeline_id);
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.data_prep_pipelines p JOIN public.data_prep_approved_configurations ac ON ac.tenant_id=p.tenant_id AND ac.pipeline_id=p.id AND ac.pipeline_version=p.version
   WHERE p.id=cfg.pipeline_id AND p.tenant_id=_tenant_id AND p.status='approved' AND p.lifecycle_state='production' AND p.version=cfg.pipeline_version
   AND p.approved_by IS NOT NULL AND p.approved_by<>r.requested_by AND ac.configuration_id=cfg.id AND ac.approved_by=p.approved_by) THEN
   RAISE EXCEPTION 'dpdi.actual_independent_approved_snapshot_required' USING ERRCODE='42501';
  END IF;

 END IF;
 INSERT INTO private.dpdi_setup_review_decisions(request_id,decision,decided_by,reason,snapshot_sha256) VALUES(r.id,_decision,actor,btrim(_reason),r.snapshot_sha256);
 PERFORM private.dpd_event(_tenant_id,_setup_id,actor,'setup.review.decided',r.id,jsonb_build_object('decision',_decision,'snapshot_sha256',r.snapshot_sha256,'approval_origin','dpdi_setup_review_v1'));RETURN private.dpdi_review_dto(r,actor);
END $function$
;

CREATE OR REPLACE FUNCTION private.rs_current_definition_sha(_tenant uuid, _definition uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE d public.recon_definitions%ROWTYPE;
BEGIN
 PERFORM private.rs_actor(_tenant,_definition,'read');
 SELECT * INTO d FROM public.recon_definitions WHERE id=_definition AND tenant_id=_tenant;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.visible_contract_definition_required' USING ERRCODE='42501';END IF;
 RETURN encode(sha256(convert_to(private.recon_definition_config_snapshot(d)::text,'UTF8')),'hex');
END $function$
;

CREATE OR REPLACE FUNCTION public.fvi_report_audit_rows(_tenant uuid, _since timestamp with time zone, _at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE rows jsonb; n integer;
BEGIN
 IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated'
 OR current_setting('role',true) IS DISTINCT FROM 'authenticated'
 OR public.rlnext_actor_allowed() IS DISTINCT FROM true
 OR _tenant IS NULL OR _since IS NULL OR _at IS NULL OR _since>_at OR _at-_since>interval '360 days'
 OR NOT EXISTS(SELECT 1 FROM public.tenant_members m WHERE m.tenant_id=_tenant AND m.user_id=auth.uid() AND m.active)
 THEN RAISE EXCEPTION 'report.current_scope_unavailable' USING ERRCODE='42501';END IF;
 PERFORM public.wfm_assert_current_section(_tenant,'reports');
 IF public.is_platform_admin(auth.uid()) IS DISTINCT FROM true AND public.user_has_permission(auth.uid(),_tenant,'recon.definition.read',NULL) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'report.current_read_permission_required' USING ERRCODE='42501';END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id::bigint),'[]'::jsonb),count(*)::integer INTO rows,n
 FROM (SELECT a.id::text AS id,a.occurred_at,a.actor_email,a.actor_user_id,a.scope,a.action,a.resource_type,a.client_ip
 FROM public.audit_log a WHERE a.tenant_id=_tenant AND a.occurred_at>=_since AND a.occurred_at<=_at
 ORDER BY a.id LIMIT 100001) r;
 IF n>100000 THEN RAISE EXCEPTION 'report.interactive_row_limit' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('contract','fvi-complete-report-rows-v1','source','audit_log','tenant_id',_tenant,'actor_id',auth.uid(),'since',_since,'through',_at,'complete',true,'count',n,'rows',rows);
END $function$
;

CREATE OR REPLACE FUNCTION public.fvi_report_run_rows(_tenant uuid, _ids uuid[], _since timestamp with time zone, _at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE rows jsonb; n integer;
BEGIN
 IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated'
 OR current_setting('role',true) IS DISTINCT FROM 'authenticated'
 OR public.rlnext_actor_allowed() IS DISTINCT FROM true
 OR _tenant IS NULL OR _ids IS NULL OR array_position(_ids,NULL::uuid) IS NOT NULL OR cardinality(_ids)>100000
 OR _since IS NULL OR _at IS NULL OR _since>_at OR _at-_since>interval '360 days'
 OR NOT EXISTS(SELECT 1 FROM public.tenant_members m WHERE m.tenant_id=_tenant AND m.user_id=auth.uid() AND m.active)
 THEN RAISE EXCEPTION 'report.current_scope_unavailable' USING ERRCODE='42501';END IF;
 IF (_ids <@ public.get_recon_list_scope_ids(_tenant,'all',NULL)) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'report.definition_scope_unavailable' USING ERRCODE='42501';END IF;
 PERFORM public.wfm_assert_current_section(_tenant,'reports');
 IF public.is_platform_admin(auth.uid()) IS DISTINCT FROM true AND public.user_has_permission(auth.uid(),_tenant,'recon.definition.read',NULL) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'report.current_read_permission_required' USING ERRCODE='42501';END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id),'[]'::jsonb),count(*)::integer INTO rows,n
 FROM (SELECT r.id,r.started_at,r.completed_at,r.matched_count,r.exception_count,r.status,r.definition_id,r.total_rows,r.stats->'matched_records' AS matched_input_memberships
 FROM public.recon_runs r WHERE r.tenant_id=_tenant AND r.definition_id=ANY(_ids) AND r.started_at>=_since AND r.started_at<=_at
 ORDER BY r.id LIMIT 100001) r;
 IF n>100000 THEN RAISE EXCEPTION 'report.interactive_row_limit' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('contract','fvi-complete-report-rows-v1','source','recon_runs','tenant_id',_tenant,'actor_id',auth.uid(),'since',_since,'through',_at,'definition_ids',_ids,'complete',true,'count',n,'rows',rows);
END $function$
;

CREATE OR REPLACE FUNCTION public.fvi_report_exception_rows(_tenant uuid, _ids uuid[], _since timestamp with time zone, _at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE rows jsonb; n integer;
BEGIN
 IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated'
 OR current_setting('role',true) IS DISTINCT FROM 'authenticated'
 OR public.rlnext_actor_allowed() IS DISTINCT FROM true
 OR _tenant IS NULL OR _ids IS NULL OR array_position(_ids,NULL::uuid) IS NOT NULL OR cardinality(_ids)>100000
 OR _since IS NULL OR _at IS NULL OR _since>_at OR _at-_since>interval '360 days'
 OR NOT EXISTS(SELECT 1 FROM public.tenant_members m WHERE m.tenant_id=_tenant AND m.user_id=auth.uid() AND m.active)
 THEN RAISE EXCEPTION 'report.current_scope_unavailable' USING ERRCODE='42501';END IF;
 IF (_ids <@ public.get_recon_list_scope_ids(_tenant,'all',NULL)) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'report.definition_scope_unavailable' USING ERRCODE='42501';END IF;
 PERFORM public.wfm_assert_current_section(_tenant,'reports');
 IF public.is_platform_admin(auth.uid()) IS DISTINCT FROM true AND public.user_has_permission(auth.uid(),_tenant,'recon.definition.read',NULL) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'report.current_read_permission_required' USING ERRCODE='42501';END IF;

 IF public.is_platform_admin(auth.uid()) IS DISTINCT FROM true AND public.user_has_permission(auth.uid(),_tenant,'break.read',NULL) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'report.current_exception_permission_required' USING ERRCODE='42501';END IF;
 IF public.wfm_workspace_row_allowed(_tenant,'exceptions') IS DISTINCT FROM true AND public.wfm_workspace_row_allowed(_tenant,'breaks') IS DISTINCT FROM true
 AND public.wfm_workspace_row_allowed(_tenant,'exception-dashboard') IS DISTINCT FROM true AND public.wfm_workspace_row_allowed(_tenant,'ageing') IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'report.exception_family_unavailable' USING ERRCODE='42501';END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id),'[]'::jsonb),count(*)::integer INTO rows,n
 FROM (SELECT e.id,e.severity,e.priority,e.lifecycle_state,e.status,e.created_at,e.resolved_at,e.due_date,e.root_cause,jsonb_build_object('definition_id',r.definition_id) AS run
 FROM public.recon_exceptions e JOIN public.recon_runs r ON r.id=e.run_id
 WHERE e.tenant_id=_tenant AND r.definition_id=ANY(_ids) AND e.created_at>=_since AND e.created_at<=_at
 ORDER BY e.id LIMIT 100001) r;
 IF n>100000 THEN RAISE EXCEPTION 'report.interactive_row_limit' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('contract','fvi-complete-report-rows-v1','source','recon_exceptions','tenant_id',_tenant,'actor_id',auth.uid(),'since',_since,'through',_at,'definition_ids',_ids,'complete',true,'count',n,'rows',rows);
END $function$
;

CREATE OR REPLACE FUNCTION public.dpw_get_dataset(_tenant_id uuid, _pipeline_id uuid, _dataset_id uuid, _logical_side text DEFAULT NULL::text, _page integer DEFAULT 1, _page_size integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_authorize(_tenant_id,_pipeline_id,'view'); d public.data_prep_prepared_datasets%ROWTYPE;
 u public.workspace_data_source_uploads%ROWTYPE; indexes integer[]; off integer:=private.dpw_page(_page,_page_size); payload_state jsonb;
BEGIN
 SELECT * INTO d FROM public.data_prep_prepared_datasets WHERE id=_dataset_id AND tenant_id=_tenant_id AND pipeline_id=_pipeline_id;
 IF NOT FOUND OR private.dpw_source_allows(actor,_tenant_id,d.data_source_id,'view') IS DISTINCT FROM true
 OR EXISTS(SELECT 1 FROM public.data_prep_run_inputs i JOIN public.data_prep_delivery_files f ON f.id=i.file_id
 WHERE i.run_id=d.run_id AND private.dpw_source_allows(actor,_tenant_id,f.data_source_id,'view') IS DISTINCT FROM true)
 THEN RAISE EXCEPTION 'dpw.dataset_read_denied'; END IF;
 PERFORM private.dps_assert_preparation_source_scope(_tenant_id,d.run_id,actor);
 payload_state:=CASE WHEN EXISTS(SELECT 1 FROM private.dpdi_public_output_links WHERE dataset_id=d.id) THEN private.dpdi_public_payload_state(_tenant_id,d.run_id,actor) ELSE private.dpw_run_payload_state(d.run_id) END;
 IF (payload_state->>'available')::boolean IS DISTINCT FROM true THEN
  RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'dataset',to_jsonb(d)||jsonb_build_object('hash_kind','structured_jsonb_sha256'),
  'payload',payload_state,'rows',NULL,'total',NULL,'page',_page,'page_size',_page_size);
 END IF;
 SELECT * INTO u FROM public.workspace_data_source_uploads WHERE id=d.upload_id AND tenant_id=_tenant_id AND data_source_id=d.data_source_id;
 IF u.id IS NULL OR u.row_count<>d.rows OR private.dpw_hash(u.rows) IS DISTINCT FROM d.content_sha256 THEN RAISE EXCEPTION 'dpw.dataset_upload_integrity_mismatch'; END IF;
 IF _logical_side IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.data_prep_delivery_runs r,jsonb_array_elements(r.snapshot->'feeds') f
 WHERE r.id=d.run_id AND f.value->>'business_side'=_logical_side) THEN RAISE EXCEPTION 'dpw.dataset_logical_side_incompatible'; END IF;
 indexes:=private.dpw_dataset_indexes(d.id,_logical_side);
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'dataset',to_jsonb(d)||jsonb_build_object('hash_kind','structured_jsonb_sha256'),
 'logical_side',_logical_side,'rows',coalesce((SELECT jsonb_agg(u.rows->x.idx ORDER BY x.ord) FROM unnest(indexes) WITH ORDINALITY x(idx,ord)
 WHERE ord>off AND ord<=off+_page_size),'[]'::jsonb),'total',cardinality(indexes),'page',_page,'page_size',_page_size);
END $function$
;

CREATE OR REPLACE FUNCTION public.dpw_publish_dataset(_tenant_id uuid, _pipeline_id uuid, _batch_id uuid, _run_id uuid, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_authorize(_tenant_id,_pipeline_id,'run'); b public.data_prep_delivery_batches%ROWTYPE;
 r public.data_prep_delivery_runs%ROWTYPE; d public.data_prep_prepared_datasets%ROWTYPE; up uuid; src uuid; f jsonb;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,false);
 b:=private.dpw_lock_batch(_tenant_id,_pipeline_id,_batch_id,actor,false);
 SELECT * INTO r FROM public.data_prep_delivery_runs WHERE id=_run_id AND batch_id=b.id AND tenant_id=_tenant_id FOR UPDATE;
 IF NOT FOUND OR r.started_by<>actor OR _request_key IS NULL THEN RAISE EXCEPTION 'dpw.publish_binding_denied'; END IF;
 PERFORM private.dps_assert_preparation_source_scope(_tenant_id,r.id,actor);
 SELECT * INTO d FROM public.data_prep_prepared_datasets WHERE run_id=r.id;
 IF FOUND THEN
  IF d.request_key<>_request_key THEN RAISE EXCEPTION 'dpw.request_conflict'; END IF;
  RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'dataset',to_jsonb(d),'is_new',false);
 END IF;
 IF b.mode<>'prepare' OR b.state<>'prepared' OR r.state NOT IN('success','warn') OR r.finished_at IS NULL
 OR private.dpw_run_payload_available(r.id) IS DISTINCT FROM true
 OR (r.result->>'publication_eligible')::boolean IS DISTINCT FROM true OR r.pipeline_version<>b.pipeline_version
 OR private.dpw_hash(r.result) IS DISTINCT FROM r.result_sha256 THEN RAISE EXCEPTION 'dpw.current_successful_dq_required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.data_prep_release_requests a JOIN public.data_prep_release_decisions decision ON decision.request_id=a.id
 WHERE a.run_id=r.id AND a.result_sha256=r.result_sha256 AND a.pipeline_version=r.pipeline_version AND decision.decision='approved')
 THEN RAISE EXCEPTION 'dpw.human_release_approval_required'; END IF;
 FOR f IN SELECT value FROM jsonb_array_elements(r.snapshot->'feeds') LOOP
  IF private.dpw_source_allows(actor,_tenant_id,(f->>'data_source_id')::uuid,'view') IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpw.source_revoked'; END IF;
 END LOOP;
 src:=(r.snapshot->>'output_data_source_id')::uuid;
 IF private.dpw_source_allows(actor,_tenant_id,src,'ingest') IS DISTINCT FROM true OR private.dpw_source_allows(actor,_tenant_id,src,'edit') IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'dpw.output_source_denied'; END IF;
 INSERT INTO public.workspace_data_source_uploads(data_source_id,tenant_id,filename,mime_type,size_bytes,row_count,columns,sample_rows,content_sha256,uploaded_by,rows)
 VALUES(src,_tenant_id,'prepared-'||r.id::text||'.json','application/json',octet_length((r.result->'acceptedRows')::text),
 jsonb_array_length(r.result->'acceptedRows'),coalesce(r.result->'profile'->'columns','[]'::jsonb),'[]'::jsonb,r.result->>'structured_data_sha256',actor,r.result->'acceptedRows') RETURNING id INTO up;
 INSERT INTO public.data_prep_prepared_datasets(tenant_id,pipeline_id,pipeline_version,batch_id,run_id,business_date,data_source_id,upload_id,rows,content_sha256,request_key,published_by)
 VALUES(_tenant_id,_pipeline_id,r.pipeline_version,b.id,r.id,b.business_date,src,up,jsonb_array_length(r.result->'acceptedRows'),r.result->>'structured_data_sha256',_request_key,actor) RETURNING * INTO d;
 UPDATE public.data_prep_delivery_batches SET state='published' WHERE id=b.id;
 PERFORM private.dpw_audit(actor,_tenant_id,'dpw.dataset.publish',d.id,jsonb_build_object('upload_id',up,'run_id',r.id,'version',r.pipeline_version));
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'dataset',to_jsonb(d),'is_new',true);
END $function$
;

CREATE OR REPLACE FUNCTION private.dpdi_public_payload_state(_tenant uuid, _run uuid, _actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE d public.data_prep_prepared_datasets%ROWTYPE;expiry timestamptz;available boolean;
BEGIN
 SELECT p.* INTO d FROM public.data_prep_prepared_datasets p JOIN private.dpdi_public_output_links l ON l.dataset_id=p.id WHERE p.tenant_id=_tenant AND p.run_id=_run;
 IF d.id IS NULL THEN RAISE EXCEPTION 'dpdi.actual_public_output_link_required';END IF;
 SELECT min(o.expires_at) INTO expiry FROM private.dpdi_run_inputs i JOIN private.dpd_original_intents o ON o.id=i.original_file_id WHERE i.run_id=_run;
 available:=private.dpdi_public_dataset_current(_tenant,d.id,_actor) IS TRUE;
 RETURN jsonb_build_object('available',available,'state',CASE WHEN available THEN 'available' WHEN expiry<=clock_timestamp() THEN 'expired' ELSE 'unavailable' END,'expires_at',expiry,'representation','registered_dpdi_output_v1','original_input_upload_id',NULL);
END $function$
;

CREATE OR REPLACE FUNCTION public.dpdi_get_job_records(_tenant_id uuid, _setup_id uuid, _job_id uuid, _kind text, _page integer, _page_size integer, _search text, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'preview.job.result',_request_context_id);
 j private.dpdi_jobs%ROWTYPE:=private.dpdi_authorize(_tenant_id,_setup_id,_job_id,actor,false);
 e private.dpdi_job_events%ROWTYPE:=private.dpdi_head(j.id);off bigint;amount bigint;records jsonb;proofs jsonb;cols jsonb;needle text;
BEGIN
 IF _kind NOT IN('rows','errors') OR _kind IS NULL OR _page IS NULL OR _page<1 OR _page_size IS NULL OR _page_size NOT BETWEEN 1 AND 100 OR _search IS NULL OR char_length(_search)>200 THEN RAISE EXCEPTION 'dpdi.bounded_record_page_required' USING ERRCODE='22023';END IF;
 off:=(_page::bigint-1)*_page_size;
 IF EXISTS(SELECT 1 FROM private.dpdi_run_inputs i WHERE i.job_id=j.id AND NOT private.dpd_original_viewable(i.original_file_id)) THEN
  RETURN private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'state','unavailable','kind',_kind,'records',NULL,'columns',NULL,'total',NULL,'page',_page,'page_size',_page_size,'search',_search,'page_proofs',NULL);
 END IF;
 IF e.phase NOT IN('success','blocked') THEN
  RETURN private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'state','pending','kind',_kind,'records',NULL,'columns',NULL,'total',NULL,'page',_page,'page_size',_page_size,'search',_search,'page_proofs',NULL);
 END IF;
 IF e.phase='blocked' AND _kind='rows' THEN
  RETURN private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'state','blocked','kind',_kind,'records',NULL,'columns',NULL,'total','0','page',_page,'page_size',_page_size,'search',_search,'page_proofs',NULL);
 END IF;
 SELECT CASE WHEN _kind='rows' THEN coalesce(jsonb_agg(v.value->>'name' ORDER BY v.ordinality),'[]')||jsonb_build_array('extras_json') ELSE ' ["input_id","original_file_id","record_index","source_row_ordinal","reasons","payload","extras_json"]'::jsonb END INTO cols
 FROM jsonb_array_elements(j.snapshot->'confirmed_mapping'->'output_schema') WITH ORDINALITY v(value,ordinality);
 needle:=lower(_search);
 IF needle='' THEN
  amount:=CASE WHEN _kind='rows' THEN e.source_records ELSE e.blocking_records END;
  -- Prefix sums cover at most the small page-metadata set, not all source records.
  WITH metadata AS(
   SELECT p.*,CASE WHEN _kind='rows' THEN p.row_count ELSE p.blocking_count END n,
    coalesce(sum(CASE WHEN _kind='rows' THEN p.row_count ELSE p.blocking_count END) OVER(ORDER BY p.sequence ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0)::bigint first_index
   FROM private.dpdi_job_pages p WHERE p.job_id=j.id
  ), relevant AS(SELECT * FROM metadata WHERE first_index<off+_page_size AND first_index+n>off),
  decoded AS(SELECT p.*,x.ordinality,x.value::jsonb record FROM relevant p CROSS JOIN LATERAL regexp_split_to_table(p.wire,E'\n') WITH ORDINALITY x(value,ordinality) WHERE x.value<>''),
  filtered AS(SELECT *,row_number() OVER(PARTITION BY sequence ORDER BY ordinality)-1 item_index FROM decoded WHERE _kind='rows' OR record->'blocking'='true'::jsonb),
  selected AS(SELECT * FROM filtered WHERE first_index+item_index>=off AND first_index+item_index<off+_page_size)
  SELECT coalesce(jsonb_agg(record ORDER BY sequence,ordinality),'[]'),coalesce((SELECT jsonb_agg(jsonb_build_object('sequence',sequence,'row_count',row_count,'sha256',sha256) ORDER BY sequence) FROM relevant),'[]') INTO records,proofs FROM selected;
 ELSE
  -- Search is over the complete authorised collection. No client loaded-row subset.
  WITH decoded AS(SELECT p.sequence,p.row_count,p.sha256,x.ordinality,x.value::jsonb record FROM private.dpdi_job_pages p CROSS JOIN LATERAL regexp_split_to_table(p.wire,E'\n') WITH ORDINALITY x(value,ordinality) WHERE p.job_id=j.id AND x.value<>''),
  matches AS(SELECT * FROM decoded WHERE (_kind='rows' OR record->'blocking'='true'::jsonb) AND strpos(lower(CASE WHEN _kind='rows' THEN ((record->'payload')||jsonb_build_object('extras_json',record->'extras_json'))::text ELSE record::text END),needle)>0),
  selected AS(SELECT * FROM matches ORDER BY sequence,ordinality LIMIT _page_size OFFSET off)
  SELECT (SELECT count(*) FROM matches),coalesce(jsonb_agg(record ORDER BY sequence,ordinality),'[]'),coalesce((SELECT jsonb_agg(jsonb_build_object('sequence',p.sequence,'row_count',p.row_count,'sha256',p.sha256) ORDER BY p.sequence) FROM(SELECT DISTINCT sequence,row_count,sha256 FROM selected)p),'[]') INTO amount,records,proofs FROM selected;
 END IF;
 IF jsonb_array_length(records)>_page_size THEN RAISE EXCEPTION 'dpdi.record_page_overflow';END IF;
 RETURN private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'state','available','kind',_kind,'records',records,'columns',cols,'total',amount::text,'page',_page,'page_size',_page_size,'search',_search,'page_proofs',proofs);
END $function$
;

CREATE OR REPLACE FUNCTION private.tgm_validate_bulk(_intent jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE c jsonb;t jsonb;
BEGIN
 IF jsonb_typeof(_intent) IS DISTINCT FROM 'object' OR _intent->>'request_key' IS NULL OR _intent->>'reason' IS NULL OR length(trim(_intent->>'reason')) NOT BETWEEN 3 AND 500 OR jsonb_typeof(_intent->'targets') IS DISTINCT FROM 'array' OR jsonb_array_length(_intent->'targets') NOT BETWEEN 1 AND 50 OR jsonb_typeof(_intent->'changes') IS DISTINCT FROM 'array' OR jsonb_array_length(_intent->'changes') NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'tgm.invalid_batch' USING ERRCODE='22023';END IF;
 PERFORM (_intent->>'request_key')::uuid;
 IF (SELECT count(DISTINCT value->>'tenant_id') FROM jsonb_array_elements(_intent->'targets'))<>jsonb_array_length(_intent->'targets') OR (SELECT count(DISTINCT(value->>'kind',value->>'key')) FROM jsonb_array_elements(_intent->'changes'))<>jsonb_array_length(_intent->'changes') THEN RAISE EXCEPTION 'tgm.duplicate_target_or_key' USING ERRCODE='22023';END IF;
 FOR t IN SELECT value FROM jsonb_array_elements(_intent->'targets') LOOP IF t->>'tenant_id' IS NULL OR t->>'expected_epoch' IS NULL OR t->>'expected_epoch'!~'^(0|[1-9][0-9]*)$' THEN RAISE EXCEPTION 'tgm.invalid_target' USING ERRCODE='22023';END IF;PERFORM(t->>'tenant_id')::uuid;END LOOP;
 FOR c IN SELECT value FROM jsonb_array_elements(_intent->'changes') LOOP
 IF jsonb_typeof(c->'enabled') IS DISTINCT FROM 'boolean' OR NOT((c->>'kind'='page' AND EXISTS(SELECT 1 FROM private.wfm_page_catalog WHERE key=c->>'key')) OR(c->>'kind'='feature' AND EXISTS(SELECT 1 FROM private.wfm_feature_catalog WHERE key=c->>'key')) OR(c->>'kind'='workspace-feature' AND EXISTS(SELECT 1 FROM private.wfm_ux_catalog WHERE key=c->>'key')) OR(c->>'kind'='mode' AND c->>'key' IN('ai_enabled','assisted_enabled','agentic_enabled'))) THEN RAISE EXCEPTION 'tgm.unknown_control' USING ERRCODE='22023';END IF;
 END LOOP;
END $function$
;

CREATE OR REPLACE FUNCTION private.tgm_bulk_actor(_intent jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid;tenant uuid;
BEGIN
 PERFORM private.tgm_validate_bulk(_intent);
 IF jsonb_array_length(_intent->'targets')>1 THEN RETURN private.wfm_platform_actor();END IF;
 tenant:=(_intent->'targets'->0->>'tenant_id')::uuid;actor:=private.wfm_actor(tenant);
 IF private.wfm_can_manage(tenant,false) IS DISTINCT FROM true THEN RAISE EXCEPTION 'tgm.current_tenant_manager_required' USING ERRCODE='42501';END IF;
 RETURN actor;
END $function$
;

CREATE OR REPLACE FUNCTION private.dps_owned_draft_input(_tenant uuid, _source uuid, _configuration uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 SELECT EXISTS(SELECT 1 FROM public.data_prep_configuration_revisions cfg
 JOIN private.dpd_raw_source_links raw ON raw.data_source_id=_source AND raw.tenant_id=_tenant
 JOIN private.dpd_setups setup ON setup.id=raw.setup_id AND setup.tenant_id=raw.tenant_id AND setup.created_by=raw.created_by AND setup.created_by=cfg.created_by
 JOIN private.dpd_original_intents original ON original.id=raw.file_id AND original.setup_id=setup.id AND original.tenant_id=_tenant AND original.created_by=setup.created_by
 JOIN private.dpd_original_receipts receipt ON receipt.file_id=original.id AND receipt.setup_id=original.setup_id AND receipt.tenant_id=original.tenant_id AND receipt.created_by=original.created_by
 AND receipt.verified_original_sha256=original.content_sha256 AND receipt.verified_size_bytes=original.size_bytes
 JOIN public.workspace_data_sources source_row ON source_row.id=raw.data_source_id AND source_row.tenant_id=_tenant AND source_row.created_by=setup.created_by AND source_row.status<>'archived'
 JOIN public.data_resource_registry registry ON registry.data_source_id=source_row.id AND registry.tenant_id=_tenant AND registry.resource_type='data_source' AND registry.created_by=setup.created_by
 WHERE cfg.id=_configuration AND cfg.tenant_id=_tenant
 AND EXISTS(SELECT 1 FROM jsonb_array_elements(cfg.payload->'confirmed_mapping'->'feeds') feed,jsonb_array_elements(feed->'original_refs') ref
  WHERE feed->>'data_source_id'=source_row.id::text AND ref->>'file_id'=original.id::text))
$function$
;

CREATE OR REPLACE FUNCTION private.dps_admin(_tenant uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_actor(_tenant);
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant,actor,true);
 IF NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant AND user_id=actor AND active IS TRUE AND role='tenant_admin')
 THEN RAISE EXCEPTION 'dps.active_tenant_admin_required' USING ERRCODE='42501';END IF;
 RETURN actor;
END $function$
;

CREATE OR REPLACE FUNCTION private.dps_ids(_ids uuid[], _max integer, _nonempty boolean)
 RETURNS uuid[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE result uuid[];
BEGIN
 IF _ids IS NULL OR array_position(_ids,NULL) IS NOT NULL OR cardinality(_ids)>_max OR (_nonempty AND cardinality(_ids)=0)
 THEN RAISE EXCEPTION 'dps.invalid_selection' USING ERRCODE='22023';END IF;
 SELECT coalesce(array_agg(DISTINCT x ORDER BY x),'{}'::uuid[]) INTO result FROM unnest(_ids) x;
 IF cardinality(result)<>cardinality(_ids) THEN RAISE EXCEPTION 'dps.duplicate_selection' USING ERRCODE='22023';END IF;
 RETURN result;
END $function$
;

CREATE OR REPLACE FUNCTION private.dps_group_bus(_tenant uuid, _group uuid, _owners uuid[])
 RETURNS uuid[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 SELECT coalesce(array_agg(DISTINCT owner.id ORDER BY owner.id),'{}'::uuid[])
 FROM public.tenant_groups g JOIN public.bu_group_assignments a ON a.group_id=g.id AND a.tenant_id=g.tenant_id
 JOIN public.business_units assigned ON assigned.id=a.bu_id AND assigned.tenant_id=a.tenant_id AND NOT assigned.is_archived
 JOIN public.business_units owner ON owner.tenant_id=g.tenant_id AND owner.id=ANY(_owners) AND NOT owner.is_archived
 AND (owner.id=assigned.id OR (a.inherit_descendants AND owner.path <@ assigned.path))
 WHERE g.id=_group AND g.tenant_id=_tenant
$function$
;

CREATE OR REPLACE FUNCTION private.dps_selections(_tenant uuid, _owners uuid[], _groups uuid[])
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE g uuid;
BEGIN
 IF EXISTS(SELECT 1 FROM unnest(_owners) x LEFT JOIN public.business_units b ON b.id=x AND b.tenant_id=_tenant AND NOT b.is_archived WHERE b.id IS NULL)
 THEN RAISE EXCEPTION 'dps.owner_scope_denied' USING ERRCODE='42501';END IF;
 FOREACH g IN ARRAY _groups LOOP
  IF cardinality(private.dps_group_bus(_tenant,g,_owners))=0 THEN RAISE EXCEPTION 'dps.group_not_assigned_to_selected_bu' USING ERRCODE='42501';END IF;
 END LOOP;
END $function$
;

CREATE OR REPLACE FUNCTION private.dps_list_groups_core(_tenant_id uuid, _owning_business_unit_ids uuid[], _search text DEFAULT ''::text, _page integer DEFAULT 1, _page_size integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dps_admin(_tenant_id);owners uuid[]:=private.dps_ids(_owning_business_unit_ids,100,true);off integer:=private.dpw_page(_page,_page_size);items jsonb;n integer;
BEGIN
 PERFORM private.dps_selections(_tenant_id,owners,'{}');IF _search IS NULL OR length(_search)>200 THEN RAISE EXCEPTION 'dps.invalid_search';END IF;
 WITH eligible AS MATERIALIZED(SELECT g.id,g.name,g.bu_id,private.dps_group_bus(_tenant_id,g.id,owners) AS bu_ids FROM public.tenant_groups g WHERE g.tenant_id=_tenant_id AND position(lower(_search) IN lower(g.name))>0),
 filtered AS MATERIALIZED(SELECT * FROM eligible WHERE cardinality(bu_ids)>0),page AS(SELECT * FROM filtered ORDER BY name,id LIMIT _page_size OFFSET off)
 SELECT (SELECT count(*) FROM filtered),(SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY name,id),'[]') FROM page) INTO n,items;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'owning_business_unit_ids',owners,'items',items,'total',n,'page',_page,'page_size',_page_size,'permission_grants_created',false);
END $function$
;

CREATE OR REPLACE FUNCTION private.dps_save_configuration_core(_tenant_id uuid, _pipeline_id uuid, _payload jsonb, _owning_business_unit_ids uuid[], _sharing_user_group_ids uuid[], _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dps_admin(_tenant_id);owners uuid[]:=private.dps_ids(_owning_business_unit_ids,100,true);groups uuid[]:=private.dps_ids(_sharing_user_group_ids,100,false);base_owners uuid[];saved jsonb;cfg public.data_prep_configuration_revisions%ROWTYPE;manifest jsonb;identity jsonb;req private.dps_scope_requests%ROWTYPE;
BEGIN
 IF _request_key IS NULL OR _payload IS NULL OR _payload ?| ARRAY['sharing_user_group_ids','requested_owning_business_unit_ids','shared_scope_contract'] THEN RAISE EXCEPTION 'dps.reserved_scope_metadata' USING ERRCODE='22023';END IF;
 PERFORM private.dps_selections(_tenant_id,owners,groups);
 base_owners:=owners;
 IF _pipeline_id IS NOT NULL THEN
  PERFORM private.dpw_authorize(_tenant_id,_pipeline_id,'edit');
  SELECT array_agg(o.bu_id ORDER BY o.bu_id) INTO base_owners FROM public.data_resource_registry r JOIN public.data_resource_registry_owner_bu o ON o.registry_id=r.id AND o.tenant_id=r.tenant_id WHERE r.tenant_id=_tenant_id AND r.data_prep_pipeline_id=_pipeline_id;
  IF base_owners IS NULL THEN RAISE EXCEPTION 'dps.existing_registered_scope_required' USING ERRCODE='42501';END IF;
 END IF;
 -- The baseline saves a draft and immutable revision. Existing ownership is retained until scope approval.
 saved:=public.dpw_save_configuration(_tenant_id,_pipeline_id,_payload||jsonb_build_object('sharing_user_group_ids',groups,'requested_owning_business_unit_ids',owners,'shared_scope_contract','dps-v1'),base_owners,_request_key);
 SELECT * INTO cfg FROM public.data_prep_configuration_revisions WHERE id=(saved->>'configuration_id')::uuid AND tenant_id=_tenant_id;
 manifest:=private.dps_manifest(_tenant_id,cfg.pipeline_id,cfg.id,owners,groups);
 identity:=jsonb_build_object('configuration_id',cfg.id,'configuration_sha256',cfg.payload_sha256,'owners',owners,'groups',groups,'source_manifest',manifest);
 PERFORM pg_advisory_xact_lock(hashtextextended(_tenant_id::text||actor::text||_request_key::text,0));
 SELECT * INTO req FROM private.dps_scope_requests WHERE tenant_id=_tenant_id AND created_by=actor AND request_key=_request_key;
 IF FOUND THEN
  IF req.configuration_id<>cfg.id OR req.owning_business_unit_ids<>owners OR req.sharing_user_group_ids<>groups THEN RAISE EXCEPTION 'dps.request_conflict';END IF;
 ELSE
  INSERT INTO private.dps_scope_requests(tenant_id,pipeline_id,configuration_id,configuration_sha256,owning_business_unit_ids,sharing_user_group_ids,source_manifest,request_sha256,request_key,created_by)
  VALUES(_tenant_id,cfg.pipeline_id,cfg.id,cfg.payload_sha256,owners,groups,manifest,private.dpw_hash(identity),_request_key,actor) RETURNING * INTO req;
  PERFORM private.dpw_audit(actor,_tenant_id,'dps.scope.request',cfg.pipeline_id,jsonb_build_object('request_id',req.id,'request_sha256',req.request_sha256,'configuration_id',cfg.id));
 END IF;
 RETURN saved||jsonb_build_object('scope_request_id',req.id,'scope_request_sha256',req.request_sha256,'owning_business_unit_ids',req.owning_business_unit_ids,'sharing_user_group_ids',req.sharing_user_group_ids,'scope_status',coalesce((SELECT decision FROM private.dps_scope_decisions WHERE request_id=req.id),'pending'),'permission_grants_created',false);
END $function$
;

CREATE OR REPLACE FUNCTION private.dps_lookup_request_core(_tenant_id uuid, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dps_admin(_tenant_id);req private.dps_scope_requests%ROWTYPE;pipeline jsonb;
BEGIN
 SELECT * INTO req FROM private.dps_scope_requests WHERE tenant_id=_tenant_id AND created_by=actor AND request_key=_request_key;
 IF req.id IS NULL THEN RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'request_key',_request_key,'found',false);END IF;
 PERFORM private.dpw_authorize(_tenant_id,req.pipeline_id,'edit');
 SELECT to_jsonb(p) INTO pipeline FROM public.data_prep_pipelines p WHERE p.id=req.pipeline_id AND p.tenant_id=_tenant_id;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'request_key',_request_key,'found',true,'saved',jsonb_build_object(
 'actor_id',actor,'tenant_id',_tenant_id,'pipeline',pipeline,'configuration_id',req.configuration_id,'is_new',false,
 'scope_request_id',req.id,'scope_request_sha256',req.request_sha256,'owning_business_unit_ids',req.owning_business_unit_ids,'sharing_user_group_ids',req.sharing_user_group_ids,
 'scope_status',coalesce((SELECT decision FROM private.dps_scope_decisions WHERE request_id=req.id),'pending'),'permission_grants_created',false));
END $function$
;

CREATE OR REPLACE FUNCTION private.dps_decide_scope_core(_tenant_id uuid, _request_id uuid, _decision text, _reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dps_admin(_tenant_id);req private.dps_scope_requests%ROWTYPE;dec private.dps_scope_decisions%ROWTYPE;manifest jsonb;target jsonb;registry uuid;g uuid;b uuid;gid uuid;prior uuid;events jsonb:='[]';oldgrant record;
BEGIN
 IF _decision IS NULL OR _decision NOT IN('approved','rejected') OR length(btrim(coalesce(_reason,''))) NOT BETWEEN 3 AND 1000 THEN RAISE EXCEPTION 'dps.invalid_decision' USING ERRCODE='22023';END IF;
 SELECT * INTO req FROM private.dps_scope_requests WHERE id=_request_id AND tenant_id=_tenant_id FOR UPDATE;
 IF req.id IS NULL OR req.created_by=actor THEN RAISE EXCEPTION 'dps.independent_admin_required' USING ERRCODE='42501';END IF;
 SELECT * INTO dec FROM private.dps_scope_decisions WHERE request_id=req.id;
 IF FOUND THEN IF dec.decision<>_decision OR dec.decided_by<>actor OR dec.reason<>btrim(_reason) THEN RAISE EXCEPTION 'dps.decision_conflict';END IF;RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'request_id',req.id,'decision',to_jsonb(dec),'is_new',false);END IF;
 IF _decision='approved' THEN
  manifest:=private.dps_manifest(_tenant_id,req.pipeline_id,req.configuration_id,req.owning_business_unit_ids,req.sharing_user_group_ids);
  IF manifest IS DISTINCT FROM req.source_manifest OR NOT EXISTS(SELECT 1 FROM public.data_prep_configuration_revisions WHERE id=req.configuration_id AND payload_sha256=req.configuration_sha256) THEN RAISE EXCEPTION 'dps.scope_binding_changed' USING ERRCODE='42501';END IF;
  FOR target IN SELECT value FROM jsonb_array_elements(manifest) WHERE value->>'kind' IN('pipeline','output') OR (value->>'kind'='input' AND (value->>'owned_draft_input')::boolean IS TRUE) LOOP
   registry:=(target->>'registry_id')::uuid;
   -- Revoke only grants created by an earlier independently approved SharedScope decision.
   FOR oldgrant IN SELECT v.* FROM public.data_resource_registry_grants v WHERE v.registry_id=registry AND v.tenant_id=_tenant_id AND v.action='view' AND v.principal_type='group'
    AND (NOT v.principal_group_id=ANY(req.sharing_user_group_ids) OR NOT v.bu_id=ANY(req.owning_business_unit_ids))
    AND EXISTS(SELECT 1 FROM private.dps_scope_decisions d, jsonb_array_elements(d.grant_events) e WHERE d.decision='approved' AND e->>'grant_id'=v.id::text AND e->>'created'='true')
   LOOP PERFORM public.revoke_typed_data_resource_action(oldgrant.id,btrim(_reason));events:=events||jsonb_build_array(jsonb_build_object('grant_id',oldgrant.id,'revoked',true));END LOOP;
   IF target->>'kind'='output' AND (SELECT array_agg((x->>'bu_id')::uuid ORDER BY (x->>'bu_id')::uuid) FROM jsonb_array_elements(target->'owners') x) IS DISTINCT FROM req.owning_business_unit_ids
   THEN RAISE EXCEPTION 'dps.output_owners_must_already_match_no_shared_source_remap' USING ERRCODE='42501';END IF;
   IF target->>'kind'='pipeline' THEN PERFORM public.set_typed_data_resource_owners(registry,req.owning_business_unit_ids,btrim(_reason));END IF;
   FOREACH g IN ARRAY req.sharing_user_group_ids LOOP
    FOREACH b IN ARRAY private.dps_group_bus(_tenant_id,g,CASE WHEN target->>'kind'='input' THEN ARRAY(SELECT (x->>'bu_id')::uuid FROM jsonb_array_elements(target->'owners') x) ELSE req.owning_business_unit_ids END) LOOP
     SELECT id INTO prior FROM public.data_resource_registry_grants WHERE registry_id=registry AND tenant_id=_tenant_id AND principal_type='group' AND principal_group_id=g AND bu_id=b AND action='view';
     gid:=public.grant_typed_data_resource_action(registry,b,'group',g,'view',btrim(_reason));
     events:=events||jsonb_build_array(jsonb_build_object('registry_id',registry,'bu_id',b,'group_id',g,'grant_id',gid,'created',prior IS NULL));
    END LOOP;
   END LOOP;
  END LOOP;
 END IF;
 INSERT INTO private.dps_scope_decisions(request_id,decision,decided_by,reason,grant_events) VALUES(req.id,_decision,actor,btrim(_reason),events) RETURNING * INTO dec;
 PERFORM private.dpw_audit(actor,_tenant_id,'dps.scope.decision',req.pipeline_id,jsonb_build_object('request_id',req.id,'decision_id',dec.id,'decision',_decision,'request_sha256',req.request_sha256,'grant_events',events));
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'request_id',req.id,'decision',to_jsonb(dec),'is_new',true);
END $function$
;

CREATE OR REPLACE FUNCTION public.tgm_preview_controls(_intent jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.tgm_bulk_actor(_intent);snapshots jsonb:='[]';t jsonb;tid uuid;s jsonb;c jsonb;
BEGIN
 PERFORM private.tgm_validate_bulk(_intent);
 FOR t IN SELECT value FROM jsonb_array_elements(_intent->'targets') ORDER BY value->>'tenant_id' LOOP
  tid:=(t->>'tenant_id')::uuid;
  FOR c IN SELECT value FROM jsonb_array_elements(_intent->'changes') LOOP IF private.wfm_can_manage(tid,c->>'kind'='mode' OR(c->>'kind'='feature' AND c->>'key' IN('copilot','agent','aidp','auto_match_ai','auto_remediation','byo_llm','cost_metering'))) IS DISTINCT FROM true THEN RAISE EXCEPTION 'tgm.current_authority_denied' USING ERRCODE='42501';END IF;END LOOP;
  s:=public.wfm_get_snapshot(tid,NULL);IF s->>'epoch'<>t->>'expected_epoch' THEN RAISE EXCEPTION 'tgm.stale_preview' USING ERRCODE='PT409';END IF;snapshots:=snapshots||jsonb_build_array(s);
 END LOOP;
 RETURN jsonb_build_object('actor_id',actor,'intent',_intent,'snapshots',snapshots,'checked_at',clock_timestamp());
END $function$
;

CREATE OR REPLACE FUNCTION public.tgm_apply_controls(_intent jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.tgm_bulk_actor(_intent);old private.tgm_requests%ROWTYPE;rk uuid;tid uuid;eid uuid;ep text;t jsonb;c jsonb;beforev jsonb;afterv jsonb;results jsonb:='[]';result jsonb;
BEGIN
 PERFORM private.tgm_validate_bulk(_intent);rk:=(_intent->>'request_key')::uuid;
 PERFORM pg_advisory_xact_lock(hashtextextended('tgm:'||actor::text||':'||rk::text,0));
 SELECT * INTO old FROM private.tgm_requests WHERE actor_id=actor AND request_key=rk;
 -- Recheck all CURRENT roles/factors even when a prior receipt exists.
 FOR t IN SELECT value FROM jsonb_array_elements(_intent->'targets') ORDER BY value->>'tenant_id' LOOP
  tid:=(t->>'tenant_id')::uuid;PERFORM pg_advisory_xact_lock(hashtextextended('wfm:'||tid::text,0));
  FOR c IN SELECT value FROM jsonb_array_elements(_intent->'changes') LOOP IF private.wfm_can_manage(tid,c->>'kind'='mode' OR(c->>'kind'='feature' AND c->>'key' IN('copilot','agent','aidp','auto_match_ai','auto_remediation','byo_llm','cost_metering'))) IS DISTINCT FROM true THEN RAISE EXCEPTION 'tgm.current_authority_denied' USING ERRCODE='42501';END IF;END LOOP;
 END LOOP;
 IF old.request_key IS NOT NULL THEN IF old.kind<>'bulk' OR old.payload IS DISTINCT FROM _intent THEN RAISE EXCEPTION 'tgm.intent_conflict' USING ERRCODE='PT409';END IF;RETURN old.result;END IF;
 -- Prevalidate every version before the first update. Any exception rolls back the entire batch.
 FOR t IN SELECT value FROM jsonb_array_elements(_intent->'targets') LOOP tid:=(t->>'tenant_id')::uuid;IF coalesce((SELECT epoch::text FROM private.wfm_epoch WHERE tenant_id=tid),'0')<>t->>'expected_epoch' THEN RAISE EXCEPTION 'tgm.epoch_conflict' USING ERRCODE='PT409';END IF;END LOOP;
 FOR t IN SELECT value FROM jsonb_array_elements(_intent->'targets') ORDER BY value->>'tenant_id' LOOP
  tid:=(t->>'tenant_id')::uuid;beforev:=public.wfm_get_snapshot(tid,NULL);
  FOR c IN SELECT value FROM jsonb_array_elements(_intent->'changes') ORDER BY value->>'kind',value->>'key' LOOP
   SELECT coalesce((SELECT epoch::text FROM private.wfm_epoch WHERE tenant_id=tid),'0') INTO ep;
   PERFORM public.wfm_set_control(tid,c->>'kind',c->>'key',(c->>'enabled')::boolean,ep,gen_random_uuid(),NULL);
  END LOOP;
  afterv:=public.wfm_get_snapshot(tid,NULL);
  INSERT INTO private.tgm_events(actor_id,tenant_id,kind,reason,request_key,before_value,after_value) VALUES(actor,tid,'bulk',trim(_intent->>'reason'),rk,beforev,afterv) RETURNING id INTO eid;
  results:=results||jsonb_build_array(jsonb_build_object('tenant_id',tid,'epoch',afterv->>'epoch','event_id',eid));
 END LOOP;
 result:=jsonb_build_object('actor_id',actor,'request_key',rk,'atomic',true,'results',results,'occurred_at',clock_timestamp());
 INSERT INTO private.tgm_requests(actor_id,request_key,kind,payload,result) VALUES(actor,rk,'bulk',_intent,result);RETURN result;
END $function$
;

CREATE OR REPLACE FUNCTION public.tgm_get_bulk_request(_request_key uuid, _tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.wfm_actor(_tenant_id);r private.tgm_requests%ROWTYPE;t jsonb;
BEGIN IF private.wfm_can_manage(_tenant_id,false) IS DISTINCT FROM true THEN RAISE EXCEPTION 'tgm.request_denied' USING ERRCODE='42501';END IF;SELECT * INTO r FROM private.tgm_requests WHERE actor_id=actor AND request_key=_request_key AND kind='bulk';IF FOUND THEN IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r.payload->'targets')x WHERE x->>'tenant_id'=_tenant_id::text) OR private.tgm_bulk_actor(r.payload) IS DISTINCT FROM actor THEN RAISE EXCEPTION 'tgm.request_scope_denied' USING ERRCODE='42501';END IF;FOR t IN SELECT value FROM jsonb_array_elements(r.payload->'targets') LOOP PERFORM private.wfm_actor((t->>'tenant_id')::uuid);END LOOP;END IF;RETURN jsonb_build_object('actor_id',actor,'request_key',_request_key,'receipt',r.result);END $function$
;

CREATE OR REPLACE FUNCTION public.tgm_control_audit(_tenant_id uuid, _search text, _offset integer, _limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.wfm_actor(_tenant_id);events jsonb;total bigint;latest jsonb;
BEGIN
 IF private.wfm_can_manage(_tenant_id,false) IS DISTINCT FROM true THEN RAISE EXCEPTION 'tgm.audit_denied' USING ERRCODE='42501';END IF;
 IF _search IS NULL OR length(_search)>120 OR _offset IS NULL OR _offset<0 OR _offset>100000 OR _limit IS NULL OR _limit<1 OR _limit>100 THEN RAISE EXCEPTION 'tgm.invalid_query' USING ERRCODE='22023';END IF;
 SELECT jsonb_build_object('id',e.id,'tenant_id',e.tenant_id,'actor_id',e.actor_id,'occurred_at',e.occurred_at,'kind',e.kind,'key',e.key,'before_value',e.before_value,'after_value',e.after_value,'epoch',e.epoch::text,'reason',(SELECT b.reason FROM private.tgm_events b WHERE b.tenant_id=e.tenant_id AND b.actor_id=e.actor_id AND b.kind='bulk' AND e.epoch>(b.before_value->>'epoch')::bigint AND e.epoch<=(b.after_value->>'epoch')::bigint ORDER BY b.occurred_at DESC,b.id LIMIT 1)) INTO latest FROM private.wfm_events e WHERE e.tenant_id=_tenant_id ORDER BY e.epoch DESC,e.id LIMIT 1;
 SELECT count(*) INTO total FROM private.wfm_events WHERE tenant_id=_tenant_id AND(_search='' OR strpos(lower(key||' '||kind||' '||actor_id::text),lower(_search))>0);
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',e.id,'tenant_id',e.tenant_id,'actor_id',e.actor_id,'occurred_at',e.occurred_at,'kind',e.kind,'key',e.key,'before_value',e.before_value,'after_value',e.after_value,'epoch',e.epoch::text,'reason',(SELECT b.reason FROM private.tgm_events b WHERE b.tenant_id=e.tenant_id AND b.actor_id=e.actor_id AND b.kind='bulk' AND e.epoch>(b.before_value->>'epoch')::bigint AND e.epoch<=(b.after_value->>'epoch')::bigint ORDER BY b.occurred_at DESC,b.id LIMIT 1)) ORDER BY e.epoch DESC),'[]') INTO events FROM(SELECT * FROM private.wfm_events WHERE tenant_id=_tenant_id AND(_search='' OR strpos(lower(key||' '||kind||' '||actor_id::text),lower(_search))>0) ORDER BY epoch DESC LIMIT _limit OFFSET _offset)e;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'search',_search,'offset',_offset,'limit',_limit,'total',total,'events',events,'latest_event',latest);
END $function$
;

CREATE OR REPLACE FUNCTION private.dps_get_scope_core(_tenant_id uuid, _pipeline_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_authorize(_tenant_id,_pipeline_id,'view');req private.dps_scope_requests%ROWTYPE;dec private.dps_scope_decisions%ROWTYPE;
BEGIN
 SELECT r.* INTO req FROM private.dps_scope_requests r JOIN private.dpw_configuration_heads h ON h.configuration_id=r.configuration_id WHERE h.pipeline_id=_pipeline_id AND r.tenant_id=_tenant_id;
 SELECT * INTO dec FROM private.dps_scope_decisions WHERE request_id=req.id;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'pipeline_id',_pipeline_id,'scope_status',CASE WHEN req.id IS NULL THEN 'legacy_not_recorded' WHEN dec.id IS NULL THEN 'pending' ELSE dec.decision END,
 'request_id',req.id,'configuration_id',req.configuration_id,'request_sha256',req.request_sha256,'owning_business_unit_ids',coalesce(req.owning_business_unit_ids,'{}'),
 'sharing_user_group_ids',coalesce(req.sharing_user_group_ids,'{}'),'decision',CASE WHEN dec.id IS NULL THEN NULL ELSE to_jsonb(dec) END,
 'actual_owner_bu_ids',coalesce((SELECT jsonb_agg(o.bu_id ORDER BY o.bu_id) FROM public.data_resource_registry r JOIN public.data_resource_registry_owner_bu o ON o.registry_id=r.id AND o.tenant_id=r.tenant_id WHERE r.tenant_id=_tenant_id AND r.data_prep_pipeline_id=_pipeline_id),'[]'),
 'actual_view_group_ids',coalesce((SELECT jsonb_agg(DISTINCT v.principal_group_id ORDER BY v.principal_group_id) FROM public.data_resource_registry r JOIN public.data_resource_registry_grants v ON v.registry_id=r.id AND v.tenant_id=r.tenant_id WHERE r.tenant_id=_tenant_id AND r.data_prep_pipeline_id=_pipeline_id AND v.action='view' AND v.principal_type='group'),'[]'));
END $function$
;

CREATE OR REPLACE FUNCTION public.tgm_get_controls(_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.wfm_actor(_tenant_id);snapshot jsonb;
BEGIN
 snapshot:=public.wfm_get_snapshot(_tenant_id,NULL);
 IF snapshot->>'actor_id' IS DISTINCT FROM actor::text OR snapshot->>'tenant_id' IS DISTINCT FROM _tenant_id::text THEN RAISE EXCEPTION 'tgm.control_scope_changed' USING ERRCODE='42501';END IF;
 RETURN snapshot||jsonb_build_object('can_manage',private.wfm_can_manage(_tenant_id,false),'can_manage_ai',private.wfm_can_manage(_tenant_id,true));
END $function$
;

CREATE OR REPLACE FUNCTION private.dps_assert_configuration_scope(_configuration uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE cfg public.data_prep_configuration_revisions%ROWTYPE;req private.dps_scope_requests%ROWTYPE;
BEGIN
 SELECT * INTO cfg FROM public.data_prep_configuration_revisions WHERE id=_configuration;
 IF cfg.id IS NULL THEN RAISE EXCEPTION 'dps.configuration_not_found' USING ERRCODE='42501';END IF;
 IF cfg.payload->>'shared_scope_contract' IS DISTINCT FROM 'dps-v1' THEN
  IF EXISTS(SELECT 1 FROM private.dps_scope_requests q WHERE q.pipeline_id=cfg.pipeline_id AND q.tenant_id=cfg.tenant_id AND q.created_at<=cfg.created_at)
  THEN RAISE EXCEPTION 'dps.shared_scope_contract_downgrade_refused' USING ERRCODE='42501';END IF;
  RETURN;
 END IF;
 SELECT * INTO req FROM private.dps_scope_requests WHERE configuration_id=cfg.id AND configuration_sha256=cfg.payload_sha256;
 IF req.id IS NULL OR NOT EXISTS(SELECT 1 FROM private.dps_scope_decisions WHERE request_id=req.id AND decision='approved') THEN RAISE EXCEPTION 'dps.approved_scope_required' USING ERRCODE='42501';END IF;
END $function$
;

CREATE OR REPLACE FUNCTION private.dps_assert_pipeline_sources_current(_tenant uuid, _pipeline uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_authorize(_tenant,_pipeline,'view');cfg public.data_prep_configuration_revisions%ROWTYPE;source uuid;
BEGIN
 SELECT c.* INTO cfg FROM public.data_prep_configuration_revisions c JOIN private.dpw_configuration_heads h ON h.configuration_id=c.id WHERE h.pipeline_id=_pipeline AND c.tenant_id=_tenant;
 IF cfg.id IS NULL THEN RETURN;END IF;
 PERFORM private.dps_assert_configuration_scope(cfg.id);
 IF cfg.payload->>'shared_scope_contract' IS DISTINCT FROM 'dps-v1' THEN RETURN;END IF;
 FOR source IN SELECT DISTINCT (value->>'data_source_id')::uuid FROM jsonb_array_elements(cfg.payload->'feeds') LOOP
  IF NOT EXISTS(SELECT 1 FROM public.data_resource_registry WHERE tenant_id=_tenant AND resource_type='data_source' AND data_source_id=source)
  OR private.dpw_source_allows(actor,_tenant,source,'view') IS DISTINCT FROM true THEN RAISE EXCEPTION 'dps.current_consumer_input_view_required' USING ERRCODE='42501';END IF;
 END LOOP;
END $function$
;

CREATE OR REPLACE FUNCTION private.dps_assert_preparation_source_scope(_tenant uuid, _run uuid, _actor uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE r public.data_prep_delivery_runs%ROWTYPE;cfg public.data_prep_configuration_revisions%ROWTYPE;source uuid;
BEGIN
 IF _actor IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'dps.current_consumer_actor_required' USING ERRCODE='42501';END IF;
 SELECT * INTO r FROM public.data_prep_delivery_runs WHERE id=_run AND tenant_id=_tenant;
 IF r.id IS NULL THEN RAISE EXCEPTION 'dps.preparation_binding_missing' USING ERRCODE='42501';END IF;
 SELECT * INTO cfg FROM public.data_prep_configuration_revisions WHERE id=nullif(r.snapshot->>'configuration_id','')::uuid AND tenant_id=_tenant AND pipeline_id=r.pipeline_id AND pipeline_version=r.pipeline_version;
 IF cfg.id IS NULL THEN
  IF EXISTS(SELECT 1 FROM private.dps_scope_requests q JOIN public.data_prep_configuration_revisions c ON c.id=q.configuration_id WHERE q.tenant_id=_tenant AND q.pipeline_id=r.pipeline_id AND c.pipeline_version=r.pipeline_version)
  THEN RAISE EXCEPTION 'dps.exact_configuration_snapshot_required' USING ERRCODE='42501';END IF;
  RETURN; -- truthful legacy absence, never reinterpret as a new approved scope
 END IF;
 PERFORM private.dps_assert_configuration_scope(cfg.id);
 IF cfg.payload->>'shared_scope_contract' IS DISTINCT FROM 'dps-v1' THEN RETURN;END IF;
 FOR source IN SELECT DISTINCT f.data_source_id FROM public.data_prep_run_inputs i JOIN public.data_prep_delivery_files f ON f.id=i.file_id AND f.tenant_id=_tenant WHERE i.run_id=r.id LOOP
  IF NOT EXISTS(SELECT 1 FROM public.data_resource_registry WHERE tenant_id=_tenant AND resource_type='data_source' AND data_source_id=source)
  OR private.dpw_source_allows(_actor,_tenant,source,'view') IS DISTINCT FROM true THEN RAISE EXCEPTION 'dps.current_original_input_view_required' USING ERRCODE='42501';END IF;
 END LOOP;
END $function$
;

CREATE OR REPLACE FUNCTION private.dpd_peer_actor(_tenant uuid, _subject jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid;
BEGIN
 IF _subject->>'role' IS DISTINCT FROM 'authenticated' OR _subject->>'sub' IS NULL OR coalesce(_subject->>'exp','')!~'^[0-9]{1,20}$' THEN RAISE EXCEPTION 'dpd.verified_subject_required' USING ERRCODE='42501';END IF;actor:=(_subject->>'sub')::uuid;
 IF private.dpw_native_factor_attest(actor,_tenant,_subject->>'aal',to_timestamp((_subject->>'exp')::double precision)) IS DISTINCT FROM true
 OR private.dpw_workspace_feature_attest(actor,_tenant) IS DISTINCT FROM true OR private.wfm_enabled(_tenant,'prep') IS DISTINCT FROM true
 OR private.rlnext_account_allowed(actor,NULL) IS DISTINCT FROM true OR private.rlnext_account_allowed(actor,_tenant) IS DISTINCT FROM true
 OR NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant AND user_id=actor AND active) THEN RAISE EXCEPTION 'dpd.current_verified_subject_denied' USING ERRCODE='42501';END IF;
 RETURN actor;
END $function$
;

CREATE OR REPLACE FUNCTION private.dpd_service_request_actor(_tenant uuid, _setup uuid, _operation text, _context uuid, _subject jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_peer_actor(_tenant,_subject);c private.dpd_request_contexts%ROWTYPE;enabled boolean;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant,actor,false);
 IF auth.role() IS DISTINCT FROM 'service_role' OR current_setting('role',true) IS DISTINCT FROM 'service_role' OR _context IS NULL THEN RAISE EXCEPTION 'dpd.fixed_service_context_required' USING ERRCODE='42501';END IF;
 SELECT * INTO c FROM private.dpd_request_contexts WHERE id=_context AND tenant_id=_tenant AND actor_id=actor AND setup_id=_setup AND operation=_operation;
 IF NOT FOUND OR c.expires_at<=clock_timestamp() OR c.verified_subject->>'sub' IS DISTINCT FROM _subject->>'sub' OR c.verified_subject->>'aal' IS DISTINCT FROM _subject->>'aal' OR c.verified_subject->>'exp' IS DISTINCT FROM _subject->>'exp' OR public.user_has_permission(actor,_tenant,'data.prep.author',NULL) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.fresh_verified_service_context_required' USING ERRCODE='42501';END IF;
 SELECT ip_allowlist_enabled INTO enabled FROM public.tenant_security_settings WHERE tenant_id=_tenant;
 IF NOT FOUND OR enabled IS NULL OR (enabled AND (c.request_ip IS NULL OR public.ip_in_tenant_allowlist(_tenant,host(c.request_ip)) IS DISTINCT FROM true)) OR NOT EXISTS(SELECT 1 FROM private.dpd_setups WHERE id=_setup AND tenant_id=_tenant AND created_by=actor) THEN RAISE EXCEPTION 'dpd.current_service_network_scope_denied' USING ERRCODE='42501';END IF;RETURN actor;
END $function$
;

CREATE OR REPLACE FUNCTION private.fvi_report_snapshot(_actor uuid, _tenant uuid, _spec jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE ids uuid[]; anchor timestamptz:=clock_timestamp(); start_at timestamptz; days integer; ops jsonb; ai jsonb; risk jsonb;
  security jsonb; audit jsonb; config jsonb; trend jsonb; users bigint; output jsonb;
BEGIN
  PERFORM private.fvi_report_validate(_spec);ids:=private.fvi_report_scope(_actor,_tenant,_spec);days:=(_spec->>'days')::integer;
  start_at:=((anchor AT TIME ZONE 'UTC')::date-(days-1))::timestamp AT TIME ZONE 'UTC';
  WITH runs AS (SELECT r.*,CASE WHEN jsonb_typeof(r.stats->'matched_records')='number'
    AND r.stats->>'matched_records' ~ '^[0-9]+$' AND r.total_rows>=0
    AND (r.stats->>'matched_records')::numeric BETWEEN 0 AND r.total_rows THEN (r.stats->>'matched_records')::numeric ELSE NULL END AS inputs_matched
    FROM public.recon_runs r WHERE r.tenant_id=_tenant AND r.definition_id=ANY(ids) AND r.started_at BETWEEN start_at AND anchor),
  totals AS (SELECT count(*) n,count(*) FILTER(WHERE status IN ('completed','succeeded')) successes,count(*) FILTER(WHERE status='failed') failures,
    CASE WHEN count(*)=0 THEN 0 WHEN count(*) FILTER(WHERE matched_count IS NULL OR matched_count<0)>0 THEN NULL ELSE sum(matched_count)::numeric END matched_groups,
    CASE WHEN count(*)=0 THEN 0 WHEN count(*) FILTER(WHERE exception_count IS NULL OR exception_count<0)>0 THEN NULL ELSE sum(exception_count)::numeric END exceptions,
    CASE WHEN count(*)=0 THEN 0 WHEN count(*) FILTER(WHERE inputs_matched IS NULL)>0 THEN NULL ELSE sum(inputs_matched) END matched_inputs,
    CASE WHEN count(*)=0 THEN 0 WHEN count(*) FILTER(WHERE inputs_matched IS NULL OR total_rows IS NULL)>0 THEN NULL ELSE sum(total_rows)::numeric END input_rows,
    avg(extract(epoch FROM completed_at-started_at)) FILTER(WHERE completed_at>=started_at) runtime FROM runs)
  SELECT jsonb_build_object('runs',n,'success',successes,'failed',failures,'matched',matched_groups,'exceptions',exceptions,
    'matched_input_memberships',matched_inputs,'total_input_rows',input_rows,'match_rate_pct',CASE WHEN input_rows>0 THEN round(100*matched_inputs/input_rows,1) ELSE NULL END,
    'avg_runtime_sec',round(runtime,1),'active_schedules',(SELECT count(*) FROM public.recon_schedules s WHERE s.tenant_id=_tenant AND s.definition_id=ANY(ids) AND s.enabled),
    'members',(SELECT count(*) FROM public.tenant_members m WHERE m.tenant_id=_tenant AND m.active)) INTO ops FROM totals;
  WITH run_rows AS (SELECT r.*,CASE WHEN jsonb_typeof(r.stats->'matched_records')='number' AND r.stats->>'matched_records' ~ '^[0-9]+$'
    AND r.total_rows>=0 AND (r.stats->>'matched_records')::numeric BETWEEN 0 AND r.total_rows THEN (r.stats->>'matched_records')::numeric ELSE NULL END inputs_matched
    FROM public.recon_runs r WHERE r.tenant_id=_tenant AND r.definition_id=ANY(ids) AND r.started_at BETWEEN start_at AND anchor),
  dates AS (SELECT d::date AS report_day FROM generate_series(start_at AT TIME ZONE 'UTC',anchor AT TIME ZONE 'UTC',interval '1 day') d),
  daily AS (SELECT d.report_day,count(r.id) n,
    CASE WHEN count(r.id)=0 THEN 0 WHEN count(*) FILTER(WHERE r.id IS NOT NULL AND (r.matched_count IS NULL OR r.matched_count<0))>0 THEN NULL ELSE sum(r.matched_count) END matched_groups,
    CASE WHEN count(r.id)=0 THEN 0 WHEN count(*) FILTER(WHERE r.id IS NOT NULL AND (r.exception_count IS NULL OR r.exception_count<0))>0 THEN NULL ELSE sum(r.exception_count) END exceptions,
    CASE WHEN count(*) FILTER(WHERE r.id IS NOT NULL AND r.inputs_matched IS NULL)>0 THEN NULL ELSE sum(r.inputs_matched) END mi,
    CASE WHEN count(*) FILTER(WHERE r.id IS NOT NULL AND r.inputs_matched IS NULL)>0 THEN NULL ELSE sum(r.total_rows) END ti
    FROM dates d LEFT JOIN run_rows r ON (r.started_at AT TIME ZONE 'UTC')::date=d.report_day GROUP BY d.report_day)
  SELECT coalesce(jsonb_agg(jsonb_build_object('day',report_day,'runs',n,'matched',matched_groups,'exceptions',exceptions,'rate',CASE WHEN ti>0 THEN round(100*mi/ti,1) ELSE NULL END) ORDER BY report_day),'[]') INTO trend FROM daily;
  WITH breaks AS (SELECT e.* FROM public.recon_exceptions e JOIN public.recon_runs r ON r.id=e.run_id AND r.tenant_id=e.tenant_id
    WHERE e.tenant_id=_tenant AND r.definition_id=ANY(ids) AND e.created_at BETWEEN start_at AND anchor),
  opened AS (SELECT * FROM breaks WHERE lifecycle_state IS DISTINCT FROM 'resolved' AND lifecycle_state IS DISTINCT FROM 'written_off' AND status IS DISTINCT FROM 'resolved' AND status IS DISTINCT FROM 'wont_fix')
  SELECT jsonb_build_object('open_breaks',count(*),'overdue',count(*) FILTER(WHERE due_date<anchor),
    'critical',count(*) FILTER(WHERE severity='critical'),'high',count(*) FILTER(WHERE severity='high')) INTO risk FROM opened;
  WITH events AS (SELECT * FROM public.ai_usage_events WHERE tenant_id=_tenant AND created_at BETWEEN start_at AND anchor),
  models AS (SELECT model,count(*) calls,CASE WHEN count(*) FILTER(WHERE tokens_in IS NULL OR tokens_out IS NULL OR tokens_in<0 OR tokens_out<0)>0 THEN NULL ELSE sum(tokens_in::numeric+tokens_out) END tokens,
    CASE WHEN count(*) FILTER(WHERE cost_usd IS NULL OR cost_usd::text !~ '^[0-9]+(\.[0-9]+)?$')>0 THEN NULL ELSE sum(cost_usd)::text END cost_usd_exact,
    count(*) FILTER(WHERE cost_usd IS NULL OR cost_usd::text !~ '^[0-9]+(\.[0-9]+)?$') unknown_cost_events FROM events GROUP BY model),
  totals AS (SELECT count(*) calls,
    CASE WHEN count(*)=0 THEN 0 WHEN count(*) FILTER(WHERE tokens_in IS NULL OR tokens_in<0)>0 THEN NULL ELSE sum(tokens_in::numeric) END ti,
    CASE WHEN count(*)=0 THEN 0 WHEN count(*) FILTER(WHERE tokens_out IS NULL OR tokens_out<0)>0 THEN NULL ELSE sum(tokens_out::numeric) END tout,
    CASE WHEN count(*)=0 THEN '0' WHEN count(*) FILTER(WHERE cost_usd IS NULL OR cost_usd::text !~ '^[0-9]+(\.[0-9]+)?$')>0 THEN NULL ELSE sum(cost_usd)::text END cost,
    count(*) FILTER(WHERE cost_usd IS NULL OR cost_usd::text !~ '^[0-9]+(\.[0-9]+)?$') missing FROM events)
  SELECT jsonb_build_object('calls',calls,'tokens_in',ti,'tokens_out',tout,'total_tokens',ti+tout,'cost_usd_exact',cost,'unknown_cost_events',missing,
    'cost_by_currency',jsonb_build_array(jsonb_build_object('currency','USD','amount',cost)),
    'by_model',coalesce((SELECT jsonb_agg(jsonb_build_object('name',model,'calls',calls,'tokens',tokens,'cost_usd_exact',cost_usd_exact,'currency','USD','unknown_cost_events',unknown_cost_events) ORDER BY model) FROM models),'[]')) INTO ai FROM totals;
  SELECT jsonb_build_object('events_total',count(*),'failed_logins',count(*) FILTER(WHERE event_type ~* 'fail|denied|invalid|lock'),
    'unique_ips',count(DISTINCT ip)) INTO security FROM public.security_events WHERE tenant_id=_tenant AND occurred_at BETWEEN start_at AND anchor;
  SELECT jsonb_build_object('events_total',count(*),'distinct_actions',count(DISTINCT action),'distinct_actors',count(DISTINCT coalesce(actor_user_id::text,actor_email::text))) INTO audit
    FROM public.audit_log WHERE tenant_id=_tenant AND occurred_at BETWEEN start_at AND anchor;
  config:=jsonb_build_object('checks',jsonb_build_array(
    jsonb_build_object('id','sso','name','Single sign-on configured','ok',EXISTS(SELECT 1 FROM public.tenant_sso_configs WHERE tenant_id=_tenant AND enabled),'control','Configuration evidence only'),
    jsonb_build_object('id','ip','name','IP allow-list configured','ok',EXISTS(SELECT 1 FROM public.tenant_ip_allowlist WHERE tenant_id=_tenant),'control','Configuration evidence only'),
    jsonb_build_object('id','mfa','name','MFA requirement configured','ok',EXISTS(SELECT 1 FROM public.tenant_security_settings WHERE tenant_id=_tenant AND mfa_required),'control','Configuration evidence only'),
    jsonb_build_object('id','audit','name','Audit events visible in this window','ok',(audit->>'events_total')::numeric>0,'control','Event presence is not chain verification')));
  output:=jsonb_build_object('window_days',days,'generated_at',anchor,'reporting_timezone','UTC','reconciliation_ids',to_jsonb(ids),
    'scope',jsonb_build_object('reconciliation_id',_spec->'reconciliation_id','bu_id',_spec->'bu_id','reconciliation_count',cardinality(ids)),
    'coverage',jsonb_build_object('snapshot','current persisted row state at generation; not historical time travel','tenant_wide_sections',jsonb_build_array('ai','security','configuration','audit','users')),
    'operations',ops,'match_rates',jsonb_build_object('trend',trend),'risk',risk,'ai_usage',ai,'security',security,'audit',audit,'compliance',config);
  IF octet_length(output::text)>1048576 THEN RAISE EXCEPTION 'Report snapshot exceeds safe interactive size' USING ERRCODE='54000'; END IF;
  RETURN output;
END $function$
;

CREATE OR REPLACE FUNCTION private.fvi_report_scope(_actor uuid, _tenant uuid, _spec jsonb)
 RETURNS uuid[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE ids uuid[]; recon uuid; bu uuid;
BEGIN
  IF NOT private.fvi_report_admin(_actor,_tenant) THEN RAISE EXCEPTION 'Active tenant administrator required' USING ERRCODE='42501'; END IF;
  recon:=nullif(_spec->>'reconciliation_id','')::uuid; bu:=nullif(_spec->>'bu_id','')::uuid;
  IF bu IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.business_units b WHERE b.id=bu AND b.tenant_id=_tenant AND NOT b.is_archived) THEN
    RAISE EXCEPTION 'Business unit unavailable' USING ERRCODE='42501'; END IF;
  SELECT coalesce(array_agg(d.id ORDER BY d.id),ARRAY[]::uuid[]) INTO ids FROM public.recon_definitions d
  WHERE d.tenant_id=_tenant AND private.user_can_access_recon(_actor,d.id,'read')
    AND (recon IS NULL OR d.id=recon) AND (bu IS NULL OR EXISTS(SELECT 1 FROM public.recon_definition_business_units o
      WHERE o.tenant_id=_tenant AND o.recon_id=d.id AND o.bu_id=bu));
  IF recon IS NOT NULL AND NOT recon=ANY(ids) THEN RAISE EXCEPTION 'Reconciliation unavailable in current scope' USING ERRCODE='42501'; END IF;
  RETURN ids;
END $function$
;

CREATE OR REPLACE FUNCTION private.fvi_report_validate(_spec jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE allowed text[]:=ARRAY['operations.runs','operations.success','operations.failed','operations.matched','operations.exceptions',
  'operations.match_rate_pct','operations.matched_input_memberships','operations.total_input_rows','operations.avg_runtime_sec',
  'risk.open_breaks','risk.overdue','ai_usage.calls','ai_usage.tokens_in','ai_usage.tokens_out','ai_usage.cost_usd_exact',
  'security.events_total','security.failed_logins','audit.events_total','audit.distinct_actions','audit.distinct_actors']; keys text[];
BEGIN
  IF jsonb_typeof(_spec)<>'object' OR _spec->>'schema_version' IS DISTINCT FROM '1'
     OR NOT _spec ?& ARRAY['schema_version','type','days','metrics','reconciliation_id','bu_id']
     OR (_spec->>'type') IS NULL OR (_spec->>'type') NOT IN ('operations','match_rates','risk','ai','security','configuration','audit','users','usage','cost','custom')
     OR (_spec->>'days') IS NULL OR (_spec->>'days') !~ '^[0-9]+$' OR (_spec->>'days')::integer NOT BETWEEN 7 AND 180
     OR jsonb_typeof(_spec->'metrics') IS DISTINCT FROM 'array'
     OR EXISTS(SELECT 1 FROM jsonb_object_keys(_spec) k WHERE k NOT IN ('schema_version','type','days','metrics','reconciliation_id','bu_id')) THEN
    RAISE EXCEPTION 'Unsupported report design' USING ERRCODE='22023'; END IF;
  SELECT coalesce(array_agg(k),ARRAY[]::text[]) INTO keys FROM jsonb_array_elements_text(_spec->'metrics') k;
  IF cardinality(keys)>20 OR NOT keys <@ allowed OR cardinality(keys)<>(SELECT count(DISTINCT k) FROM unnest(keys) k)
     OR (_spec->>'type'='custom' AND cardinality(keys)=0) THEN RAISE EXCEPTION 'Unsupported report metrics' USING ERRCODE='22023'; END IF;
  PERFORM nullif(_spec->>'reconciliation_id','')::uuid,nullif(_spec->>'bu_id','')::uuid;
END $function$
;

CREATE OR REPLACE FUNCTION private.fvi_report_cron_field(_field text, _value integer, _minimum integer, _maximum integer)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE item text; base text; step integer; low integer; high integer; matched boolean:=false;
BEGIN
  FOREACH item IN ARRAY string_to_array(_field,',') LOOP
    IF item !~ '^(\*|[0-9]+(-[0-9]+)?)(/[0-9]+)?$' THEN RAISE EXCEPTION 'Use a numeric five-field cron' USING ERRCODE='22023'; END IF;
    base:=split_part(item,'/',1); step:=CASE WHEN strpos(item,'/')>0 THEN split_part(item,'/',2)::integer ELSE 1 END;
    IF step<1 OR step>_maximum-_minimum+1 THEN RAISE EXCEPTION 'Invalid cron step' USING ERRCODE='22023'; END IF;
    IF base='*' THEN low:=_minimum;high:=_maximum;
    ELSIF strpos(base,'-')>0 THEN low:=split_part(base,'-',1)::integer;high:=split_part(base,'-',2)::integer;
    ELSE low:=base::integer;high:=CASE WHEN strpos(item,'/')>0 THEN _maximum ELSE low END; END IF;
    IF low<_minimum OR high>_maximum OR low>high THEN RAISE EXCEPTION 'Invalid cron range' USING ERRCODE='22023'; END IF;
    matched:=matched OR (_value BETWEEN low AND high AND mod(_value-low,step)=0);
  END LOOP;
  RETURN matched;
END $function$
;

CREATE OR REPLACE FUNCTION private.fvi_report_wall_instants(_wall timestamp without time zone, _zone text)
 RETURNS timestamp with time zone[]
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
  WITH offsets AS (SELECT DISTINCT extract(epoch FROM ((s AT TIME ZONE 'UTC')-(s AT TIME ZONE _zone))) AS seconds
    FROM (SELECT _wall+make_interval(hours=>h) s FROM unnest(ARRAY[-48,-24,0,24,48]) h) samples),
  candidates AS (SELECT (_wall AT TIME ZONE 'UTC')-make_interval(secs=>seconds::double precision) instant FROM offsets)
  SELECT coalesce(array_agg(instant ORDER BY instant),ARRAY[]::timestamptz[]) FROM candidates WHERE instant AT TIME ZONE _zone=_wall;
$function$
;

CREATE OR REPLACE FUNCTION private.fvi_report_next_due(_spec jsonb, _after timestamp with time zone)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE kind text:=_spec->>'kind'; zone text:=_spec->>'timezone'; tm text:=_spec->>'time'; expr text; fields text[];
  date0 date; day date; wall timestamp; instants timestamptz[]; h integer; m integer; daymatch boolean; i integer; result timestamptz;
BEGIN
  IF jsonb_typeof(_spec)<>'object' OR kind IS NULL OR kind NOT IN ('daily','weekly','monthly','cron','once')
    OR zone IS NULL OR NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=zone)
    OR tm IS NULL OR tm !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
    OR EXISTS(SELECT 1 FROM jsonb_object_keys(_spec) k WHERE k NOT IN ('kind','timezone','time','weekday','monthday','cron','once_date')) THEN
    RAISE EXCEPTION 'Invalid report schedule' USING ERRCODE='22023'; END IF;
  IF kind='once' THEN
    IF (_spec->>'once_date') IS NULL OR (_spec->>'once_date') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'Choose a one-time calendar date' USING ERRCODE='22023'; END IF;
    wall:=((_spec->>'once_date')||' '||tm)::timestamp; instants:=private.fvi_report_wall_instants(wall,zone);
    IF cardinality(instants)<>1 THEN RAISE EXCEPTION 'One-time schedule is ambiguous or nonexistent in this timezone' USING ERRCODE='22023'; END IF;
    IF instants[1]<_after+interval '1 minute' OR instants[1]>_after+interval '1 year' THEN RAISE EXCEPTION 'One-time schedule must be one minute to one year ahead' USING ERRCODE='22023'; END IF;
    RETURN instants[1];
  END IF;
  IF kind='weekly' AND ((_spec->>'weekday') IS NULL OR (_spec->>'weekday') !~ '^[0-6]$') THEN RAISE EXCEPTION 'Choose a weekday' USING ERRCODE='22023'; END IF;
  IF kind='monthly' AND ((_spec->>'monthday') IS NULL OR (_spec->>'monthday') !~ '^[0-9]{1,2}$' OR (_spec->>'monthday')::integer NOT BETWEEN 1 AND 31) THEN RAISE EXCEPTION 'Choose a day of month' USING ERRCODE='22023'; END IF;
  expr:=CASE WHEN kind='cron' THEN btrim(_spec->>'cron') ELSE split_part(tm,':',2)::integer::text||' '||split_part(tm,':',1)::integer::text||' '||
    CASE WHEN kind='monthly' THEN _spec->>'monthday' ELSE '*' END||' * '||CASE WHEN kind='weekly' THEN _spec->>'weekday' ELSE '*' END END;
  fields:=regexp_split_to_array(expr,'\s+'); IF expr IS NULL OR cardinality(fields)<>5 THEN RAISE EXCEPTION 'Use a numeric five-field cron' USING ERRCODE='22023'; END IF;
  PERFORM private.fvi_report_cron_field(fields[1],0,0,59),private.fvi_report_cron_field(fields[2],0,0,23),
    private.fvi_report_cron_field(fields[3],1,1,31),private.fvi_report_cron_field(fields[4],1,1,12),private.fvi_report_cron_field(fields[5],0,0,6);
  date0:=(_after AT TIME ZONE zone)::date;
  FOR i IN 0..1830 LOOP
    day:=date0+i;
    IF NOT private.fvi_report_cron_field(fields[4],extract(month FROM day)::integer,1,12) THEN CONTINUE; END IF;
    daymatch:=CASE WHEN fields[3]='*' OR fields[5]='*' THEN
      private.fvi_report_cron_field(fields[3],extract(day FROM day)::integer,1,31) AND private.fvi_report_cron_field(fields[5],extract(dow FROM day)::integer,0,6)
      ELSE private.fvi_report_cron_field(fields[3],extract(day FROM day)::integer,1,31) OR private.fvi_report_cron_field(fields[5],extract(dow FROM day)::integer,0,6) END;
    IF NOT daymatch THEN CONTINUE; END IF;
    result:=NULL;
    FOR h IN 0..23 LOOP
      IF NOT private.fvi_report_cron_field(fields[2],h,0,23) THEN CONTINUE; END IF;
      FOR m IN 0..59 LOOP
        IF NOT private.fvi_report_cron_field(fields[1],m,0,59) THEN CONTINUE; END IF;
        wall:=day::timestamp+make_interval(hours=>h,mins=>m);instants:=private.fvi_report_wall_instants(wall,zone);
        -- Skip nonexistent local times and run a repeated local minute only once, at its first instant.
        IF cardinality(instants)>0 AND instants[1]>_after AND (result IS NULL OR instants[1]<result) THEN result:=instants[1]; END IF;
      END LOOP;
    END LOOP;
    IF result IS NOT NULL THEN RETURN result; END IF;
  END LOOP;
  RAISE EXCEPTION 'No scheduled occurrence found in five years' USING ERRCODE='22023';
END $function$
;

CREATE OR REPLACE FUNCTION private.mapped_recon_governance_stage_complete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE q public.recon_definition_governance_requests%ROWTYPE;
BEGIN
 IF NEW.access_mode='mapped_exact' AND NEW.governance_state='staging_copy' THEN
  SELECT * INTO q FROM public.recon_definition_governance_requests WHERE tenant_id=NEW.tenant_id
   AND staging_definition_id=NEW.id AND request_kind='edit' AND status='approved' AND mapped_governance_version=1;
  IF NOT FOUND OR private.mapped_recon_governance_scope_shape(NEW.tenant_id,NEW.id)
   IS DISTINCT FROM private.mapped_recon_governance_scope_shape(NEW.tenant_id,q.parent_definition_id) THEN
   PERFORM private.mapped_recon_governance_conflict('native_exact_copy_required');
  END IF;
  PERFORM private.mapped_recon_governance_mapping(NEW.tenant_id,NEW.id);
  PERFORM private.mapped_recon_governance_requester_current(NEW.tenant_id,NEW.id,q.requested_by);
 END IF;
 RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION private.dpd_actor(_tenant uuid, _write boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_actor(_tenant);network_enabled boolean;
BEGIN
 PERFORM private.wfm_assert_enabled(_tenant,'prep');IF _write THEN PERFORM public.assert_data_prep_actor(_tenant,actor,false);END IF;
 IF public.user_has_permission(actor,_tenant,CASE WHEN _write THEN 'data.prep.author' ELSE 'data.prep.read' END,NULL) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.current_capability_denied' USING ERRCODE='42501';END IF;
 SELECT ip_allowlist_enabled INTO network_enabled FROM public.tenant_security_settings WHERE tenant_id=_tenant;
 IF NOT FOUND OR network_enabled IS NULL THEN RAISE EXCEPTION 'dpd.current_network_policy_unavailable' USING ERRCODE='42501';END IF;
 -- Captured actual dpw_check_current_ip_access takes caller IP. It is not a
 -- trusted direct-native request binding; enabled policy cannot be bypassed.
 -- Network is enforced by fresh service-issued dpd_request_actor context in every public purpose. No caller IP/GUC use here.
 RETURN actor;
END $function$
;

CREATE OR REPLACE FUNCTION private.dpd_scope(_tenant uuid, _setup uuid, _write boolean)
 RETURNS private.dpd_setups
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_actor(_tenant,_write);s private.dpd_setups%ROWTYPE;
BEGIN SELECT * INTO s FROM private.dpd_setups WHERE id=_setup AND tenant_id=_tenant;
 IF NOT FOUND OR s.created_by<>actor THEN RAISE EXCEPTION 'dpd.current_setup_scope_denied' USING ERRCODE='42501';END IF;RETURN s;END $function$
;

CREATE OR REPLACE FUNCTION private.dpd_scope_ids(_tenant uuid, _owners uuid[], _groups uuid[])
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF cardinality(_owners) IS NULL OR cardinality(_owners) NOT BETWEEN 1 AND 100 OR cardinality(_groups)>100
 OR EXISTS(SELECT 1 FROM unnest(_owners) x LEFT JOIN public.business_units b ON b.id=x AND b.tenant_id=_tenant AND NOT b.is_archived WHERE b.id IS NULL)
 OR EXISTS(SELECT 1 FROM unnest(coalesce(_groups,'{}'::uuid[])) x LEFT JOIN public.tenant_groups g ON g.id=x AND g.tenant_id=_tenant WHERE g.id IS NULL)
 THEN RAISE EXCEPTION 'dpd.actual_bu_group_scope_required' USING ERRCODE='42501';END IF;
END $function$
;

CREATE OR REPLACE FUNCTION private.dpd_event(_tenant uuid, _setup uuid, _actor uuid, _kind text, _resource uuid, _details jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN INSERT INTO private.dpd_events(setup_id,tenant_id,actor_id,event_kind,resource_id,details) VALUES(_setup,_tenant,_actor,_kind,_resource,_details);PERFORM private.dpw_audit(_actor,_tenant,'dpd.'||_kind,_setup,_details||jsonb_build_object('resource_id',_resource));END $function$
;

CREATE OR REPLACE FUNCTION private.dpd_setup_result(_tenant uuid, _setup uuid, _actor uuid, _replay boolean, _version integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE s private.dpd_setups%ROWTYPE;v private.dpd_versions%ROWTYPE;l private.dpd_preview_links%ROWTYPE;files jsonb;
BEGIN SELECT * INTO s FROM private.dpd_setups WHERE id=_setup AND tenant_id=_tenant;SELECT * INTO v FROM private.dpd_versions WHERE setup_id=s.id AND (_version IS NULL OR version=_version) ORDER BY version DESC LIMIT 1;SELECT * INTO l FROM private.dpd_preview_links WHERE setup_id=s.id AND draft_version=v.version;
 SELECT coalesce(jsonb_agg(jsonb_build_object('file_id',f.id,'feed_key',f.feed_key,'request_key',f.request_key,'content_sha256',f.content_sha256,'state',CASE WHEN r.file_id IS NULL THEN 'uploading' ELSE 'received' END,'parser_state',private.dpd_parser_state(f.id),'name',f.descriptor->>'filename','raw_row_count',sc.raw_row_count::text,'data_source_id',raw.data_source_id) ORDER BY f.created_at,f.id),'[]') INTO files FROM private.dpd_original_intents f LEFT JOIN private.dpd_original_receipts r ON r.file_id=f.id LEFT JOIN private.dpd_schema_receipts sc ON sc.file_id=f.id LEFT JOIN private.dpd_raw_source_links raw ON raw.file_id=f.id WHERE f.setup_id=s.id;
 RETURN jsonb_build_object('actor_id',_actor,'tenant_id',_tenant,'setup_id',s.id,'pipeline_id',l.pipeline_id,'batch_id',l.batch_id,'reserved_pipeline_id',s.reserved_pipeline_id,'draft_version',v.version,'head_draft_version',(SELECT max(head.version) FROM private.dpd_versions head WHERE head.setup_id=s.id),'is_current',v.version=(SELECT max(head.version) FROM private.dpd_versions head WHERE head.setup_id=s.id),'request_replay',_replay,'publish_allowed',false,'status','draft','request_key',s.request_key,'payload',v.payload,'payload_sha256',v.payload_sha256,'owner_bu_ids',v.owner_bu_ids,'group_ids',v.group_ids,'files',files,'can_submit',false,'configuration_id',l.configuration_id,'pipeline_version',l.pipeline_version);
END $function$
;

CREATE OR REPLACE FUNCTION public.dpd_create_setup(_tenant_id uuid, _bu_id uuid, _owner_bu_ids uuid[], _group_ids uuid[], _title text, _business_date date, _execution_mode text, _human_in_loop boolean, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_actor(_tenant_id,true);s private.dpd_setups%ROWTYPE;input jsonb;reserved uuid:=gen_random_uuid();
BEGIN
 PERFORM private.dpd_request_actor(_tenant_id,NULL,'setup.create',_request_context_id);
 PERFORM private.dpd_scope_ids(_tenant_id,_owner_bu_ids,_group_ids);
 IF _request_key IS NULL OR length(btrim(coalesce(_title,''))) NOT BETWEEN 2 AND 120 OR _business_date IS NULL OR _execution_mode NOT IN('manual','assisted','agentic') OR _human_in_loop IS NULL OR (_bu_id IS NOT NULL AND NOT _bu_id=ANY(_owner_bu_ids)) THEN RAISE EXCEPTION 'dpd.invalid_setup' USING ERRCODE='22023';END IF;
 -- Current authorized modes are read separately by main; no assisted/agentic
 -- admission is inferred from a selected UI value before real pipeline exists.
 IF private.dpw_mode_attest(actor,_tenant_id,reserved,_execution_mode,_human_in_loop) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.current_draft_mode_policy_binding_required' USING ERRCODE='42501';END IF;
 input:=jsonb_build_object('bu_id',_bu_id,'owner_bu_ids',to_jsonb(_owner_bu_ids),'group_ids',to_jsonb(coalesce(_group_ids,'{}'::uuid[])),'title',btrim(_title),'business_date',_business_date,'execution_mode',_execution_mode,'human_in_loop',_human_in_loop);
 PERFORM pg_advisory_xact_lock(hashtextextended('dpd-create:'||_tenant_id::text||':'||actor::text||':'||_request_key::text,0));SELECT * INTO s FROM private.dpd_setups WHERE tenant_id=_tenant_id AND created_by=actor AND request_key=_request_key;
 IF FOUND THEN IF s.input IS DISTINCT FROM input THEN RAISE EXCEPTION 'dpd.request_conflict' USING ERRCODE='PT409';END IF;RETURN private.dpd_setup_result(_tenant_id,s.id,actor,true);END IF;
 INSERT INTO private.dpd_setups(tenant_id,created_by,reserved_pipeline_id,request_key,input,input_sha256) VALUES(_tenant_id,actor,reserved,_request_key,input,private.dpw_hash(input)) RETURNING * INTO s;
 INSERT INTO private.dpd_versions(setup_id,version,request_key,created_by,payload,payload_sha256,owner_bu_ids,group_ids) VALUES(s.id,1,_request_key,actor,input,private.dpw_hash(input),_owner_bu_ids,coalesce(_group_ids,'{}'::uuid[]));
 PERFORM private.dpd_event(_tenant_id,s.id,actor,'setup.created',s.id,jsonb_build_object('draft_version',1,'reserved_pipeline_id',s.reserved_pipeline_id,'public_pipeline_created',false));RETURN private.dpd_setup_result(_tenant_id,s.id,actor,false);
END $function$
;

CREATE OR REPLACE FUNCTION public.dpd_get_setup(_tenant_id uuid, _setup_id uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,false);BEGIN
 PERFORM private.dpd_request_actor(_tenant_id,_setup_id,'setup.read',_request_context_id); RETURN private.dpd_setup_result(_tenant_id,s.id,auth.uid(),false);END $function$
;

CREATE OR REPLACE FUNCTION public.fvi_save_report_design(_tenant uuid, _request uuid, _id uuid, _expected integer, _name text, _spec jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE actor uuid:=auth.uid(); old public.fvi_report_designs; replay public.fvi_report_design_requests; version integer; body jsonb;
BEGIN
  PERFORM private.fvi_report_validate(_spec); PERFORM private.fvi_report_scope(actor,_tenant,_spec);
  IF _request IS NULL OR _id IS NULL OR _expected IS NULL OR _expected<0 OR length(btrim(_name)) NOT BETWEEN 1 AND 160 THEN RAISE EXCEPTION 'Invalid design request' USING ERRCODE='22023'; END IF;
  body:=jsonb_build_object('id',_id,'expected',_expected,'name',btrim(_name),'spec',_spec);
  PERFORM pg_advisory_xact_lock(hashtextextended(_request::text,0));
  SELECT * INTO replay FROM public.fvi_report_design_requests WHERE request_id=_request;
  IF FOUND THEN
    IF replay.actor_id<>actor OR replay.tenant_id<>_tenant OR replay.request<>body THEN RAISE EXCEPTION 'Report request key conflict' USING ERRCODE='22023'; END IF;
    RETURN jsonb_build_object('id',replay.design_id,'version',replay.version,'replayed',true);
  END IF;
  SELECT * INTO old FROM public.fvi_report_designs WHERE id=_id FOR UPDATE;
  IF FOUND THEN
    IF old.tenant_id<>_tenant OR old.current_version<>_expected THEN RAISE EXCEPTION 'Report version changed; reload before saving' USING ERRCODE='40001'; END IF;
    version:=old.current_version+1;
    UPDATE public.fvi_report_designs SET name=btrim(_name),current_version=version,updated_at=clock_timestamp() WHERE id=_id;
  ELSE
    IF _expected<>0 THEN RAISE EXCEPTION 'Report design unavailable' USING ERRCODE='40001'; END IF;
    version:=1;
    INSERT INTO public.fvi_report_designs(id,tenant_id,name,current_version,created_by) VALUES(_id,_tenant,btrim(_name),version,actor);
  END IF;
  INSERT INTO public.fvi_report_design_versions(design_id,version,tenant_id,spec,created_by) VALUES(_id,version,_tenant,_spec,actor);
  INSERT INTO public.fvi_report_design_requests(request_id,tenant_id,actor_id,request,design_id,version) VALUES(_request,_tenant,actor,body,_id,version);
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
    VALUES(actor,_tenant,'tenant','report.design.save','fvi_report_designs',_id::text,jsonb_build_object('version',version,'request_id',_request));
  RETURN jsonb_build_object('id',_id,'version',version,'replayed',false);
END $function$
;

CREATE OR REPLACE FUNCTION public.fvi_preview_report_schedule(_tenant uuid, _spec jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE after_at timestamptz:=clock_timestamp(); due timestamptz; times jsonb:='[]'; i integer;
BEGIN
  IF NOT private.fvi_report_admin(auth.uid(),_tenant) THEN RAISE EXCEPTION 'Active tenant administrator required' USING ERRCODE='42501'; END IF;
  FOR i IN 1..5 LOOP
    due:=private.fvi_report_next_due(_spec,after_at); times:=times||jsonb_build_array(due); after_at:=due;
    IF _spec->>'kind'='once' THEN EXIT; END IF;
  END LOOP;
  RETURN jsonb_build_object('timezone',_spec->>'timezone','occurrences',times,'persisted',false,'recomputed_at_approval',true);
END $function$
;

CREATE OR REPLACE FUNCTION public.dpd_lookup_setup_request(_tenant_id uuid, _request_key uuid, _expected_input jsonb, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_actor(_tenant_id,true);s private.dpd_setups%ROWTYPE;
BEGIN
 PERFORM private.dpd_request_actor(_tenant_id,NULL,'setup.lookup',_request_context_id); SELECT * INTO s FROM private.dpd_setups WHERE tenant_id=_tenant_id AND created_by=actor AND request_key=_request_key;
 IF NOT FOUND THEN RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'state','absent','result',NULL);END IF;
 IF s.input IS DISTINCT FROM _expected_input THEN RAISE EXCEPTION 'dpd.lookup_request_conflict' USING ERRCODE='PT409';END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'state','found','result',private.dpd_setup_result(_tenant_id,s.id,actor,true));END $function$
;

CREATE OR REPLACE FUNCTION public.fvi_request_report_schedule(_tenant uuid, _id uuid, _design uuid, _version integer, _spec jsonb, _formats text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE actor uuid:=auth.uid(); design jsonb; old public.fvi_report_schedules;
BEGIN
  SELECT spec INTO design FROM public.fvi_report_design_versions WHERE design_id=_design AND version=_version AND tenant_id=_tenant;
  IF NOT FOUND THEN RAISE EXCEPTION 'Report version unavailable' USING ERRCODE='42501'; END IF;
  PERFORM private.fvi_report_scope(actor,_tenant,design); PERFORM private.fvi_report_next_due(_spec,clock_timestamp());
  IF _id IS NULL OR _formats IS NULL OR cardinality(_formats) NOT BETWEEN 1 AND 5 OR NOT _formats <@ ARRAY['csv','json','xlsx','pdf','html']::text[]
    OR cardinality(_formats)<>(SELECT count(DISTINCT v) FROM unnest(_formats) v) THEN RAISE EXCEPTION 'Choose supported distinct formats' USING ERRCODE='22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(_id::text,0)); SELECT * INTO old FROM public.fvi_report_schedules WHERE id=_id;
  IF FOUND THEN
    IF old.tenant_id<>_tenant OR old.created_by<>actor OR old.design_id<>_design OR old.design_version<>_version OR old.schedule_spec<>_spec OR old.formats<>_formats THEN
      RAISE EXCEPTION 'Schedule request key conflict' USING ERRCODE='22023'; END IF;
    RETURN to_jsonb(old)||jsonb_build_object('replayed',true);
  END IF;
  INSERT INTO public.fvi_report_schedules(id,tenant_id,design_id,design_version,created_by,schedule_spec,formats)
    VALUES(_id,_tenant,_design,_version,actor,_spec,_formats) RETURNING * INTO old;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
    VALUES(actor,_tenant,'tenant','report.schedule.request','fvi_report_schedules',_id::text,jsonb_build_object('design_version',_version,'delivery','in_app'));
  RETURN to_jsonb(old)||jsonb_build_object('replayed',false);
END $function$
;

CREATE OR REPLACE FUNCTION public.fvi_decide_report_schedule(_tenant uuid, _id uuid, _revision integer, _decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE actor uuid:=auth.uid(); job public.fvi_report_schedules; design jsonb; due timestamptz;
BEGIN
  IF NOT private.fvi_report_admin(actor,_tenant) OR auth.jwt()->>'aal' IS DISTINCT FROM 'aal2' THEN RAISE EXCEPTION 'Current MFA-verified tenant administrator required' USING ERRCODE='42501'; END IF;
  IF _decision NOT IN ('approve','reject') OR _decision IS NULL THEN RAISE EXCEPTION 'Invalid schedule decision' USING ERRCODE='22023'; END IF;
  SELECT * INTO job FROM public.fvi_report_schedules WHERE id=_id AND tenant_id=_tenant FOR UPDATE;
  IF NOT FOUND OR job.state<>'pending' OR job.revision<>_revision THEN RAISE EXCEPTION 'Schedule request changed; reload' USING ERRCODE='40001'; END IF;
  IF job.created_by=actor THEN RAISE EXCEPTION 'Independent checker required' USING ERRCODE='42501'; END IF;
  SELECT spec INTO design FROM public.fvi_report_design_versions WHERE design_id=job.design_id AND version=job.design_version AND tenant_id=_tenant;
  PERFORM private.fvi_report_scope(job.created_by,_tenant,design); PERFORM private.fvi_report_scope(actor,_tenant,design);
  due:=CASE WHEN _decision='approve' THEN private.fvi_report_next_due(job.schedule_spec,clock_timestamp()) ELSE NULL END;
  UPDATE public.fvi_report_schedules SET state=CASE WHEN _decision='approve' THEN 'approved' ELSE 'rejected' END,
    approved_by=actor,approved_at=clock_timestamp(),next_run_at=due,revision=revision+1 WHERE id=_id RETURNING * INTO job;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
    VALUES(actor,_tenant,'tenant','report.schedule.'||_decision,'fvi_report_schedules',_id::text,jsonb_build_object('revision',job.revision,'design_version',job.design_version));
  RETURN to_jsonb(job);
END $function$
;

CREATE OR REPLACE FUNCTION public.fvi_manage_report_schedule(_tenant uuid, _id uuid, _revision integer, _action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE job public.fvi_report_schedules;
BEGIN
  IF NOT private.fvi_report_admin(auth.uid(),_tenant) THEN RAISE EXCEPTION 'Active tenant administrator required' USING ERRCODE='42501'; END IF;
  SELECT * INTO job FROM public.fvi_report_schedules WHERE id=_id AND tenant_id=_tenant FOR UPDATE;
  IF NOT FOUND OR job.revision<>_revision OR _action NOT IN ('pause','request_resume') OR _action IS NULL
    OR (_action='pause' AND job.state<>'approved') OR (_action='request_resume' AND job.state<>'paused') THEN RAISE EXCEPTION 'Schedule changed or transition unavailable' USING ERRCODE='40001'; END IF;
  IF _action='request_resume' AND job.created_by<>auth.uid() THEN RAISE EXCEPTION 'Original maker must request resume' USING ERRCODE='42501'; END IF;
  UPDATE public.fvi_report_schedules SET state=CASE WHEN _action='pause' THEN 'paused' ELSE 'pending' END,revision=revision+1,
    approved_by=CASE WHEN _action='pause' THEN approved_by ELSE NULL END,approved_at=CASE WHEN _action='pause' THEN approved_at ELSE NULL END,
    next_run_at=NULL WHERE id=_id RETURNING * INTO job;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
    VALUES(auth.uid(),_tenant,'tenant','report.schedule.'||_action,'fvi_report_schedules',_id::text,jsonb_build_object('revision',job.revision));
  RETURN to_jsonb(job);
END $function$
;

CREATE OR REPLACE FUNCTION public.fvi_generate_saved_report(_tenant uuid, _design uuid, _version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE spec jsonb;
BEGIN
  SELECT v.spec INTO spec FROM public.fvi_report_design_versions v WHERE v.tenant_id=_tenant AND v.design_id=_design AND v.version=_version;
  IF NOT FOUND THEN RAISE EXCEPTION 'Report version unavailable' USING ERRCODE='42501'; END IF;
  RETURN private.fvi_report_snapshot(auth.uid(),_tenant,spec);
END $function$
;

CREATE OR REPLACE FUNCTION public.fvi_list_report_library(_tenant uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
BEGIN
  IF NOT private.fvi_report_admin(auth.uid(),_tenant) THEN RAISE EXCEPTION 'Active tenant administrator required to manage saved reports' USING ERRCODE='42501'; END IF;
  RETURN jsonb_build_object('definitions',coalesce((SELECT jsonb_agg(to_jsonb(d)||jsonb_build_object('spec',v.spec) ORDER BY d.name,d.id)
    FROM public.fvi_report_designs d JOIN public.fvi_report_design_versions v ON v.design_id=d.id AND v.version=d.current_version WHERE d.tenant_id=_tenant),'[]'),
    'schedules',coalesce((SELECT jsonb_agg(to_jsonb(s) ORDER BY s.created_at DESC,s.id) FROM public.fvi_report_schedules s WHERE s.tenant_id=_tenant),'[]'),
    'runs',coalesce((SELECT jsonb_agg(to_jsonb(r)-'result' ORDER BY r.generated_at DESC,r.id) FROM (SELECT * FROM public.fvi_report_schedule_runs WHERE tenant_id=_tenant ORDER BY generated_at DESC,id LIMIT 100) r),'[]'),
    'run_page_size',100,'run_pagination','latest 100; older runs remain retained','actor_id',auth.uid(),'delivery','in_app');
END $function$
;

CREATE OR REPLACE FUNCTION public.fvi_get_report_schedule_run(_tenant uuid, _id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE r public.fvi_report_schedule_runs; spec jsonb; ids uuid[]; snapshot_ids uuid[];
BEGIN
  SELECT * INTO r FROM public.fvi_report_schedule_runs WHERE id=_id AND tenant_id=_tenant;
  IF NOT FOUND THEN RAISE EXCEPTION 'Report run unavailable' USING ERRCODE='42501'; END IF;
  SELECT v.spec INTO spec FROM public.fvi_report_design_versions v WHERE v.design_id=r.design_id AND v.version=r.design_version AND v.tenant_id=_tenant;
  ids:=private.fvi_report_scope(auth.uid(),_tenant,spec);
  IF r.state<>'completed' THEN RAISE EXCEPTION 'Report run has no completed downloadable artifact' USING ERRCODE='55000'; END IF;
  SELECT coalesce(array_agg(v::uuid),ARRAY[]::uuid[]) INTO snapshot_ids FROM jsonb_array_elements_text(r.result->'reconciliation_ids') v;
  IF NOT snapshot_ids <@ ids THEN RAISE EXCEPTION 'Report snapshot no longer lies in current authorized scope' USING ERRCODE='42501'; END IF;
  RETURN jsonb_build_object('run_id',r.id,'design_id',r.design_id,'version',r.design_version,'spec',spec,'snapshot',r.result,'due_at',r.due_at);
END $function$
;

CREATE OR REPLACE FUNCTION public.fvi_process_report_schedule_tick(_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE job public.fvi_report_schedules; design jsonb; ids uuid[]; checker_ids uuid[]; output jsonb; run_id uuid; code text; run_state text; total integer:=0;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role'
    AND NOT (auth.role() IS NULL AND auth.uid() IS NULL AND session_user=current_user) THEN
    RAISE EXCEPTION 'Trusted report scheduler service or database-owned cron required' USING ERRCODE='42501'; END IF;
  IF _limit IS NULL OR _limit NOT BETWEEN 1 AND 20 THEN RAISE EXCEPTION 'Invalid tick limit' USING ERRCODE='22023'; END IF;
  FOR job IN SELECT s.* FROM public.fvi_report_schedules s WHERE s.state='approved' AND s.next_run_at<=clock_timestamp()
    ORDER BY s.next_run_at,s.id FOR UPDATE SKIP LOCKED LIMIT _limit LOOP
    SELECT spec INTO design FROM public.fvi_report_design_versions WHERE design_id=job.design_id AND version=job.design_version AND tenant_id=job.tenant_id;
    output:=NULL;code:=NULL;run_state:='completed';
    BEGIN
      IF job.approved_by=job.created_by OR NOT private.fvi_report_admin(job.approved_by,job.tenant_id) THEN RAISE EXCEPTION 'Current independent approval unavailable' USING ERRCODE='42501'; END IF;
      ids:=private.fvi_report_scope(job.created_by,job.tenant_id,design);checker_ids:=private.fvi_report_scope(job.approved_by,job.tenant_id,design);
      IF NOT ids <@ checker_ids THEN RAISE EXCEPTION 'Checker report scope changed' USING ERRCODE='42501'; END IF;
      output:=private.fvi_report_snapshot(job.created_by,job.tenant_id,design);
    EXCEPTION WHEN OTHERS THEN
      code:=SQLSTATE;run_state:=CASE WHEN code='42501' THEN 'blocked' ELSE 'failed' END;
    END;
    INSERT INTO public.fvi_report_schedule_runs(schedule_id,tenant_id,design_id,design_version,due_at,state,result,error_code)
      VALUES(job.id,job.tenant_id,job.design_id,job.design_version,job.next_run_at,run_state,output,code)
      ON CONFLICT(schedule_id,due_at) DO NOTHING RETURNING id INTO run_id;
    IF run_id IS NOT NULL THEN
      INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
        VALUES(NULL,job.tenant_id,'tenant','report.schedule.execute','fvi_report_schedule_runs',run_id::text,
          jsonb_build_object('schedule_id',job.id,'due_at',job.next_run_at,'state',run_state,'execution_identity','trusted report scheduler','maker_id',job.created_by,'checker_id',job.approved_by));
      total:=total+1;
    END IF;
    IF run_state<>'completed' THEN
      UPDATE public.fvi_report_schedules SET state='paused',next_run_at=NULL,revision=revision+1 WHERE id=job.id;
    ELSIF job.schedule_spec->>'kind'='once' THEN
      UPDATE public.fvi_report_schedules SET state='completed',next_run_at=NULL,revision=revision+1 WHERE id=job.id;
    ELSE
      UPDATE public.fvi_report_schedules SET next_run_at=private.fvi_report_next_due(job.schedule_spec,job.next_run_at),revision=revision+1 WHERE id=job.id;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('processed',total,'delivery','in_app','emails_sent',0);
END $function$
;

CREATE OR REPLACE FUNCTION public.get_reference_table_view_summary(_tenant_id uuid, _table_ids uuid[])
 RETURNS TABLE(resource_type text, resource_id uuid, public_id text, access_state text, business_unit_names text[], business_unit_count integer, user_group_names text[], user_group_count integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE
  v_actor uuid := auth.uid(); v_role text; v_ids uuid[]; v_id uuid;
  v_root public.reference_data_tables%ROWTYPE; v_registry uuid;
  v_owners text[]; v_groups text[]; v_has_owners boolean;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'reference');

  IF v_actor IS NULL OR auth.role() IS DISTINCT FROM 'authenticated'
    OR current_setting('role', true) IS DISTINCT FROM 'authenticated' THEN
    RAISE EXCEPTION 'Reference metadata requires an authenticated caller' USING ERRCODE = '42501';
  END IF;
  IF _tenant_id IS NULL OR _table_ids IS NULL OR cardinality(_table_ids) NOT BETWEEN 1 AND 100
    OR array_ndims(_table_ids) <> 1 OR array_position(_table_ids, NULL) IS NOT NULL THEN
    RAISE EXCEPTION 'Reference metadata requires a tenant and 1 to 100 table IDs' USING ERRCODE = '22023';
  END IF;
  SELECT tm.role::text INTO v_role FROM public.tenant_members tm
    WHERE tm.tenant_id = _tenant_id AND tm.user_id = v_actor AND tm.active;
  IF v_role IS NULL THEN
    RAISE EXCEPTION 'Reference metadata is not authorized' USING ERRCODE = '42501';
  END IF;
  SELECT array_agg(DISTINCT x ORDER BY x) INTO v_ids FROM unnest(_table_ids) AS x;
  FOREACH v_id IN ARRAY v_ids LOOP
    SELECT * INTO v_root FROM public.reference_data_tables r WHERE r.id = v_id AND r.tenant_id = _tenant_id;
    IF NOT FOUND OR public.reference_scope_allows(v_id, 'view') IS NOT TRUE THEN CONTINUE; END IF;
    v_registry := NULL; v_owners := ARRAY[]::text[]; v_groups := ARRAY[]::text[];
    SELECT r.id INTO v_registry FROM public.data_resource_registry r
      WHERE r.tenant_id = _tenant_id AND r.resource_type = 'reference_table' AND r.reference_table_id = v_id;
    SELECT EXISTS (SELECT 1 FROM public.data_resource_registry_owner_bu o
      WHERE o.tenant_id = _tenant_id AND o.registry_id = v_registry) INTO v_has_owners;
    IF v_role = 'tenant_admin' OR v_root.access_mode = 'legacy_passthrough' THEN
      -- Legacy root read is an existing active-member contract. Return only
      -- declared metadata for that root; it does not grant BU/group admin access.
      SELECT coalesce(array_agg(DISTINCT b.name ORDER BY b.name), ARRAY[]::text[]) INTO v_owners
        FROM public.data_resource_registry_owner_bu o JOIN public.business_units b
          ON b.id = o.bu_id AND b.tenant_id = o.tenant_id AND NOT b.is_archived
        WHERE o.tenant_id = _tenant_id AND o.registry_id = v_registry;
      SELECT coalesce(array_agg(DISTINCT g.name ORDER BY g.name), ARRAY[]::text[]) INTO v_groups
        FROM public.data_resource_registry_grants x JOIN public.tenant_groups g
          ON g.id = x.principal_group_id AND g.tenant_id = x.tenant_id
        JOIN public.data_resource_registry_owner_bu o
          ON o.tenant_id = x.tenant_id AND o.registry_id = x.registry_id AND o.bu_id = x.bu_id
        JOIN public.business_units b ON b.id = o.bu_id AND b.tenant_id = o.tenant_id AND NOT b.is_archived
        WHERE x.tenant_id = _tenant_id AND x.registry_id = v_registry AND x.principal_type = 'group'
          AND (v_role = 'tenant_admin' OR x.action = 'view');
    ELSE
      -- Mapped ordinary readers see only qualifying current view paths. Keep
      -- the captured direct/group/inherited-BU predicate, including active BUs.
      WITH qualifying AS (
        SELECT g.bu_id, g.principal_type, g.principal_group_id
        FROM public.data_resource_registry_grants g
        JOIN public.data_resource_registry_owner_bu o
          ON o.tenant_id = g.tenant_id AND o.registry_id = g.registry_id AND o.bu_id = g.bu_id
        JOIN public.business_units target ON target.id = o.bu_id AND target.tenant_id = o.tenant_id AND NOT target.is_archived
        WHERE g.tenant_id = _tenant_id AND g.registry_id = v_registry AND g.action = 'view' AND (
          (g.principal_type = 'user' AND g.principal_user_id = v_actor AND EXISTS (
            SELECT 1 FROM public.bu_user_assignments ua JOIN public.business_units assigned
              ON assigned.id = ua.bu_id AND assigned.tenant_id = ua.tenant_id AND NOT assigned.is_archived
            WHERE ua.tenant_id = _tenant_id AND ua.user_id = v_actor
              AND (assigned.id = target.id OR (ua.inherit_descendants AND target.path <@ assigned.path))))
          OR (g.principal_type = 'group' AND EXISTS (
            SELECT 1 FROM public.tenant_group_members gm JOIN public.tenant_groups tg
              ON tg.id = gm.group_id AND tg.tenant_id = _tenant_id
            WHERE gm.group_id = g.principal_group_id AND gm.user_id = v_actor)
            AND EXISTS (SELECT 1 FROM public.bu_group_assignments ga JOIN public.business_units assigned
              ON assigned.id = ga.bu_id AND assigned.tenant_id = ga.tenant_id AND NOT assigned.is_archived
              WHERE ga.tenant_id = _tenant_id AND ga.group_id = g.principal_group_id
                AND (assigned.id = target.id OR (ga.inherit_descendants AND target.path <@ assigned.path))))
        )
      ) SELECT
        coalesce((SELECT array_agg(DISTINCT b.name ORDER BY b.name) FROM qualifying q JOIN public.business_units b
          ON b.id = q.bu_id AND b.tenant_id = _tenant_id), ARRAY[]::text[]),
        coalesce((SELECT array_agg(DISTINCT g.name ORDER BY g.name) FROM qualifying q JOIN public.tenant_groups g
          ON g.id = q.principal_group_id AND g.tenant_id = _tenant_id WHERE q.principal_type = 'group'), ARRAY[]::text[])
        INTO v_owners, v_groups;
    END IF;
    resource_type := 'reference_table'; resource_id := v_id; public_id := v_root.public_id;
    access_state := CASE WHEN v_has_owners THEN 'mapped' ELSE 'unmapped' END;
    business_unit_names := v_owners; business_unit_count := cardinality(v_owners);
    user_group_names := v_groups; user_group_count := cardinality(v_groups);
    RETURN NEXT;
  END LOOP;
END $function$
;

CREATE OR REPLACE FUNCTION public.get_workspace_dashboard_team_metrics(_tenant_id uuid, _window_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_scope boolean;
  v_ids uuid[];
  v_role text;
  v_asof timestamptz := statement_timestamp();
  v_since timestamptz;
  v_previous timestamptz;
  v_result jsonb;
BEGIN
  IF v_actor IS NULL OR _tenant_id IS NULL THEN
    RAISE EXCEPTION 'Team access unavailable' USING ERRCODE='42501';
  END IF;
  IF _window_days IS NULL OR _window_days NOT BETWEEN 7 AND 180 THEN
    RAISE EXCEPTION 'Invalid dashboard window' USING ERRCODE='22023';
  END IF;
  SELECT role::text INTO v_role FROM public.tenant_members
    WHERE tenant_id=_tenant_id AND user_id=v_actor AND active=true;
  IF NOT FOUND THEN RAISE EXCEPTION 'Active membership required' USING ERRCODE='42501'; END IF;
  -- The existing helper is the single authority for legitimate team scope.
  SELECT team_scope_available,definition_ids INTO v_scope,v_ids
    FROM public.get_workspace_dashboard_team_scope(_tenant_id);
  IF v_scope IS DISTINCT FROM true OR v_ids IS NULL THEN
    RAISE EXCEPTION 'Mapped team access required' USING ERRCODE='42501';
  END IF;
  -- Mirror the mapped definition/run SELECT policies once per definition,
  -- including their restrictive gate. Refuse mismatches instead of partials.
  IF EXISTS (SELECT 1 FROM unnest(v_ids) AS scope_id(id)
    LEFT JOIN public.recon_definitions d ON d.id=scope_id.id AND d.tenant_id=_tenant_id
    WHERE d.id IS NULL OR d.access_mode IS DISTINCT FROM 'mapped_exact'
      OR private.recon_authoritative_access_decision(d.id,'read') IS DISTINCT FROM true
      OR private.recon_run_effective_read_allowed(d.id,_tenant_id) IS DISTINCT FROM true) THEN
    RAISE EXCEPTION 'Current team read access could not be verified' USING ERRCODE='42501';
  END IF;
  v_since := (date_trunc('day',v_asof AT TIME ZONE 'UTC') - (_window_days-1)*interval '1 day') AT TIME ZONE 'UTC';
  v_previous := v_since-_window_days*interval '1 day';

  WITH definitions AS MATERIALIZED (
    SELECT d.id,d.name,d.recon_type,d.sides FROM public.recon_definitions d
    WHERE d.tenant_id=_tenant_id AND d.id=ANY(v_ids)
  ), runs AS MATERIALIZED (
    SELECT r.* FROM public.recon_runs r
    JOIN definitions d ON d.id=r.definition_id
    WHERE r.tenant_id=_tenant_id AND r.started_at>=v_previous AND r.started_at<=v_asof
  ), record_values AS (
    SELECT r.*,
      CASE WHEN jsonb_typeof(r.stats->'matched_records')='number'
        THEN (r.stats->>'matched_records')::numeric END AS matched_records,
      coalesce(r.total_rows::numeric,CASE WHEN jsonb_typeof(r.stats->'total_rows')='number'
        THEN (r.stats->>'total_rows')::numeric END) AS record_total
    FROM runs r
  ), records AS MATERIALIZED (
    SELECT r.*,coalesce(matched_records>=0 AND record_total>0 AND matched_records<=record_total
      AND matched_records<=9007199254740991 AND record_total<=9007199254740991,false) AS valid_counts
    FROM record_values r
  ), periods AS (
    SELECT (started_at>=v_since) AS current_period,count(*) AS run_count,
      count(*) FILTER(WHERE status='failed') AS failures,
      count(*) FILTER(WHERE status='completed') AS completed,
      count(*) FILTER(WHERE status IN ('completed','failed')) AS finalized,
      count(*) FILTER(WHERE status='completed' AND NOT valid_counts) AS missing,
      coalesce(sum(matched_records) FILTER(WHERE status='completed' AND valid_counts),0) AS matched,
      coalesce(sum(record_total) FILTER(WHERE status='completed' AND valid_counts),0) AS total,
      coalesce(sum(exception_count),0) AS exception_items
    FROM records GROUP BY (started_at>=v_since)
  ), current_totals AS (
    SELECT coalesce(p.run_count,0) AS run_count,coalesce(p.failures,0) AS failures,
      coalesce(p.completed,0) AS completed,coalesce(p.finalized,0) AS finalized,
      coalesce(p.missing,0) AS missing,coalesce(p.matched,0) AS matched,
      coalesce(p.total,0) AS total,coalesce(p.exception_items,0) AS exception_items,
      CASE WHEN p.completed>0 AND p.missing=0 AND p.total>0 THEN round(100*p.matched/p.total,1) END AS rate
    FROM (VALUES(1)) AS base(n) LEFT JOIN periods p ON p.current_period=true
  ), previous_totals AS (
    SELECT coalesce(p.run_count,0) AS run_count,
      CASE WHEN p.completed>0 AND p.missing=0 AND p.total>0 THEN round(100*p.matched/p.total,1) END AS rate
    FROM (VALUES(1)) AS base(n) LEFT JOIN periods p ON p.current_period=false
  ), days AS (
    SELECT generate_series(v_since AT TIME ZONE 'UTC', v_asof AT TIME ZONE 'UTC',interval '1 day')::date AS day
  ), daily_runs AS (
    SELECT (started_at AT TIME ZONE 'UTC')::date AS day,count(*) AS runs,
      count(*) FILTER(WHERE status='failed') AS failed,count(*) FILTER(WHERE status='completed') AS completed,
      count(*) FILTER(WHERE status='completed' AND NOT valid_counts) AS missing,
      coalesce(sum(matched_records) FILTER(WHERE status='completed' AND valid_counts),0) AS matched,
      coalesce(sum(record_total) FILTER(WHERE status='completed' AND valid_counts),0) AS total
    FROM records WHERE started_at>=v_since GROUP BY 1
  ), exceptions AS MATERIALIZED (
    -- Tenant equality on BOTH relations prevents malformed cross-tenant edges.
    -- Do not restrict runs to the chart window: old open/resolved cases count.
    SELECT e.severity,e.lifecycle_state,e.status,e.created_at,e.resolved_at,r.definition_id
    FROM definitions d JOIN public.recon_runs r ON r.definition_id=d.id AND r.tenant_id=_tenant_id
    JOIN public.recon_exceptions e ON e.run_id=r.id AND e.tenant_id=_tenant_id
  ), open_exceptions AS MATERIALIZED (
    SELECT * FROM exceptions WHERE status='open'
  ), opened AS (
    SELECT (created_at AT TIME ZONE 'UTC')::date AS day,count(*) AS count
    FROM exceptions WHERE created_at>=v_since AND created_at<=v_asof GROUP BY 1
  ), resolved AS (
    SELECT (resolved_at AT TIME ZONE 'UTC')::date AS day,count(*) AS count
    FROM exceptions WHERE resolved_at>=v_since AND resolved_at<=v_asof GROUP BY 1
  ), mttr AS (
    SELECT round(avg(extract(epoch FROM resolved_at-created_at))/3600,1) AS hours
    FROM exceptions WHERE resolved_at>=v_since AND resolved_at<=v_asof AND resolved_at>=created_at
  ), source_ids AS (
    SELECT DISTINCT side->>'data_source_id' AS id FROM definitions d
    CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(d.sides)='array' THEN d.sides ELSE '[]'::jsonb END) side
  ), sources AS MATERIALIZED (
    -- Mirror the current restrictive typed-resource policy as well as membership;
    -- use only source IDs actually referenced by the authorized definitions.
    SELECT s.id,coalesce(s.source_type,'unknown') AS source_type FROM public.workspace_data_sources s
    JOIN source_ids i ON s.id::text=i.id WHERE s.tenant_id=_tenant_id
      AND private.registered_typed_resource_allows(v_actor,_tenant_id,'data_source',s.id,'view')
  )
  SELECT jsonb_build_object(
    'scope','team','scope_access',jsonb_build_object('my',true,'team',true,'tenant',v_role='tenant_admin'),
    'scope_empty',cardinality(v_ids)=0,
    'provenance','Current readable reconciliations mapped through your effective same-tenant BU/group assignments. Totals include all scoped rows; detail previews show the latest eight runs.',
    'window_days',_window_days,'as_of',to_char(v_asof AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'availability',jsonb_build_object('definitions',true,'data_sources',true,'schedules',true,'tickets',false,'ai_usage',false),
    'kpis',jsonb_build_object(
      'reconciliations',jsonb_build_object('value',(SELECT count(*) FROM definitions),'delta',null),
      'match_rate',jsonb_build_object('value',ct.rate,'delta',ct.rate-pt.rate),
      'runs',jsonb_build_object('value',ct.run_count,'delta',ct.run_count-pt.run_count),
      'open_exceptions',jsonb_build_object('value',(SELECT count(*) FROM open_exceptions),'delta',0),
      'mttr_hours',jsonb_build_object('value',(SELECT hours FROM mttr),'delta',0),
      'open_tickets',jsonb_build_object('value',null,'delta',0),
      'success_rate',jsonb_build_object('value',CASE WHEN ct.finalized>0 THEN round(100.0*ct.completed/ct.finalized,1) END,'delta',CASE WHEN ct.finalized>0 THEN 0 END),
      'data_sources',jsonb_build_object('value',(SELECT count(*) FROM sources),'delta',0),
      'schedules_active',jsonb_build_object('value',(SELECT count(*) FROM public.recon_schedules s WHERE s.tenant_id=_tenant_id AND s.definition_id=ANY(v_ids) AND s.enabled),'delta',0)),
    'throughput',(SELECT jsonb_agg(jsonb_build_object('date',d.day,'runs',coalesce(r.runs,0),'failed',coalesce(r.failed,0),'completed',coalesce(r.completed,0),
      'metricsComplete',coalesce(r.missing,0)=0,'matched',CASE WHEN coalesce(r.missing,0)=0 THEN coalesce(r.matched,0) END,
      'unmatched',CASE WHEN coalesce(r.missing,0)=0 THEN coalesce(r.total-r.matched,0) END,
      'rate',CASE WHEN r.completed>0 AND r.missing=0 AND r.total>0 THEN round(100*r.matched/r.total,1) END) ORDER BY d.day) FROM days d LEFT JOIN daily_runs r ON r.day=d.day),
    'exceptions_flow',(SELECT jsonb_agg(jsonb_build_object('date',d.day,'opened',coalesce(o.count,0),'resolved',coalesce(r.count,0)) ORDER BY d.day) FROM days d LEFT JOIN opened o ON o.day=d.day LEFT JOIN resolved r ON r.day=d.day),
    'severity',(SELECT jsonb_agg(jsonb_build_object('name',v.name,'value',(SELECT count(*) FROM open_exceptions e WHERE e.severity=v.name))) FROM (VALUES('critical'),('high'),('medium'),('low')) v(name)),
    'lifecycle',coalesce((SELECT jsonb_agg(jsonb_build_object('name',name,'value',n) ORDER BY name) FROM (SELECT coalesce(lifecycle_state,'new') AS name,count(*) AS n FROM open_exceptions GROUP BY 1) x),'[]'::jsonb),
    'ageing',(SELECT jsonb_agg(jsonb_build_object('name',v.name,'value',(SELECT count(*) FROM open_exceptions e WHERE extract(epoch FROM v_asof-e.created_at)/86400>=v.lo AND (v.hi IS NULL OR extract(epoch FROM v_asof-e.created_at)/86400<v.hi)))) FROM (VALUES('<1d',-1e100::numeric,1::numeric),('1-3d',1,3),('3-7d',3,7),('7-30d',7,30),('>30d',30,null)) v(name,lo,hi)),
    'top_recons',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.open DESC,x.id) FROM (SELECT d.id,d.name,coalesce(d.recon_type,'—') AS type,count(*) AS open FROM open_exceptions e JOIN definitions d ON d.id=e.definition_id GROUP BY d.id,d.name,d.recon_type ORDER BY open DESC,d.id LIMIT 6) x),'[]'::jsonb),
    'ds_mix',coalesce((SELECT jsonb_agg(jsonb_build_object('name',source_type,'value',n) ORDER BY source_type) FROM (SELECT source_type,count(*) AS n FROM sources GROUP BY 1) x),'[]'::jsonb),
    'tickets_by_priority','[]'::jsonb,
    'ai',jsonb_build_object('tokens_in',0,'tokens_out',0,'cost_usd',0,'series',(SELECT jsonb_agg(jsonb_build_object('date',day,'cost',0,'tokens',0) ORDER BY day) FROM days)),
    'recent_runs',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.started_at DESC,x.id) FROM (
      SELECT r.id,r.definition_id,r.status,r.started_at,r.completed_at,r.matched_count,r.exception_count,r.total_rows,
        d.name AS recon_name,(r.status='completed' AND r.valid_counts) AS record_metrics_available,
        CASE WHEN r.status='completed' AND r.valid_counts THEN r.matched_records END AS matched_records,
        CASE WHEN r.status='completed' AND r.valid_counts THEN r.record_total END AS record_total,
        CASE WHEN r.status='completed' AND r.valid_counts THEN round(100*r.matched_records/r.record_total,1) END AS record_match_rate
      FROM records r JOIN definitions d ON d.id=r.definition_id WHERE r.started_at>=v_since ORDER BY r.started_at DESC,r.id LIMIT 8) x),'[]'::jsonb),
    'totals',jsonb_build_object('matched_records',ct.matched,'total_rows',ct.total,'completed_runs',ct.completed,'runs_missing_record_counts',ct.missing,
      'exception_items',ct.exception_items,'record_metrics_available',ct.completed>0 AND ct.missing=0,'failures',ct.failures)
  ) INTO v_result FROM current_totals ct CROSS JOIN previous_totals pt;
  RETURN v_result;
END
$function$
;

CREATE OR REPLACE FUNCTION public.dpd_save_setup(_tenant_id uuid, _setup_id uuid, _expected_draft_version integer, _payload jsonb, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,true);v private.dpd_versions%ROWTYPE;head private.dpd_versions%ROWTYPE;f jsonb;file private.dpd_original_intents%ROWTYPE;schema private.dpd_schema_receipts%ROWTYPE;owners uuid[];groups uuid[];scope jsonb;
BEGIN
 PERFORM private.dpd_request_actor(_tenant_id,_setup_id,'setup.save',_request_context_id);
 PERFORM private.dpd_assert_transform_configuration(_payload);
 IF _request_key IS NULL OR jsonb_typeof(_payload) IS DISTINCT FROM 'object' OR _payload->>'on_failure' IS DISTINCT FROM 'block' OR jsonb_typeof(_payload->'feeds') IS DISTINCT FROM 'array' OR jsonb_array_length(_payload->'feeds') NOT BETWEEN 1 AND 50 OR jsonb_typeof(_payload->'steps') IS DISTINCT FROM 'array' OR jsonb_typeof(_payload->'dq_rules') IS DISTINCT FROM 'array' OR jsonb_typeof(_payload->'business_fields') IS DISTINCT FROM 'array' OR jsonb_typeof(_payload->'required_fields') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'dpd.complete_current_configuration_required' USING ERRCODE='22023';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements((_payload->'steps')||(SELECT coalesce(jsonb_agg(step.value),'[]') FROM jsonb_array_elements(_payload->'feeds') AS feed(value) CROSS JOIN LATERAL jsonb_array_elements(coalesce(feed.value->'steps','[]')) AS step(value))) AS st(value) WHERE st.value->>'kind' IN('sort','dedupe','filter','filter_expr')) OR _payload ? 'approved_exclusions' THEN RAISE EXCEPTION 'dpdi.unsupported_transform_or_exclusion_choose_supported_before_save' USING ERRCODE='22023';END IF;
 PERFORM 1 FROM private.dpd_setups WHERE id=s.id FOR UPDATE;SELECT * INTO v FROM private.dpd_versions WHERE setup_id=s.id AND created_by=auth.uid() AND request_key=_request_key;
 IF FOUND THEN IF v.payload IS DISTINCT FROM _payload OR v.version IS DISTINCT FROM _expected_draft_version+1 THEN RAISE EXCEPTION 'dpd.configuration_request_conflict' USING ERRCODE='PT409';END IF;RETURN private.dpd_setup_result(_tenant_id,s.id,auth.uid(),true,v.version);END IF;
 SELECT * INTO head FROM private.dpd_versions WHERE setup_id=s.id ORDER BY version DESC LIMIT 1;IF head.version<>_expected_draft_version THEN RAISE EXCEPTION 'dpd.stale_draft_configuration' USING ERRCODE='PT409';END IF;
 PERFORM private.dpd_validate_confirmed_mapping(_tenant_id,s.id,head.version+1,_payload->'confirmed_mapping');
 FOR f IN SELECT value FROM jsonb_array_elements(_payload->'feeds') LOOP
  IF f->'original_ref' IS NULL THEN CONTINUE;END IF;
 SELECT * INTO file FROM private.dpd_original_intents WHERE id=(f->'original_ref'->>'file_id')::uuid AND setup_id=s.id AND feed_key=f->>'key';SELECT * INTO schema FROM private.dpd_schema_receipts WHERE file_id=file.id;
  IF file.id IS NULL OR schema.file_id IS NULL OR NOT EXISTS(SELECT 1 FROM private.dpd_original_receipts WHERE file_id=file.id) OR schema.schema_sha256 IS DISTINCT FROM f->'original_ref'->>'schema_sha256' OR private.dpd_original_viewable(file.id) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.exact_received_original_schema_pin_required' USING ERRCODE='PT409';END IF;
 END LOOP;
 owners:=head.owner_bu_ids;groups:=head.group_ids;
 IF _payload ? '_draft_scope' THEN
  PERFORM private.dps_admin(_tenant_id);scope:=_payload->'_draft_scope';
  IF jsonb_typeof(scope) IS DISTINCT FROM 'object' OR scope-ARRAY['owner_bu_ids','group_ids']<>'{}'::jsonb OR jsonb_typeof(scope->'owner_bu_ids') IS DISTINCT FROM 'array' OR jsonb_typeof(scope->'group_ids') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'dpd.explicit_declared_scope_required' USING ERRCODE='22023';END IF;
  owners:=private.dps_ids(ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(scope->'owner_bu_ids')),100,true);groups:=private.dps_ids(ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(scope->'group_ids')),100,false);
  PERFORM private.dps_selections(_tenant_id,owners,groups);
 END IF;
 INSERT INTO private.dpd_versions(setup_id,version,request_key,created_by,payload,payload_sha256,owner_bu_ids,group_ids) VALUES(s.id,head.version+1,_request_key,auth.uid(),_payload,private.dpw_hash(_payload),owners,groups);
 PERFORM private.dpd_event(_tenant_id,s.id,auth.uid(),'configuration.versioned',s.id,jsonb_build_object('draft_version',head.version+1,'configuration_sha256',private.dpw_hash(_payload),'original_refs',_payload->'original_refs'));RETURN private.dpd_setup_result(_tenant_id,s.id,auth.uid(),false);
END $function$
;

CREATE OR REPLACE FUNCTION public.dpd_get_draft_audit(_tenant_id uuid, _setup_id uuid, _page integer, _page_size integer, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,false);events jsonb;amount bigint;skip integer:=private.dpw_page(_page,_page_size);
BEGIN
 PERFORM private.dpd_request_actor(_tenant_id,_setup_id,'audit.read',_request_context_id); SELECT count(*) INTO amount FROM private.dpd_events WHERE setup_id=s.id;SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.created_at,q.id),'[]') INTO events FROM(SELECT * FROM private.dpd_events WHERE setup_id=s.id ORDER BY created_at,id OFFSET skip LIMIT _page_size) q;RETURN jsonb_build_object('actor_id',auth.uid(),'tenant_id',_tenant_id,'setup_id',s.id,'events',events,'total',amount,'page',_page,'page_size',_page_size);END $function$
;

CREATE OR REPLACE FUNCTION private.dpd_original_viewable(_file uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 SELECT EXISTS(SELECT 1 FROM private.dpd_original_intents f WHERE f.id=_file AND f.expires_at>clock_timestamp()) AND NOT EXISTS(SELECT 1 FROM private.dpd_original_tombstones t WHERE t.file_id=_file) $function$
;

CREATE OR REPLACE FUNCTION private.dpd_original_result(_actor uuid, _file uuid, _replay boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE f private.dpd_original_intents%ROWTYPE;r private.dpd_original_receipts%ROWTYPE;sc private.dpd_schema_receipts%ROWTYPE;raw private.dpd_raw_source_links%ROWTYPE;state text;parser text;
BEGIN SELECT * INTO f FROM private.dpd_original_intents WHERE id=_file;SELECT * INTO r FROM private.dpd_original_receipts WHERE file_id=f.id;SELECT * INTO sc FROM private.dpd_schema_receipts WHERE file_id=f.id;SELECT * INTO raw FROM private.dpd_raw_source_links WHERE file_id=f.id;
 state:=CASE WHEN r.file_id IS NULL THEN 'uploading' ELSE 'received' END;parser:=private.dpd_parser_state(f.id);
 RETURN jsonb_build_object('actor_id',_actor,'auth_role','authenticated','tenant_id',f.tenant_id,'setup_id',f.setup_id,'file_id',f.id,'feed_key',f.feed_key,'request_key',f.request_key,'content_sha256',f.content_sha256,'state',state,'parser_state',parser,'descriptor',f.descriptor,
 'storage_bucket',f.storage_bucket,'storage_path',f.original_path,'original_path',f.original_path,'created_by',f.created_by,'uploaded_by',f.created_by,'created_at',f.created_at,'received_at',r.received_at,'expires_at',f.expires_at,
 'verified_original_size_bytes',r.verified_size_bytes::text,'verified_original_sha256',r.verified_original_sha256,'storage_object_id',r.storage_object_id,
 'raw_row_count',sc.raw_row_count::text,'header_fields',CASE WHEN private.dpd_original_viewable(f.id) THEN sc.schema_manifest->'header_fields' ELSE NULL END,
 'sheet_inventory',CASE WHEN private.dpd_original_viewable(f.id) THEN coalesce(sc.schema_manifest->'sheet_inventory',r.sheet_inventory,'[]'::jsonb) ELSE '[]'::jsonb END,
 'retention',f.retention_policy||jsonb_build_object('expires_at',f.expires_at,'available',private.dpd_original_viewable(f.id),'legal_hold',private.dpd_original_has_hold(f.id),'tombstoned',EXISTS(SELECT 1 FROM private.dpd_original_tombstones WHERE file_id=f.id)),
 'data_source_id',raw.data_source_id,'upload_id',NULL,'request_replay',_replay,'is_new',NOT _replay,'original_reupload_required',false,'publish_allowed',false);
END $function$
;

CREATE OR REPLACE FUNCTION public.dpd_authorize_draft_original_intake(_tenant_id uuid, _setup_id uuid, _feed_key text, _operation text, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,_operation='intake');v private.dpd_versions%ROWTYPE;actor uuid:=auth.uid();policy jsonb;
BEGIN
 PERFORM private.dpd_request_actor(_tenant_id,_setup_id,'original.authorize',_request_context_id);
 IF _operation NOT IN('intake','original.read') OR length(coalesce(_feed_key,'')) NOT BETWEEN 1 AND 120 OR _feed_key LIKE 'legacy:%' THEN RAISE EXCEPTION 'dpd.invalid_original_operation' USING ERRCODE='22023';END IF;
 IF _operation='intake' THEN PERFORM private.wfm_assert_enabled(_tenant_id,'data');IF public.user_has_permission(actor,_tenant_id,'data.source.create',NULL) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.original_source_create_denied' USING ERRCODE='42501';END IF;END IF;
 SELECT * INTO v FROM private.dpd_versions WHERE setup_id=s.id ORDER BY version DESC LIMIT 1;policy:=private.dpw_effective_attachment_policy(_tenant_id);
 RETURN jsonb_build_object('actor_id',actor,'auth_role',auth.role(),'tenant_id',_tenant_id,'setup_id',s.id,'feed_key',_feed_key,'operation',_operation,'pipeline_id',NULL,'reserved_pipeline_id',s.reserved_pipeline_id,'draft_version',v.version,'can_upload',_operation='intake','allow_empty',false,
 'storage_capability',jsonb_build_object('bucket_id','data-prep-authoring-originals','public',false,'max_original_bytes',52428800,'max_expanded_bytes',52428800,'max_parsed_bytes',52428800,'max_rows',1000000,'max_columns',500,'chunk_max_rows',1000,'chunk_max_bytes',1048576),'retention_policy',policy,'worker_budget_qualification_required',true);
END $function$
;

CREATE OR REPLACE FUNCTION public.dpd_claim_draft_original(_tenant_id uuid, _setup_id uuid, _feed_key text, _descriptor jsonb, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE admission jsonb;actor uuid:=auth.uid();f private.dpd_original_intents%ROWTYPE;policy jsonb;ctx uuid;
BEGIN
 PERFORM private.dpd_request_actor(_tenant_id,_setup_id,'original.claim',_request_context_id);
 admission:=jsonb_build_object('retention_policy',private.dpw_effective_attachment_policy(_tenant_id));
 PERFORM private.wfm_assert_enabled(_tenant_id,'data');IF public.user_has_permission(auth.uid(),_tenant_id,'data.source.create',NULL) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.original_source_create_denied' USING ERRCODE='42501';END IF;
 IF _request_key IS NULL OR jsonb_typeof(_descriptor) IS DISTINCT FROM 'object' OR coalesce(_descriptor->>'content_sha256','')!~'^[a-f0-9]{64}$' OR coalesce(_descriptor->>'size_bytes','')!~'^[1-9][0-9]*$' OR (_descriptor->>'size_bytes')::bigint NOT BETWEEN 1 AND 52428800 OR length(coalesce(_descriptor->>'filename','')) NOT BETWEEN 1 AND 255 OR (_descriptor->>'format' IN('csv','tsv','xlsx')) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.exact_original_descriptor_required' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('dpd-original:'||_setup_id::text||':'||_feed_key||':'||actor::text||':'||_request_key::text,0));SELECT * INTO f FROM private.dpd_original_intents WHERE setup_id=_setup_id AND feed_key=_feed_key AND created_by=actor AND request_key=_request_key;
 IF FOUND THEN IF f.descriptor IS DISTINCT FROM _descriptor THEN RAISE EXCEPTION 'dpd.original_request_conflict' USING ERRCODE='PT409';END IF;RETURN private.dpd_original_result(actor,f.id,true);END IF;
 policy:=admission->'retention_policy';IF coalesce((policy->>'period_days')::integer,0)<1 OR policy->>'policy_id' IS NULL OR policy->>'version' IS NULL THEN RAISE EXCEPTION 'dpd.actual_retention_policy_required' USING ERRCODE='42501';END IF;
 ctx:=_request_context_id;
 f.id:=gen_random_uuid();INSERT INTO private.dpd_original_intents(id,setup_id,tenant_id,feed_key,created_by,request_key,descriptor,descriptor_sha256,content_sha256,size_bytes,original_path,request_context_id,retention_policy,expires_at)
 VALUES(f.id,_setup_id,_tenant_id,_feed_key,actor,_request_key,_descriptor,private.dpw_hash(_descriptor),_descriptor->>'content_sha256',(_descriptor->>'size_bytes')::bigint,_tenant_id::text||'/'||_setup_id::text||'/'||f.id::text||'/original',ctx,policy,clock_timestamp()+((policy->>'period_days')::integer)*interval '1 day');
 PERFORM private.dpd_event(_tenant_id,_setup_id,actor,'original.claimed',f.id,jsonb_build_object('request_key',_request_key,'content_sha256',_descriptor->>'content_sha256','descriptor_sha256',private.dpw_hash(_descriptor),'retention_policy',policy));RETURN private.dpd_original_result(actor,f.id,false);
END $function$
;

CREATE OR REPLACE FUNCTION public.dpd_lookup_draft_original(_tenant_id uuid, _setup_id uuid, _feed_key text, _request_key uuid, _expected_descriptor jsonb, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,false);f private.dpd_original_intents%ROWTYPE;actor uuid:=auth.uid();
BEGIN
 PERFORM private.dpd_request_actor(_tenant_id,_setup_id,'original.lookup',_request_context_id); SELECT * INTO f FROM private.dpd_original_intents WHERE setup_id=s.id AND created_by=actor AND feed_key=_feed_key AND request_key=_request_key;
 IF NOT FOUND THEN RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'state','absent','result',NULL);END IF;
 IF f.descriptor IS DISTINCT FROM _expected_descriptor THEN RAISE EXCEPTION 'dpd.original_lookup_conflict' USING ERRCODE='PT409';END IF;RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'state','found','result',private.dpd_original_result(actor,f.id,true));END $function$
;

CREATE OR REPLACE FUNCTION public.dpd_confirm_draft_original(_tenant_id uuid, _setup_id uuid, _file_id uuid, _request_key uuid, _verification jsonb, _verified_subject jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_service_request_actor(_tenant_id,_setup_id,'original.confirm',(_verification->>'request_context_id')::uuid,_verified_subject);f private.dpd_original_intents%ROWTYPE;r private.dpd_original_receipts%ROWTYPE;o storage.objects%ROWTYPE;inventory jsonb:=coalesce(_verification->'sheet_inventory','[]'::jsonb);
BEGIN
 SELECT * INTO f FROM private.dpd_original_intents WHERE id=_file_id AND setup_id=_setup_id AND tenant_id=_tenant_id FOR UPDATE;
 IF NOT FOUND OR f.created_by<>actor OR f.request_key<>_request_key OR private.dpd_original_viewable(f.id) IS DISTINCT FROM true OR _verification->>'verified_original_sha256' IS DISTINCT FROM f.content_sha256 OR (_verification->>'verified_original_size_bytes')::bigint IS DISTINCT FROM f.size_bytes OR _verification->>'storage_bucket' IS DISTINCT FROM f.storage_bucket OR _verification->>'storage_path' IS DISTINCT FROM f.original_path OR _verification->>'verification_source' IS DISTINCT FROM 'main_fixed_original_download_and_hash' OR jsonb_typeof(inventory) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'dpd.actual_original_attestation_mismatch' USING ERRCODE='PT409';END IF;
 SELECT * INTO o FROM storage.objects WHERE bucket_id=f.storage_bucket AND name=f.original_path AND is_delete_marker IS NOT TRUE AND archived_at IS NULL;
 IF NOT FOUND OR (o.metadata->>'size')::bigint IS DISTINCT FROM f.size_bytes OR coalesce(o.owner_id,o.owner::text) IS DISTINCT FROM actor::text THEN RAISE EXCEPTION 'dpd.original_storage_object_unconfirmed' USING ERRCODE='PT409';END IF;
 SELECT * INTO r FROM private.dpd_original_receipts WHERE file_id=f.id;
 IF FOUND THEN IF r.verified_original_sha256<>f.content_sha256 OR r.storage_object_id<>o.id OR r.sheet_inventory IS DISTINCT FROM inventory THEN RAISE EXCEPTION 'dpd.original_receipt_conflict' USING ERRCODE='PT409';END IF;RETURN private.dpd_original_result(actor,f.id,true)||jsonb_build_object('transport_role','service_role');END IF;
 INSERT INTO private.dpd_original_receipts(file_id,setup_id,tenant_id,created_by,verified_original_sha256,verified_size_bytes,storage_object_id,sheet_inventory,verification) VALUES(f.id,_setup_id,_tenant_id,actor,f.content_sha256,f.size_bytes,o.id,inventory,_verification||jsonb_build_object('request_context_id',(_verification->>'request_context_id')::uuid));
 PERFORM private.dpd_event(_tenant_id,_setup_id,actor,'original.received',f.id,jsonb_build_object('content_sha256',f.content_sha256,'verified_size_bytes',f.size_bytes::text,'storage_object_id',o.id,'parser_state','unparsed','publish_allowed',false));RETURN private.dpd_original_result(actor,f.id,false)||jsonb_build_object('transport_role','service_role');
END $function$
;

CREATE OR REPLACE FUNCTION public.dpd_get_draft_original(_tenant_id uuid, _setup_id uuid, _file_id uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,false);BEGIN
 PERFORM private.dpd_request_actor(_tenant_id,_setup_id,'original.read',_request_context_id); IF NOT EXISTS(SELECT 1 FROM private.dpd_original_intents WHERE id=_file_id AND setup_id=s.id AND tenant_id=_tenant_id) THEN RAISE EXCEPTION 'dpd.original_scope_mismatch' USING ERRCODE='42501';END IF;RETURN private.dpd_original_result(auth.uid(),_file_id,false);END $function$
;

CREATE OR REPLACE FUNCTION private.dpd_storage_allows(_name text, _write boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE f private.dpd_original_intents%ROWTYPE;s private.dpd_setups%ROWTYPE;actor uuid;c private.dpd_request_contexts%ROWTYPE;enabled boolean;
BEGIN SELECT * INTO f FROM private.dpd_original_intents WHERE original_path=_name;IF NOT FOUND THEN RETURN false;END IF;
 s:=private.dpd_scope(f.tenant_id,f.setup_id,_write);actor:=auth.uid();
 IF f.created_by IS DISTINCT FROM actor OR NOT private.dpd_original_viewable(f.id) OR auth.role() IS DISTINCT FROM 'authenticated' OR current_setting('role',true) IS DISTINCT FROM 'authenticated' THEN RETURN false;END IF;
 -- Storage APIs cannot accept purpose RPC arguments. Require the actual current
 -- ordinary subject and a recent fixed-server authorization for this setup;
 -- never accept caller headers/GUC/IP as an attestation.
 SELECT * INTO c FROM private.dpd_request_contexts x WHERE x.tenant_id=f.tenant_id AND x.setup_id=f.setup_id AND x.actor_id=actor AND x.operation IN('original.claim','original.authorize','original.read') AND x.expires_at>clock_timestamp() AND x.verified_subject->>'exp'=auth.jwt()->>'exp' AND x.verified_subject->>'aal'=auth.jwt()->>'aal' ORDER BY x.created_at DESC,x.id DESC LIMIT 1;
 IF NOT FOUND THEN RETURN false;END IF;PERFORM private.dpd_peer_actor(f.tenant_id,c.verified_subject);
 SELECT ip_allowlist_enabled INTO enabled FROM public.tenant_security_settings WHERE tenant_id=f.tenant_id;
 IF NOT FOUND OR enabled IS NULL OR (enabled AND (c.request_ip IS NULL OR public.ip_in_tenant_allowlist(f.tenant_id,host(c.request_ip)) IS DISTINCT FROM true)) THEN RETURN false;END IF;
 RETURN NOT _write OR NOT EXISTS(SELECT 1 FROM private.dpd_original_receipts WHERE file_id=f.id);
END $function$
;

CREATE OR REPLACE FUNCTION private.dpd_parser_state(_file uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE phase text;
BEGIN
 IF EXISTS(SELECT 1 FROM private.dpd_schema_receipts WHERE file_id=_file) THEN RETURN 'ready';END IF;
 SELECT e.phase INTO phase FROM private.dpd_parser_jobs j JOIN LATERAL(SELECT x.phase,x.created_at,x.id FROM private.dpd_parser_events x WHERE x.job_id=j.id ORDER BY x.created_at DESC,x.id DESC LIMIT 1) e ON true WHERE j.file_id=_file ORDER BY j.created_at DESC,j.id DESC LIMIT 1;
 RETURN CASE WHEN phase='queued' THEN 'queued' WHEN phase='running' THEN 'parsing' WHEN phase IN('failed','cancelled') THEN 'failed' ELSE 'unparsed' END;
END $function$
;

CREATE OR REPLACE FUNCTION public.dpd_enqueue_original_parser(_tenant_id uuid, _setup_id uuid, _file_id uuid, _parser_binding jsonb, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'parser.enqueue',_request_context_id);s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,true);f private.dpd_original_intents%ROWTYPE;j private.dpd_parser_jobs%ROWTYPE;
BEGIN
 SELECT * INTO f FROM private.dpd_original_intents WHERE id=_file_id AND setup_id=s.id AND tenant_id=_tenant_id FOR UPDATE;
 IF NOT FOUND OR f.created_by<>actor OR _request_key IS NULL OR NOT EXISTS(SELECT 1 FROM private.dpd_original_receipts WHERE file_id=f.id) OR NOT private.dpd_original_viewable(f.id) OR jsonb_typeof(_parser_binding) IS DISTINCT FROM 'object' OR _parser_binding->>'original_sha256' IS DISTINCT FROM f.content_sha256 OR nullif(_parser_binding->>'parser_version','') IS NULL THEN RAISE EXCEPTION 'dpd.exact_received_original_parser_binding_required' USING ERRCODE='PT409';END IF;
 SELECT * INTO j FROM private.dpd_parser_jobs WHERE file_id=f.id AND request_key=_request_key;
 IF FOUND THEN IF j.parser_binding IS DISTINCT FROM _parser_binding THEN RAISE EXCEPTION 'dpd.parser_request_conflict' USING ERRCODE='PT409';END IF;RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'file_id',f.id,'job_id',j.id,'state',(SELECT e.phase FROM private.dpd_parser_events e WHERE e.job_id=j.id ORDER BY e.created_at DESC,e.id DESC LIMIT 1),'request_replay',true);END IF;
 IF EXISTS(SELECT 1 FROM private.dpd_parser_jobs prior CROSS JOIN LATERAL(SELECT e.phase FROM private.dpd_parser_events e WHERE e.job_id=prior.id ORDER BY e.created_at DESC,e.id DESC LIMIT 1) head WHERE prior.file_id=f.id AND head.phase IN('queued','running')) THEN RAISE EXCEPTION 'dpd.original_parser_already_queued' USING ERRCODE='PT409';END IF;
 INSERT INTO private.dpd_parser_jobs(tenant_id,setup_id,file_id,request_key,created_by,parser_binding,parser_binding_sha256) VALUES(_tenant_id,s.id,f.id,_request_key,actor,_parser_binding,private.dpw_hash(_parser_binding)) RETURNING * INTO j;
 INSERT INTO private.dpd_parser_events(job_id,actor_id,phase,progress) VALUES(j.id,actor,'queued',jsonb_build_object('parsed_rows','0','actual_count_available',false));
 PERFORM private.dpd_event(_tenant_id,s.id,actor,'original.parser.queued',j.id,jsonb_build_object('file_id',f.id,'original_sha256',f.content_sha256,'parser_binding_sha256',j.parser_binding_sha256,'publish_allowed',false));
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'file_id',f.id,'job_id',j.id,'state','queued','request_replay',false);
END $function$
;

CREATE OR REPLACE FUNCTION public.dpd_lookup_original_parser(_tenant_id uuid, _setup_id uuid, _file_id uuid, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'parser.lookup',_request_context_id);s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,false);j private.dpd_parser_jobs%ROWTYPE;e private.dpd_parser_events%ROWTYPE;
BEGIN SELECT * INTO j FROM private.dpd_parser_jobs WHERE setup_id=s.id AND file_id=_file_id AND request_key=_request_key AND created_by=actor;IF NOT FOUND THEN RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'state','absent','result',NULL);END IF;SELECT * INTO e FROM private.dpd_parser_events WHERE job_id=j.id ORDER BY created_at DESC,id DESC LIMIT 1;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'state','found','result',jsonb_build_object('job_id',j.id,'file_id',j.file_id,'parser_binding',j.parser_binding,'state',e.phase,'progress',e.progress,'lease_expires_at',e.lease_expires_at));END $function$
;

CREATE OR REPLACE FUNCTION public.dpd_claim_original_parser(_tenant_id uuid, _setup_id uuid, _job_id uuid, _claim_key uuid, _lease_seconds integer, _request_context_id uuid, _verified_subject jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_service_request_actor(_tenant_id,_setup_id,'parser.claim',_request_context_id,_verified_subject);j private.dpd_parser_jobs%ROWTYPE;e private.dpd_parser_events%ROWTYPE;until_at timestamptz;
BEGIN
 SELECT * INTO j FROM private.dpd_parser_jobs WHERE id=_job_id AND setup_id=_setup_id AND tenant_id=_tenant_id FOR UPDATE;
 IF NOT FOUND OR j.created_by<>actor OR _claim_key IS NULL OR _lease_seconds NOT BETWEEN 1 AND 60 OR NOT private.dpd_original_viewable(j.file_id) THEN RAISE EXCEPTION 'dpd.parser_current_owned_claim_required' USING ERRCODE='42501';END IF;
 SELECT * INTO e FROM private.dpd_parser_events WHERE job_id=j.id ORDER BY created_at DESC,id DESC LIMIT 1;
 IF e.phase IN('completed','failed','cancelled') OR (e.phase='running' AND e.lease_expires_at>clock_timestamp()) THEN RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'job_id',j.id,'file_id',j.file_id,'claimed',false,'state',e.phase,'claim_key',e.claim_key,'lease_expires_at',e.lease_expires_at);END IF;
 until_at:=least(clock_timestamp()+_lease_seconds*interval '1 second',to_timestamp((_verified_subject->>'exp')::double precision));INSERT INTO private.dpd_parser_events(job_id,actor_id,phase,claim_key,lease_expires_at,progress) VALUES(j.id,actor,'running',_claim_key,until_at,e.progress);
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'job_id',j.id,'file_id',j.file_id,'claimed',true,'state','running','claim_key',_claim_key,'lease_expires_at',until_at,'parser_binding',j.parser_binding,'original',private.dpd_original_result(actor,j.file_id,false));
END $function$
;

CREATE OR REPLACE FUNCTION public.dpd_record_parser_progress(_tenant_id uuid, _setup_id uuid, _job_id uuid, _claim_key uuid, _phase text, _progress jsonb, _request_context_id uuid, _verified_subject jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_service_request_actor(_tenant_id,_setup_id,'parser.progress',_request_context_id,_verified_subject);j private.dpd_parser_jobs%ROWTYPE;e private.dpd_parser_events%ROWTYPE;
BEGIN SELECT * INTO j FROM private.dpd_parser_jobs WHERE id=_job_id AND setup_id=_setup_id AND tenant_id=_tenant_id FOR UPDATE;SELECT * INTO e FROM private.dpd_parser_events WHERE job_id=j.id ORDER BY created_at DESC,id DESC LIMIT 1;
 IF j.id IS NULL OR j.created_by<>actor OR e.phase<>'running' OR e.claim_key<>_claim_key OR e.lease_expires_at<=clock_timestamp() OR _phase NOT IN('running','completed','failed','cancelled') OR jsonb_typeof(_progress) IS DISTINCT FROM 'object' OR (_phase='completed' AND NOT EXISTS(SELECT 1 FROM private.dpd_schema_receipts WHERE file_id=j.file_id)) THEN RAISE EXCEPTION 'dpd.actual_parser_claim_outcome_required' USING ERRCODE='PT409';END IF;
 IF NOT private.dpd_original_viewable(j.file_id) THEN RAISE EXCEPTION 'dpd.parser_original_expired' USING ERRCODE='42501';END IF;
 INSERT INTO private.dpd_parser_events(job_id,actor_id,phase,claim_key,lease_expires_at,progress) VALUES(j.id,actor,_phase,_claim_key,CASE WHEN _phase='running' THEN least(clock_timestamp()+interval '60 seconds',to_timestamp((_verified_subject->>'exp')::double precision)) ELSE e.lease_expires_at END,_progress) RETURNING * INTO e;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'job_id',j.id,'file_id',j.file_id,'state',_phase,'progress',_progress,'claim_key',e.claim_key,'lease_expires_at',e.lease_expires_at,'publish_allowed',false);END $function$
;

CREATE OR REPLACE FUNCTION private.dpd_assert_parser_lease(_file uuid, _actor uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF (SELECT count(*) FROM private.dpd_parser_jobs j CROSS JOIN LATERAL(SELECT e.* FROM private.dpd_parser_events e WHERE e.job_id=j.id ORDER BY e.created_at DESC,e.id DESC LIMIT 1) head WHERE j.file_id=_file AND j.created_by=_actor AND head.actor_id=_actor AND head.phase='running' AND head.lease_expires_at>clock_timestamp())<>1 THEN RAISE EXCEPTION 'dpd.current_durable_parser_lease_required' USING ERRCODE='42501';END IF;
END $function$
;

CREATE OR REPLACE FUNCTION private.mapped_recon_governance_actor(_tenant uuid, _recon uuid, _action text, _checker boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE actor uuid:=auth.uid(); m public.tenant_members%ROWTYPE; policy public.tenant_security_settings%ROWTYPE;
BEGIN
 IF actor IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR current_setting('role',true) IS DISTINCT FROM 'authenticated' THEN
  RAISE EXCEPTION 'authenticated ordinary actor required' USING ERRCODE='42501';
 END IF;
 SELECT * INTO m FROM public.tenant_members WHERE tenant_id=_tenant AND user_id=actor AND active FOR SHARE;
 IF NOT FOUND THEN PERFORM private.mapped_recon_governance_conflict('current_membership_required'); END IF;
 IF _checker AND m.role::text<>'tenant_admin' THEN PERFORM private.mapped_recon_governance_conflict('current_checker_authority_required'); END IF;
 IF NOT private.recon_authoritative_access_decision_as(actor,_recon,_action) THEN
  PERFORM private.mapped_recon_governance_conflict(CASE WHEN _checker THEN 'current_approve_authority_required' ELSE 'current_edit_authority_required' END);
 END IF;
 SELECT * INTO policy FROM public.tenant_security_settings WHERE tenant_id=_tenant FOR SHARE;
 IF FOUND AND policy.mfa_required AND auth.jwt()->>'aal' IS DISTINCT FROM 'aal2' THEN
  PERFORM private.mapped_recon_governance_conflict('mfa_assurance_required');
 END IF;
 RETURN actor;
END $function$
;

CREATE OR REPLACE FUNCTION private.mapped_recon_governance_requester_current(_tenant uuid, _parent uuid, _requester uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
BEGIN
 PERFORM 1 FROM public.tenant_members WHERE tenant_id=_tenant AND user_id=_requester AND active FOR SHARE;
 IF NOT FOUND OR NOT private.recon_authoritative_access_decision_as(_requester,_parent,'edit') THEN
  PERFORM private.mapped_recon_governance_conflict('requester_scope_revoked');
 END IF;
END $function$
;

CREATE OR REPLACE FUNCTION private.mapped_recon_governance_effective_config(_d recon_definitions)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'private'
AS $function$
 SELECT (CASE WHEN _d.staging_generated_name IS NOT NULL AND _d.name=_d.staging_generated_name
  THEN private.recon_definition_config_snapshot(_d)-'name'||jsonb_build_object('name',_d.staging_original_name)
  ELSE private.recon_definition_config_snapshot(_d) END)
$function$
;

CREATE OR REPLACE FUNCTION private.mapped_recon_governance_transition(_request uuid, _purpose text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'auth'
AS $function$
 SELECT auth.role()='authenticated' AND current_setting('role',true)='authenticated' AND EXISTS (
  SELECT 1 FROM private.mapped_recon_governance_transitions t
  WHERE t.transaction_id=txid_current() AND t.request_id=_request
   AND t.actor_id=auth.uid() AND t.purpose=_purpose)
$function$
;

CREATE OR REPLACE FUNCTION public.dpd_append_original_chunk(_tenant_id uuid, _setup_id uuid, _file_id uuid, _sheet_key text, _chunk_index integer, _start_row bigint, _rows jsonb, _request_key uuid, _verified_subject jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_service_request_actor(_tenant_id,_setup_id,'original.chunk',(_verified_subject->>'request_context_id')::uuid,_verified_subject);f private.dpd_original_intents%ROWTYPE;c private.dpd_original_chunks%ROWTYPE;expected bigint;
BEGIN
 PERFORM private.dpd_assert_parser_lease(_file_id,actor);
 SELECT * INTO f FROM private.dpd_original_intents WHERE id=_file_id AND setup_id=_setup_id AND tenant_id=_tenant_id FOR UPDATE;
 IF NOT FOUND OR f.created_by<>actor OR NOT EXISTS(SELECT 1 FROM private.dpd_original_receipts WHERE file_id=f.id) OR NOT private.dpd_original_viewable(f.id) OR _request_key IS NULL OR _sheet_key IS NULL OR _chunk_index<0 OR _start_row<0 OR jsonb_typeof(_rows) IS DISTINCT FROM 'array' OR jsonb_array_length(_rows) NOT BETWEEN 1 AND 1000 OR octet_length(_rows::text)>1048576 OR EXISTS(SELECT 1 FROM jsonb_array_elements(_rows) row WHERE jsonb_typeof(row) IS DISTINCT FROM 'array' OR jsonb_array_length(row)>500 OR EXISTS(SELECT 1 FROM jsonb_array_elements(row) cell WHERE jsonb_typeof(cell) IS DISTINCT FROM 'string')) THEN RAISE EXCEPTION 'dpd.bounded_actual_chunk_required' USING ERRCODE='PT409';END IF;
 SELECT * INTO c FROM private.dpd_original_chunks WHERE file_id=f.id AND request_key=_request_key;
 IF FOUND THEN IF c.sheet_key<>_sheet_key OR c.chunk_index<>_chunk_index OR c.start_row<>_start_row OR c.rows IS DISTINCT FROM _rows THEN RAISE EXCEPTION 'dpd.chunk_request_conflict' USING ERRCODE='PT409';END IF;RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'file_id',f.id,'sheet_key',c.sheet_key,'chunk_index',c.chunk_index,'start_row',c.start_row::text,'row_count',c.row_count,'rows_sha256',c.rows_sha256,'request_replay',true);END IF;
 IF EXISTS(SELECT 1 FROM private.dpd_schema_receipts WHERE file_id=f.id) THEN RAISE EXCEPTION 'dpd.immutable_schema_already_finished' USING ERRCODE='PT409';END IF;
 SELECT coalesce(max(start_row+row_count),0) INTO expected FROM private.dpd_original_chunks WHERE file_id=f.id AND sheet_key=_sheet_key;
 IF _start_row<>expected OR _chunk_index<>(SELECT count(*) FROM private.dpd_original_chunks WHERE file_id=f.id AND sheet_key=_sheet_key) OR (SELECT coalesce(sum(row_count),0) FROM private.dpd_original_chunks WHERE file_id=f.id)+jsonb_array_length(_rows)>1000200 OR (SELECT coalesce(sum(octet_length(rows::text)),0) FROM private.dpd_original_chunks WHERE file_id=f.id)+octet_length(_rows::text)>52428800 THEN RAISE EXCEPTION 'dpd.contiguous_bounded_source_ordinals_required' USING ERRCODE='PT409';END IF;
 INSERT INTO private.dpd_original_chunks(file_id,sheet_key,chunk_index,start_row,row_count,rows,rows_sha256,request_key,created_by) VALUES(f.id,_sheet_key,_chunk_index,_start_row,jsonb_array_length(_rows),_rows,private.dpw_hash(_rows),_request_key,actor) RETURNING * INTO c;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'file_id',f.id,'sheet_key',c.sheet_key,'chunk_index',c.chunk_index,'start_row',c.start_row::text,'row_count',c.row_count,'rows_sha256',c.rows_sha256,'request_replay',false);
END $function$
;

CREATE OR REPLACE FUNCTION private.mapped_recon_governance_request_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE purpose text;
BEGIN
 IF OLD.mapped_governance_version IS NULL THEN RETURN NEW; END IF;
 IF TG_OP='DELETE' THEN PERFORM private.mapped_recon_governance_conflict('native_request_history_immutable'); END IF;
 purpose:=CASE WHEN OLD.request_kind='edit' THEN 'edit_decision' ELSE 'promotion_decision' END;
 IF NOT private.mapped_recon_governance_transition(OLD.id,purpose)
 OR (to_jsonb(OLD)-ARRAY['status','decision_reason','decided_by','decided_at','staging_definition_id'])
 IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['status','decision_reason','decided_by','decided_at','staging_definition_id']) THEN
  PERFORM private.mapped_recon_governance_conflict('native_request_snapshot_immutable');
 END IF;
 IF OLD.status='pending' THEN
  IF NEW.status NOT IN ('approved','rejected') OR NEW.decided_by IS DISTINCT FROM auth.uid()
   OR NEW.decided_by=OLD.requested_by OR NEW.staging_definition_id IS DISTINCT FROM OLD.staging_definition_id THEN
   PERFORM private.mapped_recon_governance_conflict('native_decision_shape_required');
  END IF;
 ELSIF NOT (OLD.status='approved' AND OLD.request_kind='edit' AND OLD.staging_definition_id IS NULL
  AND NEW.staging_definition_id IS NOT NULL AND to_jsonb(OLD)-'staging_definition_id'=to_jsonb(NEW)-'staging_definition_id') THEN
  PERFORM private.mapped_recon_governance_conflict('request_stale_or_replayed');
 END IF;
 RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.dpd_finish_original_schema(_tenant_id uuid, _setup_id uuid, _file_id uuid, _schema_manifest jsonb, _request_key uuid, _verified_subject jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_service_request_actor(_tenant_id,_setup_id,'original.schema',(_verified_subject->>'request_context_id')::uuid,_verified_subject);f private.dpd_original_intents%ROWTYPE;r private.dpd_schema_receipts%ROWTYPE;sheet jsonb;actual bigint;total bigint:=0;columns integer;
BEGIN
 PERFORM private.dpd_assert_parser_lease(_file_id,actor);
 SELECT * INTO f FROM private.dpd_original_intents WHERE id=_file_id AND setup_id=_setup_id AND tenant_id=_tenant_id FOR UPDATE;
 IF NOT FOUND OR f.created_by<>actor OR NOT EXISTS(SELECT 1 FROM private.dpd_original_receipts WHERE file_id=f.id) OR NOT private.dpd_original_viewable(f.id) OR _request_key IS NULL OR jsonb_typeof(_schema_manifest) IS DISTINCT FROM 'object' OR _schema_manifest->>'content_sha256' IS DISTINCT FROM f.content_sha256 OR jsonb_typeof(_schema_manifest->'sheet_inventory') IS DISTINCT FROM 'array' OR jsonb_array_length(_schema_manifest->'sheet_inventory') NOT BETWEEN 1 AND 200 OR jsonb_typeof(_schema_manifest->'header_fields') IS DISTINCT FROM 'array' OR jsonb_array_length(_schema_manifest->'header_fields') NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'dpd.actual_original_schema_manifest_required' USING ERRCODE='PT409';END IF;
 SELECT * INTO r FROM private.dpd_schema_receipts WHERE file_id=f.id;
 IF FOUND THEN IF r.schema_manifest IS DISTINCT FROM _schema_manifest OR r.request_key<>_request_key THEN RAISE EXCEPTION 'dpd.schema_request_conflict' USING ERRCODE='PT409';END IF;RETURN private.dpd_original_result(actor,f.id,true);END IF;
 IF (SELECT count(DISTINCT value->>'sheet_key') FROM jsonb_array_elements(_schema_manifest->'sheet_inventory'))<>jsonb_array_length(_schema_manifest->'sheet_inventory') THEN RAISE EXCEPTION 'dpd.duplicate_sheet_key' USING ERRCODE='PT409';END IF;
 FOR sheet IN SELECT value FROM jsonb_array_elements(_schema_manifest->'sheet_inventory') LOOP
  SELECT coalesce(sum(row_count),0) INTO actual FROM private.dpd_original_chunks WHERE file_id=f.id AND sheet_key=sheet->>'sheet_key';
  IF coalesce(sheet->>'raw_row_count','')!~'^(0|[1-9][0-9]*)$' OR (sheet->>'raw_row_count')::bigint<>actual OR actual>1000200 OR jsonb_typeof(sheet->'header_fields') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'dpd.complete_sheet_count_header_required' USING ERRCODE='PT409';END IF;total:=total+actual;
 END LOOP;
 IF EXISTS(SELECT 1 FROM private.dpd_original_chunks c WHERE c.file_id=f.id AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(_schema_manifest->'sheet_inventory') AS si(value) WHERE si.value->>'sheet_key'=c.sheet_key)) OR total>1000200 THEN RAISE EXCEPTION 'dpd.all_actual_sheet_chunks_required' USING ERRCODE='PT409';END IF;
 INSERT INTO private.dpd_schema_receipts(file_id,setup_id,tenant_id,created_by,schema_manifest,schema_sha256,raw_row_count,request_key) VALUES(f.id,_setup_id,_tenant_id,actor,_schema_manifest,private.dpw_hash(_schema_manifest),total,_request_key);
 PERFORM private.dpd_event(_tenant_id,_setup_id,actor,'original.schema.complete',f.id,jsonb_build_object('schema_sha256',private.dpw_hash(_schema_manifest),'raw_row_count',total::text,'header_fields_provenance','actual_original_parser_inferred_not_human_strict_types'));RETURN private.dpd_original_result(actor,f.id,false);
END $function$
;

CREATE OR REPLACE FUNCTION private.mapped_recon_governance_run(_new recon_runs)
 RETURNS recon_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE d public.recon_definitions%ROWTYPE;
BEGIN
 SELECT * INTO d FROM public.recon_definitions WHERE tenant_id=_new.tenant_id AND id=_new.definition_id FOR SHARE;
 IF NOT FOUND OR _new.run_by IS DISTINCT FROM auth.uid() THEN PERFORM private.mapped_recon_governance_conflict('native_run_actor_or_tenant_mismatch'); END IF;
 PERFORM private.mapped_recon_governance_actor(d.tenant_id,d.id,'run',false);
 IF NOT private.recon_authoritative_access_decision_as(auth.uid(),d.id,'read') THEN PERFORM private.mapped_recon_governance_conflict('native_current_read_required'); END IF;
 IF NOT ((d.environment='production' AND d.status='active' AND d.governance_state IN ('approved_locked','edit_request_pending'))
 OR (d.environment='development' AND d.governance_state='development_draft')
 OR (d.environment='staging' AND d.governance_state='staging_copy')) THEN
  PERFORM private.mapped_recon_governance_conflict('native_run_governance_not_ready');
 END IF;
 -- Retain the actual native approved revision/independent runner contract.
 PERFORM private.recon_run_bound_approved_version(_new.tenant_id,_new.definition_id,_new.run_by);
 RETURN _new;
END $function$
;

CREATE OR REPLACE FUNCTION public.dpdi_get_dataset(_tenant_id uuid, _setup_id uuid, _dataset_id uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'publication.dataset.read',_request_context_id);d private.dpdi_published_datasets%ROWTYPE;
BEGIN
 SELECT * INTO d FROM private.dpdi_published_datasets WHERE id=_dataset_id AND tenant_id=_tenant_id AND setup_id=_setup_id;
 IF NOT FOUND OR private.data_prep_pipeline_scope_allows(actor,_tenant_id,d.pipeline_id,'view') IS DISTINCT FROM true OR private.dpw_source_allows(actor,_tenant_id,d.data_source_id,'view') IS DISTINCT FROM true OR EXISTS(SELECT 1 FROM private.dpdi_run_inputs i WHERE i.job_id=d.job_id AND private.dpw_source_allows(actor,_tenant_id,i.data_source_id,'view') IS DISTINCT FROM true) THEN RAISE EXCEPTION 'dpdi.current_published_dataset_source_reader_required' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'dataset',private.dpdi_dataset_dto(d),'payload_available',NOT EXISTS(SELECT 1 FROM private.dpdi_run_inputs i WHERE i.job_id=d.job_id AND NOT private.dpd_original_viewable(i.original_file_id)));
END $function$
;

CREATE OR REPLACE FUNCTION public.dpd_read_original_rows(_tenant_id uuid, _setup_id uuid, _file_id uuid, _sheet_key text, _start_row bigint, _page_size integer, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'original.rows',_request_context_id);s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,false);f private.dpd_original_intents%ROWTYPE;sc private.dpd_schema_receipts%ROWTYPE;sheet jsonb;state text;rows jsonb;total bigint;header jsonb;inventory jsonb;
BEGIN
 IF _start_row<0 OR _page_size NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'dpd.invalid_original_page' USING ERRCODE='22023';END IF;
 SELECT * INTO f FROM private.dpd_original_intents WHERE id=_file_id AND setup_id=s.id AND tenant_id=_tenant_id;IF NOT FOUND THEN RAISE EXCEPTION 'dpd.original_row_scope_denied' USING ERRCODE='42501';END IF;
 SELECT * INTO sc FROM private.dpd_schema_receipts WHERE file_id=f.id;SELECT value INTO sheet FROM jsonb_array_elements(coalesce(sc.schema_manifest->'sheet_inventory','[]')) WHERE value->>'sheet_key'=_sheet_key;
 state:=CASE WHEN EXISTS(SELECT 1 FROM private.dpd_original_tombstones WHERE file_id=f.id) THEN 'tombstoned' WHEN f.expires_at<=clock_timestamp() THEN 'expired' WHEN NOT EXISTS(SELECT 1 FROM private.dpd_original_receipts WHERE file_id=f.id) THEN 'unavailable' WHEN sc.file_id IS NULL THEN 'parser_pending' WHEN sheet IS NULL THEN 'schema_pending' ELSE 'available' END;
 IF state='available' THEN
  total:=(sheet->>'raw_row_count')::bigint;header:=sheet->'header_fields';inventory:=sc.schema_manifest->'sheet_inventory';
  SELECT coalesce(jsonb_agg(jsonb_build_object('source_row_ordinal',q.ordinal::text,'cells',q.cells,'row_sha256',private.dpw_hash(q.cells)) ORDER BY q.ordinal),'[]') INTO rows FROM(SELECT c.start_row+v.ordinality-1 ordinal,v.value cells FROM private.dpd_original_chunks c CROSS JOIN LATERAL jsonb_array_elements(c.rows) WITH ORDINALITY v WHERE c.file_id=f.id AND c.sheet_key=_sheet_key AND c.start_row<_start_row+_page_size AND c.start_row+c.row_count>_start_row AND c.start_row+v.ordinality-1>=_start_row AND c.start_row+v.ordinality-1<_start_row+_page_size ORDER BY ordinal) q;
 END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'file_id',f.id,'content_sha256',f.content_sha256,'state',state,'rows',rows,'total_raw_rows',total::text,'header_fields',header,'sheet_inventory',coalesce(inventory,'[]'),
 'has_more',CASE WHEN state='available' THEN _start_row+_page_size<total ELSE NULL END,'start_row',_start_row::text,'page_size',_page_size,'retention',f.retention_policy||jsonb_build_object('expires_at',f.expires_at,'legal_hold',private.dpd_original_has_hold(f.id)));
END $function$
;

CREATE OR REPLACE FUNCTION private.dpd_selected_input(_file uuid, _selection jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE f private.dpd_original_intents%ROWTYPE;sc private.dpd_schema_receipts%ROWTYPE;sheet jsonb;headers jsonb;start_at bigint;header_at bigint;cells jsonb;amount bigint;
BEGIN SELECT * INTO f FROM private.dpd_original_intents WHERE id=_file;SELECT * INTO sc FROM private.dpd_schema_receipts WHERE file_id=f.id;
 IF NOT FOUND OR NOT private.dpd_original_viewable(f.id) OR _selection->>'schema_sha256' IS DISTINCT FROM sc.schema_sha256 THEN RAISE EXCEPTION 'dpd.current_received_schema_selection_required' USING ERRCODE='PT409';END IF;
 SELECT value INTO sheet FROM jsonb_array_elements(sc.schema_manifest->'sheet_inventory') WHERE value->>'sheet_key'=_selection->>'sheet_key';
 IF sheet IS NULL OR coalesce(_selection->>'header_row_index','')!~'^(0|[1-9][0-9]*)$' OR coalesce(_selection->>'data_start_row','')!~'^(0|[1-9][0-9]*)$' THEN RAISE EXCEPTION 'dpd.explicit_actual_header_selection_required' USING ERRCODE='PT409';END IF;
 header_at:=(_selection->>'header_row_index')::bigint;start_at:=(_selection->>'data_start_row')::bigint;
 SELECT c.rows->((header_at-c.start_row)::integer) INTO cells FROM private.dpd_original_chunks c WHERE c.file_id=f.id AND c.sheet_key=sheet->>'sheet_key' AND c.start_row<=header_at AND c.start_row+c.row_count>header_at;
 IF cells IS NULL OR jsonb_array_length(cells) NOT BETWEEN 1 AND 500 OR start_at<=header_at OR start_at>(sheet->>'raw_row_count')::bigint THEN RAISE EXCEPTION 'dpd.actual_data_range_required' USING ERRCODE='PT409';END IF;
 SELECT jsonb_agg(jsonb_build_object('ordinal',h.ordinality-1,'name',h.value,'observed_representation','text','strict_json_type_inferred',false) ORDER BY h.ordinality) INTO headers FROM jsonb_array_elements_text(cells) WITH ORDINALITY h;
 IF (SELECT count(DISTINCT value->>'name') FROM jsonb_array_elements(headers))<>jsonb_array_length(headers) OR EXISTS(SELECT 1 FROM jsonb_array_elements(headers) h WHERE coalesce(h->>'name','')='' OR coalesce(h->>'ordinal','')!~'^(0|[1-9][0-9]*)$') THEN RAISE EXCEPTION 'dpd.unique_confirmed_header_fields_required' USING ERRCODE='PT409';END IF;
 amount:=(sheet->>'raw_row_count')::bigint-start_at;IF amount>1000000 THEN RAISE EXCEPTION 'dpd.selected_data_row_budget_exceeded' USING ERRCODE='PT409';END IF;
 -- Metadata only: exact immutable original/schema/selection pins. Processing reads bounded pages. No whole-original JSON array or counterfeit upload rows.

 RETURN jsonb_build_object('file_id',f.id,'sheet_key',sheet->>'sheet_key','header_fields',headers,'data_start_row',start_at::text,'row_count',amount::text,'input_pin_sha256',private.dpw_hash(jsonb_build_object('original_sha256',f.content_sha256,'schema_sha256',sc.schema_sha256,'selection',_selection)),'schema_sha256',sc.schema_sha256,'selection_sha256',private.dpw_hash(_selection),'original_sha256',f.content_sha256,'size_bytes',f.size_bytes::text,'storage_bucket',f.storage_bucket,'original_path',f.original_path,'created_by',f.created_by);
END $function$
;

CREATE OR REPLACE FUNCTION public.dpd_register_received_source(_tenant_id uuid, _setup_id uuid, _file_id uuid, _source_request_key uuid, _ownership_request_key uuid, _reason text, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'source.register',_request_context_id);s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,true);f private.dpd_original_intents%ROWTYPE;sc private.dpd_schema_receipts%ROWTYPE;v private.dpd_versions%ROWTYPE;l private.dpd_raw_source_links%ROWTYPE;source jsonb;selection jsonb;input jsonb;sheet jsonb;source_id uuid;
BEGIN
 SELECT * INTO f FROM private.dpd_original_intents WHERE id=_file_id AND setup_id=s.id AND tenant_id=_tenant_id FOR UPDATE;SELECT * INTO sc FROM private.dpd_schema_receipts WHERE file_id=f.id;SELECT * INTO v FROM private.dpd_versions WHERE setup_id=s.id ORDER BY version DESC LIMIT 1;
 IF f.id IS NULL OR sc.file_id IS NULL OR NOT EXISTS(SELECT 1 FROM private.dpd_original_receipts WHERE file_id=f.id) OR NOT private.dpd_original_viewable(f.id) OR _source_request_key IS NULL OR _ownership_request_key IS NULL THEN RAISE EXCEPTION 'dpd.received_schema_before_raw_source_required' USING ERRCODE='PT409';END IF;
 SELECT * INTO l FROM private.dpd_raw_source_links WHERE file_id=f.id;
 IF FOUND THEN IF l.source_request_key<>_source_request_key OR l.ownership_request_key<>_ownership_request_key THEN RAISE EXCEPTION 'dpd.source_request_conflict' USING ERRCODE='PT409';END IF;IF private.dpw_source_allows(actor,_tenant_id,l.data_source_id,'view') IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.current_raw_source_denied' USING ERRCODE='42501';END IF;RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'file_id',f.id,'data_source_id',l.data_source_id,'request_replay',true);END IF;
 SELECT value INTO sheet FROM jsonb_array_elements(sc.schema_manifest->'sheet_inventory') WHERE value->>'sheet_key'=coalesce(f.descriptor->>'selected_sheet',sc.schema_manifest->'sheet_inventory'->0->>'sheet_key');
 IF sheet IS NULL THEN RAISE EXCEPTION 'dpd.actual_selected_sheet_required' USING ERRCODE='PT409';END IF;
 IF jsonb_typeof(sheet->'header_fields') IS DISTINCT FROM 'array' OR jsonb_array_length(sheet->'header_fields') NOT BETWEEN 1 AND 500 OR coalesce(sheet->>'raw_row_count','')!~'^(0|[1-9][0-9]*)$' THEN RAISE EXCEPTION 'dpd.actual_raw_schema_metadata_required' USING ERRCODE='PT409';END IF;
 input:=jsonb_build_object('header_fields',sheet->'header_fields','row_count',sheet->>'raw_row_count','row_count_basis','raw_records_including_headers');
 source:=public.ssb_create_source(_tenant_id,nullif(s.input->>'bu_id','')::uuid,left((s.input->>'title')||' '||f.feed_key,80),'Original received under authoring setup '||s.id::text,CASE WHEN f.descriptor->>'format'='xlsx' THEN 'xlsx' ELSE 'csv' END,_source_request_key);source_id:=(source->'source'->>'id')::uuid;IF (source->>'is_new')::boolean IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.new_raw_source_request_required_no_existing_source_rewrite' USING ERRCODE='PT409';END IF;
 -- Within this one transaction the newly created SSB draft gets its ACTUAL
 -- received schema/count. No observable fake empty received-source row.
 UPDATE public.workspace_data_sources SET inferred_schema=input->'header_fields',row_count=(input->>'row_count')::integer,status='ready',connection_config=connection_config||jsonb_build_object('authoring_original_file_id',f.id,'schema_sha256',sc.schema_sha256,'row_count_basis','raw_records_including_headers','schema_provenance','actual_parser_representation_hint_not_confirmed_output_types'),updated_at=clock_timestamp() WHERE id=source_id AND tenant_id=_tenant_id AND created_by=actor;
 PERFORM public.ssb_save_ownership(_tenant_id,source_id,v.owner_bu_ids,'{}'::uuid[],_reason,_ownership_request_key);
 IF private.dpw_source_allows(actor,_tenant_id,source_id,'view') IS DISTINCT FROM true OR private.dpw_source_allows(actor,_tenant_id,source_id,'ingest') IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.actual_registered_source_binding_required' USING ERRCODE='42501';END IF;
 INSERT INTO private.dpd_raw_source_links(file_id,setup_id,tenant_id,data_source_id,source_request_key,ownership_request_key,created_by) VALUES(f.id,s.id,_tenant_id,source_id,_source_request_key,_ownership_request_key,actor);
 PERFORM private.dpd_event(_tenant_id,s.id,actor,'original.source.registered',source_id,jsonb_build_object('file_id',f.id,'original_sha256',f.content_sha256,'actual_rows',input->>'row_count','inferred_fields_not_human_strict_json_types',true));RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'file_id',f.id,'data_source_id',source_id,'request_replay',false);
END $function$
;

CREATE OR REPLACE FUNCTION private.dpd_preview_result(_actor uuid, _link private.dpd_preview_links)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE b public.data_prep_delivery_batches%ROWTYPE;
BEGIN SELECT * INTO b FROM public.data_prep_delivery_batches WHERE id=_link.batch_id;
 RETURN jsonb_build_object('actor_id',_actor,'tenant_id',_link.tenant_id,'setup_id',_link.setup_id,'draft_version',_link.draft_version,'pipeline_id',_link.pipeline_id,'configuration_id',_link.configuration_id,'pipeline_version',_link.pipeline_version,'batch_id',_link.batch_id,'mode','preview','execution_mode',b.execution_mode,'human_in_loop',b.human_in_loop,'input_manifest',_link.input_manifest,'input_manifest_sha256',_link.input_manifest_sha256,'source_reupload_performed',false,'publish_allowed',false,'input_binding_kind','authoring_original_pinned','existing_dpw_input_file_contract_reused',false,'confirmed_mapping',(SELECT v.payload->'confirmed_mapping' FROM private.dpd_versions v WHERE v.setup_id=_link.setup_id AND v.version=_link.draft_version),'confirmed_mapping_sha256',(SELECT private.dpw_hash(v.payload->'confirmed_mapping') FROM private.dpd_versions v WHERE v.setup_id=_link.setup_id AND v.version=_link.draft_version),'configuration_request_key',_link.configuration_request_key,'delivery_request_key',_link.delivery_request_key,'input_bindings',coalesce((SELECT jsonb_agg(jsonb_build_object('input_id',i.id,'original_file_id',i.original_file_id,'feed_key',i.feed_key,'data_source_id',i.data_source_id,'selection_sha256',i.selection_sha256,'rows_count',i.rows_count::text,'binding_kind','authoring_original_pinned','dpw_file_id',NULL,'upload_id',NULL) ORDER BY i.feed_key,i.id) FROM private.dpd_preview_file_links i WHERE i.setup_id=_link.setup_id AND i.draft_version=_link.draft_version),'[]'));
END $function$
;

CREATE OR REPLACE FUNCTION public.dpd_bind_setup_preview(_tenant_id uuid, _setup_id uuid, _draft_version integer, _configuration_request_key uuid, _delivery_request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'preview.bind',_request_context_id);s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,true);v private.dpd_versions%ROWTYPE;l private.dpd_preview_links%ROWTYPE;prior private.dpd_preview_links%ROWTYPE;feed jsonb;linked private.dpd_raw_source_links%ROWTYPE;native jsonb;delivery jsonb;manifest jsonb:='[]';input jsonb;newfeeds jsonb:='[]';payload jsonb;amount bigint;item jsonb;bound private.dpd_preview_file_links%ROWTYPE;declared jsonb;ref jsonb;
BEGIN
 PERFORM 1 FROM private.dpd_setups WHERE id=s.id FOR UPDATE;SELECT * INTO v FROM private.dpd_versions WHERE setup_id=s.id ORDER BY version DESC LIMIT 1;
 IF v.version<>_draft_version OR _configuration_request_key IS NULL OR _delivery_request_key IS NULL THEN RAISE EXCEPTION 'dpd.current_draft_version_required' USING ERRCODE='PT409';END IF;
 PERFORM private.dpd_validate_confirmed_mapping(_tenant_id,s.id,v.version,v.payload->'confirmed_mapping');
 IF (v.payload ? 'sharing_user_group_ids' AND private.dps_ids(ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(v.payload->'sharing_user_group_ids')),100,false) IS DISTINCT FROM private.dps_ids(v.group_ids,100,false)) OR (v.payload ? 'owning_business_unit_ids' AND private.dps_ids(ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(v.payload->'owning_business_unit_ids')),100,true) IS DISTINCT FROM private.dps_ids(v.owner_bu_ids,100,true)) THEN RAISE EXCEPTION 'dpd.authoritative_scope_revision_required_preserve_history' USING ERRCODE='PT409';END IF;

 SELECT * INTO l FROM private.dpd_preview_links WHERE setup_id=s.id AND draft_version=v.version;
 IF FOUND THEN IF l.configuration_request_key<>_configuration_request_key OR l.delivery_request_key<>_delivery_request_key THEN RAISE EXCEPTION 'dpd.preview_request_conflict' USING ERRCODE='PT409';END IF;PERFORM private.dpw_authorize(_tenant_id,l.pipeline_id,'run');RETURN private.dpd_preview_result(actor,l);END IF;
 IF jsonb_typeof(v.payload->'feeds') IS DISTINCT FROM 'array' OR jsonb_array_length(v.payload->'feeds')=0 THEN RAISE EXCEPTION 'dpd.full_received_feed_configuration_required' USING ERRCODE='PT409';END IF;
 FOR feed IN SELECT value FROM jsonb_array_elements(v.payload->'feeds') LOOP
  SELECT x.value INTO declared FROM jsonb_array_elements(v.payload->'confirmed_mapping'->'feeds') AS x(value) WHERE x.value->>'key'=feed->>'key';
  IF declared IS NULL OR feed->'mappings' IS DISTINCT FROM declared->'mappings' THEN RAISE EXCEPTION 'dpd.pipeline_feed_confirmed_mapping_conflict' USING ERRCODE='PT409';END IF;
  newfeeds:=newfeeds||jsonb_build_array(feed||jsonb_build_object('data_source_id',declared->>'data_source_id'));
  FOR ref IN SELECT value FROM jsonb_array_elements(declared->'original_refs') LOOP
   SELECT * INTO linked FROM private.dpd_raw_source_links WHERE file_id=(ref->>'file_id')::uuid AND setup_id=s.id;
   IF NOT FOUND OR linked.data_source_id::text IS DISTINCT FROM declared->>'data_source_id' OR private.dpw_source_allows(actor,_tenant_id,linked.data_source_id,'view') IS DISTINCT FROM true OR private.dpw_source_allows(actor,_tenant_id,linked.data_source_id,'ingest') IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.registered_current_original_source_required' USING ERRCODE='42501';END IF;
   input:=private.dpd_selected_input(linked.file_id,ref);
   manifest:=manifest||jsonb_build_array(input||jsonb_build_object('original',ref,'feed_key',feed->>'key','data_source_id',linked.data_source_id,'original_ref',ref,'configuration_sha256',v.payload_sha256,'original_storage_reupload',false));
  END LOOP;
 END LOOP;
 SELECT sum((m.value->>'row_count')::bigint) INTO amount FROM jsonb_array_elements(manifest) AS m(value);IF amount>1000000 THEN RAISE EXCEPTION 'dpd.preview_selected_cohort_row_budget_exceeded' USING ERRCODE='PT409';END IF;
 SELECT * INTO prior FROM private.dpd_preview_links WHERE setup_id=s.id ORDER BY draft_version DESC LIMIT 1;payload:=private.dpd_pipeline_payload(v.payload)||jsonb_build_object('feeds',newfeeds);
 native:=public.dps_save_configuration(_tenant_id,prior.pipeline_id,payload,v.owner_bu_ids,v.group_ids,_configuration_request_key,_request_context_id,_setup_id);
 delivery:=public.dpw_create_delivery(_tenant_id,(native->'pipeline'->>'id')::uuid,(s.input->>'business_date')::date,_delivery_request_key,NULL,'preview',NULL,s.input->>'execution_mode',(s.input->>'human_in_loop')::boolean);
 INSERT INTO private.dpd_preview_links(setup_id,draft_version,tenant_id,created_by,pipeline_id,configuration_id,pipeline_version,batch_id,configuration_request_key,delivery_request_key,input_manifest,input_manifest_sha256)
 VALUES(s.id,v.version,_tenant_id,actor,(native->'pipeline'->>'id')::uuid,(native->>'configuration_id')::uuid,(native->'pipeline'->>'version')::integer,(delivery->'batch'->>'id')::uuid,_configuration_request_key,_delivery_request_key,manifest,private.dpw_hash(manifest)) RETURNING * INTO l;
 FOR item IN SELECT value FROM jsonb_array_elements(manifest) LOOP
 INSERT INTO private.dpd_preview_file_links(setup_id,draft_version,original_file_id,data_source_id,feed_key,selection,selection_sha256,rows_count) VALUES(s.id,v.version,(item->>'file_id')::uuid,(item->>'data_source_id')::uuid,item->>'feed_key',item->'original_ref',item->>'selection_sha256',(item->>'row_count')::bigint);
 END LOOP;
 PERFORM private.dpd_event(_tenant_id,s.id,actor,'preview.configuration.bound',l.batch_id,jsonb_build_object('configuration_id',l.configuration_id,'draft_version',v.version,'input_manifest_sha256',l.input_manifest_sha256,'original_reupload',false,'publish_allowed',false));RETURN private.dpd_preview_result(actor,l);
END $function$
;

CREATE OR REPLACE FUNCTION public.dpd_lookup_preview_binding(_tenant_id uuid, _setup_id uuid, _draft_version integer, _configuration_request_key uuid, _delivery_request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'preview.lookup',_request_context_id);s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,false);l private.dpd_preview_links%ROWTYPE;
BEGIN SELECT * INTO l FROM private.dpd_preview_links WHERE setup_id=s.id AND draft_version=_draft_version;IF NOT FOUND THEN RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'state','absent','result',NULL);END IF;IF l.configuration_request_key<>_configuration_request_key OR l.delivery_request_key<>_delivery_request_key THEN RAISE EXCEPTION 'dpd.preview_lookup_conflict' USING ERRCODE='PT409';END IF;PERFORM private.dpw_authorize(_tenant_id,l.pipeline_id,'run');RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'state','found','result',private.dpd_preview_result(actor,l));END $function$
;

CREATE OR REPLACE FUNCTION public.dpd_read_preview_input(_tenant_id uuid, _setup_id uuid, _draft_version integer, _input_id uuid, _start_row bigint, _page_size integer, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'preview.input',_request_context_id);s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,false);l private.dpd_preview_links%ROWTYPE;i private.dpd_preview_file_links%ROWTYPE;meta jsonb;cells jsonb;rows jsonb;first_at bigint;total bigint;
BEGIN
 IF _start_row IS NULL OR _start_row<0 OR _page_size IS NULL OR _page_size NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION 'dpd.bounded_preview_input_page_required' USING ERRCODE='22023';END IF;
 SELECT * INTO l FROM private.dpd_preview_links WHERE setup_id=s.id AND draft_version=_draft_version AND tenant_id=_tenant_id;
 SELECT * INTO i FROM private.dpd_preview_file_links WHERE id=_input_id AND setup_id=s.id AND draft_version=l.draft_version;
 IF i.id IS NULL OR private.dpw_authorize(_tenant_id,l.pipeline_id,'view') IS DISTINCT FROM actor OR private.dpw_source_allows(actor,_tenant_id,i.data_source_id,'view') IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.preview_current_input_scope_denied' USING ERRCODE='42501';END IF;
 IF NOT private.dpd_original_viewable(i.original_file_id) THEN RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'input_id',i.id,'state','unavailable','rows',NULL,'total',NULL,'has_more',NULL,'publish_allowed',false);END IF;
 meta:=private.dpd_selected_input(i.original_file_id,i.selection);first_at:=(meta->>'data_start_row')::bigint;total:=i.rows_count;
 SELECT coalesce(jsonb_agg(jsonb_build_object('record_index',(q.ordinal-first_at)::text,'source_row_ordinal',q.ordinal::text,'input_id',i.id,'original_file_id',i.original_file_id,'source_row_id',jsonb_build_array(i.original_file_id,i.selection->>'sheet_key',q.ordinal::text)::text,'values',q.record,'raw_cells',q.cells,'raw_row_sha256',private.dpw_hash(q.cells)) ORDER BY q.ordinal),'[]') INTO rows FROM (
 SELECT c.start_row+x.ordinality-1 ordinal,x.value cells,(SELECT jsonb_object_agg(h.value->>'name',coalesce(x.value->>((h.value->>'ordinal')::integer),'')) FROM jsonb_array_elements(meta->'header_fields') AS h(value)) record
 FROM private.dpd_original_chunks c CROSS JOIN LATERAL jsonb_array_elements(c.rows) WITH ORDINALITY AS x(value,ordinality)
 WHERE c.file_id=i.original_file_id AND c.sheet_key=i.selection->>'sheet_key' AND c.start_row<first_at+_start_row+_page_size AND c.start_row+c.row_count>first_at+_start_row AND c.start_row+x.ordinality-1>=first_at+_start_row AND c.start_row+x.ordinality-1<first_at+least(_start_row+_page_size,total)) q;
 IF octet_length(rows::text)>1048576 THEN RAISE EXCEPTION 'dpd.preview_page_byte_budget_exceeded_reduce_page' USING ERRCODE='22023';END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'draft_version',l.draft_version,'pipeline_id',l.pipeline_id,'configuration_id',l.configuration_id,'batch_id',l.batch_id,'input_id',i.id,'original_file_id',i.original_file_id,'input_binding_kind','authoring_original_pinned','state','available','rows',rows,'total',total::text,'has_more',_start_row+_page_size<total,'input_manifest_sha256',l.input_manifest_sha256,'selection_sha256',i.selection_sha256,'mode','preview','publish_allowed',false);
END $function$
;

CREATE OR REPLACE FUNCTION private.dpd_original_schema_pin(_tenant uuid, _setup uuid, _feed text, _ref jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE f private.dpd_original_intents%ROWTYPE;sc private.dpd_schema_receipts%ROWTYPE;raw private.dpd_raw_source_links%ROWTYPE;meta jsonb;fields jsonb;sheet jsonb;
BEGIN
 SELECT * INTO f FROM private.dpd_original_intents WHERE id=(_ref->>'file_id')::uuid AND tenant_id=_tenant AND setup_id=_setup AND feed_key=_feed;
 SELECT * INTO sc FROM private.dpd_schema_receipts WHERE file_id=f.id;SELECT * INTO raw FROM private.dpd_raw_source_links WHERE file_id=f.id;
 IF f.id IS NULL OR sc.file_id IS NULL OR NOT EXISTS(SELECT 1 FROM private.dpd_original_receipts WHERE file_id=f.id) THEN RAISE EXCEPTION 'dpd.actual_received_original_schema_required' USING ERRCODE='PT409';END IF;
 meta:=private.dpd_selected_input(f.id,_ref);SELECT x.value INTO sheet FROM jsonb_array_elements(sc.schema_manifest->'sheet_inventory') AS x(value) WHERE x.value->>'sheet_key'=_ref->>'sheet_key';
 SELECT jsonb_agg(jsonb_build_object('ordinal',(h.value->>'ordinal')::integer,'name',h.value->>'name','inferred_type','string','nullable',false) ORDER BY (h.value->>'ordinal')::integer) INTO fields FROM jsonb_array_elements(meta->'header_fields') AS h(value);
 -- Representation hints describe stored raw string cells, never human-approved
 -- strict JSON output types. Those are separately declared in confirmed_mapping.
 RETURN jsonb_build_object('file_id',f.id,'feed_key',f.feed_key,'original_request_key',f.request_key,'content_sha256',f.content_sha256,'storage_bucket',f.storage_bucket,'original_path',f.original_path,'schema_sha256',sc.schema_sha256,'sheet_key',_ref->>'sheet_key','header_row_index',_ref->>'header_row_index','data_start_row',_ref->>'data_start_row','total_raw_rows',sheet->>'raw_row_count','header_fields',fields,'data_source_id',raw.data_source_id);
END $function$
;

CREATE OR REPLACE FUNCTION private.dpd_validate_confirmed_mapping(_tenant uuid, _setup uuid, _version integer, _mapping jsonb, _for_execution boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE feed jsonb;ref jsonb;pin jsonb;field jsonb;rule jsonb;catalog jsonb:='[]';seen uuid[]:='{}';targets text[];headers text[];actor uuid:=auth.uid();key text;target text;type_name text;rule_fields text[];
BEGIN
 IF jsonb_typeof(_mapping) IS DISTINCT FROM 'object' OR _mapping->>'protocol' IS DISTINCT FROM 'data_prep_draft_confirmed_mapping_v1' OR _mapping->>'tenant_id' IS DISTINCT FROM _tenant::text OR _mapping->>'setup_id' IS DISTINCT FROM _setup::text OR (_mapping->>'draft_version')::integer IS DISTINCT FROM _version OR _mapping->>'on_failure' IS DISTINCT FROM 'block' OR _mapping->'preserve_extras' IS DISTINCT FROM 'true'::jsonb OR jsonb_typeof(_mapping->'feeds') IS DISTINCT FROM 'array' OR jsonb_array_length(_mapping->'feeds') NOT BETWEEN 1 AND 50 OR jsonb_typeof(_mapping->'output_schema') IS DISTINCT FROM 'array' OR jsonb_array_length(_mapping->'output_schema') NOT BETWEEN 1 AND 500 OR jsonb_typeof(_mapping->'quality_rules') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'dpd.full_explicit_confirmed_mapping_required' USING ERRCODE='PT409';END IF;
 IF (SELECT count(DISTINCT x.value->>'name') FROM jsonb_array_elements(_mapping->'output_schema') AS x(value))<>jsonb_array_length(_mapping->'output_schema') OR (SELECT count(DISTINCT x.value->>'key') FROM jsonb_array_elements(_mapping->'feeds') AS x(value))<>jsonb_array_length(_mapping->'feeds') THEN RAISE EXCEPTION 'dpd.duplicate_confirmed_field_feed' USING ERRCODE='PT409';END IF;
 FOR field IN SELECT value FROM jsonb_array_elements(_mapping->'output_schema') LOOP
  IF length(coalesce(field->>'name','')) NOT BETWEEN 1 AND 120 OR field->>'name' IN('extras_json','__proto__','constructor','prototype') OR field->>'name' IS DISTINCT FROM btrim(field->>'name') OR (field->>'type' IN('string','number','integer','date','boolean','json')) IS DISTINCT FROM true OR jsonb_typeof(field->'required') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'dpd.explicit_confirmed_output_field_required' USING ERRCODE='PT409';END IF;
 END LOOP;
 FOR feed IN SELECT value FROM jsonb_array_elements(_mapping->'feeds') LOOP
  IF length(coalesce(feed->>'key','')) NOT BETWEEN 1 AND 120 OR jsonb_typeof(feed->'original_refs') IS DISTINCT FROM 'array' OR jsonb_array_length(feed->'original_refs')=0 OR jsonb_typeof(feed->'mappings') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'dpd.complete_mapping_feed_required' USING ERRCODE='PT409';END IF;
  SELECT array_agg(x.value) INTO targets FROM jsonb_each_text(feed->'mappings') AS x(key,value);
  IF cardinality(targets) IS DISTINCT FROM (SELECT count(DISTINCT x) FROM unnest(targets) AS x) THEN RAISE EXCEPTION 'dpd.duplicate_mapping_target' USING ERRCODE='PT409';END IF;
  FOR ref IN SELECT value FROM jsonb_array_elements(feed->'original_refs') LOOP
   pin:=private.dpd_original_schema_pin(_tenant,_setup,feed->>'key',ref);
   IF ref IS DISTINCT FROM pin OR (ref->>'file_id')::uuid=ANY(seen) OR feed->>'data_source_id' IS DISTINCT FROM pin->>'data_source_id' THEN RAISE EXCEPTION 'dpd.confirmed_original_pin_conflict' USING ERRCODE='PT409';END IF;
   IF pin->>'data_source_id' IS NOT NULL AND (private.dpw_source_allows(actor,_tenant,(pin->>'data_source_id')::uuid,'view') IS DISTINCT FROM true OR (_for_execution AND private.dpw_source_allows(actor,_tenant,(pin->>'data_source_id')::uuid,'ingest') IS DISTINCT FROM true)) THEN RAISE EXCEPTION 'dpd.current_confirmed_source_denied' USING ERRCODE='42501';END IF;
   seen:=array_append(seen,(ref->>'file_id')::uuid);catalog:=catalog||jsonb_build_array(pin);SELECT array_agg(h.value->>'name') INTO headers FROM jsonb_array_elements(pin->'header_fields') AS h(value);
   FOR key,target IN SELECT x.key,x.value FROM jsonb_each_text(feed->'mappings') AS x(key,value) LOOP
    IF key IN('extras_json','__proto__','constructor','prototype') OR NOT key=ANY(headers) OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(_mapping->'output_schema') AS x(value) WHERE x.value->>'name'=target) THEN RAISE EXCEPTION 'dpd.mapping_actual_field_missing' USING ERRCODE='PT409';END IF;
   END LOOP;
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(_mapping->'output_schema') AS x(value) WHERE (x.value->>'required')::boolean AND NOT (x.value->>'name')=ANY(coalesce(targets,'{}'))) OR ((feed->>'allow_empty')::boolean IS DISTINCT FROM true AND (pin->>'data_start_row')::bigint=(pin->>'total_raw_rows')::bigint) THEN RAISE EXCEPTION 'dpd.required_mapping_or_nonempty_feed_missing' USING ERRCODE='PT409';END IF;
  END LOOP;
 END LOOP;
 IF EXISTS(SELECT 1 FROM private.dpd_original_intents f WHERE f.setup_id=_setup AND NOT f.id=ANY(seen)) THEN RAISE EXCEPTION 'dpd.all_received_originals_must_remain_bound' USING ERRCODE='PT409';END IF;
 IF jsonb_array_length(_mapping->'quality_rules')>50 OR (SELECT count(DISTINCT x.value->>'id') FROM jsonb_array_elements(_mapping->'quality_rules') AS x(value))<>jsonb_array_length(_mapping->'quality_rules') THEN RAISE EXCEPTION 'dpd.unique_quality_rule_ids_required' USING ERRCODE='PT409';END IF;
 FOR rule IN SELECT value FROM jsonb_array_elements(_mapping->'quality_rules') LOOP
  IF length(coalesce(rule->>'id','')) NOT BETWEEN 1 AND 120 OR (rule->>'kind' IN('required','unique_composite','bank_date_amount')) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.known_confirmed_quality_rule_required' USING ERRCODE='PT409';END IF;
  IF rule->>'kind'='required' THEN rule_fields:=ARRAY[rule->>'field'];ELSIF rule->>'kind'='unique_composite' THEN IF jsonb_typeof(rule->'fields') IS DISTINCT FROM 'array' OR jsonb_array_length(rule->'fields') NOT BETWEEN 1 AND 50 THEN RAISE EXCEPTION 'dpd.explicit_scalar_composite_fields_required' USING ERRCODE='PT409';END IF;SELECT array_agg(value) INTO rule_fields FROM jsonb_array_elements_text(rule->'fields');
  ELSE
   rule_fields:=ARRAY[rule->>'date_field',rule->>'amount_field'];IF rule->>'indicator_field' IS NOT NULL THEN rule_fields:=array_append(rule_fields,rule->>'indicator_field');END IF;
   IF (rule->>'date_format' IN('YYYY-MM-DD','DD/MM/YYYY','MM/DD/YYYY','YYYYMMDD')) IS DISTINCT FROM true OR (rule->>'amount_format' IN('decimal_dot','decimal_comma')) IS DISTINCT FROM true OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(_mapping->'output_schema') AS x(value) WHERE x.value->>'name'=rule->>'date_field' AND x.value->>'type'='date') OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(_mapping->'output_schema') AS x(value) WHERE x.value->>'name'=rule->>'amount_field' AND x.value->>'type'='number') THEN RAISE EXCEPTION 'dpd.explicit_bank_date_amount_contract_required' USING ERRCODE='PT409';END IF;
   IF rule->>'indicator_field' IS NOT NULL AND (NOT EXISTS(SELECT 1 FROM jsonb_array_elements(_mapping->'output_schema') AS x(value) WHERE x.value->>'name'=rule->>'indicator_field' AND x.value->>'type'='string') OR jsonb_typeof(rule->'debit_values') IS DISTINCT FROM 'array' OR jsonb_typeof(rule->'credit_values') IS DISTINCT FROM 'array' OR jsonb_array_length(rule->'debit_values')=0 OR jsonb_array_length(rule->'credit_values')=0 OR jsonb_typeof(rule->'debit_negative') IS DISTINCT FROM 'boolean' OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(rule->'debit_values') AS d(value) JOIN jsonb_array_elements_text(rule->'credit_values') AS c(value) ON d.value=c.value)) THEN RAISE EXCEPTION 'dpd.explicit_bank_sign_convention_required' USING ERRCODE='PT409';END IF;
  END IF;
  IF array_position(rule_fields,NULL) IS NOT NULL OR cardinality(rule_fields)<>(SELECT count(DISTINCT x) FROM unnest(rule_fields) AS x) OR EXISTS(SELECT 1 FROM unnest(rule_fields) AS f(name) WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(_mapping->'output_schema') AS x(value) WHERE x.value->>'name'=f.name AND (rule->>'kind'<>'unique_composite' OR x.value->>'type'<>'json'))) OR EXISTS(SELECT 1 FROM jsonb_array_elements(_mapping->'feeds') AS f(value) CROSS JOIN unnest(rule_fields) AS r(name) WHERE NOT EXISTS(SELECT 1 FROM jsonb_each_text(f.value->'mappings') AS m(key,value) WHERE m.value=r.name)) THEN RAISE EXCEPTION 'dpd.quality_rule_confirmed_field_missing' USING ERRCODE='PT409';END IF;
 END LOOP;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant,'setup_id',_setup,'draft_version',_version,'state','available','complete',true,'originals',catalog);
END $function$
;

CREATE OR REPLACE FUNCTION public.dpd_get_mapping_admission(_tenant_id uuid, _setup_id uuid, _draft_version integer, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'mapping.read',_request_context_id);s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,false);v private.dpd_versions%ROWTYPE;catalog jsonb;
BEGIN
 SELECT * INTO v FROM private.dpd_versions WHERE setup_id=s.id ORDER BY version DESC LIMIT 1;
 IF v.version IS DISTINCT FROM _draft_version THEN RAISE EXCEPTION 'dpd.current_saved_mapping_version_required' USING ERRCODE='PT409';END IF;
 catalog:=private.dpd_validate_confirmed_mapping(_tenant_id,s.id,v.version,v.payload->'confirmed_mapping',false);
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'draft_version',v.version,'catalog',catalog,'confirmed_mapping',v.payload->'confirmed_mapping','confirmed_mapping_sha256',private.dpw_hash(v.payload->'confirmed_mapping'),'publish_allowed',false);
END $function$
;

CREATE OR REPLACE FUNCTION private.dps_setup_admission(_tenant uuid, _setup uuid, _actor uuid, _operation text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF _operation NOT IN('scope.groups','scope.save','scope.read','scope.lookup','scope.decide','preview.bind') THEN RAISE EXCEPTION 'dps.fixed_operation_required' USING ERRCODE='42501';END IF;
 IF _operation<>'scope.read' THEN
  PERFORM public.assert_data_prep_actor(_tenant,_actor,true);
  IF NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant AND user_id=_actor AND active IS TRUE AND role='tenant_admin') THEN RAISE EXCEPTION 'dps.active_tenant_admin_required' USING ERRCODE='42501';END IF;
 END IF;
 IF _operation='scope.groups' AND _setup IS NULL THEN
  RETURN;
 END IF;
 IF _setup IS NULL OR NOT EXISTS(SELECT 1 FROM private.dpd_setups WHERE id=_setup AND tenant_id=_tenant) THEN RAISE EXCEPTION 'dps.exact_setup_required' USING ERRCODE='42501';END IF;
 IF _operation='scope.decide' THEN
  IF NOT EXISTS(SELECT 1 FROM private.dpd_preview_links l JOIN private.dps_scope_requests q ON q.configuration_id=l.configuration_id AND q.pipeline_id=l.pipeline_id AND q.tenant_id=l.tenant_id
    JOIN private.dpd_setups s ON s.id=l.setup_id AND s.tenant_id=l.tenant_id AND s.created_by=q.created_by
    WHERE l.setup_id=_setup AND l.tenant_id=_tenant AND q.created_by<>_actor)
  THEN RAISE EXCEPTION 'dps.independent_setup_scope_required' USING ERRCODE='42501';END IF;
 ELSIF _operation='scope.read' THEN
  IF NOT EXISTS(SELECT 1 FROM private.dpd_setups WHERE id=_setup AND tenant_id=_tenant AND created_by=_actor)
   AND NOT EXISTS(SELECT 1 FROM private.dpd_preview_links l WHERE l.setup_id=_setup AND l.tenant_id=_tenant AND private.data_prep_pipeline_scope_allows(_actor,_tenant,l.pipeline_id,'view') IS TRUE)
  THEN RAISE EXCEPTION 'dps.current_read_scope_required' USING ERRCODE='42501';END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM private.dpd_setups WHERE id=_setup AND tenant_id=_tenant AND created_by=_actor) THEN RAISE EXCEPTION 'dps.original_setup_creator_required' USING ERRCODE='42501';END IF;
 END IF;
END $function$
;

CREATE OR REPLACE FUNCTION public.dps_issue_request_context(_tenant_id uuid, _verified_subject jsonb, _trusted_ip text, _ttl_seconds integer, _operation text, _setup_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid;enabled boolean;ip inet;expires timestamptz;c private.dpd_request_contexts%ROWTYPE;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR current_setting('role',true) IS DISTINCT FROM 'service_role' OR _ttl_seconds NOT BETWEEN 1 AND 60 OR _ttl_seconds IS NULL
 OR _operation NOT IN('scope.groups','scope.save','scope.read','scope.lookup','scope.decide') OR _operation IS NULL THEN RAISE EXCEPTION 'dps.fixed_server_issuer_required' USING ERRCODE='42501';END IF;
 actor:=private.dpd_peer_actor(_tenant_id,_verified_subject);
 IF public.user_has_permission(actor,_tenant_id,CASE WHEN _operation IN('scope.save','scope.decide') THEN 'data.prep.author' ELSE 'data.prep.read' END,NULL) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'dps.current_capability_required' USING ERRCODE='42501';END IF;
 PERFORM private.dps_setup_admission(_tenant_id,_setup_id,actor,_operation);
 SELECT ip_allowlist_enabled INTO enabled FROM public.tenant_security_settings WHERE tenant_id=_tenant_id;
 IF NOT FOUND OR enabled IS NULL THEN RAISE EXCEPTION 'dps.current_network_unavailable' USING ERRCODE='42501';END IF;
 BEGIN ip:=nullif(_trusted_ip,'')::inet;EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'dps.fixed_transport_ip_invalid' USING ERRCODE='42501';END;
 IF enabled AND (ip IS NULL OR public.ip_in_tenant_allowlist(_tenant_id,host(ip)) IS DISTINCT FROM true) THEN RAISE EXCEPTION 'dps.current_bound_network_denied' USING ERRCODE='42501';END IF;
 expires:=least(clock_timestamp()+_ttl_seconds*interval '1 second',to_timestamp((_verified_subject->>'exp')::double precision));IF expires<=clock_timestamp() THEN RAISE EXCEPTION 'dps.subject_expired' USING ERRCODE='42501';END IF;
 c.id:=gen_random_uuid();INSERT INTO private.dpd_request_contexts(id,token_sha256,tenant_id,actor_id,verified_subject,operation,setup_id,intent_sha256,transport_kind,request_ip,transport_attestation_sha256,expires_at)
 VALUES(c.id,encode(sha256(convert_to(c.id::text,'UTF8')),'hex'),_tenant_id,actor,_verified_subject,_operation,_setup_id,private.dpw_hash(jsonb_build_object('operation',_operation,'setup_id',_setup_id)),
 'main_fixed_service_verified_middleware_CF_transport',ip,private.dpw_hash(jsonb_build_object('actor',actor,'tenant',_tenant_id,'operation',_operation,'setup',_setup_id,'issuer_role','service_role')),expires) RETURNING * INTO c;
 PERFORM private.dpw_audit(actor,_tenant_id,'dps.request_context.issued',c.id,jsonb_build_object('operation',_operation,'setup_id',_setup_id,'expires_at',expires,'browser_issuance_allowed',false));
 RETURN jsonb_build_object('request_context_id',c.id,'actor_id',actor,'tenant_id',_tenant_id,'operation',_operation,'setup_id',_setup_id,'expires_at',expires,
 'network_policy_available',true,'network_policy_enabled',enabled,'network_allowed',true,'issuer_transport','service_role','verified_subject_expires_at',to_timestamp((_verified_subject->>'exp')::double precision),'browser_issuance_allowed',false);
END $function$
;

CREATE OR REPLACE FUNCTION private.dps_context_actor(_tenant uuid, _setup uuid, _operation text, _context uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=auth.uid();c private.dpd_request_contexts%ROWTYPE;enabled boolean;
BEGIN
 IF actor IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR current_setting('role',true) IS DISTINCT FROM 'authenticated' OR _context IS NULL THEN RAISE EXCEPTION 'dps.original_authenticated_context_required' USING ERRCODE='42501';END IF;
 SELECT * INTO c FROM private.dpd_request_contexts WHERE id=_context AND tenant_id=_tenant AND actor_id=actor AND operation=_operation AND setup_id IS NOT DISTINCT FROM _setup;
 IF NOT FOUND OR c.expires_at<=clock_timestamp() OR c.verified_subject->>'sub' IS DISTINCT FROM actor::text OR c.verified_subject->>'aal' IS DISTINCT FROM auth.jwt()->>'aal' OR c.verified_subject->>'exp' IS DISTINCT FROM auth.jwt()->>'exp'
 THEN RAISE EXCEPTION 'dps.fresh_same_subject_context_required' USING ERRCODE='42501';END IF;
 IF private.dpd_peer_actor(_tenant,c.verified_subject) IS DISTINCT FROM actor THEN RAISE EXCEPTION 'dps.current_subject_denied' USING ERRCODE='42501';END IF;
 IF public.user_has_permission(actor,_tenant,CASE WHEN _operation IN('scope.save','scope.decide','preview.bind') THEN 'data.prep.author' ELSE 'data.prep.read' END,NULL) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dps.current_capability_required' USING ERRCODE='42501';END IF;
 PERFORM private.dps_setup_admission(_tenant,_setup,actor,_operation);
 SELECT ip_allowlist_enabled INTO enabled FROM public.tenant_security_settings WHERE tenant_id=_tenant;
 IF NOT FOUND OR enabled IS NULL OR (enabled AND (c.request_ip IS NULL OR public.ip_in_tenant_allowlist(_tenant,host(c.request_ip)) IS DISTINCT FROM true)) THEN RAISE EXCEPTION 'dps.current_bound_network_denied' USING ERRCODE='42501';END IF;
 RETURN actor;
END $function$
;

CREATE OR REPLACE FUNCTION public.issue_user_delegated_api_token(_tenant_id uuid, _name text, _prefix text, _token_hash text, _scopes text[], _expires_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid := auth.uid(); token_id uuid; audit_id bigint; slug text;
BEGIN
 IF auth.role() IS DISTINCT FROM 'authenticated' OR current_setting('role',true) IS DISTINCT FROM 'authenticated'
   OR actor IS NULL THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 IF _tenant_id IS NULL OR _name IS NULL OR length(btrim(_name)) NOT BETWEEN 1 AND 120
   OR _prefix IS NULL OR _prefix !~ '^fvi_[0-9a-f]{8}$'
   OR _token_hash IS NULL OR _token_hash !~ '^[0-9a-f]{64}$'
   OR _scopes IS NULL OR cardinality(_scopes) NOT BETWEEN 1 AND 22
   OR array_position(_scopes,NULL) IS NOT NULL OR NOT (_scopes <@ ARRAY['recons.read','recons.run','breaks.write','connectors.read','connectors.run','connectors.agent','watchers.read','watchers.write','data-prep.read','data-prep.write','data-prep.run','data-prep.approve','data-prep.promote','reference-data.read','reference-data.write','reference-data.approve','reports.read','environment-changes.read','environment-changes.write','environment-changes.approve','ai.inference','aidp:extract']::text[])
   OR cardinality(_scopes)<>(SELECT count(DISTINCT s) FROM unnest(_scopes) s)
   OR (_expires_at IS NOT NULL AND (_expires_at<=clock_timestamp() OR _expires_at>clock_timestamp()+interval '730 days')) THEN
   RAISE EXCEPTION 'invalid token issuance input' USING ERRCODE='22023';
 END IF;
 PERFORM 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=actor AND active=true AND role='tenant_admin' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 SELECT t.slug INTO slug FROM public.tenants t WHERE t.id=_tenant_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 -- Reject hash reuse without printing any token/hash. Existing hash index is nonunique.
 PERFORM pg_advisory_xact_lock(hashtextextended(_token_hash,743301));
 IF EXISTS(SELECT 1 FROM public.api_tokens WHERE token_hash=_token_hash) THEN
   RAISE EXCEPTION 'token collision' USING ERRCODE='23505';
 END IF;
 INSERT INTO public.api_tokens(tenant_id,name,prefix,token_hash,scopes,expires_at,created_by,principal_kind,subject_user_id)
 VALUES(_tenant_id,btrim(_name),_prefix,_token_hash,_scopes,_expires_at,actor,'user_delegated',actor) RETURNING id INTO token_id;
 INSERT INTO public.audit_log(tenant_id,tenant_slug,actor_user_id,scope,action,resource_type,resource_id,context)
 VALUES(_tenant_id,slug,actor,'tenant','api.token.create','api_tokens',token_id::text,
   jsonb_build_object('name',btrim(_name),'scopes',_scopes,'principal_kind','user_delegated','subject_user_id',actor)) RETURNING id INTO audit_id;
 IF NOT EXISTS(SELECT 1 FROM public.audit_log a JOIN public.audit_chain_head h ON h.singleton=true
   AND h.last_audit_id=a.id AND h.last_hash=a.row_hash WHERE a.id=audit_id
   AND a.actor_user_id=actor AND a.tenant_id=_tenant_id AND a.resource_id=token_id::text AND octet_length(a.row_hash)=32) THEN
   RAISE EXCEPTION 'token issuance audit receipt absent';
 END IF;
 RETURN jsonb_build_object('id',token_id,'audit_id',audit_id::text);
END $function$
;

CREATE OR REPLACE FUNCTION public.dps_list_groups(_tenant_id uuid, _owning_business_unit_ids uuid[], _search text DEFAULT ''::text, _page integer DEFAULT 1, _page_size integer DEFAULT 50, _request_context_id uuid DEFAULT NULL::uuid, _setup_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN PERFORM private.dps_context_actor(_tenant_id,_setup_id,'scope.groups',_request_context_id);RETURN private.dps_list_groups_core(_tenant_id,_owning_business_unit_ids,_search,_page,_page_size);END $function$
;

CREATE OR REPLACE FUNCTION public.revoke_user_delegated_api_token(_tenant_id uuid, _token_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid := auth.uid(); audit_id bigint; slug text;
BEGIN
 IF auth.role() IS DISTINCT FROM 'authenticated' OR current_setting('role',true) IS DISTINCT FROM 'authenticated'
   OR actor IS NULL THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=actor AND active=true AND role='tenant_admin' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 SELECT t.slug INTO slug FROM public.tenants t WHERE t.id=_tenant_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.api_tokens WHERE id=_token_id AND tenant_id=_tenant_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 -- Idempotent repeat keeps the existing timestamp and creates an attributed receipt.
 UPDATE public.api_tokens SET revoked_at=coalesce(revoked_at,clock_timestamp()) WHERE id=_token_id AND tenant_id=_tenant_id;
 INSERT INTO public.audit_log(tenant_id,tenant_slug,actor_user_id,scope,action,resource_type,resource_id,context)
 VALUES(_tenant_id,slug,actor,'tenant','api.token.revoke','api_tokens',_token_id::text,'{}') RETURNING id INTO audit_id;
 IF NOT EXISTS(SELECT 1 FROM public.audit_log a JOIN public.audit_chain_head h ON h.singleton=true
   AND h.last_audit_id=a.id AND h.last_hash=a.row_hash WHERE a.id=audit_id
   AND a.actor_user_id=actor AND a.tenant_id=_tenant_id AND a.resource_id=_token_id::text AND octet_length(a.row_hash)=32) THEN
   RAISE EXCEPTION 'token revocation audit receipt absent';
 END IF;
 RETURN jsonb_build_object('id',_token_id,'audit_id',audit_id::text);
END $function$
;

CREATE OR REPLACE FUNCTION private.recon_api_persisted_result_page(_tenant_id uuid, _run_id uuid, _page integer DEFAULT 0, _status text DEFAULT 'all'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'private'
 SET row_security TO 'on'
AS $function$
DECLARE
  definition_id uuid;
  result jsonb;
BEGIN
  IF _tenant_id IS NULL OR _run_id IS NULL OR _page IS NULL OR _page < 0 THEN
    RAISE EXCEPTION 'tenant, run and non-negative page are required' USING ERRCODE = '22023';
  END IF;
  IF _status IS NULL OR _status NOT IN ('all','match','partial','missing','duplicate','invalid_key','other','unavailable') THEN
    RAISE EXCEPTION 'unsupported run result status' USING ERRCODE = '22023';
  END IF;

  WITH exception_base AS (
    SELECT e.*,
      CASE WHEN e.payload->>'disposition' = 'keyless_input' THEN 'invalid_key'
        WHEN CASE WHEN jsonb_typeof(private.recon_result_missing_sides(e.payload)) = 'array' THEN jsonb_array_length(private.recon_result_missing_sides(e.payload)) > 0 ELSE false END THEN 'missing'
        WHEN e.payload->>'rule_kind' = 'unique' THEN 'duplicate'
        WHEN jsonb_typeof(e.payload->'key') = 'string' AND jsonb_typeof(e.payload->'sides') = 'object' THEN 'partial'
        WHEN e.payload IS NULL OR e.payload = '{}'::jsonb THEN 'unavailable' ELSE 'other' END AS status_bucket,
      CASE WHEN CASE WHEN jsonb_typeof(private.recon_result_missing_sides(e.payload)) = 'array' THEN jsonb_array_length(private.recon_result_missing_sides(e.payload)) > 0 ELSE false END
          AND jsonb_typeof(e.payload->'key') = 'string'
        THEN 'missing:' || jsonb_build_array(e.payload->'key', private.recon_result_missing_sides(e.payload))::text
        ELSE 'exception:' || e.id::text END AS parent_key
    FROM public.recon_exceptions e WHERE e.tenant_id = _tenant_id AND e.run_id = _run_id
  ), exception_items AS (
    SELECT parent_key, status_bucket, min(created_at) AS created_at,
      jsonb_agg(jsonb_build_object('id',id,'public_case_id',public_case_id,'side',side,'reason',reason,'status',status,
        'payload',payload,'created_at',created_at) ORDER BY created_at,id) AS items
    FROM exception_base GROUP BY parent_key,status_bucket
  ), source_rows AS (
    SELECT parent_key, side, jsonb_agg(source_row ORDER BY created_at,id,member_order) AS rows
    FROM (
      SELECT parent_key,side,payload->'row' AS source_row,created_at,id,1 AS member_order
      FROM exception_base WHERE jsonb_typeof(payload->'row') = 'object'
      UNION ALL
      SELECT e.parent_key,side_entry.key,member_rows.row_data,e.created_at,e.id,member_rows.ordinality::integer
      FROM exception_base e
      CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(e.payload->'members')='object' THEN e.payload->'members' WHEN jsonb_typeof(e.payload->'sides')='object' THEN e.payload->'sides' ELSE '{}'::jsonb END) side_entry
      CROSS JOIN LATERAL jsonb_array_elements(
        CASE WHEN jsonb_typeof(side_entry.value)='array' THEN side_entry.value ELSE jsonb_build_array(side_entry.value) END
      ) WITH ORDINALITY AS member_rows(row_data,ordinality)
    ) values_by_side
    GROUP BY parent_key,side
  ), source_members AS (
    SELECT parent_key, jsonb_object_agg(side,rows) AS members
    FROM source_rows GROUP BY parent_key
  ), exception_parents AS (
    SELECT i.parent_key,i.status_bucket,i.created_at,i.items,
      COALESCE(s.members,'{}'::jsonb) AS members
    FROM exception_items i LEFT JOIN source_members s USING (parent_key)
  ), result_rows AS (
    SELECT m.created_at,'match:'||m.id::text AS result_id,'match'::text AS status_bucket,
      jsonb_build_object('kind','match','id',m.id,'created_at',m.created_at,'rule_id',m.rule_id,
        'cardinality',m.cardinality,'members',m.members,'exception_items','[]'::jsonb) AS row
    FROM public.recon_matches m WHERE m.tenant_id=_tenant_id AND m.run_id=_run_id
    UNION ALL
    SELECT p.created_at,p.parent_key,p.status_bucket,
      jsonb_build_object('kind','exception','id',p.parent_key,'created_at',p.created_at,
        'status_bucket',p.status_bucket,'members',p.members,'exception_items',p.items) AS row
    FROM exception_parents p
  ), filtered AS (
    SELECT * FROM result_rows WHERE _status='all' OR status_bucket=_status
  ), counts AS (
    SELECT count(*) AS parent_count FROM filtered
  ), page AS (
    SELECT row,created_at,result_id FROM filtered ORDER BY created_at,result_id OFFSET _page*50 LIMIT 50
  ), fields AS (
    SELECT COALESCE(jsonb_agg(field_name ORDER BY field_name),'[]'::jsonb) AS names
    FROM (
      SELECT DISTINCT field_name FROM (
        SELECT field.key AS field_name
        FROM public.recon_matches m
        CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(m.members)='object' THEN m.members ELSE '{}'::jsonb END) side
        CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(side.value)='array' THEN side.value ELSE jsonb_build_array(side.value) END) member
        CROSS JOIN LATERAL jsonb_object_keys(CASE WHEN jsonb_typeof(member.value)='object' THEN member.value ELSE '{}'::jsonb END) field(key)
        WHERE m.tenant_id=_tenant_id AND m.run_id=_run_id
        UNION ALL
        SELECT field.key
        FROM public.recon_exceptions e
        CROSS JOIN LATERAL jsonb_object_keys(CASE WHEN jsonb_typeof(e.payload->'row')='object' THEN e.payload->'row' ELSE '{}'::jsonb END) field(key)
        WHERE e.tenant_id=_tenant_id AND e.run_id=_run_id
        UNION ALL
        SELECT field.key
        FROM public.recon_exceptions e
        CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(e.payload->'members')='object' THEN e.payload->'members' WHEN jsonb_typeof(e.payload->'sides')='object' THEN e.payload->'sides' ELSE '{}'::jsonb END) side
        CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(side.value)='array' THEN side.value ELSE jsonb_build_array(side.value) END) AS member_rows(row_data)
        CROSS JOIN LATERAL jsonb_object_keys(CASE WHEN jsonb_typeof(member_rows.row_data)='object' THEN member_rows.row_data ELSE '{}'::jsonb END) field(key)
        WHERE e.tenant_id=_tenant_id AND e.run_id=_run_id
      ) all_fields
    ) distinct_fields
  )
  SELECT jsonb_build_object('rows',COALESCE((SELECT jsonb_agg(page.row ORDER BY page.created_at,page.result_id) FROM page),'[]'::jsonb),
    'field_names',fields.names,
    'parent_count',counts.parent_count,'page',_page,'page_size',50,
    'has_next',((_page+1)*50 < counts.parent_count)) INTO result FROM counts CROSS JOIN fields;
  RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.recon_api_persisted_result_counts(_tenant_id uuid, _run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'private'
 SET row_security TO 'on'
AS $function$
DECLARE
  definition_id uuid;
  match_groups bigint;
  exception_items bigint;
  buckets jsonb;
BEGIN
  IF _tenant_id IS NULL OR _run_id IS NULL THEN
    RAISE EXCEPTION 'tenant and run are required' USING ERRCODE = '22023';
  END IF;
  SELECT count(*) INTO match_groups FROM public.recon_matches m
    WHERE m.tenant_id = _tenant_id AND m.run_id = _run_id;
  WITH categorized AS (
    SELECT CASE
      WHEN e.payload->>'disposition' = 'keyless_input' THEN 'invalid_key'
      WHEN CASE WHEN jsonb_typeof(private.recon_result_missing_sides(e.payload)) = 'array' THEN jsonb_array_length(private.recon_result_missing_sides(e.payload)) > 0 ELSE false END THEN 'missing'
      WHEN e.payload->>'rule_kind' = 'unique' THEN 'duplicate'
      WHEN jsonb_typeof(e.payload->'key') = 'string' AND jsonb_typeof(e.payload->'sides') = 'object' THEN 'partial'
      WHEN e.payload IS NULL OR e.payload = '{}'::jsonb THEN 'unavailable'
      ELSE 'other' END AS status_bucket
    FROM public.recon_exceptions e WHERE e.tenant_id = _tenant_id AND e.run_id = _run_id
  ), totals AS (
    SELECT status_bucket,count(*) AS item_count FROM categorized GROUP BY status_bucket
  )
  SELECT (SELECT count(*) FROM categorized), jsonb_build_object(
    'partial',COALESCE((SELECT item_count FROM totals WHERE status_bucket='partial'),0),
    'missing',COALESCE((SELECT item_count FROM totals WHERE status_bucket='missing'),0),
    'duplicate',COALESCE((SELECT item_count FROM totals WHERE status_bucket='duplicate'),0),
    'invalid_key',COALESCE((SELECT item_count FROM totals WHERE status_bucket='invalid_key'),0),
    'other',COALESCE((SELECT item_count FROM totals WHERE status_bucket='other'),0),
    'unavailable',COALESCE((SELECT item_count FROM totals WHERE status_bucket='unavailable'),0)
  ) INTO exception_items,buckets;
  RETURN jsonb_build_object('run_id', _run_id, 'match_groups', match_groups,
    'exception_items', exception_items, 'exception_buckets', buckets,
    'semantics', jsonb_build_object('match','persisted recon_matches groups',
      'partial','exception items with persisted key and sides, excluding missing, duplicate and keyless markers',
      'missing','exception items with a non-empty persisted missing_sides array',
      'duplicate','exception items with persisted rule_kind unique',
      'invalid_key','exception items with persisted disposition keyless_input',
      'other','non-empty legacy payload not classified by the markers above',
      'unavailable','exception items with no usable payload', 'workflow_status_is_separate',true));
END;
$function$
;

CREATE OR REPLACE FUNCTION public.dps_decide_scope(_tenant_id uuid, _request_id uuid, _decision text, _reason text, _request_context_id uuid DEFAULT NULL::uuid, _setup_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 PERFORM private.dps_context_actor(_tenant_id,_setup_id,'scope.decide',_request_context_id);
 IF NOT EXISTS(SELECT 1 FROM private.dpd_preview_links l JOIN private.dps_scope_requests q ON q.configuration_id=l.configuration_id AND q.pipeline_id=l.pipeline_id AND q.tenant_id=l.tenant_id WHERE q.id=_request_id AND l.setup_id=_setup_id AND l.tenant_id=_tenant_id)
 THEN RAISE EXCEPTION 'dps.exact_request_setup_binding_required' USING ERRCODE='42501';END IF;
 RETURN private.dps_decide_scope_core(_tenant_id,_request_id,_decision,_reason);
END $function$
;

CREATE OR REPLACE FUNCTION private.settle_public_ai_dispatch(_attempt_id uuid, _tokens_in integer, _tokens_out integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid:=(SELECT subject_user_id FROM private.public_ai_inference_requests WHERE id=_attempt_id); r public.copilot_spend_reservations%ROWTYPE; actual_c numeric; actual_t numeric;
BEGIN
 IF actor IS NULL OR _tokens_in IS NULL OR _tokens_out IS NULL OR _tokens_in<0 OR _tokens_out<0 THEN RAISE EXCEPTION 'copilot.usage_unavailable'; END IF;
 PERFORM pg_advisory_xact_lock(61000,1);
 SELECT * INTO r FROM public.copilot_spend_reservations WHERE id=_attempt_id::text FOR UPDATE;
 IF NOT FOUND OR r.actor_id<>actor OR r.llm_provider_id IS NULL THEN RAISE EXCEPTION 'copilot.forbidden'; END IF;
 IF r.state='settled' AND r.tokens_in=_tokens_in AND r.tokens_out=_tokens_out THEN RETURN jsonb_build_object('settled',true); END IF;
 IF r.state<>'dispatched' THEN RAISE EXCEPTION 'copilot.settlement_conflict'; END IF;
 actual_t:=_tokens_in::numeric+_tokens_out;
 actual_c:=ceil(_tokens_in::numeric*r.input_rate+_tokens_out::numeric*r.output_rate);
 IF actual_t=0 OR actual_c<=0 THEN RAISE EXCEPTION 'copilot.usage_unavailable'; END IF;
 -- Authenticated reports are NOT a trusted provider attestation. Keep a bound
 -- floor in enforcement, so forged zero/small counters cannot release money.
 UPDATE public.copilot_spend_reservations SET state='settled',tokens_in=_tokens_in,tokens_out=_tokens_out,
   actual_tokens=actual_t,actual_micro_usd=actual_c,accounted_tokens=greatest(bound_tokens,actual_t),
   accounted_micro_usd=greatest(bound_micro_usd,actual_c) WHERE id=r.id;
 IF r.tenant_id IS NOT NULL THEN
   INSERT INTO public.ai_usage_events(tenant_id,user_id,scope,model,tokens_in,tokens_out,cost_usd,meta)
   VALUES(r.tenant_id,actor,'copilot',r.model_key,_tokens_in,_tokens_out,actual_c/1000000,
     jsonb_build_object('public_request_id',_attempt_id::text,'source','ai_inference_router.http','copilot_reservation_id',r.id,'pricing_basis',r.pricing_basis,'usage_source','server_upstream_response',
       'budget_enforcement','catalog_bound_floor'));
 END IF;
 RETURN jsonb_build_object('settled',true);
END $function$
;

CREATE OR REPLACE FUNCTION public.dps_get_scope(_tenant_id uuid, _pipeline_id uuid, _request_context_id uuid DEFAULT NULL::uuid, _setup_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN PERFORM private.dps_context_actor(_tenant_id,_setup_id,'scope.read',_request_context_id);
 IF NOT EXISTS(SELECT 1 FROM private.dpd_preview_links WHERE setup_id=_setup_id AND tenant_id=_tenant_id AND pipeline_id=_pipeline_id) THEN RAISE EXCEPTION 'dps.setup_pipeline_binding_required' USING ERRCODE='42501';END IF;
 RETURN private.dps_get_scope_core(_tenant_id,_pipeline_id);END $function$
;

CREATE OR REPLACE FUNCTION public.dps_lookup_request(_tenant_id uuid, _request_key uuid, _request_context_id uuid DEFAULT NULL::uuid, _setup_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE saved jsonb;
BEGIN PERFORM private.dps_context_actor(_tenant_id,_setup_id,'scope.lookup',_request_context_id);saved:=private.dps_lookup_request_core(_tenant_id,_request_key);
 IF (saved->>'found')::boolean AND NOT EXISTS(SELECT 1 FROM private.dpd_preview_links WHERE setup_id=_setup_id AND tenant_id=_tenant_id AND configuration_id=(saved->'saved'->>'configuration_id')::uuid) THEN RAISE EXCEPTION 'dps.lookup_setup_binding_required' USING ERRCODE='42501';END IF;RETURN saved;END $function$
;

CREATE OR REPLACE FUNCTION public.dpd_get_authoring_shared_review(_tenant_id uuid, _setup_id uuid, _draft_version integer, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'review.shared.read',_request_context_id);l private.dpd_preview_links%ROWTYPE;review jsonb;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,true);
 SELECT * INTO l FROM private.dpd_preview_links WHERE tenant_id=_tenant_id AND setup_id=_setup_id AND draft_version=_draft_version;
 IF NOT FOUND THEN RAISE EXCEPTION 'dpd.actual_shared_review_binding_required' USING ERRCODE='PT409';END IF;
 review:=private.dps_get_scope_core(_tenant_id,l.pipeline_id);
 IF review->>'configuration_id' IS DISTINCT FROM l.configuration_id::text THEN RAISE EXCEPTION 'dpd.shared_review_configuration_changed' USING ERRCODE='PT409';END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'draft_version',l.draft_version,'pipeline_id',l.pipeline_id,'configuration_id',l.configuration_id,'review',review,'publish_allowed',false);
END $function$
;

CREATE OR REPLACE FUNCTION public.signup_invite_recovery(_action text, _attempt_id uuid, _email_hash text, _payload_hash text, _recovery_hash text, _lease_id uuid DEFAULT NULL::uuid, _outcome text DEFAULT NULL::text, _code text DEFAULT NULL::text, _status integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r public.signup_invitation_attempts; claimed boolean := false;
BEGIN
  IF _attempt_id IS NULL OR _email_hash IS NULL OR _payload_hash IS NULL OR _recovery_hash IS NULL
    OR _email_hash !~ '^[a-f0-9]{64}$' OR _payload_hash !~ '^[a-f0-9]{64}$' OR _recovery_hash !~ '^[a-f0-9]{64}$'
    OR _action NOT IN ('reserve','check','claim','defer','settle') OR _action IS NULL THEN
    RAISE EXCEPTION 'Invalid recovery request' USING ERRCODE='22023';
  END IF;
  IF _action IN ('reserve','check') THEN
    INSERT INTO public.signup_invitation_attempts(attempt_id,email_hash,payload_hash,recovery_hash)
      VALUES (_attempt_id,_email_hash,_payload_hash,_recovery_hash) ON CONFLICT DO NOTHING;
  END IF;
  SELECT * INTO r FROM public.signup_invitation_attempts WHERE attempt_id=_attempt_id
    AND email_hash=_email_hash AND payload_hash=_payload_hash AND recovery_hash=_recovery_hash FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('state','blocked');
  END IF;
  IF _action='claim' AND r.state IN ('reserved','not_sent') THEN
    BEGIN
      UPDATE public.signup_invitation_attempts SET state='sending',lease_id=pg_catalog.gen_random_uuid(),code=NULL,status=NULL,updated_at=now()
        WHERE attempt_id=r.attempt_id RETURNING * INTO r;
      claimed := true;
    EXCEPTION WHEN unique_violation THEN
      UPDATE public.signup_invitation_attempts SET state='blocked',updated_at=now()
        WHERE attempt_id=r.attempt_id RETURNING * INTO r;
    END;
  ELSIF _action='defer' AND r.state IN ('reserved','not_sent') THEN
    IF _code NOT IN ('SIGNUP_RATE_LIMITED','SIGNUP_NOT_STARTED') OR _status NOT IN (429,503) OR _code IS NULL OR _status IS NULL THEN
      RAISE EXCEPTION 'Invalid recovery result' USING ERRCODE='22023';
    END IF;
    UPDATE public.signup_invitation_attempts SET state='not_sent',code=_code,status=_status,updated_at=now()
      WHERE attempt_id=r.attempt_id RETURNING * INTO r;
  ELSIF _action='settle' THEN
    IF _outcome IS NULL OR _outcome NOT IN ('accepted','existing','unconfirmed') THEN
      RAISE EXCEPTION 'Invalid recovery result' USING ERRCODE='22023';
    END IF;
    IF r.state='sending' AND r.lease_id=_lease_id THEN
      UPDATE public.signup_invitation_attempts SET state=_outcome,updated_at=now()
        WHERE attempt_id=r.attempt_id RETURNING * INTO r;
    END IF;
  END IF;
  RETURN jsonb_build_object('state',r.state,'request_id',r.request_id,'code',r.code,'status',r.status,
    'claimed',claimed,'lease_id',CASE WHEN claimed THEN r.lease_id ELSE NULL END);
END $function$
;

CREATE OR REPLACE FUNCTION public.dpd_decide_authoring_shared_review(_tenant_id uuid, _setup_id uuid, _draft_version integer, _request_id uuid, _decision text, _reason text, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'review.shared.decide',_request_context_id);l private.dpd_preview_links%ROWTYPE;r private.dps_scope_requests%ROWTYPE;decision jsonb;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,true);
 SELECT * INTO l FROM private.dpd_preview_links WHERE tenant_id=_tenant_id AND setup_id=_setup_id AND draft_version=_draft_version;
 SELECT * INTO r FROM private.dps_scope_requests WHERE id=_request_id AND tenant_id=_tenant_id AND pipeline_id=l.pipeline_id AND configuration_id=l.configuration_id;
 IF l.setup_id IS NULL OR r.id IS NULL OR r.created_by=actor THEN RAISE EXCEPTION 'dpd.exact_independent_shared_scope_review_required' USING ERRCODE='42501';END IF;
 -- Native dps_decide_scope rechecks current admin/pipeline/input/group rights,
 -- its immutable original manifest, independent maker and exact grant/revoke set.
 decision:=private.dps_decide_scope_core(_tenant_id,r.id,_decision,_reason);
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'draft_version',l.draft_version,'pipeline_id',l.pipeline_id,'configuration_id',l.configuration_id,'request_id',r.id,'decision',decision->'decision','is_new',(decision->>'is_new')::boolean,'publish_allowed',false);
END $function$
;

CREATE OR REPLACE FUNCTION private.dpdi_head(_job uuid)
 RETURNS private.dpdi_job_events
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$SELECT e FROM private.dpdi_job_events e WHERE e.job_id=_job ORDER BY e.id DESC LIMIT 1$function$
;

CREATE OR REPLACE FUNCTION private.dpdi_authorize(_tenant uuid, _setup uuid, _job uuid, _actor uuid, _write boolean)
 RETURNS private.dpdi_jobs
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE j private.dpdi_jobs%ROWTYPE;l private.dpd_preview_links%ROWTYPE;p public.data_prep_pipelines%ROWTYPE;c public.data_prep_configuration_revisions%ROWTYPE;i private.dpd_preview_file_links%ROWTYPE;b public.data_prep_delivery_batches%ROWTYPE;
BEGIN
 SELECT * INTO j FROM private.dpdi_jobs WHERE id=_job AND tenant_id=_tenant AND setup_id=_setup AND (NOT _write OR actor_id=_actor);
 SELECT * INTO l FROM private.dpd_preview_links WHERE setup_id=j.setup_id AND draft_version=j.draft_version AND tenant_id=_tenant;
 SELECT * INTO p FROM public.data_prep_pipelines WHERE id=l.pipeline_id AND tenant_id=_tenant;SELECT * INTO c FROM public.data_prep_configuration_revisions WHERE id=l.configuration_id AND tenant_id=_tenant;
 SELECT * INTO b FROM public.data_prep_delivery_batches WHERE id=(j.snapshot->>'batch_id')::uuid AND tenant_id=_tenant;
 IF j.id IS NULL OR l.setup_id IS NULL OR p.id IS NULL OR c.id IS NULL OR p.lifecycle_state='archived' OR c.pipeline_version<>l.pipeline_version OR b.mode IS DISTINCT FROM j.snapshot->>'mode' OR j.snapshot->>'mode' NOT IN('preview','prepare') OR (j.snapshot->>'mode'='prepare' AND (j.snapshot->>'approval_origin' IS DISTINCT FROM 'dpdi_setup_review_v1' OR NOT EXISTS(SELECT 1 FROM private.dpdi_setup_review_decisions sd JOIN private.dpdi_setup_review_requests sr ON sr.id=sd.request_id WHERE sd.id=(j.snapshot->>'setup_review_decision_id')::uuid AND sd.decision='approved' AND sr.setup_id=j.setup_id AND sr.draft_version=j.draft_version AND sd.decided_by<>sr.requested_by)))
 OR private.dpw_mode_attest(_actor,_tenant,p.id,b.execution_mode,b.human_in_loop) IS DISTINCT FROM true
 OR private.data_prep_pipeline_scope_allows(_actor,_tenant,p.id,CASE WHEN _write THEN 'run' ELSE 'view' END) IS DISTINCT FROM true
 OR (_write AND (p.status NOT IN('draft','approved') OR p.version<>l.pipeline_version OR (SELECT max(v.version) FROM private.dpd_versions v WHERE v.setup_id=j.setup_id)<>j.draft_version OR c.payload_sha256 IS DISTINCT FROM j.snapshot->>'configuration_sha256'))
 THEN RAISE EXCEPTION 'dpdi.current_exact_preview_origin_required' USING ERRCODE='42501';END IF;
 FOR i IN SELECT * FROM private.dpd_preview_file_links WHERE setup_id=j.setup_id AND draft_version=j.draft_version LOOP
  IF private.dpw_source_allows(_actor,_tenant,i.data_source_id,'view') IS DISTINCT FROM true OR (_write AND (private.dpw_source_allows(_actor,_tenant,i.data_source_id,'ingest') IS DISTINCT FROM true OR NOT private.dpd_original_viewable(i.original_file_id))) THEN RAISE EXCEPTION 'dpdi.current_original_source_denied' USING ERRCODE='42501';END IF;
 END LOOP;RETURN j;
END $function$
;

CREATE OR REPLACE FUNCTION private.dpdi_dto(j private.dpdi_jobs)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE e private.dpdi_job_events%ROWTYPE:=private.dpdi_head(j.id);r public.data_prep_delivery_runs%ROWTYPE;
BEGIN SELECT * INTO r FROM public.data_prep_delivery_runs WHERE id=j.reserved_run_id;
 RETURN jsonb_build_object('actor_id',j.actor_id,'execution_actor_id',j.actor_id,'tenant_id',j.tenant_id,'setup_id',j.setup_id,'draft_version',j.draft_version,'job_id',j.id,'run_id',r.id,'reserved_run_id',j.reserved_run_id,'request_key',j.request_key,'mode',j.snapshot->>'mode','input_binding_kind','authoring_original_pinned','phase',e.phase,'input_index',e.input_index,'next_record',e.next_record::text,'source_records',e.source_records::text,'blocking_records',e.blocking_records::text,'output_pages',e.output_pages,'output_root_sha256',e.output_root_sha256,'last_page_sha256',e.last_page_sha256,'claim_key',e.claim_key,'lease_expires_at',e.lease_expires_at,'snapshot_sha256',j.snapshot_sha256,'full_final_ack',e.phase IN('success','blocked'),'released_rows','0','publication_eligible',false,'publish_allowed',false);
END $function$
;

CREATE OR REPLACE FUNCTION private.dpdi_live_lease(j private.dpdi_jobs, _claim uuid)
 RETURNS private.dpdi_job_events
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE e private.dpdi_job_events%ROWTYPE:=private.dpdi_head(j.id);BEGIN IF e.phase<>'running' OR e.claim_key IS DISTINCT FROM _claim OR e.lease_expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'dpdi.actual_live_owned_lease_required' USING ERRCODE='42501';END IF;RETURN e;END $function$
;

CREATE OR REPLACE FUNCTION public.dpdi_claim_preview(_tenant_id uuid, _setup_id uuid, _job_id uuid, _claim_key uuid, _lease_seconds integer, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'preview.job.claim',_request_context_id);j private.dpdi_jobs%ROWTYPE:=private.dpdi_authorize(_tenant_id,_setup_id,_job_id,actor,true);e private.dpdi_job_events%ROWTYPE;expires timestamptz;run public.data_prep_delivery_runs%ROWTYPE;firstidx integer;terminal jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('dpdi-preview:'||_tenant_id::text||':'||_setup_id::text,0));PERFORM 1 FROM private.dpdi_jobs WHERE id=j.id FOR UPDATE;e:=private.dpdi_head(j.id);
 IF _claim_key IS NULL OR _lease_seconds IS NULL OR _lease_seconds NOT BETWEEN 1 AND 60 THEN RAISE EXCEPTION 'dpdi.bounded_actual_claim_required' USING ERRCODE='22023';END IF;
 IF e.phase IN('success','blocked','cancelled') OR (e.phase='running' AND e.lease_expires_at>clock_timestamp()) THEN RETURN private.dpdi_dto(j)||jsonb_build_object('claimed',false);END IF;
 IF EXISTS(SELECT 1 FROM private.dpdi_jobs older CROSS JOIN LATERAL private.dpdi_head(older.id) head WHERE older.setup_id=j.setup_id AND older.id<>j.id AND (head.phase='running' AND head.lease_expires_at>clock_timestamp() OR head.phase IN('queued','running') AND (older.created_at,older.id)<(j.created_at,j.id))) THEN RETURN private.dpdi_dto(j)||jsonb_build_object('claimed',false,'queue_blocked',true);END IF;
 expires:=least(clock_timestamp()+_lease_seconds*interval '1 second',to_timestamp((auth.jwt()->>'exp')::double precision));
 SELECT * INTO run FROM public.data_prep_delivery_runs WHERE id=j.reserved_run_id;
 IF NOT FOUND THEN
  INSERT INTO public.data_prep_delivery_runs(id,tenant_id,pipeline_id,batch_id,pipeline_version,request_key,started_by,snapshot,snapshot_sha256,state) VALUES(j.reserved_run_id,_tenant_id,(j.snapshot->>'pipeline_id')::uuid,(j.snapshot->>'batch_id')::uuid,(j.snapshot->>'pipeline_version')::integer,j.request_key,actor,j.snapshot,j.snapshot_sha256,'running');
  IF j.snapshot->>'mode'='prepare' THEN UPDATE public.data_prep_delivery_batches SET state='processing' WHERE id=(j.snapshot->>'batch_id')::uuid AND state='collecting';END IF;
  INSERT INTO private.dpdi_run_inputs(run_id,job_id,input_id,original_file_id,data_source_id,rows_count,selection_sha256) SELECT j.reserved_run_id,j.id,i.id,i.original_file_id,i.data_source_id,i.rows_count,i.selection_sha256 FROM private.dpd_preview_file_links i WHERE i.setup_id=j.setup_id AND i.draft_version=j.draft_version;
 END IF;
 firstidx:=e.input_index;WHILE firstidx<jsonb_array_length(j.snapshot->'inputs') AND (j.snapshot->'inputs'->firstidx->>'rows_count')::bigint=0 LOOP firstidx:=firstidx+1;END LOOP;
 IF firstidx=jsonb_array_length(j.snapshot->'inputs') AND e.source_records=0 THEN
  terminal:=jsonb_build_object('representation','dpdi_authoring_pages_v1','mode',j.snapshot->>'mode','job_id',j.id,'status','success','publication_eligible',false,'source_records','0','blocking_records','0','preview_rows','0','full_final_ack',true,'zero_source_basis','actual_confirmed_allow_empty_selections');
  INSERT INTO private.dpdi_job_events(job_id,actor_id,phase,claim_key,lease_expires_at,input_index) VALUES(j.id,actor,'success',_claim_key,expires,firstidx);
  UPDATE public.data_prep_delivery_runs SET state='success',result=terminal,result_sha256=private.dpw_hash(terminal),finished_at=clock_timestamp() WHERE id=j.reserved_run_id AND state='running';
 ELSE
  INSERT INTO private.dpdi_job_events(job_id,actor_id,phase,claim_key,lease_expires_at,input_index,next_record,source_records,blocking_records,output_pages,output_root_sha256,last_page_sha256) VALUES(j.id,actor,'running',_claim_key,expires,firstidx,e.next_record,e.source_records,e.blocking_records,e.output_pages,e.output_root_sha256,e.last_page_sha256);
 END IF;
 RETURN private.dpdi_dto(j)||jsonb_build_object('claimed',true,'snapshot',j.snapshot);
END $function$
;

CREATE OR REPLACE FUNCTION public.dpdi_get_preview_job(_tenant_id uuid, _setup_id uuid, _job_id uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'preview.job.status',_request_context_id);j private.dpdi_jobs%ROWTYPE:=private.dpdi_authorize(_tenant_id,_setup_id,_job_id,actor,false);BEGIN RETURN private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'execution_actor_id',j.actor_id,'head_event_id',(private.dpdi_head(j.id)).id::text,'terminal_intent',(SELECT private.dpdi_terminal_intent_dto(t) FROM private.dpdi_terminal_intents t WHERE t.job_id=j.id));END $function$
;

CREATE OR REPLACE FUNCTION public.dpdi_enqueue_preview(_tenant_id uuid, _setup_id uuid, _draft_version integer, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'preview.job.enqueue',_request_context_id);s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,true);l private.dpd_preview_links%ROWTYPE;v private.dpd_versions%ROWTYPE;c public.data_prep_configuration_revisions%ROWTYPE;b public.data_prep_delivery_batches%ROWTYPE;j private.dpdi_jobs%ROWTYPE;snap jsonb;inputs jsonb;
BEGIN
 PERFORM 1 FROM private.dpd_setups WHERE id=s.id FOR UPDATE;SELECT * INTO l FROM private.dpd_preview_links WHERE setup_id=s.id AND draft_version=_draft_version;SELECT * INTO v FROM private.dpd_versions WHERE setup_id=s.id ORDER BY version DESC LIMIT 1;
 SELECT * INTO c FROM public.data_prep_configuration_revisions WHERE id=l.configuration_id;SELECT * INTO b FROM public.data_prep_delivery_batches WHERE id=l.batch_id;
 IF l.setup_id IS NULL OR v.version<>_draft_version OR _request_key IS NULL OR b.mode IS DISTINCT FROM 'preview' THEN RAISE EXCEPTION 'dpdi.actual_current_authoring_preview_required' USING ERRCODE='PT409';END IF;
 PERFORM private.dpd_validate_confirmed_mapping(_tenant_id,s.id,v.version,v.payload->'confirmed_mapping');PERFORM private.dpw_authorize(_tenant_id,l.pipeline_id,'run');
 SELECT jsonb_agg(jsonb_build_object('input_id',i.id,'original_file_id',i.original_file_id,'data_source_id',i.data_source_id,'feed_key',i.feed_key,'selection',i.selection,'selection_sha256',i.selection_sha256,'rows_count',i.rows_count::text,'dpw_file_id',NULL,'upload_id',NULL) ORDER BY i.feed_key,i.id) INTO inputs FROM private.dpd_preview_file_links i WHERE i.setup_id=s.id AND i.draft_version=v.version;
 IF inputs IS NULL OR (SELECT sum((x.value->>'rows_count')::bigint) FROM jsonb_array_elements(inputs) AS x(value))>1000000 THEN RAISE EXCEPTION 'dpdi.complete_selected_input_budget_required';END IF;
 snap:=jsonb_build_object('tenant_id',_tenant_id,'setup_id',s.id,'draft_version',v.version,'pipeline_id',l.pipeline_id,'pipeline_version',l.pipeline_version,'configuration_id',l.configuration_id,'configuration_sha256',c.payload_sha256,'batch_id',l.batch_id,'business_date',b.business_date,'mode','preview','configuration_status',(SELECT p.status FROM public.data_prep_pipelines p WHERE p.id=l.pipeline_id),'input_binding_kind','authoring_original_pinned','inputs',inputs,'input_manifest_sha256',l.input_manifest_sha256,'confirmed_mapping',v.payload->'confirmed_mapping','confirmed_mapping_sha256',private.dpw_hash(v.payload->'confirmed_mapping'),'pipeline_configuration',c.payload,'feeds',c.payload->'feeds','publish_allowed',false);
 SELECT * INTO j FROM private.dpdi_jobs WHERE tenant_id=_tenant_id AND actor_id=actor AND request_key=_request_key;
 IF FOUND THEN IF j.setup_id<>s.id OR j.draft_version<>v.version OR j.snapshot IS DISTINCT FROM snap THEN RAISE EXCEPTION 'dpdi.preview_request_conflict' USING ERRCODE='PT409';END IF;RETURN private.dpdi_dto(j)||jsonb_build_object('request_replay',true);END IF;
 PERFORM private.dpd_assert_transform_configuration(snap->'pipeline_configuration');
 INSERT INTO private.dpdi_jobs(tenant_id,setup_id,draft_version,actor_id,request_key,snapshot,snapshot_sha256) VALUES(_tenant_id,s.id,v.version,actor,_request_key,snap,private.dpw_hash(snap)) RETURNING * INTO j;
 PERFORM private.dpdi_authorize(_tenant_id,s.id,j.id,actor,true);INSERT INTO private.dpdi_job_events(job_id,actor_id,phase) VALUES(j.id,actor,'queued');PERFORM private.dpd_event(_tenant_id,s.id,actor,'preview.job.queued',j.id,jsonb_build_object('snapshot_sha256',j.snapshot_sha256,'mode','preview','publish_allowed',false));RETURN private.dpdi_dto(j)||jsonb_build_object('request_replay',false);
END $function$
;

CREATE OR REPLACE FUNCTION public.dpdi_preview_input_page(_tenant_id uuid, _setup_id uuid, _job_id uuid, _claim_key uuid, _page_size integer, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'preview.job.input',_request_context_id);j private.dpdi_jobs%ROWTYPE:=private.dpdi_authorize(_tenant_id,_setup_id,_job_id,actor,true);e private.dpdi_job_events%ROWTYPE:=private.dpdi_live_lease(j,_claim_key);input jsonb:=j.snapshot->'inputs'->e.input_index;page jsonb;meta jsonb;rows jsonb;first_at bigint;fid uuid;sheet text;total bigint;
BEGIN
 IF input IS NULL THEN RETURN private.dpdi_dto(j)||jsonb_build_object('input_complete',true,'page',NULL);END IF;
 IF _page_size IS NULL OR _page_size NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION 'dpdi.bounded_input_page_required';END IF;
 fid:=(input->>'original_file_id')::uuid;meta:=private.dpd_selected_input(fid,input->'selection');first_at:=(meta->>'data_start_row')::bigint;sheet:=input->'selection'->>'sheet_key';total:=(input->>'rows_count')::bigint;
 SELECT coalesce(jsonb_agg(jsonb_build_object('record_index',(q.ordinal-first_at)::text,'source_row_ordinal',q.ordinal::text,'input_id',input->>'input_id','original_file_id',fid,'source_row_id',jsonb_build_array(fid,sheet,q.ordinal::text)::text,'values',q.value,'raw_cells',q.cells,'raw_row_sha256',private.dpw_hash(q.cells)) ORDER BY q.ordinal),'[]') INTO rows FROM(
 SELECT c.start_row+x.ordinality-1 ordinal,x.value cells,(SELECT jsonb_object_agg(h.value->>'name',coalesce(x.value->>((h.value->>'ordinal')::integer),'')) FROM jsonb_array_elements(meta->'header_fields') AS h(value)) value FROM private.dpd_original_chunks c CROSS JOIN LATERAL jsonb_array_elements(c.rows) WITH ORDINALITY AS x(value,ordinality) WHERE c.file_id=fid AND c.sheet_key=sheet AND c.start_row<first_at+e.next_record+_page_size AND c.start_row+c.row_count>first_at+e.next_record AND c.start_row+x.ordinality-1>=first_at+e.next_record AND c.start_row+x.ordinality-1<first_at+least(e.next_record+_page_size,total)) q;
 IF octet_length(rows::text)>1048576 THEN RAISE EXCEPTION 'dpdi.input_page_byte_budget_reduce_explicit_page' USING ERRCODE='22023';END IF;
 RETURN private.dpdi_dto(j)||jsonb_build_object('input_complete',false,'input',input,'rows',rows,'total',total::text,'first_record',e.next_record::text,'has_more',e.next_record+jsonb_array_length(rows)<total,'snapshot',j.snapshot);
END $function$
;

CREATE OR REPLACE FUNCTION public.dpdi_preview_unique_page(_tenant_id uuid, _setup_id uuid, _job_id uuid, _claim_key uuid, _keys jsonb, _request_context_id uuid, _verified_subject jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_service_request_actor(_tenant_id,_setup_id,'preview.job.unique',_request_context_id,_verified_subject);j private.dpdi_jobs%ROWTYPE:=private.dpdi_authorize(_tenant_id,_setup_id,_job_id,actor,true);e private.dpdi_job_events%ROWTYPE:=private.dpdi_live_lease(j,_claim_key);input uuid:=(j.snapshot->'inputs'->e.input_index->>'input_id')::uuid;answer jsonb;collision boolean;
BEGIN
 IF jsonb_typeof(_keys)IS DISTINCT FROM'array'OR jsonb_array_length(_keys)NOT BETWEEN 1 AND 4096 OR octet_length(_keys::text)>1048576 OR EXISTS(SELECT 1 FROM jsonb_array_elements(_keys)k WHERE k->>'input_id'IS DISTINCT FROM input::text OR coalesce(k->>'record_index','')!~'^(0|[1-9][0-9]*)$'OR(k->>'record_index')::bigint<e.next_record OR(k->>'record_index')::bigint>=e.next_record+1000 OR(k->>'record_index')::bigint>=(j.snapshot->'inputs'->e.input_index->>'rows_count')::bigint OR length(coalesce(k->>'rule_id',''))NOT BETWEEN 1 AND 255 OR jsonb_typeof(k->'key_canonical')IS DISTINCT FROM'string'OR octet_length(k->>'key_canonical')>32768 OR k->>'key_sha256'IS NULL OR k->>'key_sha256'!~'^[a-f0-9]{64}$'OR encode(sha256(convert_to(k->>'key_canonical','UTF8')),'hex')IS DISTINCT FROM k->>'key_sha256')THEN RAISE EXCEPTION 'dpdi.complete_canonical_key_sha_page_required';END IF;
 PERFORM 1 FROM private.dpdi_jobs WHERE id=j.id FOR UPDATE;
 WITH entries AS MATERIALIZED(SELECT k->>'rule_id'rule_id,substring(convert_to(k->>'key_canonical','UTF8')FROM 1 FOR 32)prefix,decode(k->>'key_sha256','hex')digest,k->>'key_canonical'canonical,input input_id,(k->>'record_index')::bigint record_index,ord FROM jsonb_array_elements(_keys)WITH ORDINALITY x(k,ord)),ins AS(INSERT INTO private.dpdi_optimized_unique_keys SELECT DISTINCT ON(rule_id,prefix,digest)j.id,rule_id,prefix,digest,canonical,input_id,record_index FROM entries ORDER BY rule_id,prefix,digest,ord ON CONFLICT DO NOTHING RETURNING *),matched AS(SELECT x.*,coalesce(n.input_id,old.input_id)first_input,coalesce(n.record_index,old.record_index)first_record,coalesce(n.key_canonical,old.key_canonical)first_canonical FROM entries x LEFT JOIN ins n ON n.rule_id=x.rule_id AND n.key_prefix=x.prefix AND n.key_sha256=x.digest LEFT JOIN private.dpdi_optimized_unique_keys old ON old.job_id=j.id AND old.rule_id=x.rule_id AND old.key_prefix=x.prefix AND old.key_sha256=x.digest AND n.rule_id IS NULL)
 SELECT jsonb_agg(input_id=first_input AND record_index=first_record ORDER BY ord),bool_or(first_canonical IS DISTINCT FROM canonical)INTO answer,collision FROM matched;
 IF collision IS DISTINCT FROM false OR answer@>'[null]'::jsonb OR jsonb_array_length(answer)<>jsonb_array_length(_keys)THEN RAISE EXCEPTION 'dpdi.canonical_collision_or_incomplete_verdict';END IF;RETURN private.dpdi_dto(j)||jsonb_build_object('unique',answer);
END$function$
;

CREATE OR REPLACE FUNCTION public.dpdi_commit_preview_page(_tenant_id uuid, _setup_id uuid, _job_id uuid, _claim_key uuid, _input_id uuid, _first_record bigint, _wire text, _sha256 text, _request_context_id uuid, _verified_subject jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_service_request_actor(_tenant_id,_setup_id,'preview.job.commit',_request_context_id,_verified_subject);j private.dpdi_jobs%ROWTYPE:=private.dpdi_authorize(_tenant_id,_setup_id,_job_id,actor,true);e private.dpdi_job_events%ROWTYPE;prior private.dpdi_job_pages%ROWTYPE;input jsonb;row jsonb;line text;cells jsonb;n integer:=0;blocked integer:=0;total bigint;nextidx integer;nextrec bigint;root text;phase text;terminal_result jsonb;expires timestamptz;raword bigint;
BEGIN
 PERFORM 1 FROM private.dpdi_jobs WHERE id=j.id FOR UPDATE;SELECT * INTO prior FROM private.dpdi_job_pages WHERE job_id=j.id AND input_id=_input_id AND first_record=_first_record;
 IF FOUND THEN IF prior.wire IS DISTINCT FROM _wire OR prior.sha256 IS DISTINCT FROM _sha256 THEN RAISE EXCEPTION 'dpdi.immutable_page_request_conflict' USING ERRCODE='PT409';END IF;RETURN private.dpdi_dto(j)||jsonb_build_object('page_replay',true);END IF;
 e:=private.dpdi_live_lease(j,_claim_key);input:=j.snapshot->'inputs'->e.input_index;total:=(input->>'rows_count')::bigint;
 IF input->>'input_id' IS DISTINCT FROM _input_id::text OR _first_record IS DISTINCT FROM e.next_record OR _wire IS NULL OR octet_length(_wire)>2097152 OR _sha256 IS DISTINCT FROM encode(sha256(convert_to(_wire,'UTF8')),'hex') THEN RAISE EXCEPTION 'dpdi.exact_bounded_page_required' USING ERRCODE='PT409';END IF;
 FOR line IN SELECT value FROM regexp_split_to_table(_wire,E'\n') AS l(value) WHERE value<>'' LOOP
  row:=line::jsonb;IF row->>'input_id' IS DISTINCT FROM _input_id::text OR row->>'original_file_id' IS DISTINCT FROM input->>'original_file_id' OR (row->>'record_index')::bigint IS DISTINCT FROM _first_record+n OR (row->>'source_row_ordinal')::bigint IS DISTINCT FROM (input->'selection'->>'data_start_row')::bigint+_first_record+n OR jsonb_typeof(row->'payload') IS DISTINCT FROM 'object' OR jsonb_typeof(row->'extras_json') IS DISTINCT FROM 'object' OR jsonb_typeof(row->'blocking') IS DISTINCT FROM 'boolean' OR jsonb_typeof(row->'reasons') IS DISTINCT FROM 'array' OR row->'excluded' IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION 'dpdi.actual_original_lineage_and_strict_disposition_required' USING ERRCODE='PT409';END IF;
  raword:=(row->>'source_row_ordinal')::bigint;
  SELECT c.rows->((raword-c.start_row)::integer) INTO cells FROM private.dpd_original_chunks c WHERE c.file_id=(input->>'original_file_id')::uuid AND c.sheet_key=input->'selection'->>'sheet_key' AND c.start_row<=raword AND c.start_row+c.row_count>raword;
  IF cells IS NULL OR row->>'raw_row_sha256' IS DISTINCT FROM private.dpw_hash(cells) OR (row->>'source_row_id')::jsonb IS DISTINCT FROM jsonb_build_array(input->>'original_file_id',input->'selection'->>'sheet_key',raword::text) OR ((row->>'blocking')::boolean IS DISTINCT FROM (jsonb_array_length(row->'reasons')>0)) THEN RAISE EXCEPTION 'dpdi.exact_stored_raw_hash_identity_and_blocking_required' USING ERRCODE='PT409';END IF;
  n:=n+1;IF (row->>'blocking')::boolean THEN blocked:=blocked+1;END IF;
 END LOOP;
 IF n NOT BETWEEN 1 AND 1000 OR _first_record+n>total THEN RAISE EXCEPTION 'dpdi.complete_page_count_required';END IF;
 INSERT INTO private.dpdi_job_pages(job_id,sequence,input_id,first_record,row_count,blocking_count,wire,sha256) VALUES(j.id,e.output_pages+1,_input_id,_first_record,n,blocked,_wire,_sha256);
 nextidx:=e.input_index;nextrec:=e.next_record+n;IF nextrec=total THEN nextidx:=nextidx+1;nextrec:=0;END IF;
 WHILE nextidx<jsonb_array_length(j.snapshot->'inputs') AND (j.snapshot->'inputs'->nextidx->>'rows_count')::bigint=0 LOOP nextidx:=nextidx+1;END LOOP;
 root:=encode(sha256(convert_to(e.output_root_sha256||E'\t'||(e.output_pages+1)::text||E'\t'||n::text||E'\t'||_sha256||E'\n','UTF8')),'hex');phase:=CASE WHEN nextidx=jsonb_array_length(j.snapshot->'inputs') THEN CASE WHEN e.blocking_records+blocked>0 THEN 'blocked' ELSE 'success' END ELSE 'running' END;
 expires:=least(clock_timestamp()+interval '60 seconds',to_timestamp((_verified_subject->>'exp')::double precision));
 INSERT INTO private.dpdi_job_events(job_id,actor_id,phase,claim_key,lease_expires_at,input_index,next_record,source_records,blocking_records,output_pages,output_root_sha256,last_page_sha256) VALUES(j.id,actor,phase,_claim_key,expires,nextidx,nextrec,e.source_records+n,e.blocking_records+blocked,e.output_pages+1,root,_sha256);
 IF phase IN('success','blocked') THEN
  IF e.source_records+n IS DISTINCT FROM (SELECT sum((x.value->>'rows_count')::bigint) FROM jsonb_array_elements(j.snapshot->'inputs') AS x(value)) THEN RAISE EXCEPTION 'dpdi.full_original_coverage_required';END IF;
  terminal_result:=jsonb_build_object('representation','dpdi_authoring_pages_v1','mode',j.snapshot->>'mode','job_id',j.id,'status',CASE WHEN phase='success' THEN 'success' ELSE 'failed' END,'publication_eligible',j.snapshot->>'mode'='prepare' AND phase='success','blocking_failure',phase='blocked','source_records',(e.source_records+n)::text,'blocking_records',(e.blocking_records+blocked)::text,'preview_rows',CASE WHEN phase='success' THEN (e.source_records+n)::text ELSE '0' END,'acceptedRows',NULL,'outputLineage',NULL,'structured_data_sha256',root,'hash_kind','immutable_page_prefix_sha256','page_count',e.output_pages+1,'full_final_ack',true);
  UPDATE public.data_prep_delivery_runs SET state=CASE WHEN phase='success' THEN 'success' ELSE 'failed' END,result=terminal_result,result_sha256=private.dpw_hash(terminal_result),finished_at=clock_timestamp() WHERE id=j.reserved_run_id AND state='running';
  IF j.snapshot->>'mode'='prepare' THEN UPDATE public.data_prep_delivery_batches SET state=CASE WHEN phase='success' THEN 'prepared' ELSE 'failed' END WHERE id=(j.snapshot->>'batch_id')::uuid AND state='processing';END IF;
  PERFORM private.dpd_event(_tenant_id,_setup_id,actor,'preview.job.completed',j.id,jsonb_build_object('phase',phase,'source_records',(e.source_records+n)::text,'output_root_sha256',root,'publish_allowed',false));
 END IF;
 RETURN private.dpdi_dto(j)||jsonb_build_object('page_replay',false);
END $function$
;

CREATE OR REPLACE FUNCTION public.dpdi_release_preview_lease(_tenant_id uuid, _setup_id uuid, _job_id uuid, _claim_key uuid, _request_context_id uuid, _verified_subject jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_service_request_actor(_tenant_id,_setup_id,'preview.job.release',_request_context_id,_verified_subject);j private.dpdi_jobs%ROWTYPE:=private.dpdi_authorize(_tenant_id,_setup_id,_job_id,actor,true);e private.dpdi_job_events%ROWTYPE:=private.dpdi_head(j.id);
BEGIN IF e.phase='running' AND e.claim_key=_claim_key THEN INSERT INTO private.dpdi_job_events(job_id,actor_id,phase,claim_key,lease_expires_at,input_index,next_record,source_records,blocking_records,output_pages,output_root_sha256,last_page_sha256) VALUES(j.id,actor,'running',_claim_key,clock_timestamp(),e.input_index,e.next_record,e.source_records,e.blocking_records,e.output_pages,e.output_root_sha256,e.last_page_sha256);END IF;RETURN private.dpdi_dto(j);END $function$
;

CREATE OR REPLACE FUNCTION public.dpdi_preview_result_page(_tenant_id uuid, _setup_id uuid, _job_id uuid, _after_page integer, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'preview.job.result',_request_context_id);j private.dpdi_jobs%ROWTYPE:=private.dpdi_authorize(_tenant_id,_setup_id,_job_id,actor,false);e private.dpdi_job_events%ROWTYPE:=private.dpdi_head(j.id);p private.dpdi_job_pages%ROWTYPE;records jsonb;errors jsonb;
BEGIN
 IF _after_page IS NULL OR _after_page<0 THEN RAISE EXCEPTION 'dpdi.result_page_required';END IF;
 IF EXISTS(SELECT 1 FROM private.dpdi_run_inputs i WHERE i.job_id=j.id AND NOT private.dpd_original_viewable(i.original_file_id)) THEN RETURN private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'execution_actor_id',j.actor_id,'state','unavailable','wire',NULL,'row_count',NULL,'preview_rows',NULL);END IF;
 IF e.phase NOT IN('success','blocked') THEN RETURN private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'execution_actor_id',j.actor_id,'state','pending','wire',NULL,'row_count',NULL,'preview_rows',NULL);END IF;
 SELECT * INTO p FROM private.dpdi_job_pages WHERE job_id=j.id AND sequence>_after_page ORDER BY sequence LIMIT 1;
 SELECT coalesce(jsonb_agg(x.value::jsonb ORDER BY x.ordinality),'[]'),coalesce(jsonb_agg(x.value::jsonb ORDER BY x.ordinality) FILTER(WHERE (x.value::jsonb->>'blocking')::boolean),'[]') INTO records,errors FROM regexp_split_to_table(coalesce(p.wire,''),E'\n') WITH ORDINALITY AS x(value,ordinality) WHERE x.value<>'';
 RETURN private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'execution_actor_id',j.actor_id,'state',CASE WHEN e.phase='blocked' THEN 'blocked' ELSE 'available' END,'page_sequence',p.sequence,'wire',CASE WHEN e.phase='success' THEN p.wire ELSE NULL END,'error_wire',CASE WHEN e.phase='blocked' THEN errors::text ELSE NULL END,'records',CASE WHEN e.phase='success' THEN records ELSE NULL END,'errors',errors,'error_count',jsonb_array_length(errors),'row_count',p.row_count,'sha256',p.sha256,'preview_rows',CASE WHEN e.phase='success' THEN e.source_records::text ELSE '0' END);
END $function$
;

CREATE OR REPLACE FUNCTION public.dpdi_next_owned_preview(_tenant_id uuid, _setup_id uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'preview.job.next',_request_context_id);s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,false);j private.dpdi_jobs%ROWTYPE;e private.dpdi_job_events%ROWTYPE;
BEGIN
 SELECT q.* INTO j FROM private.dpdi_jobs q CROSS JOIN LATERAL private.dpdi_head(q.id) h WHERE q.tenant_id=_tenant_id AND q.setup_id=s.id AND h.phase IN('queued','running') ORDER BY q.created_at,q.id LIMIT 1;
 IF j.id IS NULL THEN RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'mode','preview','publish_allowed',false,'state','no_pending_head','job',NULL);END IF;
 IF j.actor_id<>actor THEN RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'mode','preview','publish_allowed',false,'state','other_actor_transport_required','job',NULL);END IF;
 PERFORM private.dpdi_authorize(_tenant_id,_setup_id,j.id,actor,false);e:=private.dpdi_head(j.id);
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'mode','preview','publish_allowed',false,'state',CASE WHEN e.phase='running' AND e.lease_expires_at>clock_timestamp() THEN 'owned_active' ELSE 'owned_ready_head' END,'job',private.dpdi_dto(j));
END $function$
;

CREATE OR REPLACE FUNCTION public.dpd_get_received_catalogue(_tenant_id uuid, _setup_id uuid, _draft_version integer, _selections jsonb, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'catalogue.read',_request_context_id);s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,false);v private.dpd_versions%ROWTYPE;f private.dpd_original_intents%ROWTYPE;sc private.dpd_schema_receipts%ROWTYPE;raw private.dpd_raw_source_links%ROWTYPE;selection jsonb;sheet jsonb;cells jsonb;headers jsonb;files jsonb:='[]';pins jsonb:='[]';state text:='available';file_state text;header_at bigint;start_at bigint;total bigint;selected integer:=0;catalog jsonb;
BEGIN
 SELECT * INTO v FROM private.dpd_versions WHERE setup_id=s.id ORDER BY version DESC LIMIT 1;
 IF v.version IS DISTINCT FROM _draft_version OR jsonb_typeof(_selections) IS DISTINCT FROM 'array' OR jsonb_array_length(_selections)>1000 OR (SELECT count(DISTINCT x.value->>'file_id') FROM jsonb_array_elements(_selections) AS x(value))<>jsonb_array_length(_selections) THEN RAISE EXCEPTION 'dpd.current_catalogue_version_selection_required' USING ERRCODE='PT409';END IF;
 FOR f IN SELECT * FROM private.dpd_original_intents WHERE setup_id=s.id AND tenant_id=_tenant_id ORDER BY created_at,id LOOP
  SELECT * INTO sc FROM private.dpd_schema_receipts WHERE file_id=f.id;SELECT * INTO raw FROM private.dpd_raw_source_links WHERE file_id=f.id;
  IF raw.data_source_id IS NOT NULL AND private.dpw_source_allows(actor,_tenant_id,raw.data_source_id,'view') IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.current_catalogue_source_read_denied' USING ERRCODE='42501';END IF;
  file_state:=CASE WHEN NOT private.dpd_original_viewable(f.id) THEN 'unavailable' WHEN NOT EXISTS(SELECT 1 FROM private.dpd_original_receipts WHERE file_id=f.id AND setup_id=s.id AND tenant_id=_tenant_id AND created_by=f.created_by) THEN 'receipt_pending' WHEN sc.file_id IS NULL THEN 'schema_pending' ELSE 'selection_required' END;
  SELECT x.value INTO selection FROM jsonb_array_elements(_selections) AS x(value) WHERE x.value->>'file_id'=f.id::text;
  IF file_state='selection_required' AND selection IS NOT NULL THEN
   IF selection->>'schema_sha256' IS DISTINCT FROM sc.schema_sha256 THEN RAISE EXCEPTION 'dpd.selected_schema_digest_changed_refresh_catalogue' USING ERRCODE='PT409';END IF;
   SELECT x.value INTO sheet FROM jsonb_array_elements(sc.schema_manifest->'sheet_inventory') AS x(value) WHERE x.value->>'sheet_key'=selection->>'sheet_key';
   IF sheet IS NULL OR coalesce(selection->>'header_row_index','')!~'^(0|[1-9][0-9]*)$' OR coalesce(selection->>'data_start_row','')!~'^(0|[1-9][0-9]*)$' THEN RAISE EXCEPTION 'dpd.explicit_actual_sheet_header_selection_required' USING ERRCODE='PT409';END IF;
   header_at:=(selection->>'header_row_index')::bigint;start_at:=(selection->>'data_start_row')::bigint;total:=(sheet->>'raw_row_count')::bigint;
   IF header_at>=total OR start_at<=header_at OR start_at>total THEN RAISE EXCEPTION 'dpd.actual_selected_source_range_required' USING ERRCODE='PT409';END IF;
   SELECT c.rows->((header_at-c.start_row)::integer) INTO cells FROM private.dpd_original_chunks c WHERE c.file_id=f.id AND c.sheet_key=sheet->>'sheet_key' AND c.start_row<=header_at AND c.start_row+c.row_count>header_at;
   IF cells IS NULL OR jsonb_typeof(cells) IS DISTINCT FROM 'array' OR jsonb_array_length(cells) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'dpd.actual_stored_header_cells_required' USING ERRCODE='PT409';END IF;
   IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(cells) AS h(value) WHERE btrim(h.value)='' OR h.value IS DISTINCT FROM btrim(h.value)) OR (SELECT count(DISTINCT h.value) FROM jsonb_array_elements_text(cells) AS h(value))<>jsonb_array_length(cells) THEN RAISE EXCEPTION 'dpd.explicit_unambiguous_nonblank_header_selection_required_choose_actual_header_row' USING ERRCODE='PT409';END IF;
   SELECT jsonb_agg(jsonb_build_object('ordinal',h.ordinality-1,'name',h.value,'inferred_type','string','nullable',false) ORDER BY h.ordinality) INTO headers FROM jsonb_array_elements_text(cells) WITH ORDINALITY AS h(value,ordinality);
   pins:=pins||jsonb_build_array(jsonb_build_object('file_id',f.id,'feed_key',f.feed_key,'original_request_key',f.request_key,'content_sha256',f.content_sha256,'storage_bucket',f.storage_bucket,'original_path',f.original_path,'schema_sha256',sc.schema_sha256,'sheet_key',sheet->>'sheet_key','header_row_index',header_at::text,'data_start_row',start_at::text,'total_raw_rows',total::text,'header_fields',headers,'data_source_id',raw.data_source_id));file_state:='available';selected:=selected+1;
  END IF;
  IF file_state<>'available' THEN state:=CASE WHEN file_state='unavailable' THEN 'unavailable' WHEN state='available' THEN file_state ELSE state END;END IF;
  files:=files||jsonb_build_array(jsonb_build_object('file_id',f.id,'feed_key',f.feed_key,'request_key',f.request_key,'content_sha256',f.content_sha256,'created_by',f.created_by,'state',file_state,'schema_sha256',sc.schema_sha256,'data_source_id',raw.data_source_id,'sheet_inventory',CASE WHEN private.dpd_original_viewable(f.id) THEN coalesce(sc.schema_manifest->'sheet_inventory','[]') ELSE NULL END,'selected_header_cells',CASE WHEN file_state='available' THEN cells ELSE NULL END,'source_type_provenance','actual_raw_string_cells_hint_not_declared_output_types'));
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(_selections) AS x(value) WHERE NOT EXISTS(SELECT 1 FROM private.dpd_original_intents original_row WHERE original_row.id=(x.value->>'file_id')::uuid AND original_row.setup_id=s.id AND original_row.tenant_id=_tenant_id)) THEN RAISE EXCEPTION 'dpd.catalogue_foreign_original_denied' USING ERRCODE='42501';END IF;
 IF jsonb_array_length(files)=0 THEN state:='receipt_pending';END IF;
 IF state='available' AND selected=jsonb_array_length(files) THEN catalog:=jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'draft_version',v.version,'state','available','complete',true,'originals',pins);END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'draft_version',v.version,'state',state,'complete',catalog IS NOT NULL,'catalog',catalog,'catalog_sha256',CASE WHEN catalog IS NOT NULL THEN private.dpw_hash(catalog) ELSE NULL END,'files',files,'confirmed_mapping',NULL,'confirmed_mapping_required',false,'strict_output_types_inferred',false,'processor_capabilities',jsonb_build_object('unsupported_transform_kinds',jsonb_build_array('sort','dedupe','filter','filter_expr'),'independent_exclusions_supported',false,'reject_unsupported_before_save',true,'ordered_supported_transforms',true,'bounded_native_results',true),'publish_allowed',false);
END $function$
;

CREATE OR REPLACE FUNCTION private.dpdi_review_reader(_tenant uuid, _setup uuid, _actor uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 SELECT EXISTS(SELECT 1 FROM private.dpdi_setup_review_requests r JOIN public.tenant_groups g ON g.id=r.approver_group_id AND g.tenant_id=r.tenant_id JOIN public.tenant_group_members m ON m.group_id=g.id AND m.user_id=_actor WHERE r.tenant_id=_tenant AND r.setup_id=_setup)
$function$
;

CREATE OR REPLACE FUNCTION private.dpdi_review_dto(r private.dpdi_setup_review_requests, _actor uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
 SELECT jsonb_build_object('actor_id',_actor,'tenant_id',r.tenant_id,'setup_id',r.setup_id,'draft_version',r.draft_version,'request_id',r.id,'request_key',r.request_key,'requested_by',r.requested_by,'approver_group_id',r.approver_group_id,'job_id',r.job_id,'snapshot_sha256',r.snapshot_sha256,'status',coalesce((SELECT d.decision FROM private.dpdi_setup_review_decisions d WHERE d.request_id=r.id),'pending'),'decision',(SELECT to_jsonb(d) FROM private.dpdi_setup_review_decisions d WHERE d.request_id=r.id),'approval_origin','dpdi_setup_review_v1','publish_allowed',false)
$function$
;

CREATE OR REPLACE FUNCTION public.dpdi_request_setup_review(_tenant_id uuid, _setup_id uuid, _draft_version integer, _job_id uuid, _approver_group_id uuid, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'review.setup.request',_request_context_id);j private.dpdi_jobs%ROWTYPE:=private.dpdi_authorize(_tenant_id,_setup_id,_job_id,actor,true);head private.dpdi_job_events%ROWTYPE:=private.dpdi_head(j.id);r private.dpdi_setup_review_requests%ROWTYPE;
BEGIN
 IF j.draft_version<>_draft_version OR head.phase<>'success' OR head.blocking_records<>0 OR _request_key IS NULL OR NOT EXISTS(SELECT 1 FROM public.tenant_groups WHERE id=_approver_group_id AND tenant_id=_tenant_id) THEN RAISE EXCEPTION 'dpdi.full_current_successful_preview_review_required' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM private.dpd_setups WHERE id=_setup_id FOR UPDATE;SELECT * INTO r FROM private.dpdi_setup_review_requests WHERE tenant_id=_tenant_id AND requested_by=actor AND request_key=_request_key;
 IF FOUND THEN IF r.setup_id<>_setup_id OR r.draft_version<>_draft_version OR r.job_id<>j.id OR r.approver_group_id<>_approver_group_id OR r.snapshot_sha256<>j.snapshot_sha256 THEN RAISE EXCEPTION 'dpdi.review_request_conflict' USING ERRCODE='PT409';END IF;RETURN private.dpdi_review_dto(r,actor);END IF;
 INSERT INTO private.dpdi_setup_review_requests(tenant_id,setup_id,draft_version,job_id,approver_group_id,request_key,requested_by,snapshot,snapshot_sha256) VALUES(_tenant_id,_setup_id,_draft_version,j.id,_approver_group_id,_request_key,actor,j.snapshot,j.snapshot_sha256) RETURNING * INTO r;
 PERFORM private.dpd_event(_tenant_id,_setup_id,actor,'setup.review.requested',r.id,jsonb_build_object('job_id',j.id,'snapshot_sha256',j.snapshot_sha256,'approver_group_id',_approver_group_id));RETURN private.dpdi_review_dto(r,actor);
END $function$
;

CREATE OR REPLACE FUNCTION public.dpdi_get_setup_review(_tenant_id uuid, _setup_id uuid, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'review.setup.read',_request_context_id);r private.dpdi_setup_review_requests%ROWTYPE;
BEGIN SELECT * INTO r FROM private.dpdi_setup_review_requests WHERE tenant_id=_tenant_id AND setup_id=_setup_id AND request_key=_request_key;
 IF r.id IS NULL THEN RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'state','absent','result',NULL,'publish_allowed',false);END IF;
 IF actor<>r.requested_by AND NOT EXISTS(SELECT 1 FROM public.tenant_group_members WHERE group_id=r.approver_group_id AND user_id=actor) THEN RAISE EXCEPTION 'dpdi.current_selected_reviewer_required' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'state','found','result',private.dpdi_review_dto(r,actor),'publish_allowed',false);
END $function$
;

CREATE OR REPLACE FUNCTION public.upsert_data_prep_pipeline_for_api(_tenant_id uuid, _pipeline_id uuid, _payload jsonb, _actor_user_id uuid)
 RETURNS TABLE(pipeline_id uuid, public_uid text, pipeline_status text, pipeline_version integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  target public.data_prep_pipelines%ROWTYPE;
  created public.data_prep_pipelines%ROWTYPE;
BEGIN
  PERFORM public.assert_data_prep_actor(_tenant_id,_actor_user_id,false);
  IF _payload IS NULL OR jsonb_typeof(_payload) <> 'object' THEN RAISE EXCEPTION 'Data Prep payload is required'; END IF;
  IF _pipeline_id IS NULL THEN
    INSERT INTO public.data_prep_pipelines(
      tenant_id,name,description,source_data_source_id,output_data_source_id,steps,dq_rules,
      on_failure,enabled,status,lifecycle_state,created_by
    ) VALUES (
      _tenant_id,_payload->>'name',nullif(_payload->>'description',''),
      nullif(_payload->>'source_data_source_id','')::uuid,nullif(_payload->>'output_data_source_id','')::uuid,
      coalesce(_payload->'steps','[]'::jsonb),coalesce(_payload->'dq_rules','[]'::jsonb),
      coalesce(_payload->>'on_failure','block'),coalesce((_payload->>'enabled')::boolean,true),
      'draft','production',_actor_user_id
    ) RETURNING * INTO created;
    INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
    VALUES (_actor_user_id,_tenant_id,'api','data_prep.create','data_prep_pipeline',created.id,
      jsonb_build_object('public_uid',created.public_uid,'version',created.version));
    RETURN QUERY SELECT created.id,created.public_uid,created.status,created.version;
    RETURN;
  END IF;
  SELECT * INTO target FROM public.data_prep_pipelines
  WHERE id=_pipeline_id AND tenant_id=_tenant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Data Prep pipeline not found'; END IF;
  -- Current registered scope remains authoritative after a group is revoked.
  IF EXISTS (
    SELECT 1 FROM public.data_resource_registry r
    WHERE r.tenant_id=_tenant_id AND r.data_prep_pipeline_id=_pipeline_id
  ) AND NOT EXISTS (
    SELECT 1 FROM public.data_resource_registry r
    WHERE r.tenant_id=_tenant_id AND r.data_prep_pipeline_id=_pipeline_id
      AND private.data_resource_shadow_allows_actor(_actor_user_id,r.id,'edit') IS TRUE
  ) THEN
    RAISE EXCEPTION 'Not authorized to edit this Data Prep pipeline' USING ERRCODE='42501';
  END IF;
  IF target.lifecycle_state='archived' THEN RAISE EXCEPTION 'Archived Data Prep pipeline cannot be edited'; END IF;
  IF target.promotion_status='pending' THEN RAISE EXCEPTION 'Pending promotion pipeline cannot be edited'; END IF;
  UPDATE public.data_prep_pipelines SET
    name=coalesce(_payload->>'name',target.name),
    description=CASE WHEN _payload ? 'description' THEN nullif(_payload->>'description','') ELSE target.description END,
    source_data_source_id=CASE WHEN _payload ? 'source_data_source_id' THEN nullif(_payload->>'source_data_source_id','')::uuid ELSE target.source_data_source_id END,
    output_data_source_id=CASE WHEN _payload ? 'output_data_source_id' THEN nullif(_payload->>'output_data_source_id','')::uuid ELSE target.output_data_source_id END,
    steps=coalesce(_payload->'steps',target.steps),dq_rules=coalesce(_payload->'dq_rules',target.dq_rules),
    on_failure=coalesce(_payload->>'on_failure',target.on_failure),
    enabled=coalesce((_payload->>'enabled')::boolean,target.enabled),
    status=CASE WHEN target.status='approved' THEN 'draft' ELSE target.status END,
    version=CASE WHEN target.status='approved' THEN coalesce(target.version,1)+1 ELSE target.version END,
    approved_at=CASE WHEN target.status='approved' THEN NULL ELSE target.approved_at END,
    approved_by=CASE WHEN target.status='approved' THEN NULL ELSE target.approved_by END
  WHERE id=_pipeline_id AND tenant_id=_tenant_id RETURNING * INTO created;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES (_actor_user_id,_tenant_id,'api','data_prep.update','data_prep_pipeline',created.id,
    jsonb_build_object('public_uid',created.public_uid,'version',created.version,'reapproval_required',target.status='approved'));
  RETURN QUERY SELECT created.id,created.public_uid,created.status,created.version;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.effective_user_permissions(_user_id uuid, _tenant_id uuid, _bu_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(permission_id text, source text, role_id uuid, group_id uuid, bu_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT rp.permission_id, 'direct'::text, g.role_id, NULL::uuid, g.scope_id
    FROM public.rbac_user_grants g
    JOIN public.rbac_role_permissions rp ON rp.role_id = g.role_id
   WHERE (
       _user_id = auth.uid()
       OR public.is_platform_admin(auth.uid()) IS TRUE
       OR EXISTS (SELECT 1 FROM public.tenant_members caller
         WHERE caller.tenant_id=_tenant_id AND caller.user_id=auth.uid()
           AND caller.active AND caller.role='tenant_admin'::public.tenant_role)
       OR auth.role()='service_role'
       OR (auth.role() IS NULL AND session_user IN ('postgres','supabase_admin'))
     ) AND g.user_id = _user_id AND g.tenant_id = _tenant_id
     AND g.revoked_at IS NULL
     AND (g.expires_at IS NULL OR g.expires_at > now())
     AND (_bu_id IS NULL OR g.scope_type <> 'business_unit' OR g.scope_id = _bu_id)
  UNION
  SELECT rp.permission_id, 'group'::text, gr.role_id, tg.id, tg.bu_id
    FROM public.tenant_group_members m
    JOIN public.tenant_groups tg          ON tg.id = m.group_id
    JOIN public.tenant_group_roles gr     ON gr.group_id = tg.id
    JOIN public.rbac_role_permissions rp  ON rp.role_id = gr.role_id
   WHERE (
       _user_id = auth.uid()
       OR public.is_platform_admin(auth.uid()) IS TRUE
       OR EXISTS (SELECT 1 FROM public.tenant_members caller
         WHERE caller.tenant_id=_tenant_id AND caller.user_id=auth.uid()
           AND caller.active AND caller.role='tenant_admin'::public.tenant_role)
       OR auth.role()='service_role'
       OR (auth.role() IS NULL AND session_user IN ('postgres','supabase_admin'))
     ) AND m.user_id = _user_id AND tg.tenant_id = _tenant_id
     AND (_bu_id IS NULL OR tg.bu_id IS NULL OR tg.bu_id = _bu_id)
  UNION
  SELECT rp.permission_id, 'bu_group'::text, gr.role_id, m.group_id, bga.bu_id
    FROM public.bu_group_assignments bga
    JOIN public.tenant_group_members m    ON m.group_id = bga.group_id
    JOIN public.tenant_group_roles gr     ON gr.group_id = bga.group_id
    JOIN public.rbac_role_permissions rp  ON rp.role_id = gr.role_id
   WHERE (
       _user_id = auth.uid()
       OR public.is_platform_admin(auth.uid()) IS TRUE
       OR EXISTS (SELECT 1 FROM public.tenant_members caller
         WHERE caller.tenant_id=_tenant_id AND caller.user_id=auth.uid()
           AND caller.active AND caller.role='tenant_admin'::public.tenant_role)
       OR auth.role()='service_role'
       OR (auth.role() IS NULL AND session_user IN ('postgres','supabase_admin'))
     ) AND m.user_id = _user_id AND bga.tenant_id = _tenant_id
     AND (_bu_id IS NULL OR bga.bu_id = _bu_id);
$function$
;

CREATE OR REPLACE FUNCTION public.dpdi_request_publication(_tenant_id uuid, _setup_id uuid, _job_id uuid, _setup_review_decision_id uuid, _approver_group_id uuid, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'publication.request',_request_context_id);j private.dpdi_jobs%ROWTYPE:=private.dpdi_authorize(_tenant_id,_setup_id,_job_id,actor,false);e private.dpdi_job_events%ROWTYPE:=private.dpdi_head(j.id);r private.dpdi_publication_requests%ROWTYPE;
BEGIN
 IF j.snapshot->>'mode' IS DISTINCT FROM 'prepare' OR e.phase<>'success' OR e.blocking_records<>0 OR NOT EXISTS(SELECT 1 FROM private.dpdi_setup_review_decisions d JOIN private.dpdi_setup_review_requests q ON q.id=d.request_id WHERE d.id=_setup_review_decision_id AND d.decision='approved' AND q.tenant_id=_tenant_id AND q.setup_id=_setup_id AND q.draft_version=j.draft_version AND d.decided_by<>q.requested_by) OR NOT EXISTS(SELECT 1 FROM public.tenant_groups WHERE id=_approver_group_id AND tenant_id=_tenant_id) THEN RAISE EXCEPTION 'dpdi.actual_approved_prepare_origin_required_no_preview_publication' USING ERRCODE='42501';END IF;
 SELECT * INTO r FROM private.dpdi_publication_requests WHERE tenant_id=_tenant_id AND requested_by=actor AND request_key=_request_key;
 IF FOUND THEN IF r.job_id<>j.id OR r.setup_review_decision_id<>_setup_review_decision_id OR r.approver_group_id<>_approver_group_id OR r.output_root_sha256<>e.output_root_sha256 THEN RAISE EXCEPTION 'dpdi.publication_request_conflict' USING ERRCODE='PT409';END IF;ELSE INSERT INTO private.dpdi_publication_requests(tenant_id,setup_id,draft_version,job_id,setup_review_decision_id,approver_group_id,request_key,requested_by,output_root_sha256) VALUES(_tenant_id,_setup_id,j.draft_version,j.id,_setup_review_decision_id,_approver_group_id,_request_key,actor,e.output_root_sha256) RETURNING * INTO r;END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'request_id',r.id,'status','pending','publication_performed',false);
END $function$
;

CREATE OR REPLACE FUNCTION private.fvi_seed_missing_group_presets(_tenant uuid, _bu uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE p record;g uuid;r uuid;rk text;n integer:=0;
BEGIN
 PERFORM 1 FROM public.business_units b WHERE b.id=_bu AND b.tenant_id=_tenant AND NOT b.is_archived FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Select an active business unit in this tenant' USING ERRCODE='22023';END IF;
 FOR p IN SELECT * FROM public.tenant_group_presets WHERE is_default ORDER BY sort_order LOOP
   IF EXISTS(SELECT 1 FROM public.tenant_groups x WHERE x.tenant_id=_tenant AND x.preset_key=p.preset_key) THEN CONTINUE;END IF;
   INSERT INTO public.tenant_groups(tenant_id,name,description,is_system,preset_key,bu_id)
   VALUES(_tenant,p.name,p.description,true,p.preset_key,_bu)
   ON CONFLICT(tenant_id,preset_key) DO NOTHING RETURNING id INTO g;
   IF g IS NULL THEN CONTINUE;END IF;
   INSERT INTO public.bu_group_assignments(tenant_id,bu_id,group_id,role,inherit_descendants,created_by)
   VALUES(_tenant,_bu,g,'bu_member',false,auth.uid());
   FOREACH rk IN ARRAY p.role_keys LOOP
     SELECT id INTO r FROM public.rbac_roles WHERE key=rk AND is_system LIMIT 1;
     IF r IS NOT NULL THEN INSERT INTO public.tenant_group_roles(group_id,role_id) VALUES(g,r) ON CONFLICT DO NOTHING;END IF;
   END LOOP;
   n:=n+1;
 END LOOP;
 RETURN n;
END $function$
;

CREATE OR REPLACE FUNCTION public.seed_tenant_group_presets_for_bu(_tenant_id uuid, _bu_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
BEGIN
 IF NOT private.fvi_active_structure_admin(_tenant_id,auth.uid()) THEN
   RAISE EXCEPTION 'Active tenant administrator required for group presets' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM public.tenants WHERE id=_tenant_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Tenant not found' USING ERRCODE='22023';END IF;
 RETURN private.fvi_seed_missing_group_presets(_tenant_id,_bu_id);
END $function$
;

CREATE OR REPLACE FUNCTION public.seed_default_tenant_groups(_tenant_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_bu uuid;v_processed integer;
BEGIN
 PERFORM 1 FROM public.tenants WHERE id=_tenant_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Tenant not found' USING ERRCODE='22023';END IF;
 SELECT count(*) INTO v_processed FROM public.tenant_group_presets WHERE is_default;
 IF NOT EXISTS(SELECT 1 FROM public.tenant_group_presets p WHERE p.is_default AND NOT EXISTS(SELECT 1 FROM public.tenant_groups g WHERE g.tenant_id=_tenant_id AND g.preset_key=p.preset_key)) THEN RETURN v_processed;END IF;
 -- Explicit NEW foundation BU; no arbitrary old-BU selection or backfill.
 INSERT INTO public.business_units(tenant_id,name,code,description,created_by)
 VALUES(_tenant_id,'Preset groups business unit','FVI-PRESET-'||left(gen_random_uuid()::text,8),'Explicit foundation for newly seeded default groups',auth.uid()) RETURNING id INTO v_bu;
 PERFORM private.fvi_seed_missing_group_presets(_tenant_id,v_bu);
 RETURN v_processed;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.dpdi_enqueue_approved_prepare(_tenant_id uuid, _setup_id uuid, _setup_review_decision_id uuid, _business_date date, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'prepare.job.enqueue',_request_context_id);r private.dpdi_setup_review_requests%ROWTYPE;d private.dpdi_setup_review_decisions%ROWTYPE;preview private.dpdi_jobs%ROWTYPE;j private.dpdi_jobs%ROWTYPE;batch public.data_prep_delivery_batches%ROWTYPE;snap jsonb;pipe uuid;
BEGIN
 PERFORM 1 FROM private.dpd_setups WHERE id=_setup_id AND tenant_id=_tenant_id AND created_by=actor FOR UPDATE;
 IF NOT FOUND OR _business_date IS NULL OR _request_key IS NULL THEN RAISE EXCEPTION 'dpdi.current_prepare_creator_and_explicit_business_date_required' USING ERRCODE='42501';END IF;
 SELECT * INTO d FROM private.dpdi_setup_review_decisions WHERE id=_setup_review_decision_id AND decision='approved';SELECT * INTO r FROM private.dpdi_setup_review_requests WHERE id=d.request_id AND tenant_id=_tenant_id AND setup_id=_setup_id;
 SELECT * INTO preview FROM private.dpdi_jobs WHERE id=r.job_id;
 IF r.id IS NULL OR d.decided_by=r.requested_by OR preview.snapshot_sha256<>d.snapshot_sha256 OR (SELECT max(version) FROM private.dpd_versions WHERE setup_id=_setup_id)<>r.draft_version THEN RAISE EXCEPTION 'dpdi.exact_current_human_approved_configuration_required' USING ERRCODE='42501';END IF;
 PERFORM private.dpdi_authorize(_tenant_id,_setup_id,preview.id,actor,true);pipe:=(preview.snapshot->>'pipeline_id')::uuid;
 IF NOT EXISTS(SELECT 1 FROM public.data_prep_pipelines p WHERE p.id=pipe AND p.tenant_id=_tenant_id AND p.status='approved' AND p.lifecycle_state='production' AND p.version=(preview.snapshot->>'pipeline_version')::integer) OR NOT EXISTS(SELECT 1 FROM public.data_prep_approved_configurations ac WHERE ac.tenant_id=_tenant_id AND ac.pipeline_id=pipe AND ac.pipeline_version=(preview.snapshot->>'pipeline_version')::integer AND ac.configuration_id=(preview.snapshot->>'configuration_id')::uuid AND ac.approved_by<>actor) THEN RAISE EXCEPTION 'dpdi.actual_governed_approved_production_transition_required_no_private_approval_waiver' USING ERRCODE='42501';END IF;
 SELECT * INTO j FROM private.dpdi_jobs WHERE tenant_id=_tenant_id AND actor_id=actor AND request_key=_request_key;
 IF FOUND THEN IF j.setup_id<>_setup_id OR j.snapshot->>'mode'<>'prepare' OR j.snapshot->>'setup_review_decision_id'<>d.id::text OR j.snapshot->>'business_date'<>_business_date::text THEN RAISE EXCEPTION 'dpdi.prepare_request_conflict' USING ERRCODE='PT409';END IF;RETURN private.dpdi_dto(j)||jsonb_build_object('request_replay',true);END IF;
 PERFORM private.dpd_assert_transform_configuration(preview.snapshot->'pipeline_configuration');
 INSERT INTO public.data_prep_delivery_batches(tenant_id,pipeline_id,pipeline_version,business_date,mode,execution_mode,human_in_loop,request_key,created_by,configuration_snapshot)
 VALUES(_tenant_id,pipe,(preview.snapshot->>'pipeline_version')::integer,_business_date,'prepare',(SELECT execution_mode FROM public.data_prep_delivery_batches WHERE id=(preview.snapshot->>'batch_id')::uuid),(SELECT human_in_loop FROM public.data_prep_delivery_batches WHERE id=(preview.snapshot->>'batch_id')::uuid),_request_key,actor,preview.snapshot||jsonb_build_object('approval_origin','dpdi_setup_review_v1','setup_review_decision_id',d.id)) RETURNING * INTO batch;
 snap:=preview.snapshot||jsonb_build_object('mode','prepare','business_date',_business_date,'batch_id',batch.id,'approval_origin','dpdi_setup_review_v1','setup_review_decision_id',d.id,'configuration_status','dpdi_review_approved','pipeline_status_actual',(SELECT status FROM public.data_prep_pipelines WHERE id=pipe),'publication_eligible',false);
 INSERT INTO private.dpdi_jobs(tenant_id,setup_id,draft_version,actor_id,request_key,snapshot,snapshot_sha256) VALUES(_tenant_id,_setup_id,r.draft_version,actor,_request_key,snap,private.dpw_hash(snap)) RETURNING * INTO j;
 INSERT INTO private.dpdi_job_events(job_id,actor_id,phase) VALUES(j.id,actor,'queued');PERFORM private.dpd_event(_tenant_id,_setup_id,actor,'approved.prepare.queued',j.id,jsonb_build_object('approval_origin','dpdi_setup_review_v1','decision_id',d.id,'business_date',_business_date,'publish_allowed',false));RETURN private.dpdi_dto(j)||jsonb_build_object('request_replay',false);
END $function$
;

CREATE OR REPLACE FUNCTION private.dpdi_reviewer_reference(_tenant uuid, _kind text, _request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF _kind='setup' THEN RETURN(SELECT to_jsonb(r)||jsonb_build_object('kind','setup','status',coalesce(d.decision,'pending'),'decision',to_jsonb(d)) FROM private.dpdi_setup_review_requests r LEFT JOIN private.dpdi_setup_review_decisions d ON d.request_id=r.id WHERE r.id=_request AND r.tenant_id=_tenant);
 ELSIF _kind='publication' THEN RETURN(SELECT to_jsonb(r)||jsonb_build_object('kind','publication','status',coalesce(d.decision,'pending'),'decision',to_jsonb(d)) FROM private.dpdi_publication_requests r LEFT JOIN private.dpdi_publication_decisions d ON d.request_id=r.id WHERE r.id=_request AND r.tenant_id=_tenant);
 ELSE RAISE EXCEPTION 'dpdi.review_kind_required' USING ERRCODE='22023';END IF;
END $function$
;

CREATE OR REPLACE FUNCTION public.dpdi_list_reviewer_requests(_tenant_id uuid, _kind text, _status text, _page integer, _page_size integer, _search text, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,NULL,'review.queue.read',_request_context_id);amount bigint;items jsonb;ctx private.dpd_request_contexts%ROWTYPE;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,true);
 IF NOT EXISTS(SELECT 1 FROM public.tenant_members tm WHERE tm.tenant_id=_tenant_id AND tm.user_id=actor AND tm.active AND tm.role='tenant_admin') THEN RAISE EXCEPTION 'dpdi.actual_tenant_admin_reviewer_required' USING ERRCODE='42501';END IF;
 IF _kind IS NULL OR _kind NOT IN('all','setup','publication') OR _status IS NULL OR _status NOT IN('all','pending','approved','rejected') OR _page IS NULL OR _page<1 OR _page_size IS NULL OR _page_size NOT BETWEEN 1 AND 100 OR _search IS NULL OR length(_search)>200 THEN RAISE EXCEPTION 'dpdi.bounded_reviewer_queue_required' USING ERRCODE='22023';END IF;
 WITH requests AS(SELECT 'setup'::text kind,r.id,r.created_at,r.job_id,r.request_key,coalesce(d.decision,'pending') status FROM private.dpdi_setup_review_requests r LEFT JOIN private.dpdi_setup_review_decisions d ON d.request_id=r.id WHERE r.tenant_id=_tenant_id UNION ALL SELECT 'publication',r.id,r.created_at,r.job_id,r.request_key,coalesce(d.decision,'pending') FROM private.dpdi_publication_requests r LEFT JOIN private.dpdi_publication_decisions d ON d.request_id=r.id WHERE r.tenant_id=_tenant_id),
 allowed AS MATERIALIZED(SELECT r.* FROM requests r JOIN private.dpdi_jobs j ON j.id=r.job_id JOIN public.data_prep_pipelines p ON p.id=(j.snapshot->>'pipeline_id')::uuid WHERE (_kind='all' OR r.kind=_kind) AND (_status='all' OR r.status=_status) AND (_search='' OR strpos(lower(p.name||' '||r.request_key::text),lower(_search))>0) AND private.dpdi_reviewer_visible(_tenant_id,r.kind,r.id,actor)),
 selected AS(SELECT * FROM allowed ORDER BY created_at DESC,id DESC LIMIT _page_size OFFSET (_page::bigint-1)*_page_size)
 SELECT (SELECT count(*) FROM allowed),coalesce(jsonb_agg(private.dpdi_reviewer_evidence(_tenant_id,kind,id,actor,_request_context_id,false) ORDER BY created_at DESC,id DESC),'[]') INTO amount,items FROM selected;
 SELECT * INTO ctx FROM private.dpd_request_contexts WHERE id=_request_context_id;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'kind',_kind,'status_filter',_status,'page',_page,'page_size',_page_size,'search',_search,'total',amount::text,'requests',items,'current_context',jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'operation','review.queue.read','issued_at',ctx.created_at,'expires_at',ctx.expires_at,'read_context_sha256',private.dpw_hash(jsonb_build_object('context',ctx.id,'actor',actor,'tenant',_tenant_id,'kind',_kind,'status',_status))));
END $function$
;

CREATE OR REPLACE FUNCTION public.dpdi_read_reviewer_request(_tenant_id uuid, _setup_id uuid, _kind text, _request_id uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,CASE WHEN _kind='setup' THEN 'review.setup.read' WHEN _kind='publication' THEN 'publication.read' ELSE NULL END,_request_context_id);r jsonb:=private.dpdi_reviewer_reference(_tenant_id,_kind,_request_id);
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,true);
 IF r IS NULL OR r->>'setup_id' IS DISTINCT FROM _setup_id::text THEN RAISE EXCEPTION 'dpdi.actual_selected_reviewer_request_required' USING ERRCODE='42501';END IF;
 RETURN private.dpdi_reviewer_evidence(_tenant_id,_kind,_request_id,actor,_request_context_id);
END $function$
;

CREATE OR REPLACE FUNCTION public.dpdi_read_reviewer_records(_tenant_id uuid, _setup_id uuid, _request_kind text, _request_id uuid, _kind text, _page integer, _page_size integer, _search text, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,CASE WHEN _request_kind='setup' THEN 'review.setup.read' WHEN _request_kind='publication' THEN 'publication.read' ELSE NULL END,_request_context_id);
 frame jsonb:=private.dpdi_reviewer_frame(_tenant_id,_request_kind,_request_id,actor);
 j private.dpdi_jobs%ROWTYPE:=private.dpdi_authorize(_tenant_id,_setup_id,(frame->>'job_id')::uuid,actor,false);
 e private.dpdi_job_events%ROWTYPE:=private.dpdi_head(j.id);off bigint;amount bigint;records jsonb;proofs jsonb;cols jsonb;needle text;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,true);
 IF frame->'reference'->>'setup_id' IS DISTINCT FROM _setup_id::text THEN RAISE EXCEPTION 'dpdi.actual_reviewer_setup_binding_required' USING ERRCODE='42501';END IF;
 IF frame->>'availability' IN('expired','stale') THEN RETURN private.dpdi_reviewer_evidence(_tenant_id,_request_kind,_request_id,actor,_request_context_id,false)||jsonb_build_object('state','unavailable','records',NULL,'columns',NULL,'total',NULL,'page',_page,'page_size',_page_size,'search',_search);END IF;
 IF _kind NOT IN('rows','errors') OR _kind IS NULL OR _page IS NULL OR _page<1 OR _page_size IS NULL OR _page_size NOT BETWEEN 1 AND 100 OR _search IS NULL OR char_length(_search)>200 THEN RAISE EXCEPTION 'dpdi.bounded_record_page_required' USING ERRCODE='22023';END IF;
 off:=(_page::bigint-1)*_page_size;
 IF EXISTS(SELECT 1 FROM private.dpdi_run_inputs i WHERE i.job_id=j.id AND NOT private.dpd_original_viewable(i.original_file_id)) THEN
  RETURN jsonb_build_object('request_id',_request_id,'request_kind',_request_kind,'current_context',(private.dpdi_reviewer_evidence(_tenant_id,_request_kind,_request_id,actor,_request_context_id,false))->'current_context')||private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'state','unavailable','kind',_kind,'records',NULL,'columns',NULL,'total',NULL,'page',_page,'page_size',_page_size,'search',_search,'page_proofs',NULL);
 END IF;
 IF e.phase NOT IN('success','blocked') THEN
  RETURN jsonb_build_object('request_id',_request_id,'request_kind',_request_kind,'current_context',(private.dpdi_reviewer_evidence(_tenant_id,_request_kind,_request_id,actor,_request_context_id,false))->'current_context')||private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'state','pending','kind',_kind,'records',NULL,'columns',NULL,'total',NULL,'page',_page,'page_size',_page_size,'search',_search,'page_proofs',NULL);
 END IF;
 IF e.phase='blocked' AND _kind='rows' THEN
  RETURN jsonb_build_object('request_id',_request_id,'request_kind',_request_kind,'current_context',(private.dpdi_reviewer_evidence(_tenant_id,_request_kind,_request_id,actor,_request_context_id,false))->'current_context')||private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'state','blocked','kind',_kind,'records',NULL,'columns',NULL,'total','0','page',_page,'page_size',_page_size,'search',_search,'page_proofs',NULL);
 END IF;
 SELECT CASE WHEN _kind='rows' THEN coalesce(jsonb_agg(v.value->>'name' ORDER BY v.ordinality),'[]')||jsonb_build_array('extras_json') ELSE ' ["input_id","original_file_id","record_index","source_row_ordinal","reasons","payload","extras_json"]'::jsonb END INTO cols
 FROM jsonb_array_elements(j.snapshot->'confirmed_mapping'->'output_schema') WITH ORDINALITY v(value,ordinality);
 needle:=lower(_search);
 IF needle='' THEN
  amount:=CASE WHEN _kind='rows' THEN e.source_records ELSE e.blocking_records END;
  -- Prefix sums cover at most the small page-metadata set, not all source records.
  WITH metadata AS(
   SELECT p.*,CASE WHEN _kind='rows' THEN p.row_count ELSE p.blocking_count END n,
    coalesce(sum(CASE WHEN _kind='rows' THEN p.row_count ELSE p.blocking_count END) OVER(ORDER BY p.sequence ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0)::bigint first_index
   FROM private.dpdi_job_pages p WHERE p.job_id=j.id
  ), relevant AS(SELECT * FROM metadata WHERE first_index<off+_page_size AND first_index+n>off),
  decoded AS(SELECT p.*,x.ordinality,x.value::jsonb record FROM relevant p CROSS JOIN LATERAL regexp_split_to_table(p.wire,E'\n') WITH ORDINALITY x(value,ordinality) WHERE x.value<>''),
  filtered AS(SELECT *,row_number() OVER(PARTITION BY sequence ORDER BY ordinality)-1 item_index FROM decoded WHERE _kind='rows' OR record->'blocking'='true'::jsonb),
  selected AS(SELECT * FROM filtered WHERE first_index+item_index>=off AND first_index+item_index<off+_page_size)
  SELECT coalesce(jsonb_agg(record ORDER BY sequence,ordinality),'[]'),coalesce((SELECT jsonb_agg(jsonb_build_object('sequence',sequence,'row_count',row_count,'sha256',sha256) ORDER BY sequence) FROM relevant),'[]') INTO records,proofs FROM selected;
 ELSE
  -- Search is over the complete authorised collection. No client loaded-row subset.
  WITH decoded AS(SELECT p.sequence,p.row_count,p.sha256,x.ordinality,x.value::jsonb record FROM private.dpdi_job_pages p CROSS JOIN LATERAL regexp_split_to_table(p.wire,E'\n') WITH ORDINALITY x(value,ordinality) WHERE p.job_id=j.id AND x.value<>''),
  matches AS(SELECT * FROM decoded WHERE (_kind='rows' OR record->'blocking'='true'::jsonb) AND strpos(lower(CASE WHEN _kind='rows' THEN ((record->'payload')||jsonb_build_object('extras_json',record->'extras_json'))::text ELSE record::text END),needle)>0),
  selected AS(SELECT * FROM matches ORDER BY sequence,ordinality LIMIT _page_size OFFSET off)
  SELECT (SELECT count(*) FROM matches),coalesce(jsonb_agg(record ORDER BY sequence,ordinality),'[]'),coalesce((SELECT jsonb_agg(jsonb_build_object('sequence',p.sequence,'row_count',p.row_count,'sha256',p.sha256) ORDER BY p.sequence) FROM(SELECT DISTINCT sequence,row_count,sha256 FROM selected)p),'[]') INTO amount,records,proofs FROM selected;
 END IF;
 IF jsonb_array_length(records)>_page_size THEN RAISE EXCEPTION 'dpdi.record_page_overflow';END IF;
 RETURN jsonb_build_object('request_id',_request_id,'request_kind',_request_kind,'current_context',(private.dpdi_reviewer_evidence(_tenant_id,_request_kind,_request_id,actor,_request_context_id,false))->'current_context')||private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'state','available','kind',_kind,'records',records,'columns',cols,'total',amount::text,'page',_page,'page_size',_page_size,'search',_search,'page_proofs',proofs);
END $function$
;

CREATE OR REPLACE FUNCTION public.dpd_issue_request_context(_tenant_id uuid, _verified_subject jsonb, _trusted_ip text, _ttl_seconds integer, _operation text, _setup_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid;enabled boolean;ip inet;expires timestamptz;c private.dpd_request_contexts%ROWTYPE;write boolean;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR current_setting('role',true) IS DISTINCT FROM 'service_role' OR _ttl_seconds IS NULL OR _ttl_seconds NOT BETWEEN 1 AND 60
 OR (_operation IN('setup.create','setup.read','setup.lookup','setup.save','original.authorize','original.claim','original.lookup','original.read','original.rows','source.register','preview.bind','preview.lookup','audit.read','original.confirm','original.chunk','original.schema','parser.enqueue','parser.lookup','parser.claim','parser.progress','preview.input','mapping.read','review.shared.read','review.shared.decide','preview.job.enqueue','preview.job.claim','preview.job.input','preview.job.unique','preview.job.commit','preview.job.release','preview.job.cancel','preview.job.status','preview.job.result','preview.job.next','catalogue.read','review.setup.request','review.setup.read','review.setup.decide','prepare.job.enqueue','publication.request','publication.read','publication.decide','publication.perform','publication.dataset.read','review.queue.read')) IS DISTINCT FROM true
 OR (_setup_id IS NULL AND _operation NOT IN('setup.create','setup.lookup','review.queue.read')) THEN RAISE EXCEPTION 'dpd.fixed_closed_request_context_required' USING ERRCODE='42501';END IF;
 actor:=private.dpd_peer_actor(_tenant_id,_verified_subject);IF _operation='review.queue.read' AND NOT EXISTS(SELECT 1 FROM public.tenant_members tm WHERE tm.tenant_id=_tenant_id AND tm.user_id=actor AND tm.active AND tm.role='tenant_admin') THEN RAISE EXCEPTION 'dpdi.actual_tenant_admin_queue_required' USING ERRCODE='42501';END IF;IF _operation IN('review.shared.read','review.shared.decide','review.queue.read') THEN PERFORM public.assert_data_prep_actor(_tenant_id,actor,true);END IF;write:=_operation IN('setup.create','setup.save','original.authorize','original.claim','source.register','preview.bind','original.confirm','original.chunk','original.schema','parser.enqueue','parser.claim','parser.progress','review.shared.decide','preview.job.enqueue','preview.job.claim','preview.job.unique','preview.job.commit','preview.job.release','preview.job.cancel','review.setup.request','review.setup.decide','prepare.job.enqueue','publication.request','publication.decide','publication.perform');IF write THEN PERFORM public.assert_data_prep_actor(_tenant_id,actor,false);END IF;
 IF public.user_has_permission(actor,_tenant_id,CASE WHEN write THEN 'data.prep.author' ELSE 'data.prep.read' END,NULL) IS DISTINCT FROM true
 OR (_setup_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM private.dpd_setups WHERE id=_setup_id AND tenant_id=_tenant_id AND (created_by=actor OR (_operation IN('preview.job.status','preview.job.result') AND EXISTS(SELECT 1 FROM private.dpd_preview_links read_link WHERE read_link.setup_id=_setup_id AND read_link.tenant_id=_tenant_id AND private.data_prep_pipeline_scope_allows(actor,_tenant_id,read_link.pipeline_id,'view') IS TRUE)) OR _operation IN('review.shared.read','review.shared.decide') OR (_operation IN('review.setup.read','review.setup.decide','publication.read','publication.decide') AND private.dpdi_review_reader(_tenant_id,_setup_id,actor)) OR (_operation='publication.dataset.read' AND EXISTS(SELECT 1 FROM private.dpdi_published_datasets ds WHERE ds.setup_id=_setup_id AND ds.tenant_id=_tenant_id AND private.data_prep_pipeline_scope_allows(actor,_tenant_id,ds.pipeline_id,'view') IS TRUE))))) THEN RAISE EXCEPTION 'dpd.context_current_scope_denied' USING ERRCODE='42501';END IF;
 SELECT ip_allowlist_enabled INTO enabled FROM public.tenant_security_settings WHERE tenant_id=_tenant_id;IF NOT FOUND OR enabled IS NULL THEN RAISE EXCEPTION 'dpd.current_network_policy_unavailable' USING ERRCODE='42501';END IF;
 BEGIN ip:=nullif(_trusted_ip,'')::inet;EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'dpd.trusted_transport_ip_invalid' USING ERRCODE='42501';END;
 IF enabled AND (ip IS NULL OR public.ip_in_tenant_allowlist(_tenant_id,host(ip)) IS DISTINCT FROM true) THEN RAISE EXCEPTION 'dpd.current_network_denied' USING ERRCODE='42501';END IF;
 expires:=least(clock_timestamp()+_ttl_seconds*interval '1 second',to_timestamp((_verified_subject->>'exp')::double precision));IF expires<=clock_timestamp() THEN RAISE EXCEPTION 'dpd.subject_expired' USING ERRCODE='42501';END IF;
 c.id:=gen_random_uuid();
 INSERT INTO private.dpd_request_contexts(id,token_sha256,tenant_id,actor_id,verified_subject,operation,setup_id,intent_sha256,transport_kind,request_ip,transport_attestation_sha256,expires_at)
 VALUES(c.id,encode(sha256(convert_to(c.id::text,'UTF8')),'hex'),_tenant_id,actor,_verified_subject,_operation,_setup_id,private.dpw_hash(jsonb_build_object('operation',_operation,'setup_id',_setup_id)),
 'main_fixed_service_verified_middleware_CF_transport',ip,private.dpw_hash(jsonb_build_object('actor',actor,'tenant',_tenant_id,'operation',_operation,'setup',_setup_id,'issuer_role','service_role')),expires) RETURNING * INTO c;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context) VALUES(actor,_tenant_id,'workspace','dpd.request_context.issued','data_prep_authoring_context',c.id::text,jsonb_build_object('operation',_operation,'setup_id',_setup_id,'expires_at',expires,'network_policy_enabled',enabled,'issuer_transport','service_role','browser_issuance_allowed',false));
 RETURN jsonb_build_object('request_context_id',c.id,'actor_id',actor,'tenant_id',_tenant_id,'operation',_operation,'setup_id',_setup_id,'expires_at',expires,'network_policy_available',true,'network_policy_enabled',enabled,'network_allowed',true,'issuer_transport','service_role','verified_subject_expires_at',to_timestamp((_verified_subject->>'exp')::double precision),'browser_issuance_allowed',false);
END $function$
;

