 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$SELECT '{"trim":{"params":[{"name":"field","label":"Field","kind":"text","required":true}]},"ltrim":{"params":[{"name":"field","label":"Field","kind":"text","required":true}]},"rtrim":{"params":[{"name":"field","label":"Field","kind":"text","required":true}]},"collapse_whitespace":{"params":[{"name":"field","label":"Field","kind":"text","required":true}]},"uppercase":{"params":[{"name":"field","label":"Field","kind":"text","required":true}]},"lowercase":{"params":[{"name":"field","label":"Field","kind":"text","required":true}]},"titlecase":{"params":[{"name":"field","label":"Field","kind":"text","required":true}]},"remove_non_printable":{"params":[{"name":"field","label":"Field","kind":"text","required":true}]},"pad_left":{"params":[{"name":"field","label":"Field","kind":"text","required":true},{"name":"length","label":"Length","kind":"number","required":true},{"name":"char","label":"Pad char","kind":"text","placeholder":"0"}]},"pad_right":{"params":[{"name":"field","label":"Field","kind":"text","required":true},{"name":"length","label":"Length","kind":"number","required":true},{"name":"char","label":"Pad char","kind":"text","placeholder":" "}]},"substring":{"params":[{"name":"field","label":"Field","kind":"text","required":true},{"name":"start","label":"Start","kind":"number","required":true},{"name":"end","label":"End","kind":"number"}]},"replace":{"params":[{"name":"field","label":"Field","kind":"text","required":true},{"name":"find","label":"Find","kind":"text","required":true},{"name":"replace","label":"Replace with","kind":"text"}]},"regex_replace":{"params":[{"name":"field","label":"Field","kind":"text","required":true},{"name":"pattern","label":"Regex","kind":"text","required":true},{"name":"replace","label":"Replacement","kind":"text"}]},"cast_number":{"params":[{"name":"field","label":"Field","kind":"text","required":true}]},"cast_int":{"params":[{"name":"field","label":"Field","kind":"text","required":true}]},"cast_boolean":{"params":[{"name":"field","label":"Field","kind":"text","required":true}]},"cast_date":{"params":[{"name":"field","label":"Field","kind":"text","required":true}]},"parse_date_format":{"params":[{"name":"field","label":"Field","kind":"text","required":true},{"name":"format","label":"Format","kind":"select","options":["DD/MM/YYYY","MM/DD/YYYY","YYYY-MM-DD","DD-MMM-YYYY","YYYYMMDD"],"required":true}]},"round":{"params":[{"name":"field","label":"Field","kind":"text","required":true},{"name":"decimals","label":"Decimals","kind":"number","required":true}]},"abs":{"params":[{"name":"field","label":"Field","kind":"text","required":true}]},"rename":{"params":[{"name":"field","label":"From","kind":"text","required":true},{"name":"to","label":"To","kind":"text","required":true}]},"drop_columns":{"params":[{"name":"fields","label":"Fields (comma list)","kind":"csv","required":true}]},"select_columns":{"params":[{"name":"fields","label":"Fields (comma list)","kind":"csv","required":true}]},"fill_null":{"params":[{"name":"field","label":"Field","kind":"text","required":true},{"name":"value","label":"Default value","kind":"text","required":true}]},"coalesce":{"params":[{"name":"fields","label":"Source fields (csv)","kind":"csv","required":true},{"name":"to","label":"Target field","kind":"text","required":true}]},"dedupe":{"params":[{"name":"fields","label":"Key fields (csv)","kind":"csv","required":true}]},"sort":{"params":[{"name":"field","label":"Field","kind":"text","required":true},{"name":"direction","label":"Direction","kind":"select","options":["asc","desc"]}]},"filter":{"params":[{"name":"field","label":"Field","kind":"text","required":true},{"name":"pattern","label":"Regex","kind":"text","required":true}]},"filter_expr":{"params":[{"name":"field","label":"Field","kind":"text","required":true},{"name":"expr","label":"Expression","kind":"text","placeholder":"> 100","required":true}]},"derive_concat":{"params":[{"name":"fields","label":"Source fields (csv)","kind":"csv","required":true},{"name":"to","label":"Target field","kind":"text","required":true},{"name":"separator","label":"Separator","kind":"text","placeholder":" "}]},"derive_arithmetic":{"params":[{"name":"left","label":"Left field","kind":"text","required":true},{"name":"op","label":"Op","kind":"select","options":["+","-","*","/"],"required":true},{"name":"right","label":"Right field","kind":"text","required":true},{"name":"to","label":"Target field","kind":"text","required":true}]},"split":{"params":[{"name":"field","label":"Field","kind":"text","required":true},{"name":"delimiter","label":"Delimiter","kind":"text","required":true},{"name":"index","label":"Token #","kind":"number","required":true},{"name":"to","label":"Target field","kind":"text","required":true}]},"json_extract":{"params":[{"name":"field","label":"JSON field","kind":"text","required":true},{"name":"path","label":"Dotted path","kind":"text","placeholder":"data.amount","required":true},{"name":"to","label":"Target field","kind":"text","required":true}]},"normalize_currency_amount":{"params":[{"name":"field","label":"Field","kind":"text","required":true}]},"flip_sign_when":{"params":[{"name":"amount_field","label":"Amount field","kind":"text","required":true},{"name":"indicator_field","label":"Indicator field","kind":"text","required":true},{"name":"indicator_value","label":"When equals","kind":"text","placeholder":"DR","required":true}]},"normalize_iban":{"params":[{"name":"field","label":"Field","kind":"text","required":true}]},"normalize_bic":{"params":[{"name":"field","label":"Field","kind":"text","required":true}]},"normalize_isin":{"params":[{"name":"field","label":"Field","kind":"text","required":true}]},"normalize_country":{"params":[{"name":"field","label":"Field","kind":"text","required":true}]},"mask_pii":{"params":[{"name":"field","label":"Field","kind":"text","required":true},{"name":"show_last","label":"Show last #","kind":"number","placeholder":"4"}]},"hash_field":{"params":[{"name":"field","label":"Field","kind":"text","required":true}]},"redact":{"params":[{"name":"field","label":"Field","kind":"text","required":true},{"name":"token","label":"Token","kind":"text","placeholder":"[REDACTED]"}]}}'::jsonb$function$
;

CREATE OR REPLACE FUNCTION private.dpd_transform_issues(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE entry record;step jsonb;definition jsonb;parameter jsonb;value jsonb;issues jsonb:='[]';location jsonb;
BEGIN
 IF jsonb_typeof(_payload->'steps') IS DISTINCT FROM 'array' OR jsonb_typeof(_payload->'feeds') IS DISTINCT FROM 'array' THEN
  RETURN jsonb_build_array(jsonb_build_object('path','[]'::jsonb,'code','configuration_step_arrays_required'));
 END IF;
 FOR entry IN
  SELECT x.value step,jsonb_build_array('steps',x.ordinality-1) path FROM jsonb_array_elements(_payload->'steps') WITH ORDINALITY x(value,ordinality)
  UNION ALL
  SELECT x.value,jsonb_build_array('feeds',f.ordinality-1,'steps',x.ordinality-1) FROM jsonb_array_elements(_payload->'feeds') WITH ORDINALITY f(value,ordinality)
   CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(f.value->'steps')='array' THEN f.value->'steps' ELSE '[]'::jsonb END) WITH ORDINALITY x(value,ordinality)
 LOOP
  step:=entry.step;location:=entry.path;definition:=private.dpd_canonical_transform_catalog()->(step->>'kind');
  IF jsonb_typeof(step) IS DISTINCT FROM 'object' OR definition IS NULL THEN
   issues:=issues||jsonb_build_array(jsonb_build_object('path',location||jsonb_build_array('kind'),'code','unknown_transform_kind','kind',step->>'kind'));CONTINUE;
  END IF;
  FOR parameter IN SELECT p.value FROM jsonb_array_elements(definition->'params') p(value) LOOP
   value:=step->(parameter->>'name');IF value IS NULL OR value='null'::jsonb THEN value:=step->'params'->(parameter->>'name');END IF;
   IF coalesce((parameter->>'required')::boolean,false) AND (value IS NULL OR value='null'::jsonb OR value='""'::jsonb OR value='[]'::jsonb) THEN
    issues:=issues||jsonb_build_array(jsonb_build_object('path',location||jsonb_build_array(parameter->>'name'),'code','required_transform_parameter'));CONTINUE;
   END IF;
   IF value IS NULL OR value='null'::jsonb OR value='""'::jsonb THEN CONTINUE;END IF;
   IF (parameter->>'kind'='csv' AND (jsonb_typeof(value)<>'array' OR EXISTS(SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(value)='array' THEN value ELSE '[]'::jsonb END) v(cell) WHERE jsonb_typeof(v.cell)<>'string' OR btrim(v.cell#>>'{}')='')))
    OR (parameter->>'kind'='number' AND jsonb_typeof(value)<>'number')
    OR (parameter->>'kind'='select' AND (jsonb_typeof(value)<>'string' OR NOT(parameter->'options' @> jsonb_build_array(value)))) THEN
    issues:=issues||jsonb_build_array(jsonb_build_object('path',location||jsonb_build_array(parameter->>'name'),'code','transform_parameter_domain'));
   END IF;
  END LOOP;
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(_payload->'feeds') f WHERE f ? 'steps' AND jsonb_typeof(f->'steps') IS DISTINCT FROM 'array') THEN
  issues:=issues||jsonb_build_array(jsonb_build_object('path',jsonb_build_array('feeds','steps'),'code','configuration_step_arrays_required'));
 END IF;
 RETURN issues;
END $function$
;

CREATE OR REPLACE FUNCTION private.dpd_assert_transform_configuration(_payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE issues jsonb:=private.dpd_transform_issues(_payload);
BEGIN IF jsonb_array_length(issues)>0 THEN RAISE EXCEPTION 'dpd.invalid_transform_configuration' USING ERRCODE='22023',DETAIL=issues::text,HINT='Use canonical catalog kinds and valid parameters in a new explicit configuration version; existing snapshots are immutable.';END IF;END $function$
;

CREATE OR REPLACE FUNCTION private.dpdi_terminal_intent_dto(t private.dpdi_terminal_intents)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
 SELECT to_jsonb(t)||jsonb_build_object('previous_head_event_id',t.previous_head_event_id::text,'event_id',t.event_id::text)
$function$
;

CREATE OR REPLACE FUNCTION public.dpdi_cancel_owned_job(_tenant_id uuid, _setup_id uuid, _job_id uuid, _expected_snapshot_sha256 text, _expected_head_event_id bigint, _claim_key uuid, _reason_code text, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'preview.job.cancel',_request_context_id);
 j private.dpdi_jobs%ROWTYPE;e private.dpdi_job_events%ROWTYPE;t private.dpdi_terminal_intents%ROWTYPE;
 run public.data_prep_delivery_runs%ROWTYPE;issues jsonb;terminal_result jsonb;phase text;event_id bigint;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,false);
 IF public.user_has_permission(actor,_tenant_id,'data.prep.author',NULL) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpdi.current_author_required_for_owned_terminal_intent' USING ERRCODE='42501';END IF;
 SELECT * INTO j FROM private.dpdi_jobs WHERE id=_job_id AND tenant_id=_tenant_id AND setup_id=_setup_id AND actor_id=actor FOR UPDATE;
 IF j.id IS NULL THEN RAISE EXCEPTION 'dpdi.actual_owned_job_required' USING ERRCODE='42501';END IF;
 -- Read authorization retains the exact historical configuration without requiring
 -- the latest draft version. Cancellation adds current RUN and source INGEST gates.
 PERFORM private.dpdi_authorize(_tenant_id,_setup_id,j.id,actor,false);
 IF private.data_prep_pipeline_scope_allows(actor,_tenant_id,(j.snapshot->>'pipeline_id')::uuid,'run') IS DISTINCT FROM true
 OR EXISTS(SELECT 1 FROM private.dpd_preview_file_links i WHERE i.setup_id=j.setup_id AND i.draft_version=j.draft_version AND
  (private.dpw_source_allows(actor,_tenant_id,i.data_source_id,'view') IS DISTINCT FROM true OR private.dpw_source_allows(actor,_tenant_id,i.data_source_id,'ingest') IS DISTINCT FROM true))
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(j.snapshot->'inputs') pin(value) WHERE NOT EXISTS(
  SELECT 1 FROM private.dpd_preview_file_links i WHERE i.setup_id=j.setup_id AND i.draft_version=j.draft_version
   AND i.id::text=pin.value->>'input_id' AND i.data_source_id::text=pin.value->>'data_source_id'
   AND i.original_file_id::text=pin.value->>'original_file_id' AND i.selection_sha256 IS NOT DISTINCT FROM pin.value->>'selection_sha256'))
 THEN RAISE EXCEPTION 'dpdi.current_snapshot_source_run_authority_required' USING ERRCODE='42501';END IF;
 IF _request_key IS NULL OR _expected_head_event_id IS NULL OR _expected_snapshot_sha256 IS DISTINCT FROM j.snapshot_sha256
 OR private.dpw_hash(j.snapshot) IS DISTINCT FROM j.snapshot_sha256 OR _reason_code IS NULL OR _reason_code NOT IN('invalid_configuration','owner_cancelled')
 THEN RAISE EXCEPTION 'dpdi.exact_terminal_snapshot_intent_required' USING ERRCODE='PT409';END IF;
 SELECT * INTO t FROM private.dpdi_terminal_intents WHERE job_id=j.id OR (tenant_id=_tenant_id AND actor_id=actor AND request_key=_request_key);
 IF FOUND THEN
  IF t.job_id<>j.id OR t.request_key<>_request_key OR t.snapshot_sha256<>_expected_snapshot_sha256 OR t.previous_head_event_id<>_expected_head_event_id
   OR t.claim_key IS DISTINCT FROM _claim_key OR t.reason_code<>_reason_code THEN RAISE EXCEPTION 'dpdi.immutable_terminal_request_conflict' USING ERRCODE='PT409';END IF;
  RETURN private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'head_event_id',t.event_id::text,'terminal_intent',private.dpdi_terminal_intent_dto(t),'request_replay',true,'released_rows','0','publish_allowed',false);
 END IF;
 e:=private.dpdi_head(j.id);
 IF e.id<>_expected_head_event_id OR e.phase NOT IN('queued','running') THEN RAISE EXCEPTION 'dpdi.terminal_head_changed_status_first' USING ERRCODE='PT409';END IF;
 IF e.phase='running' AND e.lease_expires_at>clock_timestamp() AND (e.claim_key IS DISTINCT FROM _claim_key OR _claim_key IS NULL)
 THEN RAISE EXCEPTION 'dpdi.live_owned_claim_required_for_cancellation' USING ERRCODE='42501';END IF;
 issues:=private.dpd_transform_issues(j.snapshot->'pipeline_configuration');
 IF _reason_code='invalid_configuration' AND jsonb_array_length(issues)=0 THEN RAISE EXCEPTION 'dpdi.native_invalid_configuration_evidence_required' USING ERRCODE='22023';END IF;
 phase:=CASE WHEN _reason_code='invalid_configuration' THEN 'blocked' ELSE 'cancelled' END;
 SELECT * INTO run FROM public.data_prep_delivery_runs WHERE id=j.reserved_run_id AND tenant_id=_tenant_id FOR UPDATE;
 IF run.id IS NOT NULL AND run.state<>'running' THEN RAISE EXCEPTION 'dpdi.terminal_run_state_changed' USING ERRCODE='PT409';END IF;
 INSERT INTO private.dpdi_job_events(job_id,actor_id,phase,claim_key,lease_expires_at,input_index,next_record,source_records,blocking_records,output_pages,output_root_sha256,last_page_sha256)
 VALUES(j.id,actor,phase,e.claim_key,clock_timestamp(),e.input_index,e.next_record,e.source_records,e.blocking_records,e.output_pages,e.output_root_sha256,e.last_page_sha256) RETURNING id INTO event_id;
 INSERT INTO private.dpdi_terminal_intents(tenant_id,setup_id,job_id,actor_id,request_key,snapshot_sha256,previous_head_event_id,event_id,claim_key,reason_code,phase,validation_issues)
 VALUES(_tenant_id,_setup_id,j.id,actor,_request_key,j.snapshot_sha256,e.id,event_id,_claim_key,_reason_code,phase,issues) RETURNING * INTO t;
 terminal_result:=jsonb_build_object('representation','dpdi_configuration_terminal_v1','job_id',j.id,'status',CASE WHEN phase='blocked' THEN 'failed' ELSE 'cancelled' END,
  'terminal_reason_code',_reason_code,'validation_issues',issues,'snapshot_sha256',j.snapshot_sha256,'terminal_event_id',event_id::text,
  'full_final_ack',true,'full_original_rescan',false,'source_records',e.source_records::text,'blocking_records',e.blocking_records::text,
  'configuration_blocking_failure',phase='blocked','blocking_failure',true,'accepted_records','0','preview_rows','0','released_rows','0','publication_eligible',false,'acceptedRows',NULL,'outputLineage',NULL);
 IF run.id IS NOT NULL THEN UPDATE public.data_prep_delivery_runs SET state='failed',result=terminal_result,result_sha256=private.dpw_hash(terminal_result),finished_at=clock_timestamp() WHERE id=run.id;END IF;
 IF j.snapshot->>'mode'='prepare' THEN UPDATE public.data_prep_delivery_batches SET state='failed' WHERE id=(j.snapshot->>'batch_id')::uuid AND tenant_id=_tenant_id AND state='processing';END IF;
 PERFORM private.dpd_event(_tenant_id,_setup_id,actor,'job.terminal_intent.recorded',j.id,jsonb_build_object('intent_id',t.id,'request_key',t.request_key,'snapshot_sha256',j.snapshot_sha256,'previous_head_event_id',e.id::text,'event_id',event_id::text,'reason_code',_reason_code,'phase',phase,'validation_issues',issues,'publish_allowed',false));
 RETURN private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'head_event_id',event_id::text,'terminal_intent',private.dpdi_terminal_intent_dto(t),'request_replay',false,'released_rows','0','publish_allowed',false);
END $function$
;
CREATE VIEW "public"."v_recon_matches_consolidated" WITH (security_invoker=true) AS  SELECT id AS match_id,
    tenant_id,
    run_id,
    match_key,
    rule_id,
    cardinality,
    confidence,
    score,
    created_at,
    members -> 'A'::text AS side_a,
    members -> 'B'::text AS side_b,
    members -> 'C'::text AS side_c,
    jsonb_build_object('amount_delta', COALESCE((((members -> 'A'::text) ->> 'amount'::text)::numeric) - (((members -> 'B'::text) ->> 'amount'::text)::numeric), 0::numeric), 'has_diff', ((members -> 'A'::text) ->> 'amount'::text) IS DISTINCT FROM ((members -> 'B'::text) ->> 'amount'::text)) AS deltas
   FROM recon_matches m;
CREATE VIEW "public"."llm_providers_safe" WITH (security_invoker=true) AS  SELECT id,
    scope,
    tenant_id,
    provider,
    display_name,
    base_url,
    model,
    key_last4,
    is_active,
    allowed_regions,
    created_at,
    updated_at
   FROM llm_providers;
CREATE VIEW "public"."tenant_invitations_for_invitee" WITH (security_invoker=true) AS  SELECT id,
    tenant_id,
    email,
    role,
    invited_by,
    expires_at,
    created_at
   FROM tenant_invitations
  WHERE (auth.jwt() ->> 'email'::text) IS NOT NULL AND lower(email::text) = lower(auth.jwt() ->> 'email'::text) AND accepted_at IS NULL AND expires_at > now();
CREATE VIEW "public"."aidp_outputs_live" WITH (security_invoker=true) AS  SELECT id,
    tenant_id,
    document_id,
    entity_type_id,
    prediction_field_id,
    value_text,
    value_number,
    value_date,
    value_json,
    confidence,
    source_annotation_id,
    supersedes_id,
    superseded_at,
    generated_at,
    generated_by,
    origin,
    created_at
   FROM aidp_outputs
  WHERE superseded_at IS NULL;
CREATE VIEW "public"."v_substantiation_status" WITH (security_invoker=true) AS  SELECT id,
    tenant_id,
    signoff_id,
    account_code,
    account_name,
    currency,
    gl_balance,
    sub_ledger_balance,
    variance,
    tolerance,
    status,
    evidence,
    note,
    prepared_by,
    prepared_at,
    approved_by,
    approved_at,
    created_at,
    updated_at,
    gl_source,
    recon_id,
    recon_run_id,
    ageing_buckets,
    supporting_items,
    variance_explanation,
    variance_category,
    reviewer_id,
    reviewed_at,
    last_recon_status,
    last_recon_at,
        CASE
            WHEN abs(COALESCE(variance, 0::numeric)) <= COALESCE(tolerance, 0::numeric) THEN 'green'::text
            WHEN abs(COALESCE(variance, 0::numeric)) <= (COALESCE(tolerance, 0::numeric) * 3::numeric) THEN 'amber'::text
            ELSE 'red'::text
        END AS traffic_light
   FROM balance_substantiations b;
CREATE VIEW "public"."v_schedule_priority_queue" WITH (security_invoker=true) AS  SELECT s.id,
    s.tenant_id,
    s.definition_id,
    s.name,
    s.cron_expression,
    s.enabled,
    s.last_run_at,
    s.last_status,
    s.last_run_id,
    s.last_error,
    s.created_by,
    s.created_at,
    s.updated_at,
    s.mode,
    s.poll_interval_seconds,
    s.watermark_column,
    s.watermark_value,
    s.intraday_window_minutes,
    s.risk_score,
    s.risk_tier,
    s.priority_boost,
    s.value_threshold,
    s.volatility_30d,
    s.last_risk_eval_at,
    d.name AS recon_name,
    d.tenant_id AS recon_tenant_id
   FROM recon_schedules s
     JOIN recon_definitions d ON d.id = s.definition_id
  WHERE s.enabled = true
  ORDER BY (s.risk_score + s.priority_boost::numeric) DESC NULLS LAST, s.last_run_at NULLS FIRST;
CREATE VIEW "public"."tenant_custom_domains_public" WITH (security_invoker=true) AS  SELECT host,
    verification_status = 'verified'::text AS is_verified
   FROM tenant_custom_domains
  WHERE verification_status = 'verified'::text;
CREATE VIEW "public"."tenant_scoped_tables_audit" WITH (security_invoker=on) AS  SELECT c.relname AS table_name,
    c.relrowsecurity AS rls_enabled,
    c.relforcerowsecurity AS rls_forced,
    ( SELECT count(*) AS count
           FROM pg_policies p
          WHERE p.schemaname = 'public'::name AND p.tablename = c.relname) AS policy_count
   FROM pg_class c
     JOIN pg_namespace n ON n.oid = c.relnamespace
     JOIN pg_attribute a ON a.attrelid = c.oid
  WHERE n.nspname = 'public'::name AND c.relkind = 'r'::"char" AND a.attname = 'tenant_id'::name AND NOT a.attisdropped;
CREATE VIEW "public"."v_mkt_certification_report" WITH (security_invoker=true) AS  SELECT t.id,
    t.slug,
    t.title,
    c.name AS category,
    t.domain_key,
    t.pack_type::text AS pack_type,
    t.certification::text AS certification,
    t.spec_valid,
    t.certification_score,
    t.recon_score,
    t.ai_score,
    t.governance_score,
    t.refactor_gaps,
    t.removal_reason,
    t.install_count,
    t.updated_at
   FROM mkt_templates t
     LEFT JOIN mkt_template_categories c ON c.id = t.category_id;
CREATE VIEW "public"."v_marketplace_ratings_unified" WITH (security_invoker=true) AS  SELECT mr.id,
    mr.listing_id,
    mr.tenant_id,
    mr.user_id,
    mr.rating AS stars,
    mr.review,
    mr.created_at,
    'canonical'::text AS source
   FROM marketplace_ratings mr
UNION ALL
 SELECT mtr.id,
    ml.id AS listing_id,
    mtr.tenant_id,
    mtr.user_id,
    mtr.stars,
    mtr.review,
    mtr.created_at,
    'legacy_mkt'::text AS source
   FROM mkt_template_ratings mtr
     JOIN marketplace_listings ml ON ml.legacy_mkt_template_id = mtr.template_id;
CREATE VIEW "public"."v_marketplace_analytics" WITH (security_invoker=true) AS  SELECT ml.id AS listing_id,
    ml.slug,
    ml.title,
    ml.kind,
    ml.tier,
    ml.channel,
    ml.status,
    ml.install_count,
    count(DISTINCT mi.tenant_id) AS installed_tenants,
    count(DISTINCT wtu.workspace_id) AS active_workspaces,
    count(wtu.id) AS usage_events,
    COALESCE(avg(vru.stars)::numeric(3,2), NULL::numeric) AS rating_avg,
    count(vru.id) AS rating_count,
    max(mi.installed_at) AS last_installed_at,
    max(wtu.created_at) AS last_used_at
   FROM marketplace_listings ml
     LEFT JOIN marketplace_installs mi ON mi.listing_id = ml.id
     LEFT JOIN tenant_templates tt ON tt.source_template_id = ml.legacy_mkt_template_id
     LEFT JOIN workspace_template_usage wtu ON wtu.tenant_template_id = tt.id
     LEFT JOIN v_marketplace_ratings_unified vru ON vru.listing_id = ml.id
  GROUP BY ml.id, ml.slug, ml.title, ml.kind, ml.tier, ml.channel, ml.status, ml.install_count;
