ALTER TABLE "public"."data_resource_registry" ADD CONSTRAINT "data_resource_registry_resource_type_check" CHECK ((resource_type = ANY (ARRAY['data_source'::text, 'db_connection'::text, 'inline_api_source'::text, 'erp_connection'::text, 'file_watcher'::text, 'aidp_template'::text, 'aidp_document'::text, 'reference_table'::text, 'data_prep_pipeline'::text, 'data_source_schedule'::text, 'tenant_template'::text, 'collateral_schedule'::text, 'collateral_csa_agreement'::text])));
ALTER TABLE "public"."data_resource_registry" ADD CONSTRAINT "data_resource_registry_exact_root_ck" CHECK (((num_nonnulls(data_source_id, db_connection_id, inline_api_source_id, erp_connection_id, file_watcher_id, aidp_template_id, aidp_document_id, reference_table_id, data_prep_pipeline_id, data_source_schedule_id, tenant_template_id, collateral_schedule_id, collateral_csa_agreement_id) = 1) AND
CASE resource_type
    WHEN 'data_source'::text THEN (data_source_id IS NOT NULL)
    WHEN 'db_connection'::text THEN (db_connection_id IS NOT NULL)
    WHEN 'inline_api_source'::text THEN (inline_api_source_id IS NOT NULL)
    WHEN 'erp_connection'::text THEN (erp_connection_id IS NOT NULL)
    WHEN 'file_watcher'::text THEN (file_watcher_id IS NOT NULL)
    WHEN 'aidp_template'::text THEN (aidp_template_id IS NOT NULL)
    WHEN 'aidp_document'::text THEN (aidp_document_id IS NOT NULL)
    WHEN 'reference_table'::text THEN (reference_table_id IS NOT NULL)
    WHEN 'data_prep_pipeline'::text THEN (data_prep_pipeline_id IS NOT NULL)
    WHEN 'data_source_schedule'::text THEN (data_source_schedule_id IS NOT NULL)
    WHEN 'tenant_template'::text THEN (tenant_template_id IS NOT NULL)
    WHEN 'collateral_schedule'::text THEN (collateral_schedule_id IS NOT NULL)
    WHEN 'collateral_csa_agreement'::text THEN (collateral_csa_agreement_id IS NOT NULL)
    ELSE false
END));
