CREATE POLICY "recon_defs_update" ON "public"."recon_definitions" AS PERMISSIVE FOR UPDATE TO "authenticated" USING (
CASE
    WHEN (access_mode = 'legacy_passthrough'::text) THEN (private.user_can_access_recon(auth.uid(), id, 'edit'::text) AND (private.has_tenant_role(auth.uid(), tenant_id, 'tenant_admin'::tenant_role) OR private.has_tenant_role(auth.uid(), tenant_id, 'tenant_analyst'::tenant_role)))
    ELSE private.recon_authoritative_access_decision(id, 'edit'::text)
END) WITH CHECK (
CASE
    WHEN (access_mode = 'legacy_passthrough'::text) THEN (private.user_can_access_recon(auth.uid(), id, 'edit'::text) AND (private.has_tenant_role(auth.uid(), tenant_id, 'tenant_admin'::tenant_role) OR private.has_tenant_role(auth.uid(), tenant_id, 'tenant_analyst'::tenant_role)))
    ELSE private.recon_authoritative_access_decision(id, 'edit'::text)
END);
CREATE POLICY "recon_defs_delete" ON "public"."recon_definitions" AS PERMISSIVE FOR DELETE TO "authenticated" USING (((status = 'draft'::text) AND (retired_at IS NULL) AND (NOT (EXISTS ( SELECT 1
   FROM recon_runs run_row
  WHERE (run_row.definition_id = recon_definitions.id)))) AND (access_mode = 'legacy_passthrough'::text) AND private.user_can_access_recon(auth.uid(), id, 'edit'::text) AND (EXISTS ( SELECT 1
   FROM tenant_members member_row
  WHERE ((member_row.tenant_id = recon_definitions.tenant_id) AND (member_row.user_id = auth.uid()) AND (member_row.active = true)))) AND (private.has_tenant_role(auth.uid(), tenant_id, 'tenant_admin'::tenant_role) OR private.has_tenant_role(auth.uid(), tenant_id, 'tenant_analyst'::tenant_role))));
